        $1, $2, $3, $4::regprocedure)
$$;

CREATE FUNCTION pgreact_api.author_deadline_rule(
    rule_name text,
    condition regclass,
    semantic_key name,
    deadline_column name,
    kind text DEFAULT NULL,
    on_activate text DEFAULT NULL,
    on_deactivate text DEFAULT NULL,
