CREATE TABLE pgreact_internal.keyed_derived_relations (
    relation_version_id uuid PRIMARY KEY REFERENCES pgreact_internal.derived_relation_versions,
    public_name text NOT NULL UNIQUE,
    internal_name text NOT NULL UNIQUE,
    public_row_type regtype NOT NULL,
    internal_row_type regtype NOT NULL,
    key_columns name[] NOT NULL CHECK (cardinality(key_columns) BETWEEN 1 AND 4),
    key_types regtype[] NOT NULL,
    key_collations regcollation[] NOT NULL
);

CREATE FUNCTION pgreact_api.declare_derived_relation(
    relation_name text,
    row_type regtype,
    semantic_keys name[],
    relation_version integer DEFAULT 1
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    identity_parts text[] := parse_ident(relation_name, true);
    public_schema name;
    public_relation name;
    type_relation oid;
    type_owner oid;
    attribute record;
    key_column name;
    key_types regtype[] := ARRAY[]::regtype[];
    key_collations regcollation[] := ARRAY[]::regcollation[];
    attribute_definitions text[] := ARRAY[]::text[];
    public_columns text[] := ARRAY[]::text[];
    internal_suffix text := md5(relation_name || ':' || relation_version::text);
    internal_type_name name;
    internal_relation_name name;
    internal_type regtype;
    created_version uuid;
BEGIN
    IF cardinality(identity_parts) <> 2 THEN
        RAISE EXCEPTION 'M15_RELATION_NAME: derived relation names must be schema-qualified';
    END IF;
    public_schema := identity_parts[1];
    public_relation := identity_parts[2];
    IF NOT has_schema_privilege(session_user, public_schema, 'CREATE') THEN
        RAISE EXCEPTION 'M15_RELATION_SCHEMA: % cannot create in schema %', session_user, public_schema;
    END IF;
    SELECT type.typrelid, type.typowner INTO STRICT type_relation, type_owner
    FROM pg_type type WHERE type.oid = row_type;
    IF type_relation = 0 OR type_owner <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RAISE EXCEPTION 'M15_RELATION_TYPE: the author must own composite row type %', row_type;
    END IF;
    IF cardinality(semantic_keys) NOT BETWEEN 1 AND 4
       OR array_position(semantic_keys, NULL) IS NOT NULL
       OR (SELECT count(DISTINCT key) FROM unnest(semantic_keys) key)
          <> cardinality(semantic_keys) THEN
        RAISE EXCEPTION 'M15_KEY_ARITY: semantic keys require one to four distinct named attributes';
    END IF;
    FOR attribute IN
        SELECT value.attname, value.atttypid, value.atttypmod, value.attcollation,
               attribute_collation.collname, attribute_collation.collisdeterministic
        FROM pg_attribute value
        LEFT JOIN pg_collation attribute_collation
          ON attribute_collation.oid = value.attcollation
        WHERE value.attrelid = type_relation AND value.attnum > 0 AND NOT value.attisdropped
        ORDER BY value.attnum
    LOOP
        attribute_definitions := attribute_definitions || format(
            '%I %s%s', attribute.attname,
            format_type(attribute.atttypid, attribute.atttypmod),
            CASE WHEN attribute.attcollation = 0 THEN ''
                 ELSE format(' COLLATE %I', attribute.collname) END);
        public_columns := public_columns || format('%I', attribute.attname);
    END LOOP;
    FOREACH key_column IN ARRAY semantic_keys LOOP
        SELECT value.atttypid::regtype, value.attcollation::regcollation,
               key_collation.collname, key_collation.collisdeterministic,
               current_database_row.datcollate
        INTO STRICT attribute
        FROM pg_attribute value
        LEFT JOIN pg_collation key_collation ON key_collation.oid = value.attcollation
        CROSS JOIN pg_database current_database_row
        WHERE value.attrelid = type_relation AND value.attname = key_column
          AND value.attnum > 0 AND NOT value.attisdropped
          AND current_database_row.datname = current_database();
        IF attribute.atttypid NOT IN ('bigint'::regtype, 'uuid'::regtype, 'text'::regtype) THEN
            RAISE EXCEPTION 'M15_KEY_TYPE: %.% has unsupported type %',
                row_type, key_column, attribute.atttypid;
        END IF;
        IF attribute.atttypid = 'text'::regtype
           AND (NOT attribute.collisdeterministic
                OR (attribute.collname <> 'C'
                    AND NOT (attribute.collname = 'default'
                             AND attribute.datcollate IN ('C', 'C.UTF-8', 'C.utf8')))) THEN
            RAISE EXCEPTION 'M15_KEY_COLLATION: %.% requires deterministic C collation',
                row_type, key_column;
        END IF;
        key_types := key_types || attribute.atttypid;
        key_collations := key_collations || attribute.attcollation;
    END LOOP;
    internal_type_name := ('m15_type_' || internal_suffix)::name;
    internal_relation_name := ('m15_relation_' || internal_suffix)::name;
    EXECUTE format(
        'CREATE TYPE pgreact_runtime.%I AS (%s, __pgreact_canonical bytea, '
        '__pgreact_key bigint, __pgreact_public_key jsonb)',
        internal_type_name, array_to_string(attribute_definitions, ', '));
    EXECUTE format('ALTER TYPE pgreact_runtime.%I OWNER TO %I',
                   internal_type_name, session_user);
    EXECUTE format('GRANT USAGE ON SCHEMA pgreact_runtime TO %I', session_user);
    internal_type := format('pgreact_runtime.%I', internal_type_name)::regtype;
    EXECUTE format('GRANT CREATE ON SCHEMA pgreact_runtime TO %I', session_user);
    created_version := pgreact.create_derived_relation(
        format('pgreact_runtime.%I', internal_relation_name), internal_type,
        ARRAY['__pgreact_key'::name], relation_version);
    EXECUTE format('REVOKE CREATE ON SCHEMA pgreact_runtime FROM %I', session_user);
    EXECUTE format(
        'CREATE VIEW %I.%I AS SELECT %s FROM pgreact_runtime.%I',
        public_schema, public_relation, array_to_string(public_columns, ', '),
        internal_relation_name);
    EXECUTE format('GRANT SELECT ON %I.%I TO %I WITH GRANT OPTION',
                   public_schema, public_relation, session_user);
    INSERT INTO pgreact_internal.keyed_derived_relations VALUES (
        created_version, format('%I.%I', public_schema, public_relation),
        format('pgreact_runtime.%I', internal_relation_name), row_type, internal_type,
        semantic_keys, key_types, key_collations);
    RETURN created_version;
END
$$;

CREATE FUNCTION pgreact_internal.normalize_program(definition jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    normalized jsonb := pgreact_api.infer_program(definition);
    rule_item record;
    dependency record;
    derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    wrapper regclass;
    source regclass;
BEGIN
    FOR rule_item IN
        SELECT value, ordinal
        FROM jsonb_array_elements(definition -> 'rules')
             WITH ORDINALITY rules(value, ordinal)
        ORDER BY ordinal
    LOOP
        SELECT * INTO derived
        FROM pgreact_internal.keyed_derived_relations
        WHERE public_name = rule_item.value ->> 'target';
        IF NOT FOUND THEN CONTINUE; END IF;
        source := to_regclass(rule_item.value ->> 'definition');
        IF source IS NULL THEN
            RAISE EXCEPTION 'M15_DERIVATION_SOURCE: definition view % does not exist',
                rule_item.value ->> 'definition';
        END IF;
        wrapper := pgreact_internal.create_key_wrapper(source, derived.key_columns);
        normalized := jsonb_set(normalized,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'definition'],
            to_jsonb(wrapper::text));
        normalized := jsonb_set(normalized,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'key'],
            to_jsonb('__pgreact_key'::text));
        normalized := jsonb_set(normalized,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'target'],
            to_jsonb(derived.internal_name));
        FOR dependency IN
            SELECT dependency_kind, dependency_value, dependency_ordinal
            FROM (
                SELECT 'inputs'::text, value, ordinal
                FROM jsonb_array_elements(COALESCE(normalized #> ARRAY[
                    'rules', (rule_item.ordinal - 1)::text, 'inputs'], '[]'::jsonb))
                     WITH ORDINALITY input(value, ordinal)
                UNION ALL
                SELECT 'negative_inputs'::text, value, ordinal
                FROM jsonb_array_elements(COALESCE(rule_item.value -> 'negative_inputs', '[]'::jsonb))
                     WITH ORDINALITY negative_input(value, ordinal)
            ) dependencies(dependency_kind, dependency_value, dependency_ordinal)
        LOOP
            source := to_regclass(dependency.dependency_value ->> 'relation');
            IF source IS NULL THEN
                RAISE EXCEPTION 'M15_DERIVATION_INPUT: relation % does not exist',
                    dependency.dependency_value ->> 'relation';
            END IF;
            wrapper := pgreact_internal.create_key_wrapper(source, derived.key_columns);
            normalized := jsonb_set(normalized, ARRAY[
                'rules', (rule_item.ordinal - 1)::text, dependency.dependency_kind,
                (dependency.dependency_ordinal - 1)::text, 'relation'], to_jsonb(wrapper::text));
            normalized := jsonb_set(normalized, ARRAY[
                'rules', (rule_item.ordinal - 1)::text, dependency.dependency_kind,
                (dependency.dependency_ordinal - 1)::text, 'key'], to_jsonb('__pgreact_key'::text));
        END LOOP;
        IF rule_item.value -> 'aggregate_input' IS NOT NULL THEN
            source := to_regclass(rule_item.value #>> '{aggregate_input,relation}');
            IF source IS NULL THEN
                RAISE EXCEPTION 'M15_DERIVATION_INPUT: relation % does not exist',
                    rule_item.value #>> '{aggregate_input,relation}';
            END IF;
            wrapper := pgreact_internal.create_key_wrapper(source, derived.key_columns);
            normalized := jsonb_set(normalized,
                ARRAY['rules', (rule_item.ordinal - 1)::text, 'aggregate_input', 'relation'],
                to_jsonb(wrapper::text));
            normalized := jsonb_set(normalized,
                ARRAY['rules', (rule_item.ordinal - 1)::text, 'aggregate_input', 'key'],
                to_jsonb('__pgreact_key'::text));
        END IF;
    END LOOP;
    RETURN normalized;
END
$$;

ALTER FUNCTION pgreact_api.validate_program(jsonb) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.validate_program(jsonb) RENAME TO validate_program_m14;
ALTER FUNCTION pgreact_api.preview_program(jsonb) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.preview_program(jsonb) RENAME TO preview_program_m14;
ALTER FUNCTION pgreact_api.deploy_program(jsonb, text) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.deploy_program(jsonb, text) RENAME TO deploy_program_m14;

CREATE FUNCTION pgreact_api.validate_program(definition jsonb)
RETURNS TABLE(
    contract_version integer, code text, severity text,
    object_identity text, message text, hint text, details jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE normalized jsonb;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(definition -> 'rules') rule
        JOIN pgreact_internal.keyed_derived_relations relation_spec
          ON relation_spec.public_name = rule ->> 'target') THEN
        RETURN QUERY SELECT * FROM pgreact_internal.validate_program_m14(definition);
        RETURN;
    END IF;
    normalized := pgreact_internal.normalize_program(definition);
    RETURN QUERY
    SELECT 5, diagnostic.code, diagnostic.severity, diagnostic.object_identity,
           diagnostic.message, diagnostic.hint,
           diagnostic.details || jsonb_build_object('normalized_definition', normalized)
    FROM pgreact.validate_derivation_program(normalized) diagnostic;
END
$$;

CREATE FUNCTION pgreact_api.preview_program(definition jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    normalized jsonb;
    inferred jsonb;
    diagnostic record;
    plan text;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(definition -> 'rules') rule
        JOIN pgreact_internal.keyed_derived_relations relation_spec
          ON relation_spec.public_name = rule ->> 'target') THEN
        RETURN pgreact_internal.preview_program_m14(definition);
    END IF;
    normalized := pgreact_internal.normalize_program(definition);
    SELECT * INTO diagnostic FROM pgreact.validate_derivation_program(normalized)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M15_PROGRAM_INVALID: % for %', diagnostic.code, diagnostic.object_identity
            USING HINT = diagnostic.hint;
    END IF;
    inferred := pgreact_api.infer_program(definition);
    plan := encode(sha256(convert_to(normalized::text || ':' || session_user, 'UTF8')), 'hex');
    RETURN jsonb_build_object(
        'contract_version', 5, 'program', inferred, 'plan_digest', plan);
END
$$;

CREATE FUNCTION pgreact_api.deploy_program(definition jsonb, expected_plan_digest text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    normalized jsonb;
    actual_plan_digest text;
    deployed uuid;
    rule_item record;
    derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    version_id uuid;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(definition -> 'rules') rule
        JOIN pgreact_internal.keyed_derived_relations relation_spec
          ON relation_spec.public_name = rule ->> 'target') THEN
        RETURN pgreact_internal.deploy_program_m14(definition, expected_plan_digest);
    END IF;
    normalized := pgreact_internal.normalize_program(definition);
    actual_plan_digest := encode(
        sha256(convert_to(normalized::text || ':' || session_user, 'UTF8')), 'hex');
    IF expected_plan_digest IS NOT NULL AND expected_plan_digest <> actual_plan_digest THEN
        RAISE EXCEPTION 'M15_PROGRAM_PREVIEW_STALE'
            USING HINT = 'Preview the program again after DDL or deployment changes.';
    END IF;
    deployed := pgreact_internal.deploy_derivation_program(normalized, NULL);
    FOR rule_item IN
        SELECT original.value, normalized_rule.value AS normalized_value
        FROM jsonb_array_elements(definition -> 'rules') WITH ORDINALITY original(value, ordinal)
        JOIN jsonb_array_elements(normalized -> 'rules') WITH ORDINALITY normalized_rule(value, ordinal)
          USING (ordinal)
    LOOP
        SELECT * INTO derived
        FROM pgreact_internal.keyed_derived_relations
        WHERE public_name = rule_item.value ->> 'target';
        IF NOT FOUND THEN CONTINUE; END IF;
        SELECT version.rule_version_id INTO STRICT version_id
        FROM pgreact_internal.rules rule
        JOIN pgreact_internal.rule_versions version USING (rule_id)
        WHERE rule.rule_name = rule_item.value ->> 'name' AND version.state = 'ACTIVE';
        INSERT INTO pgreact_internal.keyed_rule_versions VALUES (
            version_id, to_regclass(rule_item.value ->> 'definition'),
            to_regclass(rule_item.normalized_value ->> 'definition'),
            derived.key_columns, derived.key_types, derived.key_collations)
        ON CONFLICT (rule_version_id) DO UPDATE
        SET public_condition = EXCLUDED.public_condition,
            wrapper_condition = EXCLUDED.wrapper_condition,
            key_columns = EXCLUDED.key_columns,
            key_types = EXCLUDED.key_types,
            key_collations = EXCLUDED.key_collations;
    END LOOP;
    RETURN deployed;
END
$$;

CREATE OR REPLACE FUNCTION pgreact_internal.is_operator_admin()
RETURNS boolean
LANGUAGE SQL
STABLE
PARALLEL SAFE
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT (SELECT rolsuper FROM pg_catalog.pg_roles WHERE rolname = session_user)
        OR (to_regrole('pgreact_admin') IS NOT NULL
            AND pg_catalog.pg_has_role(session_user, 'pgreact_admin', 'member'))
        OR EXISTS (
            SELECT 1 FROM pgreact_internal.application_roles application_role
            WHERE application_role.role_kind = 'operator'
              AND pg_catalog.pg_has_role(session_user, application_role.role_oid, 'member'))
        OR EXISTS (
            SELECT 1 FROM pgreact_internal.managed_processes process
            WHERE process.database_oid = (SELECT oid FROM pg_database WHERE datname = current_database())
              AND process.backend_pid = pg_backend_pid())
$$;

CREATE FUNCTION pgreact_internal.sync_semantic_keys()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    keyed record;
    identity record;
    existing bytea;
BEGIN
    FOR keyed IN
        SELECT spec.*
        FROM pgreact_internal.keyed_rule_versions spec
        JOIN pgreact_internal.rule_versions version USING (rule_version_id)
        WHERE version.state = 'ACTIVE'
        ORDER BY spec.public_condition::regclass::text, spec.rule_version_id
    LOOP
        FOR identity IN EXECUTE format(
            'SELECT __pgreact_key AS semantic_key, __pgreact_canonical AS canonical_key, '
            '__pgreact_public_key AS public_key, count(*) OVER (PARTITION BY __pgreact_key) AS occurrences '
            'FROM %s', keyed.wrapper_condition::regclass)
        LOOP
            IF identity.semantic_key IS NULL OR identity.canonical_key IS NULL
               OR identity.public_key IS NULL THEN
                RAISE EXCEPTION 'M15_KEY_NULL: every semantic key component in % must be non-null',
                    keyed.public_condition::regclass;
            END IF;
            IF identity.occurrences <> 1 THEN
                RAISE EXCEPTION 'M15_KEY_DUPLICATE: key % occurs % times in %',
                    identity.public_key, identity.occurrences, keyed.public_condition::regclass;
            END IF;
            SELECT canonical_key INTO existing
            FROM pgreact_internal.semantic_key_identities
            WHERE rule_version_id = keyed.rule_version_id
              AND semantic_key = identity.semantic_key;
            IF existing IS NOT NULL AND existing <> identity.canonical_key THEN
                RAISE EXCEPTION 'M15_KEY_COLLISION: distinct typed keys share one internal identity in %',
                    keyed.public_condition::regclass
                    USING HINT = 'Change a key component or report the SHA-256 prefix collision.';
            END IF;
            INSERT INTO pgreact_internal.semantic_key_identities (
                rule_version_id, semantic_key, canonical_key, public_key)
            VALUES (
                keyed.rule_version_id, identity.semantic_key,
                identity.canonical_key, identity.public_key)
            ON CONFLICT (rule_version_id, semantic_key) DO UPDATE
            SET public_key = EXCLUDED.public_key, last_seen_at = clock_timestamp();
        END LOOP;
    END LOOP;
END
$$;

ALTER FUNCTION pgreact_api.run(timestamptz) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.run(timestamptz) RENAME TO run_m14;

CREATE FUNCTION pgreact_api.run(sampled_time timestamptz DEFAULT clock_timestamp())
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE result jsonb;
BEGIN
    PERFORM pgreact_internal.sync_semantic_keys();
    result := pgreact_internal.run_m14(sampled_time);
    RETURN jsonb_set(result, '{contract_version}', '5'::jsonb);
END
$$;

CREATE FUNCTION pgreact_internal.managed_cycle(process_pid integer)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    worker text := format('pg-react-managed/%s/%s', current_database(), process_pid);
    batch_limit integer := current_setting('pg_react.batch_size')::integer;
    pending_limit integer := current_setting('pg_react.max_pending_jobs')::integer;
    pending bigint;
    processed bigint := 0;
    claimed record;
    runtime_state text := 'ready';
    run_result jsonb;
BEGIN
    SELECT count(*) INTO pending
    FROM pgreact_internal.agenda job
    WHERE job.state IN ('PENDING', 'LEASED', 'RETRY_WAIT');
    INSERT INTO pgreact_internal.managed_processes (
        database_oid, database_name, backend_pid, state, protocol, pending_jobs)
    VALUES ((SELECT oid FROM pg_database WHERE datname = current_database()),
            current_database(), process_pid, 'ready', 2, pending)
    ON CONFLICT (database_oid) DO UPDATE
    SET database_name = EXCLUDED.database_name, backend_pid = EXCLUDED.backend_pid,
        state = EXCLUDED.state, protocol = EXCLUDED.protocol,
        pending_jobs = EXCLUDED.pending_jobs, started_at = CASE
            WHEN pgreact_internal.managed_processes.backend_pid = EXCLUDED.backend_pid
            THEN pgreact_internal.managed_processes.started_at ELSE clock_timestamp() END,
        heartbeat_at = clock_timestamp(), detail = NULL;

    IF pg_is_in_recovery() THEN
        runtime_state := 'standby';
    ELSIF NOT pgreact.worker_protocol_compatible(2) THEN
        runtime_state := 'error';
        UPDATE pgreact_internal.managed_processes
        SET state = runtime_state, detail = 'worker protocol 2 is incompatible',
            heartbeat_at = clock_timestamp()
        WHERE database_oid = (SELECT oid FROM pg_database WHERE datname = current_database());
        RETURN jsonb_build_object('state', runtime_state, 'pending_jobs', pending, 'processed_jobs', 0);
    ELSE
        IF pending >= pending_limit THEN
            runtime_state := 'backpressure';
        ELSE
            run_result := pgreact_api.run();
        END IF;
        FOR claimed IN
            SELECT * FROM pgreact_api.claim(worker, batch_limit, interval '60 seconds')
        LOOP
            PERFORM pgreact_api.execute(claimed.episode_id, worker, claimed.lease_token);
            processed := processed + 1;
        END LOOP;
    END IF;
    SELECT count(*) INTO pending
    FROM pgreact_internal.agenda job
    WHERE job.state IN ('PENDING', 'LEASED', 'RETRY_WAIT');
    UPDATE pgreact_internal.managed_processes
    SET state = runtime_state, pending_jobs = pending,
        processed_jobs = processed_jobs + processed,
        heartbeat_at = clock_timestamp(), detail = NULL
    WHERE database_oid = (SELECT oid FROM pg_database WHERE datname = current_database());
    RETURN jsonb_build_object(
        'state', runtime_state, 'pending_jobs', pending, 'processed_jobs', processed,
        'run', run_result);
EXCEPTION WHEN OTHERS THEN
    INSERT INTO pgreact_internal.managed_processes (
        database_oid, database_name, backend_pid, state, protocol, detail)
    VALUES ((SELECT oid FROM pg_database WHERE datname = current_database()),
            current_database(), process_pid, 'error', 2, SQLSTATE || ': ' || SQLERRM)
    ON CONFLICT (database_oid) DO UPDATE
    SET backend_pid = EXCLUDED.backend_pid, state = 'error',
        heartbeat_at = clock_timestamp(), detail = EXCLUDED.detail;
    RETURN jsonb_build_object('state', 'error', 'sqlstate', SQLSTATE, 'message', SQLERRM);
END
$$;

CREATE FUNCTION pgreact_api.managed_cycle()
RETURNS jsonb
LANGUAGE SQL
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$ SELECT pgreact_internal.managed_cycle(pg_backend_pid()) $$;

CREATE FUNCTION pgreact_api.managed_status()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 5,
        'database', current_database(),
        'configured', current_database() = ANY (regexp_split_to_array(
            current_setting('pg_react.databases', true), '\\s*,\\s*')),
        'process', CASE WHEN process.database_oid IS NULL THEN NULL ELSE jsonb_build_object(
            'pid', process.backend_pid, 'state', process.state,
            'protocol', process.protocol, 'pending_jobs', process.pending_jobs,
            'processed_jobs', process.processed_jobs,
            'started_at', process.started_at, 'heartbeat_at', process.heartbeat_at,
            'detail', process.detail) END)
    FROM (SELECT 1) singleton
    LEFT JOIN pgreact_internal.managed_processes process
      ON process.database_oid = (SELECT oid FROM pg_database WHERE datname = current_database())
$$;

CREATE FUNCTION pgreact_api.key_codecs()
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
PARALLEL SAFE
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 5, 'codec_version', 2, 'max_arity', 4,
        'scalar_types', jsonb_build_array('bigint', 'uuid', 'text'),
        'null_components', false, 'component_order', 'declared',
        'text_collation', 'C')
$$;

CREATE OR REPLACE FUNCTION pgreact_api.status(name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE SQL
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 5,
        'rules', COALESCE(jsonb_agg(jsonb_build_object(
            'rule', rule.rule_name,
            'condition', COALESCE(spec.public_condition::regclass::text, rule.source_view_name),
            'key', CASE WHEN spec.rule_version_id IS NULL THEN to_jsonb(rule.key_column)
                        WHEN cardinality(spec.key_columns) = 1 THEN to_jsonb(spec.key_columns[1])
                        ELSE to_jsonb(spec.key_columns) END,
            'state', lower(rule.state),
            'actions', COALESCE((
                SELECT jsonb_agg(jsonb_build_object(
                    'action', lower(binding.event_kind),
                    'function', COALESCE(proxy.action_oid::regprocedure::text,
                                         binding.function_identity))
                    ORDER BY binding.event_kind)
                FROM pgreact_internal.consequence_bindings binding
                LEFT JOIN pgreact_internal.action_proxies proxy
                  ON proxy.proxy_oid = binding.function_oid
                WHERE binding.rule_version_id = rule.rule_version_id
            ), '[]'::jsonb)) ORDER BY rule.rule_name), '[]'::jsonb))
    FROM pgreact.rules rule
    LEFT JOIN pgreact_internal.keyed_rule_versions spec USING (rule_version_id)
    WHERE $1 IS NULL OR rule.rule_name = $1
$$;

CREATE OR REPLACE FUNCTION pgreact_api.matches(name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE SQL
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 5,
        'matches', COALESCE(jsonb_agg(jsonb_build_object(
            'rule', rule.rule_name,
            'key', COALESCE(identity.public_key, to_jsonb(match.semantic_key)),
            'matched_at', match.first_seen_at,
            'observed_at', match.last_seen_at)
            ORDER BY rule.rule_name, COALESCE(identity.public_key, to_jsonb(match.semantic_key))), '[]'::jsonb))
    FROM pgreact_internal.activation_state match
    JOIN pgreact_internal.rule_versions version USING (rule_version_id)
    JOIN pgreact_internal.rules rule USING (rule_id)
    LEFT JOIN pgreact_internal.semantic_key_identities identity
      ON identity.rule_version_id = match.rule_version_id
     AND identity.semantic_key = match.semantic_key
    WHERE match.active AND ($1 IS NULL OR rule.rule_name = $1)
$$;

CREATE OR REPLACE FUNCTION pgreact_api.jobs(name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE SQL
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 3,
        'jobs', COALESCE(jsonb_agg(jsonb_build_object(
            'job_id', job.episode_id,
            'rule', rule.rule_name,
            'action', lower(job.event_kind),
            'state', lower(job.state),
            'available_at', job.available_at,
            'claimed_at', job.claimed_at,
            'completed_at', job.completed_at,
            'idempotency_key', job.idempotency_key) ||
            CASE WHEN spec.rule_version_id IS NULL THEN '{}'::jsonb
                 ELSE jsonb_build_object('key', identity.public_key) END
            ORDER BY job.episode_id), '[]'::jsonb))
    FROM pgreact_internal.agenda job
    JOIN pgreact_internal.rules rule USING (rule_id)
    LEFT JOIN pgreact_internal.keyed_rule_versions spec USING (rule_version_id)
    LEFT JOIN pgreact_internal.activation_state activation
      ON activation.rule_version_id = job.rule_version_id
     AND activation.activation_id = job.activation_id
    LEFT JOIN pgreact_internal.semantic_key_identities identity
      ON identity.rule_version_id = job.rule_version_id
     AND identity.semantic_key = activation.semantic_key
    WHERE $1 IS NULL OR rule.rule_name = $1
$$;

CREATE OR REPLACE FUNCTION pgreact_api.attempts(name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE SQL
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 3,
        'attempts', COALESCE(jsonb_agg(jsonb_build_object(
            'job_id', attempt.episode_id,
            'attempt', attempt.attempt_no,
            'worker', attempt.worker_id,
            'status', lower(attempt.status),
            'started_at', attempt.started_at,
            'finished_at', attempt.finished_at,
            'error_code', attempt.error_code,
            'error_message', attempt.error_message) ||
            CASE WHEN spec.rule_version_id IS NULL THEN '{}'::jsonb
                 ELSE jsonb_build_object('key', identity.public_key) END
            ORDER BY attempt.episode_id, attempt.attempt_no), '[]'::jsonb))
    FROM pgreact_internal.executions attempt
    JOIN pgreact_internal.agenda job USING (episode_id)
    JOIN pgreact_internal.rules rule USING (rule_id)
    LEFT JOIN pgreact_internal.keyed_rule_versions spec USING (rule_version_id)
    LEFT JOIN pgreact_internal.activation_state activation
      ON activation.rule_version_id = job.rule_version_id
     AND activation.activation_id = job.activation_id
    LEFT JOIN pgreact_internal.semantic_key_identities identity
      ON identity.rule_version_id = job.rule_version_id
     AND identity.semantic_key = activation.semantic_key
    WHERE $1 IS NULL OR rule.rule_name = $1
$$;

CREATE OR REPLACE FUNCTION pgreact_api.deadline_history(name text)
RETURNS jsonb
LANGUAGE SQL
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 2,
        'rule_name', $1,
        'events', COALESCE(jsonb_agg(jsonb_build_object(
            'rule_name', rule.rule_name,
            'semantic_key', COALESCE(identity.public_key, to_jsonb(activation.semantic_key)),
            'generation', event.generation,
            'revision', event.revision,
            'event_kind', event.event_kind,
            'declared_deadline', deadline.declared_deadline,
            'clock_frontier', deadline.observed_frontier)
            ORDER BY event.event_id), '[]'::jsonb))
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    JOIN pgreact_internal.lifecycle_events event USING (rule_version_id)
    JOIN pgreact_internal.deadline_lifecycle deadline USING (event_id)
    JOIN pgreact_internal.activation_state activation
      ON activation.rule_version_id = event.rule_version_id
     AND activation.activation_id = event.activation_id
    LEFT JOIN pgreact_internal.semantic_key_identities identity
      ON identity.rule_version_id = activation.rule_version_id
     AND identity.semantic_key = activation.semantic_key
    WHERE rule.rule_name = $1
$$;

CREATE FUNCTION pgreact_internal.public_json(input_value jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    result jsonb;
    member record;
    item jsonb;
    public_key jsonb;
    public_name text;
BEGIN
    CASE jsonb_typeof(input_value)
    WHEN 'object' THEN
        result := '{}'::jsonb;
        public_key := input_value -> '__pgreact_public_key';
        FOR member IN
            SELECT entry.key, entry.value
            FROM jsonb_each(input_value) entry ORDER BY entry.key
        LOOP
            IF left(member.key, 10) = '__pgreact_' THEN CONTINUE; END IF;
            item := member.value;
            IF member.key IN ('key', 'semantic_key', 'group_key')
               AND jsonb_typeof(item) = 'number' THEN
                IF public_key IS NULL THEN
                    SELECT identity.public_key INTO public_key
                    FROM pgreact_internal.semantic_key_identities identity
                    WHERE identity.semantic_key = (item #>> '{}')::bigint
                    ORDER BY identity.rule_version_id LIMIT 1;
                END IF;
                item := COALESCE(public_key, item);
            END IF;
            result := result || jsonb_build_object(
                member.key, pgreact_internal.public_json(item));
        END LOOP;
        RETURN result;
    WHEN 'array' THEN
        SELECT COALESCE(jsonb_agg(pgreact_internal.public_json(element) ORDER BY ordinal), '[]'::jsonb)
        INTO result
        FROM jsonb_array_elements(input_value) WITH ORDINALITY item(element, ordinal);
        RETURN result;
    WHEN 'string' THEN
        SELECT spec.public_name || substring(input_value #>> '{}'
            FROM length(spec.internal_name) + 1) INTO public_name
        FROM pgreact_internal.keyed_derived_relations spec
        WHERE input_value #>> '{}' = spec.internal_name
           OR input_value #>> '{}' LIKE spec.internal_name || '@%';
        IF public_name IS NULL THEN
            SELECT wrapper.public_condition::regclass::text INTO public_name
            FROM pgreact_internal.key_wrappers wrapper
            WHERE wrapper.wrapper_condition::regclass::text = input_value #>> '{}';
        END IF;
        RETURN COALESCE(to_jsonb(public_name), input_value);
    ELSE
        RETURN input_value;
    END CASE;
END
$$;

CREATE FUNCTION pgreact_api.explain(target text, semantic_key jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    activation uuid;
    derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    surrogate bigint;
    result jsonb;
BEGIN
    SELECT * INTO derived
    FROM pgreact_internal.keyed_derived_relations
    WHERE public_name = target;
    IF FOUND THEN
        EXECUTE format(
            'SELECT __pgreact_key FROM %s WHERE __pgreact_public_key = $1',
            derived.internal_name)
        INTO surrogate USING semantic_key;
        IF surrogate IS NULL THEN
            RETURN jsonb_build_object(
                'contract_version', 5,
                'target', jsonb_build_object('kind', 'fact', 'name', target, 'key', semantic_key),
                'evidence', NULL);
        END IF;
        result := pgreact_api.explain(derived.internal_name, surrogate);
        result := jsonb_set(result, '{contract_version}', '5'::jsonb);
        result := jsonb_set(result, '{target}', jsonb_build_object(
            'kind', 'fact', 'name', target, 'key', semantic_key));
        IF result #> '{evidence,fact}' IS NOT NULL THEN
            result := jsonb_set(result, '{evidence,fact}',
                (result #> '{evidence,fact}')
                - ARRAY['__pgreact_canonical', '__pgreact_key', '__pgreact_public_key']);
        END IF;
        RETURN pgreact_internal.public_json(result);
    END IF;
    SELECT state.activation_id INTO activation
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    JOIN pgreact_internal.semantic_key_identities identity USING (rule_version_id)
    JOIN pgreact_internal.activation_state state
      ON state.rule_version_id = identity.rule_version_id
     AND state.semantic_key = identity.semantic_key
    WHERE rule.rule_name = target AND version.state = 'ACTIVE'
      AND identity.public_key = $2;
    IF activation IS NULL THEN
        RETURN jsonb_build_object(
            'contract_version', 5,
            'target', jsonb_build_object('kind', 'match', 'rule', target, 'key', semantic_key),
            'evidence', NULL);
    END IF;
    RETURN pgreact_internal.public_json(jsonb_set(
        pgreact_api.explain(target, activation), '{contract_version}', '5'::jsonb)
        || jsonb_build_object(
            'target', jsonb_build_object('kind', 'match', 'rule', target, 'key', semantic_key)));
END
$$;

CREATE OR REPLACE FUNCTION pgreact_api.doctor()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    WITH diagnostics AS (
        SELECT diagnostic FROM jsonb_array_elements(pgreact_api.health() -> 'diagnostics') diagnostic
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M15_EXTENSION_VERSION', 'severity', 'ERROR', 'object_identity', 'pg_react',
            'message', 'pg_react extension version is not 0.12.0',
            'hint', 'Install matching files and run ALTER EXTENSION pg_react UPDATE.')
        WHERE NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_react' AND extversion = '0.12.0')
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M15_TRICKLE_VERSION', 'severity', 'ERROR', 'object_identity', 'pg_trickle',
            'message', 'pg_trickle extension version is not 0.81.0',
            'hint', 'Install the supported pg_trickle 0.81.0 extension.')
        WHERE NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_trickle' AND extversion = '0.81.0')
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M15_ROLE_CONFIGURATION', 'severity', 'WARNING', 'object_identity', 'pgreact_api',
            'message', 'application facade roles are not configured',
            'hint', 'The extension owner must call pgreact_api.configure_roles with five distinct roles.')
        WHERE (SELECT count(*) FROM pgreact_internal.application_roles) <> 4
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M15_MANAGED_CONFIGURATION', 'severity', 'ERROR', 'object_identity', current_database(),
            'message', 'this database is not configured for a managed worker',
            'hint', 'Preload pg_react, add this database to pg_react.databases, and restart PostgreSQL.')
        WHERE NOT current_database() = ANY (regexp_split_to_array(
            current_setting('pg_react.databases', true), '\\s*,\\s*'))
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M15_MANAGED_PROCESS', 'severity', 'ERROR', 'object_identity', current_database(),
            'message', CASE WHEN process.database_oid IS NULL THEN 'managed worker has not attached'
                            ELSE 'managed worker state is ' || process.state END,
            'hint', 'Inspect pgreact_api.managed_status(), PostgreSQL logs, preload settings, and worker role connectivity.')
        FROM (SELECT 1) singleton
        LEFT JOIN pgreact_internal.managed_processes process
          ON process.database_oid = (SELECT oid FROM pg_database WHERE datname = current_database())
        WHERE process.database_oid IS NULL OR process.state <> 'ready'
           OR process.heartbeat_at < clock_timestamp() - interval '10 seconds'
    ), ordered AS (
        SELECT diagnostic FROM diagnostics
        ORDER BY CASE diagnostic ->> 'severity' WHEN 'ERROR' THEN 1 WHEN 'WARNING' THEN 2 ELSE 3 END,
                 diagnostic ->> 'code', diagnostic ->> 'object_identity'
    )
    SELECT jsonb_build_object(
        'contract_version', 5,
        'status', CASE WHEN EXISTS (SELECT 1 FROM ordered WHERE diagnostic ->> 'severity' = 'ERROR')
                       THEN 'attention' ELSE 'ready' END,
        'diagnostics', COALESCE((SELECT jsonb_agg(diagnostic) FROM ordered), '[]'::jsonb))
$$;

ALTER FUNCTION pgreact_api.configure_roles(regrole, regrole, regrole, regrole, regrole)
SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.configure_roles(regrole, regrole, regrole, regrole, regrole)
RENAME TO configure_roles_m14;

CREATE FUNCTION pgreact_api.configure_roles(
    author_role regrole,
    operator_role regrole,
    worker_role regrole,
    reader_role regrole,
    advanced_reader_role regrole
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    PERFORM pgreact_internal.configure_roles_m14(
        author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    EXECUTE format('GRANT USAGE ON SCHEMA pgtrickle TO %I', author_role::text);
    EXECUTE format('GRANT SELECT ON ALL TABLES IN SCHEMA pgtrickle TO %I',
                   author_role::text);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.managed_status() TO %I, %I',
        operator_role::text, reader_role::text);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.key_codecs(), '
        'pgreact_api.explain(text,jsonb) TO %I, %I',
        operator_role::text, reader_role::text);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.managed_cycle() TO %I',
        worker_role::text);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.validate_rule(regclass,name[],name,name,name,name), '
        'pgreact_api.author_rule(text,regclass,name[],name,name), '
        'pgreact_api.author_rule(text,regclass,name[],name,name,name,name), '
        'pgreact_api.author_deadline_rule(text,regclass,name[],name,name,name), '
        'pgreact_api.author_deadline_rule(text,regclass,name[],name,name,name,name,name), '
        'pgreact_api.replace_rule(text,regclass,name[],name,name,name,name), '
        'pgreact_api.replace_deadline_rule(text,regclass,name[],name,name,name,name,name), '
        'pgreact_api.declare_derived_relation(text,regtype,name[],integer) TO %I',
        author_role::text);
END
$$;

REVOKE ALL ON ALL TABLES IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_internal FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pgreact_internal.derivation_program_graph(jsonb) TO PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_api FROM PUBLIC;

DO $$
DECLARE
    author_role regrole;
    operator_role regrole;
    worker_role regrole;
    reader_role regrole;
    advanced_reader_role regrole;
BEGIN
    SELECT role_oid::regrole INTO author_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'author';
    SELECT role_oid::regrole INTO operator_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'operator';
    SELECT role_oid::regrole INTO worker_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'worker';
    SELECT role_oid::regrole INTO reader_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'reader';
    SELECT role_oid::regrole INTO advanced_reader_role
    FROM pgreact_internal.advanced_readers;
    IF author_role IS NOT NULL AND operator_role IS NOT NULL
       AND worker_role IS NOT NULL AND reader_role IS NOT NULL
       AND advanced_reader_role IS NOT NULL THEN
        PERFORM pgreact_api.configure_roles(
            author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    END IF;
END
$$;

COMMENT ON EXTENSION pg_react IS
    'M15 PostgreSQL-managed runtime, typed semantic keys, and qualified public workflow';

-- M16 richer stratified aggregation. The declaration remains one aggregate
-- dependency per rule and adds one typed column expression.

ALTER TABLE pgreact_internal.derivation_program_aggregate_inputs
    ALTER COLUMN threshold DROP NOT NULL,
    ADD COLUMN aggregate_function text NOT NULL DEFAULT 'COUNT_STAR'
        CHECK (aggregate_function IN ('COUNT_STAR', 'COUNT', 'SUM', 'MIN', 'MAX')),
    ADD COLUMN value_expression name,
    ADD COLUMN expression_attnum smallint,
    ADD COLUMN input_type oid,
    ADD COLUMN input_type_name text,
    ADD COLUMN result_type oid NOT NULL DEFAULT 'bigint'::regtype,
    ADD COLUMN result_type_name text NOT NULL DEFAULT 'bigint',
    ADD COLUMN expression_collation oid NOT NULL DEFAULT 0,
    ADD COLUMN expression_collation_name text,
    ADD COLUMN public_relation_name text,
    ADD COLUMN typed_threshold text;

UPDATE pgreact_internal.derivation_program_aggregate_inputs
SET typed_threshold = threshold::text;

ALTER TABLE pgreact_internal.derivation_program_aggregate_inputs
    ALTER COLUMN typed_threshold SET NOT NULL;

ALTER TABLE pgreact_internal.aggregate_dependency_evidence
    ALTER COLUMN exact_count DROP NOT NULL,
    ALTER COLUMN threshold DROP NOT NULL,
    ADD COLUMN aggregate_function text NOT NULL DEFAULT 'COUNT_STAR'
        CHECK (aggregate_function IN ('COUNT_STAR', 'COUNT', 'SUM', 'MIN', 'MAX')),
    ADD COLUMN value_expression name,
    ADD COLUMN input_type oid,
    ADD COLUMN input_type_name text,
    ADD COLUMN result_type oid NOT NULL DEFAULT 'bigint'::regtype,
    ADD COLUMN result_type_name text NOT NULL DEFAULT 'bigint',
    ADD COLUMN expression_collation oid NOT NULL DEFAULT 0,
    ADD COLUMN expression_collation_name text,
    ADD COLUMN exact_value text,
    ADD COLUMN typed_threshold text,
    ADD COLUMN truth_result boolean,
    ADD COLUMN public_group_key jsonb,
    ADD COLUMN canonical_group_key bytea;

UPDATE pgreact_internal.aggregate_dependency_evidence
SET exact_value = exact_count::text,
    typed_threshold = threshold::text,
    truth_result = CASE comparison
        WHEN '=' THEN exact_count = threshold
        WHEN '<' THEN exact_count < threshold
        WHEN '<=' THEN exact_count <= threshold
        WHEN '>' THEN exact_count > threshold
        WHEN '>=' THEN exact_count >= threshold
    END;

ALTER TABLE pgreact_internal.aggregate_dependency_evidence
    ALTER COLUMN typed_threshold SET NOT NULL;

ALTER TABLE pgreact_internal.derivation_program_repair_diagnostics
    DROP CONSTRAINT derivation_program_repair_diagnostics_code_check;
ALTER TABLE pgreact_internal.derivation_program_repair_diagnostics
    ADD CHECK (code IN (
        'MISSING_SUPPORT', 'EXTRA_SUPPORT', 'STALE_SUPPORT',
        'MISSING_FACT', 'EXTRA_FACT', 'STALE_FACT',
        'CIRCULAR_ONLY', 'WRONG_FRONTIER', 'MISSING_EVIDENCE',
        'EXTRA_EVIDENCE', 'STALE_EVIDENCE', 'WRONG_STRATUM',
        'MISSING_AGGREGATE_EVIDENCE', 'EXTRA_AGGREGATE_EVIDENCE',
        'STALE_AGGREGATE_EVIDENCE', 'WRONG_COUNT', 'WRONG_AGGREGATE'
    ));

CREATE FUNCTION pgreact_internal.aggregate_result_type(
    aggregate_function text,
    input_type oid
)
RETURNS oid
LANGUAGE SQL
IMMUTABLE
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT CASE
        WHEN $1 IN ('COUNT_STAR', 'COUNT') THEN 'bigint'::regtype::oid
        WHEN $1 = 'SUM' AND $2 IN ('smallint'::regtype, 'integer'::regtype)
            THEN 'bigint'::regtype::oid
        WHEN $1 = 'SUM' AND $2 IN ('bigint'::regtype, 'numeric'::regtype)
            THEN 'numeric'::regtype::oid
        WHEN $1 = 'SUM' AND $2 = 'real'::regtype THEN 'real'::regtype::oid
        WHEN $1 = 'SUM' AND $2 = 'double precision'::regtype
            THEN 'double precision'::regtype::oid
        WHEN $1 IN ('MIN', 'MAX') AND $2 IN (
            'smallint'::regtype, 'integer'::regtype, 'bigint'::regtype,
            'numeric'::regtype, 'real'::regtype, 'double precision'::regtype,
            'text'::regtype, 'date'::regtype, 'timestamp'::regtype,
            'timestamp with time zone'::regtype, 'uuid'::regtype)
            THEN $2
        ELSE NULL
    END
$$;

ALTER FUNCTION pgreact.validate_derivation_program(jsonb)
    RENAME TO validate_derivation_program_m15;
ALTER FUNCTION pgreact.validate_derivation_program_m15(jsonb)
    SET SCHEMA pgreact_internal;

CREATE FUNCTION pgreact.validate_derivation_program(definition jsonb)
RETURNS TABLE(
    contract_version integer,
    code text,
    severity text,
    object_identity text,
    message text,
    hint text,
    details jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    rule_item record;
    aggregate_item jsonb;
    source_oid oid;
    identity_oid oid;
    source_identity text;
    expression_attribute record;
    function_name text;
    resolved_result_type oid;
    base_definition jsonb;
    diagnostic record;
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(CASE
            WHEN jsonb_typeof(definition -> 'rules') = 'array'
            THEN definition -> 'rules' ELSE '[]'::jsonb END) rule(value)
        WHERE rule.value ? 'aggregate_input'
          AND (rule.value -> 'aggregate_input') ? 'function'
    ) THEN
        RETURN QUERY SELECT *
        FROM pgreact_internal.validate_derivation_program_m15(definition);
        RETURN;
    END IF;

    FOR rule_item IN
        SELECT value, ordinal
        FROM jsonb_array_elements(CASE
            WHEN jsonb_typeof(definition -> 'rules') = 'array'
            THEN definition -> 'rules' ELSE '[]'::jsonb END)
        WITH ORDINALITY rules(value, ordinal)
    LOOP
        IF NOT rule_item.value ? 'aggregate_input' THEN CONTINUE; END IF;
        aggregate_item := rule_item.value -> 'aggregate_input';
        IF NOT aggregate_item ? 'function' THEN CONTINUE; END IF;
        IF jsonb_typeof(aggregate_item) IS DISTINCT FROM 'object'
           OR NOT aggregate_item ?& ARRAY[
               'relation', 'key', 'function', 'expression', 'comparison', 'threshold']
           OR (SELECT count(*) FROM jsonb_object_keys(aggregate_item)) NOT IN (6, 7)
           OR ((SELECT count(*) FROM jsonb_object_keys(aggregate_item)) = 7
               AND NOT aggregate_item ? 'public_relation') THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_INVALID', 'ERROR',
                COALESCE(rule_item.value ->> 'name', rule_item.ordinal::text),
                'typed aggregate_input requires exactly relation, key, function, expression, comparison, and threshold',
                'Declare one COUNT, SUM, MIN, or MAX over one named input column.',
                '{}'::jsonb;
            RETURN;
        END IF;
        function_name := aggregate_item ->> 'function';
        IF function_name NOT IN ('COUNT', 'SUM', 'MIN', 'MAX') THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_FUNCTION_UNSUPPORTED', 'ERROR',
                rule_item.value ->> 'name',
                'aggregate function is outside the M16 allow-list',
                'Use COUNT, SUM, MIN, or MAX; COUNT(*) keeps the inherited four-field declaration.',
                jsonb_build_object('function', function_name);
            RETURN;
        END IF;
        IF jsonb_typeof(aggregate_item -> 'expression') IS DISTINCT FROM 'string'
           OR aggregate_item ->> 'expression' = '' THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_EXPRESSION_UNSUPPORTED', 'ERROR',
                rule_item.value ->> 'name',
                'aggregate value expression must be one immutable named column',
                'Project casts or immutable calculations into the input view, then name that output column.',
                jsonb_build_object('expression', aggregate_item -> 'expression');
            RETURN;
        END IF;
        source_identity := COALESCE(
            aggregate_item ->> 'public_relation', aggregate_item ->> 'relation');
        IF strpos(source_identity, '.') = 0 THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_IDENTITY_AMBIGUOUS', 'ERROR',
                rule_item.value ->> 'name',
                'typed aggregate input relation must be schema-qualified',
                'Use a schema-qualified relation so search_path cannot retarget the dependency.',
                jsonb_build_object('relation', source_identity);
            RETURN;
        END IF;
        identity_oid := to_regclass(source_identity);
        source_oid := to_regclass(aggregate_item ->> 'relation');
        IF source_oid IS NULL OR identity_oid IS NULL THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_UNRESOLVED', 'ERROR',
                source_identity,
                'aggregate input does not resolve to a finite table or view',
                'Name one authoritative or active lower-stratum relation.',
                jsonb_build_object('rule', rule_item.value ->> 'name');
            RETURN;
        END IF;
        IF EXISTS (
            WITH RECURSIVE relations(relid) AS (
                SELECT identity_oid
                UNION
                SELECT dependency.refobjid
                FROM relations parent
                JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
                JOIN pg_depend dependency
                  ON dependency.classid = 'pg_rewrite'::regclass
                 AND dependency.objid = rewrite.oid
                 AND dependency.refclassid = 'pg_class'::regclass
                JOIN pg_class relation ON relation.oid = dependency.refobjid
                WHERE relation.relkind IN ('r', 'p', 'v', 'm')
            )
            SELECT 1 FROM relations
            JOIN pg_class relation ON relation.oid = relations.relid
            WHERE relation.relrowsecurity
        ) THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_RLS_UNSUPPORTED', 'ERROR',
                rule_item.value ->> 'name',
                'aggregate input closure contains a row-security relation',
                'Use an unprotected authoritative projection owned by the program author.',
                jsonb_build_object('relation', source_identity);
            RETURN;
        END IF;
        IF EXISTS (
            WITH RECURSIVE relations(relid) AS (
                SELECT identity_oid
                UNION
                SELECT dependency.refobjid
                FROM relations parent
                JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
                JOIN pg_depend dependency
                  ON dependency.classid = 'pg_rewrite'::regclass
                 AND dependency.objid = rewrite.oid
                 AND dependency.refclassid = 'pg_class'::regclass
                JOIN pg_class relation ON relation.oid = dependency.refobjid
                WHERE relation.relkind IN ('v', 'm')
            ), trees AS (
                SELECT pgreact_internal.relation_query_tree(relid) AS tree
                FROM relations
            ), procedure_ids(oid) AS (
                SELECT match[1]::oid
                FROM trees
                CROSS JOIN LATERAL regexp_matches(tree, E':funcid ([0-9]+)', 'g') match
            ), operator_ids(oid) AS (
                SELECT match[1]::oid
                FROM trees
                CROSS JOIN LATERAL regexp_matches(tree, E':opno ([0-9]+)', 'g') match
            )
            SELECT 1 FROM trees
            WHERE tree ~ E'\\{SQLVALUEFUNCTION'
               OR tree ~ E':has(Aggs|WindowFuncs|TargetSRFs|SubLinks) true'
            UNION ALL
            SELECT 1
            FROM procedure_ids
            JOIN pg_proc procedure USING (oid)
            JOIN pg_namespace namespace ON namespace.oid = procedure.pronamespace
            WHERE (procedure.provolatile <> 'i' OR procedure.proretset
               OR namespace.nspname <> 'pg_catalog')
              AND NOT (
                  procedure.oid =
                      'pg_catalog.jsonb_populate_record(anyelement,jsonb)'::regprocedure
                  AND EXISTS (
                      SELECT 1
                      FROM pgreact_internal.keyed_derived_relations derived
                      JOIN pgreact_internal.derived_relation_versions version
                        USING (relation_version_id)
                      WHERE derived.public_name = source_identity
                        AND version.state = 'ACTIVE'))
            UNION ALL
            SELECT 1
            FROM operator_ids
            JOIN pg_operator operator USING (oid)
            JOIN pg_namespace namespace ON namespace.oid = operator.oprnamespace
            JOIN pg_proc procedure ON procedure.oid = operator.oprcode
            WHERE procedure.provolatile <> 'i' OR procedure.proretset
               OR namespace.nspname <> 'pg_catalog'
        ) THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_VOLATILE', 'ERROR',
                rule_item.value ->> 'name',
                'aggregate input closure must use only immutable PostgreSQL expressions',
                'Project values through immutable pg_catalog functions and operators only.',
                jsonb_build_object('relation', source_identity);
            RETURN;
        END IF;
        SELECT attribute.attnum, attribute.atttypid, attribute.attcollation,
               collation_row.collname, collation_row.collisdeterministic,
               database_row.datcollate
        INTO expression_attribute
        FROM pg_attribute attribute
        LEFT JOIN pg_collation collation_row ON collation_row.oid = attribute.attcollation
        CROSS JOIN pg_database database_row
        WHERE attribute.attrelid = source_oid
          AND attribute.attname = (aggregate_item ->> 'expression')::name
          AND attribute.attnum > 0 AND NOT attribute.attisdropped
          AND database_row.datname = current_database();
        IF NOT FOUND THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_EXPRESSION_UNRESOLVED', 'ERROR',
                rule_item.value ->> 'name',
                'aggregate value expression column does not exist',
                'Project one supported typed column from the aggregate input relation.',
                jsonb_build_object('relation', source_identity,
                                   'expression', aggregate_item ->> 'expression');
            RETURN;
        END IF;
        resolved_result_type := pgreact_internal.aggregate_result_type(
            function_name, expression_attribute.atttypid);
        IF resolved_result_type IS NULL THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_TYPE_UNSUPPORTED', 'ERROR',
                rule_item.value ->> 'name',
                'aggregate input type is outside the M16 allow-list',
                'Use COUNT on a built-in scalar, SUM on a supported numeric, or MIN/MAX on a supported ordered type.',
                jsonb_build_object('function', function_name,
                                   'input_type', expression_attribute.atttypid::regtype::text);
            RETURN;
        END IF;
        IF function_name = 'COUNT'
           AND expression_attribute.atttypid NOT IN (
               'boolean'::regtype, 'smallint'::regtype, 'integer'::regtype,
               'bigint'::regtype, 'numeric'::regtype, 'real'::regtype,
               'double precision'::regtype, 'text'::regtype, 'date'::regtype,
               'timestamp'::regtype, 'timestamp with time zone'::regtype,
               'uuid'::regtype) THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_TYPE_UNSUPPORTED', 'ERROR',
                rule_item.value ->> 'name',
                'aggregate input type is outside the M16 allow-list',
                'Project one supported built-in scalar column.',
                jsonb_build_object('function', function_name,
                                   'input_type', expression_attribute.atttypid::regtype::text);
            RETURN;
        END IF;
        IF expression_attribute.atttypid = 'text'::regtype
           AND (NOT expression_attribute.collisdeterministic
                OR (expression_attribute.collname <> 'C'
                    AND NOT (expression_attribute.collname = 'default'
                             AND expression_attribute.datcollate IN ('C', 'C.UTF-8', 'C.utf8')))) THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_COLLATION_UNSUPPORTED', 'ERROR',
                rule_item.value ->> 'name',
                'text aggregation requires deterministic C collation',
                'Project the value column with COLLATE "C".',
                jsonb_build_object('collation', expression_attribute.collname);
            RETURN;
        END IF;
        IF NOT has_table_privilege(session_user, identity_oid, 'SELECT')
           OR NOT has_column_privilege(
               session_user, identity_oid, aggregate_item ->> 'expression', 'SELECT') THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_UNAUTHORIZED', 'ERROR',
                rule_item.value ->> 'name',
                'program owner cannot read the aggregate input expression',
                'Grant SELECT on the relation and value column before validation.',
                jsonb_build_object('relation', source_identity,
                                   'expression', aggregate_item ->> 'expression');
            RETURN;
        END IF;
        IF aggregate_item ->> 'comparison' NOT IN ('=', '<', '<=', '>', '>=')
           OR jsonb_typeof(aggregate_item -> 'threshold') NOT IN ('number', 'string')
           OR NOT COALESCE(pg_input_is_valid(
               aggregate_item ->> 'threshold', resolved_result_type::regtype::text), false) THEN
            RETURN QUERY SELECT 5, 'PROGRAM_AGGREGATE_THRESHOLD_INVALID', 'ERROR',
                rule_item.value ->> 'name',
                'aggregate threshold cannot be cast to the exact result type with a supported comparison',
                'Use =, <, <=, >, or >= and a PostgreSQL literal for the published result type.',
                jsonb_build_object('comparison', aggregate_item ->> 'comparison',
                                   'threshold', aggregate_item -> 'threshold',
                                   'result_type', resolved_result_type::regtype::text);
            RETURN;
        END IF;
    END LOOP;

    base_definition := jsonb_set(definition, '{rules}', COALESCE((
        SELECT jsonb_agg(CASE
            WHEN value ? 'aggregate_input' AND (value -> 'aggregate_input') ? 'function'
            THEN jsonb_set(value, '{aggregate_input}',
                jsonb_build_object(
                    'relation', value #>> '{aggregate_input,relation}',
                    'key', value #>> '{aggregate_input,key}',
                    'comparison', value #>> '{aggregate_input,comparison}',
                    'threshold', 0))
            ELSE value END ORDER BY ordinal)
        FROM jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY rules(value, ordinal)
    ), '[]'::jsonb), true);
    FOR diagnostic IN
        SELECT *
        FROM pgreact_internal.validate_derivation_program_m15(base_definition) legacy
        WHERE legacy.code <> 'OK'
    LOOP
        RETURN QUERY SELECT 5, diagnostic.code, diagnostic.severity,
            diagnostic.object_identity, diagnostic.message, diagnostic.hint,
            diagnostic.details;
        RETURN;
    END LOOP;
    RETURN QUERY SELECT 5, 'OK', 'INFO', definition ->> 'name',
        'typed stratified aggregate derivation program is valid',
        'Preview and deploy the program.',
        jsonb_build_object('version', (definition ->> 'version')::integer,
                           'rules', jsonb_array_length(definition -> 'rules'));
END
$$;

CREATE OR REPLACE FUNCTION pgreact_internal.normalize_program(definition jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    normalized jsonb := pgreact_api.infer_program(definition);
    rule_item record;
    dependency record;
    derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    dependency_derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    wrapper regclass;
    source regclass;
BEGIN
    FOR rule_item IN
        SELECT value, ordinal
        FROM jsonb_array_elements(definition -> 'rules')
             WITH ORDINALITY rules(value, ordinal)
        ORDER BY ordinal
    LOOP
        SELECT * INTO derived
        FROM pgreact_internal.keyed_derived_relations
        WHERE public_name = rule_item.value ->> 'target';
        IF NOT FOUND THEN CONTINUE; END IF;
        source := to_regclass(rule_item.value ->> 'definition');
        IF source IS NULL THEN
            RAISE EXCEPTION 'M15_DERIVATION_SOURCE: definition view % does not exist',
                rule_item.value ->> 'definition';
        END IF;
        SELECT * INTO dependency_derived
        FROM pgreact_internal.keyed_derived_relations
        WHERE public_name = rule_item.value ->> 'definition';
        IF FOUND THEN
            wrapper := dependency_derived.internal_name::regclass;
        ELSE
            wrapper := pgreact_internal.create_key_wrapper(source, derived.key_columns);
        END IF;
        normalized := jsonb_set(normalized,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'definition'],
            to_jsonb(wrapper::text));
        normalized := jsonb_set(normalized,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'key'],
            to_jsonb('__pgreact_key'::text));
        normalized := jsonb_set(normalized,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'target'],
            to_jsonb(derived.internal_name));
        FOR dependency IN
            SELECT dependency_kind, dependency_value, dependency_ordinal
            FROM (
                SELECT 'inputs'::text, value, ordinal
                FROM jsonb_array_elements(COALESCE(normalized #> ARRAY[
                    'rules', (rule_item.ordinal - 1)::text, 'inputs'], '[]'::jsonb))
                     WITH ORDINALITY input(value, ordinal)
                UNION ALL
                SELECT 'negative_inputs'::text, value, ordinal
                FROM jsonb_array_elements(COALESCE(rule_item.value -> 'negative_inputs', '[]'::jsonb))
                     WITH ORDINALITY negative_input(value, ordinal)
            ) dependencies(dependency_kind, dependency_value, dependency_ordinal)
        LOOP
            source := to_regclass(dependency.dependency_value ->> 'relation');
            IF source IS NULL THEN
                RAISE EXCEPTION 'M15_DERIVATION_INPUT: relation % does not exist',
                    dependency.dependency_value ->> 'relation';
            END IF;
            SELECT * INTO dependency_derived
            FROM pgreact_internal.keyed_derived_relations
            WHERE public_name = dependency.dependency_value ->> 'relation';
            IF FOUND THEN
                wrapper := dependency_derived.internal_name::regclass;
            ELSE
                wrapper := pgreact_internal.create_key_wrapper(source, derived.key_columns);
            END IF;
            normalized := jsonb_set(normalized, ARRAY[
                'rules', (rule_item.ordinal - 1)::text, dependency.dependency_kind,
                (dependency.dependency_ordinal - 1)::text, 'relation'], to_jsonb(wrapper::text));
            normalized := jsonb_set(normalized, ARRAY[
                'rules', (rule_item.ordinal - 1)::text, dependency.dependency_kind,
                (dependency.dependency_ordinal - 1)::text, 'key'], to_jsonb('__pgreact_key'::text));
        END LOOP;
        IF rule_item.value -> 'aggregate_input' IS NOT NULL THEN
            source := to_regclass(rule_item.value #>> '{aggregate_input,relation}');
            IF source IS NULL THEN
                RAISE EXCEPTION 'M15_DERIVATION_INPUT: relation % does not exist',
                    rule_item.value #>> '{aggregate_input,relation}';
            END IF;
            SELECT * INTO dependency_derived
            FROM pgreact_internal.keyed_derived_relations
            WHERE public_name = rule_item.value #>> '{aggregate_input,relation}';
            IF FOUND THEN
                wrapper := dependency_derived.internal_name::regclass;
            ELSE
                wrapper := pgreact_internal.create_key_wrapper(source, derived.key_columns);
            END IF;
            IF (rule_item.value -> 'aggregate_input') ? 'function' THEN
                normalized := jsonb_set(normalized,
                    ARRAY['rules', (rule_item.ordinal - 1)::text,
                          'aggregate_input', 'public_relation'],
                    to_jsonb(rule_item.value #>> '{aggregate_input,relation}'));
            END IF;
            normalized := jsonb_set(normalized,
                ARRAY['rules', (rule_item.ordinal - 1)::text, 'aggregate_input', 'relation'],
                to_jsonb(wrapper::text));
            normalized := jsonb_set(normalized,
                ARRAY['rules', (rule_item.ordinal - 1)::text, 'aggregate_input', 'key'],
                to_jsonb('__pgreact_key'::text));
        END IF;
    END LOOP;
    RETURN normalized;
END
$$;

CREATE OR REPLACE FUNCTION pgreact_api.validate_program(definition jsonb)
RETURNS TABLE(
    contract_version integer, code text, severity text,
    object_identity text, message text, hint text, details jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE normalized jsonb; diagnostic record;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(definition -> 'rules') rule
        JOIN pgreact_internal.keyed_derived_relations relation_spec
          ON relation_spec.public_name = rule ->> 'target') THEN
        RETURN QUERY SELECT * FROM pgreact_internal.validate_program_m14(definition);
        RETURN;
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(definition -> 'rules') rule
        WHERE (rule -> 'aggregate_input') ? 'function') THEN
        SELECT * INTO diagnostic
        FROM pgreact.validate_derivation_program(definition) result
        WHERE result.severity = 'ERROR'
          AND result.code IN (
              'PROGRAM_AGGREGATE_INVALID',
              'PROGRAM_AGGREGATE_FUNCTION_UNSUPPORTED',
              'PROGRAM_AGGREGATE_EXPRESSION_UNSUPPORTED',
              'PROGRAM_AGGREGATE_IDENTITY_AMBIGUOUS',
              'PROGRAM_AGGREGATE_UNRESOLVED',
              'PROGRAM_AGGREGATE_RLS_UNSUPPORTED',
              'PROGRAM_AGGREGATE_VOLATILE',
              'PROGRAM_AGGREGATE_EXPRESSION_UNRESOLVED',
              'PROGRAM_AGGREGATE_TYPE_UNSUPPORTED',
              'PROGRAM_AGGREGATE_COLLATION_UNSUPPORTED',
              'PROGRAM_AGGREGATE_UNAUTHORIZED',
              'PROGRAM_AGGREGATE_THRESHOLD_INVALID')
        ORDER BY result.code, result.object_identity LIMIT 1;
        IF FOUND THEN
            RETURN QUERY SELECT 5, diagnostic.code, diagnostic.severity,
                diagnostic.object_identity, diagnostic.message, diagnostic.hint,
                diagnostic.details;
            RETURN;
        END IF;
    END IF;
    normalized := pgreact_internal.normalize_program(definition);
    RETURN QUERY
    SELECT 5, result.code, result.severity, result.object_identity,
           result.message, result.hint,
           result.details || jsonb_build_object('normalized_definition', normalized)
    FROM pgreact.validate_derivation_program(normalized) result;
END
$$;

CREATE FUNCTION pgreact_internal.program_plan_digest(normalized jsonb)
RETURNS text
LANGUAGE SQL
STABLE
STRICT
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    WITH relations(relation_name) AS (
        SELECT rule ->> 'definition'
        FROM jsonb_array_elements($1 -> 'rules') rule
        UNION
        SELECT input ->> 'relation'
        FROM jsonb_array_elements($1 -> 'rules') rule
        CROSS JOIN LATERAL jsonb_array_elements(COALESCE(rule -> 'inputs', '[]'::jsonb)) input
        UNION
        SELECT input ->> 'relation'
        FROM jsonb_array_elements($1 -> 'rules') rule
        CROSS JOIN LATERAL jsonb_array_elements(COALESCE(rule -> 'negative_inputs', '[]'::jsonb)) input
        UNION
        SELECT rule #>> '{aggregate_input,relation}'
        FROM jsonb_array_elements($1 -> 'rules') rule
        WHERE rule ? 'aggregate_input'
    ), fingerprints AS (
        SELECT relation_name,
               encode(pgreact_internal.source_closure_digest(to_regclass(relation_name)), 'hex')
                   AS definition_digest,
               encode(pgreact_internal.source_row_signature(to_regclass(relation_name)), 'hex')
                   AS row_signature
        FROM relations
    )
    SELECT encode(sha256(convert_to(
        $1::text || ':' || session_user || ':' || COALESCE(string_agg(
            relation_name || ':' || definition_digest || ':' || row_signature,
            E'\n' ORDER BY relation_name), ''), 'UTF8')), 'hex')
    FROM fingerprints
$$;

CREATE OR REPLACE FUNCTION pgreact_api.preview_program(definition jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    normalized jsonb;
    inferred jsonb;
    diagnostic record;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(definition -> 'rules') rule
        JOIN pgreact_internal.keyed_derived_relations relation_spec
          ON relation_spec.public_name = rule ->> 'target') THEN
        RETURN pgreact_internal.preview_program_m14(definition);
    END IF;
    SELECT * INTO diagnostic FROM pgreact_api.validate_program(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M16_PROGRAM_INVALID: % for %', diagnostic.code, diagnostic.object_identity
            USING HINT = diagnostic.hint;
    END IF;
    normalized := pgreact_internal.normalize_program(definition);
    inferred := pgreact_api.infer_program(definition);
    RETURN jsonb_build_object(
        'contract_version', 5, 'program', inferred,
        'plan_digest', pgreact_internal.program_plan_digest(normalized));
END
$$;

CREATE OR REPLACE FUNCTION pgreact_api.deploy_program(
    definition jsonb,
    expected_plan_digest text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    normalized jsonb;
    actual_plan_digest text;
    deployed uuid;
    rule_item record;
    derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    version_id uuid;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(definition -> 'rules') rule
        JOIN pgreact_internal.keyed_derived_relations relation_spec
          ON relation_spec.public_name = rule ->> 'target') THEN
        RETURN pgreact_internal.deploy_program_m14(definition, expected_plan_digest);
    END IF;
    SELECT * INTO rule_item FROM pgreact_api.validate_program(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M16_PROGRAM_INVALID: % for %', rule_item.code, rule_item.object_identity
            USING HINT = rule_item.hint;
    END IF;
    normalized := pgreact_internal.normalize_program(definition);
    actual_plan_digest := pgreact_internal.program_plan_digest(normalized);
    IF expected_plan_digest IS NOT NULL AND expected_plan_digest <> actual_plan_digest THEN
        RAISE EXCEPTION 'M16_PROGRAM_PREVIEW_STALE'
            USING HINT = 'Preview the program again after DDL or deployment changes.';
    END IF;
    deployed := pgreact_internal.deploy_derivation_program(normalized, NULL);
    FOR rule_item IN
        SELECT original.value, normalized_rule.value AS normalized_value
        FROM jsonb_array_elements(definition -> 'rules') WITH ORDINALITY original(value, ordinal)
        JOIN jsonb_array_elements(normalized -> 'rules') WITH ORDINALITY normalized_rule(value, ordinal)
          USING (ordinal)
    LOOP
        SELECT * INTO derived
        FROM pgreact_internal.keyed_derived_relations
        WHERE public_name = rule_item.value ->> 'target';
        IF NOT FOUND THEN CONTINUE; END IF;
        SELECT version.rule_version_id INTO STRICT version_id
        FROM pgreact_internal.rules rule
        JOIN pgreact_internal.rule_versions version USING (rule_id)
        WHERE rule.rule_name = rule_item.value ->> 'name' AND version.state = 'ACTIVE';
        INSERT INTO pgreact_internal.keyed_rule_versions VALUES (
            version_id, to_regclass(rule_item.value ->> 'definition'),
            to_regclass(rule_item.normalized_value ->> 'definition'),
            derived.key_columns, derived.key_types, derived.key_collations)
        ON CONFLICT (rule_version_id) DO UPDATE
        SET public_condition = EXCLUDED.public_condition,
            wrapper_condition = EXCLUDED.wrapper_condition,
            key_columns = EXCLUDED.key_columns,
            key_types = EXCLUDED.key_types,
            key_collations = EXCLUDED.key_collations;
    END LOOP;
    RETURN deployed;
END
$$;

CREATE OR REPLACE FUNCTION pgreact_internal.derivation_component_fingerprint(
    target_program uuid,
    target_component uuid
)
RETURNS bytea
LANGUAGE SQL
STABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT sha256(convert_to(
        COALESCE((
            SELECT string_agg(format('%s@%s:%s@%s:%s:%s:%s:%s',
                                     rule.rule_name, rule_version.version,
                                     relation.relation_name, relation_version.version,
                                     support.semantic_key, support.fact::text,
                                     support.source_binding::text,
                                     COALESCE((
                                         SELECT string_agg(format('%s@%s:%s',
                                             input_relation.relation_name, input_version.version,
                                             input.semantic_key), ',' ORDER BY input.input_order)
                                         FROM pgreact_internal.derived_support_inputs input
                                         JOIN pgreact_internal.derived_relation_versions input_version
                                           ON input_version.relation_version_id = input.relation_version_id
                                         JOIN pgreact_internal.derived_relations input_relation USING (relation_id)
                                         WHERE input.support_id = support.support_id
                                     ), '')),
                E'\n' ORDER BY rule.rule_name, rule_version.version, relation.relation_name,
                relation_version.version, support.semantic_key, support.fact::text,
                support.source_binding::text)
            FROM pgreact_internal.derived_supports support
            JOIN pgreact_internal.derivation_program_rules member
              ON member.program_version_id = $1 AND member.component_id = $2
             AND member.rule_version_id = support.rule_version_id
            JOIN pgreact_internal.derivation_rule_versions rule_version
              ON rule_version.rule_version_id = support.rule_version_id
            JOIN pgreact_internal.rules rule ON rule.rule_id = rule_version.rule_id
            JOIN pgreact_internal.derived_relation_versions relation_version
              ON relation_version.relation_version_id = support.relation_version_id
            JOIN pgreact_internal.derived_relations relation USING (relation_id)
            WHERE support.active
        ), '') || E'\n--facts--\n' || COALESCE((
            SELECT string_agg(format('%s@%s:%s:%s', relation.relation_name,
                relation_version.version, fact.semantic_key, fact.fact::text), E'\n'
                ORDER BY relation.relation_name, relation_version.version, fact.semantic_key)
            FROM pgreact_internal.derived_facts fact
            JOIN pgreact_internal.derivation_program_components component
              ON component.program_version_id = $1 AND component.component_id = $2
             AND fact.relation_version_id = ANY (component.target_relations)
            JOIN pgreact_internal.derived_relation_versions relation_version
              ON relation_version.relation_version_id = fact.relation_version_id
            JOIN pgreact_internal.derived_relations relation USING (relation_id)
        ), '') || E'\n--aggregates--\n' || COALESCE((
            SELECT string_agg(CASE WHEN evidence.aggregate_function = 'COUNT_STAR'
                THEN format('%s:%s:%s:%s:%s:%s', evidence.rule_version_id,
                    evidence.semantic_key, evidence.exact_count, evidence.comparison,
                    evidence.threshold, evidence.active)
                ELSE format('%s:%s:%s:%s:%s:%s:%s:%s:%s:%s',
                    evidence.rule_version_id, evidence.semantic_key,
                    encode(evidence.canonical_group_key, 'hex'),
                    evidence.aggregate_function, evidence.value_expression,
                    evidence.result_type_name, evidence.exact_value,
                    evidence.comparison, evidence.typed_threshold, evidence.truth_result)
                END, E'\n'
                ORDER BY evidence.rule_version_id, evidence.semantic_key)
            FROM pgreact_internal.aggregate_dependency_evidence evidence
            JOIN pgreact_internal.derivation_program_rules rule
              ON rule.program_version_id = $1 AND rule.component_id = $2
             AND rule.rule_version_id = evidence.rule_version_id
        ), ''), 'UTF8'))
$$;

CREATE OR REPLACE FUNCTION pgreact.reconcile_derivation_program(target_program uuid)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    activation_row record;
    aggregate_evidence record;
    actual_value text;
    actual_truth boolean;
    actual_threshold text;
    expected_evidence_id uuid;
    expected_evidence_ids uuid[] := '{}'::uuid[];
    expected_metadata jsonb;
    actual_metadata jsonb;
    reconciliation_row_id bigint;
    next_diagnostic_order integer;
    aggregate_defects jsonb := '[]'::jsonb;
    aggregate_defect jsonb;
BEGIN
    PERFORM pgreact_internal.assert_program_owner(target_program);
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    PERFORM set_config('TimeZone', 'UTC', true);
    PERFORM set_config('DateStyle', 'ISO, YMD', true);
    PERFORM set_config('extra_float_digits', '3', true);
    FOR activation_row IN
        SELECT activation.rule_version_id, activation.activation_id,
               activation.semantic_key,
               activation.current_bindings -> '__pgreact_public_key' AS public_group_key,
               (activation.current_bindings ->> '__pgreact_canonical')::bytea
                   AS canonical_group_key,
               input.relation_oid, input.relation_name, input.key_column,
               input.comparison, input.typed_threshold,
               input.aggregate_function, input.value_expression,
               input.input_type, input.input_type_name,
               input.result_type, input.result_type_name,
               input.expression_collation, input.expression_collation_name,
               COALESCE(source_component.stratum, 0) AS source_stratum,
               target_component.stratum AS target_stratum,
               version.frontier,
               support.support_id
        FROM pgreact_internal.activation_state activation
        JOIN pgreact_internal.derivation_program_rules rule
          ON rule.program_version_id = target_program
         AND rule.rule_version_id = activation.rule_version_id
        JOIN pgreact_internal.derivation_program_aggregate_inputs input
          ON input.program_version_id = target_program
         AND input.rule_version_id = activation.rule_version_id
        JOIN pgreact_internal.derivation_program_versions version
          ON version.program_version_id = target_program
        JOIN pgreact_internal.derivation_program_components target_component
          ON target_component.program_version_id = target_program
         AND target_component.component_id = rule.component_id
        LEFT JOIN pgreact_internal.derived_relation_versions source_version
          ON source_version.public_view_oid = input.relation_oid
         AND source_version.state = 'ACTIVE'
        LEFT JOIN pgreact_internal.derivation_program_components source_component
          ON source_component.program_version_id = target_program
         AND source_version.relation_version_id = ANY (source_component.target_relations)
        LEFT JOIN pgreact_internal.derived_supports support
          ON support.rule_version_id = activation.rule_version_id
         AND support.activation_id = activation.activation_id AND support.active
        WHERE activation.active
        ORDER BY rule.rule_order, activation.activation_id
    LOOP
        IF activation_row.aggregate_function = 'COUNT_STAR' THEN
            EXECUTE format(
                'SELECT count(*)::text, count(*) OPERATOR(pg_catalog.%s) $2::bigint, '
                '$2::bigint::text FROM %s WHERE %I = $1', activation_row.comparison,
                activation_row.relation_oid::regclass, activation_row.key_column)
            INTO actual_value, actual_truth, actual_threshold
            USING activation_row.semantic_key, activation_row.typed_threshold;
        ELSIF activation_row.aggregate_function IN ('MIN', 'MAX')
              AND activation_row.input_type = 'uuid'::regtype THEN
            EXECUTE format(
                'SELECT aggregate_value::text, '
                'aggregate_value OPERATOR(pg_catalog.%s) $2::uuid, $2::uuid::text '
                'FROM (SELECT (SELECT %I FROM %s '
                'WHERE %I = $1 AND __pgreact_canonical = $3 AND %I IS NOT NULL '
                'ORDER BY %I %s LIMIT 1) AS aggregate_value) aggregate_result',
                activation_row.comparison, activation_row.value_expression,
                activation_row.relation_oid::regclass, activation_row.key_column,
                activation_row.value_expression, activation_row.value_expression,
                CASE activation_row.aggregate_function
                    WHEN 'MIN' THEN 'ASC' ELSE 'DESC' END)
            INTO actual_value, actual_truth, actual_threshold
            USING activation_row.semantic_key, activation_row.typed_threshold,
                  activation_row.canonical_group_key;
        ELSE
            EXECUTE format(
                'SELECT aggregate_value::text, '
                'aggregate_value OPERATOR(pg_catalog.%s) $2::%s, $2::%s::text '
                'FROM (SELECT pg_catalog.%s(%I) AS aggregate_value FROM %s '
                'WHERE %I = $1 AND __pgreact_canonical = $3) aggregate_result',
                activation_row.comparison, activation_row.result_type::regtype,
                activation_row.result_type::regtype, activation_row.aggregate_function,
                activation_row.value_expression, activation_row.relation_oid::regclass,
                activation_row.key_column)
            INTO actual_value, actual_truth, actual_threshold
            USING activation_row.semantic_key, activation_row.typed_threshold,
                  activation_row.canonical_group_key;
        END IF;
        expected_evidence_id := pgreact_internal.activation_uuid(sha256(convert_to(
            target_program::text || ':' || activation_row.rule_version_id::text || ':' ||
            CASE WHEN activation_row.aggregate_function = 'COUNT_STAR'
                 THEN activation_row.semantic_key::text
                 ELSE encode(activation_row.canonical_group_key, 'hex') END, 'UTF8')));
        expected_evidence_ids := expected_evidence_ids || expected_evidence_id;
        expected_metadata := jsonb_build_object(
            'support_id', activation_row.support_id,
            'semantic_key', activation_row.semantic_key,
            'relation_oid', activation_row.relation_oid,
            'relation_name', activation_row.relation_name,
            'exact_count', CASE WHEN activation_row.aggregate_function IN ('COUNT_STAR', 'COUNT')
                                THEN actual_value::bigint END,
            'comparison', activation_row.comparison,
            'threshold', CASE WHEN activation_row.aggregate_function = 'COUNT_STAR'
                              THEN actual_threshold::bigint END,
            'source_stratum', activation_row.source_stratum,
            'target_stratum', activation_row.target_stratum,
            'function', activation_row.aggregate_function,
            'expression', activation_row.value_expression,
            'input_type', activation_row.input_type,
            'input_type_name', activation_row.input_type_name,
            'result_type', activation_row.result_type,
            'result_type_name', activation_row.result_type_name,
            'collation', activation_row.expression_collation,
            'collation_name', activation_row.expression_collation_name,
            'value', actual_value, 'typed_threshold', actual_threshold,
            'truth', actual_truth,
            'public_group_key', activation_row.public_group_key,
            'canonical_group_key', encode(activation_row.canonical_group_key, 'hex'));
        SELECT * INTO aggregate_evidence
        FROM pgreact_internal.aggregate_dependency_evidence evidence
        WHERE evidence.evidence_id = expected_evidence_id AND evidence.active;
        IF NOT FOUND THEN
            aggregate_defects := aggregate_defects || jsonb_build_array(jsonb_build_object(
                'code', 'MISSING_EVIDENCE', 'evidence_id', expected_evidence_id,
                'expected', expected_metadata, 'actual', NULL));
            CONTINUE;
        END IF;
        actual_metadata := jsonb_build_object(
            'support_id', aggregate_evidence.support_id,
            'semantic_key', aggregate_evidence.semantic_key,
            'relation_oid', aggregate_evidence.relation_oid,
            'relation_name', aggregate_evidence.relation_name,
            'exact_count', aggregate_evidence.exact_count,
            'comparison', aggregate_evidence.comparison,
            'threshold', aggregate_evidence.threshold,
            'source_stratum', aggregate_evidence.source_stratum,
            'target_stratum', aggregate_evidence.target_stratum,
            'function', aggregate_evidence.aggregate_function,
            'expression', aggregate_evidence.value_expression,
            'input_type', aggregate_evidence.input_type,
            'input_type_name', aggregate_evidence.input_type_name,
            'result_type', aggregate_evidence.result_type,
            'result_type_name', aggregate_evidence.result_type_name,
            'collation', aggregate_evidence.expression_collation,
            'collation_name', aggregate_evidence.expression_collation_name,
            'value', aggregate_evidence.exact_value,
            'typed_threshold', aggregate_evidence.typed_threshold,
            'truth', aggregate_evidence.truth_result,
            'public_group_key', aggregate_evidence.public_group_key,
            'canonical_group_key', encode(aggregate_evidence.canonical_group_key, 'hex'));
        IF actual_metadata IS DISTINCT FROM expected_metadata THEN
            aggregate_defects := aggregate_defects || jsonb_build_array(jsonb_build_object(
                'code', CASE WHEN activation_row.aggregate_function = 'COUNT_STAR'
                             THEN 'WRONG_COUNT' ELSE 'WRONG_AGGREGATE' END,
                'evidence_id', expected_evidence_id,
                'expected', expected_metadata, 'actual', actual_metadata));
        END IF;
        IF aggregate_evidence.lower_frontier > activation_row.frontier THEN
            aggregate_defects := aggregate_defects || jsonb_build_array(jsonb_build_object(
                'code', 'WRONG_FRONTIER', 'evidence_id', expected_evidence_id,
                'expected', jsonb_build_object('maximum', activation_row.frontier),
                'actual', jsonb_build_object(
                    'lower_frontier', aggregate_evidence.lower_frontier)));
        END IF;
    END LOOP;
    FOR aggregate_evidence IN
        SELECT * FROM pgreact_internal.aggregate_dependency_evidence evidence
        WHERE evidence.program_version_id = target_program AND evidence.active
          AND evidence.evidence_id <> ALL (expected_evidence_ids)
        ORDER BY evidence.evidence_id
    LOOP
        aggregate_defects := aggregate_defects || jsonb_build_array(jsonb_build_object(
            'code', 'EXTRA_EVIDENCE', 'evidence_id', aggregate_evidence.evidence_id,
            'expected', NULL,
            'actual', jsonb_build_object('function', aggregate_evidence.aggregate_function,
                                         'value', aggregate_evidence.exact_value,
                                         'truth', aggregate_evidence.truth_result)));
    END LOOP;
    PERFORM pgreact_internal.reconcile_derivation_program_m9(target_program);
    IF jsonb_array_length(aggregate_defects) > 0 THEN
        UPDATE pgreact_internal.aggregate_dependency_evidence evidence
        SET active = false, support_id = NULL, invalidated_at = clock_timestamp()
        WHERE evidence.program_version_id = target_program AND evidence.active
          AND evidence.evidence_id <> ALL (expected_evidence_ids);
        PERFORM pgreact_internal.rebuild_derivation_program(
            target_program, true, true);
    END IF;
    SELECT max(reconciliation_id) INTO reconciliation_row_id
    FROM pgreact_internal.derivation_program_reconciliations
    WHERE program_version_id = target_program;
    SELECT COALESCE(max(diagnostic_order), 0) INTO next_diagnostic_order
    FROM pgreact_internal.derivation_program_repair_diagnostics
    WHERE reconciliation_id = reconciliation_row_id;
    DELETE FROM pgreact_internal.derivation_program_repair_diagnostics diagnostic
    USING pgreact_internal.activation_state activation,
          pgreact_internal.aggregate_dependency_evidence evidence
    WHERE diagnostic.reconciliation_id = reconciliation_row_id
      AND diagnostic.code = 'MISSING_SUPPORT'
      AND activation.rule_version_id = (diagnostic.details ->> 'rule_version_id')::uuid
      AND activation.activation_id = (diagnostic.details ->> 'activation_id')::uuid
      AND evidence.program_version_id = target_program
      AND evidence.rule_version_id = activation.rule_version_id
      AND evidence.semantic_key = activation.semantic_key
      AND evidence.active;
    FOR aggregate_defect IN
        SELECT value FROM jsonb_array_elements(aggregate_defects)
    LOOP
        next_diagnostic_order := next_diagnostic_order + 1;
        INSERT INTO pgreact_internal.derivation_program_repair_diagnostics VALUES (
            reconciliation_row_id, next_diagnostic_order,
            aggregate_defect ->> 'code',
            aggregate_defect ->> 'evidence_id', jsonb_build_object(
                'expected', aggregate_defect -> 'expected',
                'actual', aggregate_defect -> 'actual'));
    END LOOP;
    UPDATE pgreact_internal.derivation_program_reconciliations
    SET repairs = (SELECT count(*) FROM pgreact_internal.derivation_program_repair_diagnostics
                   WHERE reconciliation_id = reconciliation_row_id)
    WHERE reconciliation_id = reconciliation_row_id;
    RETURN (SELECT reconciliation.repairs
            FROM pgreact_internal.derivation_program_reconciliations reconciliation
            WHERE reconciliation.reconciliation_id = reconciliation_row_id);
END
$$;

CREATE OR REPLACE FUNCTION pgreact_internal.attach_derivation_aggregate_input()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    aggregate_item jsonb;
    function_name text;
    expression_attnum smallint;
    expression_type oid;
    expression_collation oid;
BEGIN
    SELECT rule.value -> 'aggregate_input' INTO aggregate_item
    FROM pgreact_internal.derivation_program_versions version
    CROSS JOIN LATERAL jsonb_array_elements(version.definition -> 'rules') rule(value)
    WHERE version.program_version_id = NEW.program_version_id
      AND rule.value ->> 'name' = NEW.rule_name;
    IF aggregate_item IS NULL THEN RETURN NEW; END IF;
    function_name := COALESCE(aggregate_item ->> 'function', 'COUNT_STAR');
    IF function_name <> 'COUNT_STAR' THEN
        SELECT attnum, atttypid, attcollation
        INTO STRICT expression_attnum, expression_type, expression_collation
        FROM pg_attribute
        WHERE attrelid = to_regclass(aggregate_item ->> 'relation')
          AND attname = (aggregate_item ->> 'expression')::name
          AND attnum > 0 AND NOT attisdropped;
    END IF;
    INSERT INTO pgreact_internal.derivation_program_aggregate_inputs (
        program_version_id, rule_version_id, relation_oid, relation_name, key_column,
        comparison, threshold, relation_definition_digest, relation_row_signature,
        aggregate_function, value_expression, expression_attnum, input_type,
        input_type_name, result_type, result_type_name,
        expression_collation, expression_collation_name,
        public_relation_name, typed_threshold
    ) VALUES (
        NEW.program_version_id, NEW.rule_version_id,
        to_regclass(aggregate_item ->> 'relation'), aggregate_item ->> 'relation',
        (aggregate_item ->> 'key')::name, aggregate_item ->> 'comparison',
        CASE WHEN function_name = 'COUNT_STAR'
             THEN (aggregate_item ->> 'threshold')::bigint END,
        pgreact_internal.source_closure_digest(to_regclass(aggregate_item ->> 'relation')),
        pgreact_internal.source_row_signature(to_regclass(aggregate_item ->> 'relation')),
        function_name, (aggregate_item ->> 'expression')::name,
        expression_attnum, expression_type,
        CASE WHEN expression_type IS NULL THEN NULL ELSE expression_type::regtype::text END,
        pgreact_internal.aggregate_result_type(function_name, expression_type),
        pgreact_internal.aggregate_result_type(function_name, expression_type)::regtype::text,
        COALESCE(expression_collation, 0),
        CASE WHEN COALESCE(expression_collation, 0) = 0 THEN NULL
             ELSE expression_collation::regcollation::text END,
        aggregate_item ->> 'public_relation',
        aggregate_item ->> 'threshold'
    );
    RETURN NEW;
END
$$;

CREATE OR REPLACE FUNCTION pgreact_internal.rebuild_derivation_program(
    target_program uuid,
    force_rebuild boolean DEFAULT false,
    preserve_frontier boolean DEFAULT false,
    existing_run_id bigint DEFAULT NULL
)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    input_row record;
    drift record;
BEGIN
    PERFORM pg_advisory_xact_lock(5788046901200000);
    FOR input_row IN
        SELECT * FROM pgreact_internal.derivation_program_aggregate_inputs
        WHERE program_version_id = target_program
        ORDER BY relation_oid
    LOOP
        EXECUTE format('LOCK TABLE %s IN ACCESS SHARE MODE', input_row.relation_oid::regclass);
    END LOOP;
    SELECT rule.rule_name, input.relation_name,
           encode(input.relation_definition_digest, 'hex') AS expected_digest,
           encode(pgreact_internal.source_closure_digest(input.relation_oid), 'hex') AS current_digest,
           encode(input.relation_row_signature, 'hex') AS expected_signature,
           encode(pgreact_internal.source_row_signature(input.relation_oid), 'hex') AS current_signature
    INTO drift
    FROM pgreact_internal.derivation_program_aggregate_inputs input
    JOIN pgreact_internal.derivation_program_rules rule
      USING (program_version_id, rule_version_id)
    LEFT JOIN pg_attribute expression_attribute
      ON expression_attribute.attrelid = input.relation_oid
     AND expression_attribute.attname = input.value_expression
     AND expression_attribute.attnum > 0 AND NOT expression_attribute.attisdropped
    WHERE input.program_version_id = target_program
      AND (input.relation_definition_digest IS DISTINCT FROM
               pgreact_internal.source_closure_digest(input.relation_oid)
           OR input.relation_row_signature IS DISTINCT FROM
               pgreact_internal.source_row_signature(input.relation_oid)
           OR (input.aggregate_function <> 'COUNT_STAR' AND (
               expression_attribute.attnum IS DISTINCT FROM input.expression_attnum
               OR expression_attribute.atttypid IS DISTINCT FROM input.input_type
               OR expression_attribute.attcollation IS DISTINCT FROM input.expression_collation
               OR pgreact_internal.aggregate_result_type(
                    input.aggregate_function, expression_attribute.atttypid)
                  IS DISTINCT FROM input.result_type)))
    ORDER BY rule.rule_order, rule.rule_name LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'derivation program aggregate-input drift for %', drift.rule_name
            USING HINT = 'Replace the complete derivation program through its public API.',
                  DETAIL = format(
                      'relation %s; expected definition %s, current %s; expected row signature %s, current %s',
                      drift.relation_name, drift.expected_digest, drift.current_digest,
                      drift.expected_signature, drift.current_signature);
    END IF;
    RETURN pgreact_internal.rebuild_derivation_program_m9(
        target_program, force_rebuild, preserve_frontier, existing_run_id);
END
$$;

ALTER FUNCTION pgreact_internal.maintain_derived_support(uuid, uuid)
    RENAME TO maintain_derived_support_m15;

CREATE FUNCTION pgreact_internal.maintain_derived_support(
    target_rule_version uuid,
    target_activation uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    program_rule record;
    aggregate_input record;
    activation_key bigint;
    activation_public_key jsonb;
    activation_canonical_key bytea;
    current_value text;
    current_threshold text;
    holds boolean;
    current_support uuid;
    old_support record;
    frontier_value bigint;
    lower_frontier bigint;
    source_stratum_value integer;
    target_stratum_value integer;
BEGIN
    SELECT rule.*, version.definition, version.frontier AS program_frontier
    INTO program_rule
    FROM pgreact_internal.derivation_program_rules rule
    JOIN pgreact_internal.derivation_program_versions version USING (program_version_id)
    WHERE rule.rule_version_id = target_rule_version AND version.state = 'ACTIVE'
    ORDER BY version.created_at DESC LIMIT 1;
    SELECT input.* INTO aggregate_input
    FROM pgreact_internal.derivation_program_aggregate_inputs input
    WHERE input.rule_version_id = target_rule_version
      AND input.program_version_id = program_rule.program_version_id;
    IF NOT FOUND THEN
        PERFORM pgreact_internal.maintain_derived_support_m9(
            target_rule_version, target_activation);
        RETURN;
    END IF;
    SELECT semantic_key,
           current_bindings -> '__pgreact_public_key',
           (current_bindings ->> '__pgreact_canonical')::bytea
    INTO activation_key, activation_public_key, activation_canonical_key
    FROM pgreact_internal.activation_state
    WHERE rule_version_id = target_rule_version
      AND activation_id = target_activation AND active;
    IF NOT FOUND THEN
        UPDATE pgreact_internal.aggregate_dependency_evidence
        SET active = false, support_id = NULL, invalidated_at = clock_timestamp()
        WHERE activation_id = target_activation AND active;
        PERFORM pgreact_internal.maintain_derived_support_m9(
            target_rule_version, target_activation);
        RETURN;
    END IF;
    PERFORM set_config('TimeZone', 'UTC', true);
    PERFORM set_config('DateStyle', 'ISO, YMD', true);
    PERFORM set_config('extra_float_digits', '3', true);
    IF aggregate_input.aggregate_function = 'COUNT_STAR' THEN
        EXECUTE format(
            'SELECT count(*)::text, count(*) OPERATOR(pg_catalog.%s) $2::bigint, '
            '$2::bigint::text FROM %s WHERE %I = $1',
            aggregate_input.comparison, aggregate_input.relation_oid::regclass,
            aggregate_input.key_column)
        INTO current_value, holds, current_threshold
        USING activation_key, aggregate_input.typed_threshold;
    ELSIF aggregate_input.aggregate_function IN ('MIN', 'MAX')
          AND aggregate_input.input_type = 'uuid'::regtype THEN
        IF activation_canonical_key IS NULL OR activation_public_key IS NULL THEN
            RAISE EXCEPTION 'M16_AGGREGATE_KEY_IDENTITY: typed aggregate activation lacks canonical identity';
        END IF;
        EXECUTE format(
            'SELECT aggregate_value::text, '
            'aggregate_value OPERATOR(pg_catalog.%s) $2::uuid, $2::uuid::text '
            'FROM (SELECT (SELECT %I FROM %s '
            'WHERE %I = $1 AND __pgreact_canonical = $3 AND %I IS NOT NULL '
            'ORDER BY %I %s LIMIT 1) AS aggregate_value) aggregate_result',
            aggregate_input.comparison, aggregate_input.value_expression,
            aggregate_input.relation_oid::regclass, aggregate_input.key_column,
            aggregate_input.value_expression, aggregate_input.value_expression,
            CASE aggregate_input.aggregate_function
                WHEN 'MIN' THEN 'ASC' ELSE 'DESC' END)
        INTO current_value, holds, current_threshold
        USING activation_key, aggregate_input.typed_threshold, activation_canonical_key;
    ELSE
        IF activation_canonical_key IS NULL OR activation_public_key IS NULL THEN
            RAISE EXCEPTION 'M16_AGGREGATE_KEY_IDENTITY: typed aggregate activation lacks canonical identity';
        END IF;
        EXECUTE format(
            'SELECT aggregate_value::text, '
            'aggregate_value OPERATOR(pg_catalog.%s) $2::%s, $2::%s::text '
            'FROM (SELECT pg_catalog.%s(%I) AS aggregate_value '
            'FROM %s WHERE %I = $1 AND __pgreact_canonical = $3) aggregate_result',
            aggregate_input.comparison, aggregate_input.result_type::regtype,
            aggregate_input.result_type::regtype,
            aggregate_input.aggregate_function, aggregate_input.value_expression,
            aggregate_input.relation_oid::regclass, aggregate_input.key_column)
        INTO current_value, holds, current_threshold
        USING activation_key, aggregate_input.typed_threshold, activation_canonical_key;
    END IF;
    SELECT COALESCE(source_component.stratum, 0), target_component.stratum
    INTO STRICT source_stratum_value, target_stratum_value
    FROM pgreact_internal.derivation_program_components target_component
    LEFT JOIN pgreact_internal.derived_relation_versions source_version
      ON source_version.public_view_oid = aggregate_input.relation_oid
     AND source_version.state = 'ACTIVE'
    LEFT JOIN pgreact_internal.derivation_program_components source_component
      ON source_component.program_version_id = program_rule.program_version_id
     AND source_version.relation_version_id = ANY (source_component.target_relations)
    WHERE target_component.program_version_id = program_rule.program_version_id
      AND target_component.component_id = program_rule.component_id;
    SELECT component_frontier.frontier INTO lower_frontier
    FROM pgreact_internal.derivation_program_components component
    JOIN pgreact_internal.derivation_program_component_frontiers component_frontier
      USING (program_version_id, component_id)
    JOIN pgreact_internal.derived_relation_versions relation_version
      ON relation_version.relation_version_id = ANY (component.target_relations)
    WHERE component.program_version_id = program_rule.program_version_id
      AND relation_version.public_view_oid = aggregate_input.relation_oid;
    lower_frontier := COALESCE(lower_frontier,
        NULLIF(current_setting('pgreact.program_support_frontier', true), '')::bigint,
        program_rule.program_frontier + 1);
    IF holds THEN
        PERFORM pgreact_internal.maintain_derived_support_m9(
            target_rule_version, target_activation);
    ELSE
        SELECT support_id, relation_version_id, semantic_key INTO old_support
        FROM pgreact_internal.derived_supports
        WHERE rule_version_id = target_rule_version
          AND activation_id = target_activation AND active;
        IF FOUND THEN
            frontier_value := pgreact_internal.advance_derived_frontier(
                old_support.relation_version_id);
            UPDATE pgreact_internal.derived_supports
            SET active = false, grounded = false, last_frontier = frontier_value,
                invalidated_at = clock_timestamp()
            WHERE support_id = old_support.support_id;
            PERFORM pgreact_internal.recompute_derived_fact(
                old_support.relation_version_id, old_support.semantic_key, frontier_value);
        END IF;
    END IF;
    SELECT support_id INTO current_support
    FROM pgreact_internal.derived_supports
    WHERE rule_version_id = target_rule_version
      AND activation_id = target_activation AND active;
    INSERT INTO pgreact_internal.aggregate_dependency_evidence (
        evidence_id, program_version_id, rule_version_id, activation_id, support_id,
        semantic_key, relation_oid, relation_name, exact_count, comparison, threshold,
        source_stratum, target_stratum, lower_frontier, active,
        aggregate_function, value_expression, input_type, result_type,
        input_type_name, result_type_name, expression_collation,
        expression_collation_name, exact_value, typed_threshold, truth_result,
        public_group_key, canonical_group_key
    ) VALUES (
        pgreact_internal.activation_uuid(sha256(convert_to(
            program_rule.program_version_id::text || ':' || target_rule_version::text || ':' ||
            CASE WHEN aggregate_input.aggregate_function = 'COUNT_STAR'
                 THEN activation_key::text
                 ELSE encode(activation_canonical_key, 'hex') END, 'UTF8'))),
        program_rule.program_version_id, target_rule_version, target_activation, current_support,
        activation_key, aggregate_input.relation_oid, aggregate_input.relation_name,
        CASE WHEN aggregate_input.aggregate_function IN ('COUNT_STAR', 'COUNT')
             THEN current_value::bigint END,
        aggregate_input.comparison,
        CASE WHEN aggregate_input.aggregate_function = 'COUNT_STAR'
             THEN aggregate_input.typed_threshold::bigint END,
        source_stratum_value, target_stratum_value, lower_frontier, true,
        aggregate_input.aggregate_function, aggregate_input.value_expression,
        aggregate_input.input_type, aggregate_input.result_type,
        aggregate_input.input_type_name, aggregate_input.result_type_name,
        aggregate_input.expression_collation,
        aggregate_input.expression_collation_name, current_value,
        current_threshold, holds, activation_public_key, activation_canonical_key
    ) ON CONFLICT (evidence_id) DO UPDATE SET
        activation_id = EXCLUDED.activation_id,
        support_id = EXCLUDED.support_id,
        semantic_key = EXCLUDED.semantic_key,
        relation_oid = EXCLUDED.relation_oid,
        relation_name = EXCLUDED.relation_name,
        exact_count = EXCLUDED.exact_count,
        comparison = EXCLUDED.comparison,
        threshold = EXCLUDED.threshold,
        source_stratum = EXCLUDED.source_stratum,
        target_stratum = EXCLUDED.target_stratum,
        lower_frontier = CASE
            WHEN pgreact_internal.aggregate_dependency_evidence.exact_value
                     IS DISTINCT FROM EXCLUDED.exact_value
              OR pgreact_internal.aggregate_dependency_evidence.comparison
                     IS DISTINCT FROM EXCLUDED.comparison
              OR pgreact_internal.aggregate_dependency_evidence.typed_threshold
                     IS DISTINCT FROM EXCLUDED.typed_threshold
            THEN EXCLUDED.lower_frontier
            ELSE pgreact_internal.aggregate_dependency_evidence.lower_frontier
        END,
        active = true,
        invalidated_at = NULL,
        aggregate_function = EXCLUDED.aggregate_function,
        value_expression = EXCLUDED.value_expression,
        input_type = EXCLUDED.input_type,
        input_type_name = EXCLUDED.input_type_name,
        result_type = EXCLUDED.result_type,
        result_type_name = EXCLUDED.result_type_name,
        expression_collation = EXCLUDED.expression_collation,
        expression_collation_name = EXCLUDED.expression_collation_name,
        exact_value = EXCLUDED.exact_value,
        typed_threshold = EXCLUDED.typed_threshold,
        truth_result = EXCLUDED.truth_result,
        public_group_key = EXCLUDED.public_group_key,
        canonical_group_key = EXCLUDED.canonical_group_key;
END
$$;

CREATE OR REPLACE FUNCTION pgreact_internal.recursive_fact_proof(
    target_program uuid,
    target_relation uuid,
    target_key bigint,
    path uuid[]
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    fact_row record;
    support_row record;
    input_row record;
    evidence_row record;
    supports jsonb := '[]'::jsonb;
    inputs jsonb;
    negative_checks jsonb;
    aggregate_conditions jsonb;
    support_node jsonb;
    input_node jsonb;
    relation_identity text;
BEGIN
    SELECT fact.fact_id, fact.fact, relation.relation_name, version.version
    INTO fact_row
    FROM pgreact_internal.derived_facts fact
    JOIN pgreact_internal.derived_relation_versions version USING (relation_version_id)
    JOIN pgreact_internal.derived_relations relation USING (relation_id)
    WHERE fact.relation_version_id = target_relation AND fact.semantic_key = target_key;
    IF NOT FOUND THEN RETURN NULL; END IF;
    relation_identity := fact_row.relation_name || '@' || fact_row.version;
    IF fact_row.fact_id = ANY (path) THEN
        RETURN jsonb_build_object('cycle', true, 'relation', relation_identity,
                                  'semantic_key', target_key);
    END IF;
    FOR support_row IN
        SELECT support.support_id, support.logical_support_id, support.source_binding,
               rule.rule_name, derivation.version
        FROM pgreact_internal.derived_supports support
        JOIN pgreact_internal.derivation_program_rules program_rule
          ON program_rule.program_version_id = target_program
         AND program_rule.rule_version_id = support.rule_version_id
        JOIN pgreact_internal.derivation_rule_versions derivation
          ON derivation.rule_version_id = support.rule_version_id
        JOIN pgreact_internal.rules rule ON rule.rule_id = derivation.rule_id
        WHERE support.relation_version_id = target_relation
          AND support.semantic_key = target_key AND support.active
        ORDER BY rule.rule_name, derivation.version, support.logical_support_id
    LOOP
        inputs := '[]'::jsonb;
        FOR input_row IN
            SELECT input.*, relation.relation_name, version.version
            FROM pgreact_internal.derived_support_inputs input
            JOIN pgreact_internal.derived_relation_versions version
              ON version.relation_version_id = input.relation_version_id
            JOIN pgreact_internal.derived_relations relation USING (relation_id)
            WHERE input.support_id = support_row.support_id
            ORDER BY input.input_order
        LOOP
            IF input_row.fact_id = ANY (path || fact_row.fact_id) THEN
                input_node := jsonb_build_object('cycle', true,
                    'relation', input_row.relation_name || '@' || input_row.version,
                    'semantic_key', input_row.semantic_key);
            ELSE
                input_node := pgreact_internal.recursive_fact_proof(
                    target_program, input_row.relation_version_id,
                    input_row.semantic_key, path || fact_row.fact_id);
            END IF;
            inputs := inputs || jsonb_build_array(input_node);
        END LOOP;
        negative_checks := '[]'::jsonb;
        FOR evidence_row IN
            SELECT * FROM pgreact_internal.negative_dependency_evidence
            WHERE support_id = support_row.support_id AND active ORDER BY input_order
        LOOP
            negative_checks := negative_checks || jsonb_build_array(jsonb_build_object(
                'evidence_id', evidence_row.evidence_id,
                'relation', evidence_row.relation_name,
                'semantic_key', evidence_row.semantic_key,
                'source_stratum', evidence_row.source_stratum,
                'lower_frontier', evidence_row.lower_frontier));
        END LOOP;
        aggregate_conditions := '[]'::jsonb;
        FOR evidence_row IN
            SELECT evidence.*,
                   COALESCE(input.public_relation_name, evidence.relation_name)
                       AS public_relation_name
            FROM pgreact_internal.aggregate_dependency_evidence evidence
            JOIN pgreact_internal.derivation_program_aggregate_inputs input
              USING (program_version_id, rule_version_id)
            WHERE evidence.support_id = support_row.support_id AND evidence.active
            ORDER BY evidence.evidence_id
        LOOP
            aggregate_conditions := aggregate_conditions || jsonb_build_array(CASE
                WHEN evidence_row.aggregate_function = 'COUNT_STAR' THEN
                    jsonb_build_object(
                        'evidence_id', evidence_row.evidence_id,
                        'relation', evidence_row.public_relation_name,
                        'group_key', evidence_row.semantic_key,
                        'count', evidence_row.exact_count,
                        'comparison', evidence_row.comparison,
                        'threshold', evidence_row.threshold,
                        'source_stratum', evidence_row.source_stratum,
                        'lower_frontier', evidence_row.lower_frontier)
                ELSE jsonb_build_object(
                    'evidence_id', evidence_row.evidence_id,
                    'relation', evidence_row.public_relation_name,
                    'group_key', evidence_row.public_group_key,
                    'function', evidence_row.aggregate_function,
                    'expression', evidence_row.value_expression,
                    'input_type', evidence_row.input_type_name,
                    'result_type', evidence_row.result_type_name,
                    'value', evidence_row.exact_value,
                    'comparison', evidence_row.comparison,
                    'threshold', evidence_row.typed_threshold,
                    'truth', evidence_row.truth_result,
                    'source_stratum', evidence_row.source_stratum,
                    'lower_frontier', evidence_row.lower_frontier)
                END);
        END LOOP;
        support_node := jsonb_build_object(
            'rule', support_row.rule_name || '@' || support_row.version,
            'source_binding', support_row.source_binding,
            'inputs', inputs,
            'negative_checks', negative_checks);
        IF aggregate_conditions <> '[]'::jsonb THEN
            support_node := support_node || jsonb_build_object(
                'aggregate_conditions', aggregate_conditions);
        END IF;
        supports := supports || jsonb_build_array(support_node);
    END LOOP;
    RETURN jsonb_build_object('relation', relation_identity,
                              'fact', fact_row.fact, 'supports', supports);
END
$$;

CREATE OR REPLACE VIEW pgreact.aggregate_dependency_evidence AS
SELECT evidence.evidence_id, evidence.program_version_id, program.program_name,
       version.version AS program_version, evidence.rule_version_id, rule.rule_name,
       evidence.semantic_key AS group_key,
       COALESCE(input.public_relation_name,
                wrapper.public_condition::regclass::text,
                evidence.relation_name) AS counted_relation,
       evidence.exact_count, evidence.comparison, evidence.threshold,
       evidence.source_stratum, evidence.target_stratum, evidence.lower_frontier,
       evidence.aggregate_function, evidence.value_expression,
       CASE WHEN evidence.input_type IS NULL THEN NULL
            ELSE evidence.input_type::regtype END AS input_type,
       evidence.result_type::regtype AS result_type,
       evidence.exact_value, evidence.typed_threshold, evidence.truth_result,
       CASE WHEN evidence.expression_collation = 0 THEN NULL
            ELSE evidence.expression_collation::regcollation END AS expression_collation,
       evidence.public_group_key, evidence.input_type_name,
       evidence.result_type_name, evidence.expression_collation_name
FROM pgreact_internal.aggregate_dependency_evidence evidence
JOIN pgreact_internal.derivation_program_versions version USING (program_version_id)
JOIN pgreact_internal.derivation_programs program USING (program_id)
JOIN pgreact_internal.derivation_program_rules rule
  USING (program_version_id, rule_version_id)
JOIN pgreact_internal.derivation_program_aggregate_inputs input
  USING (program_version_id, rule_version_id)
LEFT JOIN pgreact_internal.key_wrappers wrapper
  ON wrapper.wrapper_condition = evidence.relation_oid
WHERE version.state = 'ACTIVE' AND evidence.active;

CREATE OR REPLACE FUNCTION pgreact_api.explain(target text, semantic_key jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    activation uuid;
    derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    surrogate bigint;
    result jsonb;
    aggregate_summary jsonb;
BEGIN
    SELECT * INTO derived
    FROM pgreact_internal.keyed_derived_relations
    WHERE public_name = target;
    IF FOUND THEN
        EXECUTE format(
            'SELECT __pgreact_key FROM %s WHERE __pgreact_public_key = $1',
            derived.internal_name)
        INTO surrogate USING semantic_key;
        IF surrogate IS NULL THEN
            SELECT jsonb_build_object(
                'program', program.program_name || '@' || version.version,
                'frontier', version.frontier,
                'aggregate_conditions', jsonb_agg(jsonb_build_object(
                    'relation', input.public_relation_name,
                    'group_key', evidence.public_group_key,
                    'function', evidence.aggregate_function,
                    'expression', evidence.value_expression,
                    'input_type', evidence.input_type_name,
                    'result_type', evidence.result_type_name,
                    'value', evidence.exact_value,
                    'comparison', evidence.comparison,
                    'threshold', evidence.typed_threshold,
                    'truth', evidence.truth_result,
                    'source_stratum', evidence.source_stratum,
                    'target_stratum', evidence.target_stratum,
                    'lower_frontier', evidence.lower_frontier)
                    ORDER BY rule.rule_name))
            INTO aggregate_summary
            FROM pgreact_internal.aggregate_dependency_evidence evidence
            JOIN pgreact_internal.derivation_program_aggregate_inputs input
              USING (program_version_id, rule_version_id)
            JOIN pgreact_internal.derivation_program_rules rule
              USING (program_version_id, rule_version_id)
            JOIN pgreact_internal.derivation_program_versions version
              USING (program_version_id)
            JOIN pgreact_internal.derivation_programs program USING (program_id)
            WHERE rule.target_relation_version_id = derived.relation_version_id
              AND evidence.public_group_key = $2
              AND evidence.active AND version.state = 'ACTIVE'
            GROUP BY program.program_name, version.version, version.frontier;
            RETURN jsonb_build_object(
                'contract_version', 5,
                'target', jsonb_build_object(
                    'kind', 'fact', 'name', target, 'key', semantic_key),
                'evidence', aggregate_summary);
        END IF;
        result := pgreact_api.explain(derived.internal_name, surrogate);
        result := jsonb_set(result, '{contract_version}', '5'::jsonb);
        result := jsonb_set(result, '{target}', jsonb_build_object(
            'kind', 'fact', 'name', target, 'key', semantic_key));
        IF result #> '{evidence,fact}' IS NOT NULL THEN
            result := jsonb_set(result, '{evidence,fact}',
                (result #> '{evidence,fact}')
                - ARRAY['__pgreact_canonical', '__pgreact_key', '__pgreact_public_key']);
        END IF;
        RETURN pgreact_internal.public_json(result);
    END IF;
    SELECT state.activation_id INTO activation
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    JOIN pgreact_internal.semantic_key_identities identity USING (rule_version_id)
    JOIN pgreact_internal.activation_state state
      ON state.rule_version_id = identity.rule_version_id
     AND state.semantic_key = identity.semantic_key
    WHERE rule.rule_name = target AND version.state = 'ACTIVE'
      AND identity.public_key = $2;
    IF activation IS NULL THEN
        RETURN jsonb_build_object(
            'contract_version', 5,
            'target', jsonb_build_object(
                'kind', 'match', 'rule', target, 'key', semantic_key),
            'evidence', NULL);
    END IF;
    RETURN pgreact_internal.public_json(jsonb_set(
        pgreact_api.explain(target, activation), '{contract_version}', '5'::jsonb)
        || jsonb_build_object(
            'target', jsonb_build_object(
                'kind', 'match', 'rule', target, 'key', semantic_key)));
END
$$;

CREATE FUNCTION pgreact_api.reconcile_program(program_name text)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE target_program uuid;
BEGIN
    SELECT version.program_version_id INTO STRICT target_program
    FROM pgreact_internal.derivation_programs program
    JOIN pgreact_internal.derivation_program_versions version USING (program_id)
    WHERE program.program_name = $1 AND version.state = 'ACTIVE';
    RETURN pgreact.reconcile_derivation_program(target_program);
EXCEPTION WHEN no_data_found THEN
    RAISE EXCEPTION 'M16_PROGRAM_NOT_ACTIVE: %', $1
        USING HINT = 'Name one active derivation program.';
END
$$;

CREATE OR REPLACE FUNCTION pgreact_api.remove_program(
    program_name text,
    program_version integer
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE target_program uuid;
BEGIN
    SELECT version.program_version_id INTO STRICT target_program
    FROM pgreact_internal.derivation_programs program
    JOIN pgreact_internal.derivation_program_versions version USING (program_id)
    WHERE program.program_name = $1 AND version.version = $2
      AND version.state = 'ACTIVE';
    PERFORM pgreact.remove_derivation_program(target_program);
EXCEPTION WHEN no_data_found THEN
    RAISE EXCEPTION 'M16_PROGRAM_NOT_ACTIVE: %@%', $1, $2
        USING HINT = 'Name the active program version.';
END
$$;

ALTER FUNCTION pgreact_api.configure_roles(regrole, regrole, regrole, regrole, regrole)
SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.configure_roles(regrole, regrole, regrole, regrole, regrole)
RENAME TO configure_roles_m15;

CREATE FUNCTION pgreact_api.configure_roles(
    author_role regrole,
    operator_role regrole,
    worker_role regrole,
    reader_role regrole,
    advanced_reader_role regrole
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    PERFORM pgreact_internal.configure_roles_m15(
        author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.reconcile_program(text) TO %I',
        operator_role::text);
END
$$;

CREATE OR REPLACE FUNCTION pgreact_api.doctor()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    WITH diagnostics AS (
        SELECT diagnostic FROM jsonb_array_elements(pgreact_api.health() -> 'diagnostics') diagnostic
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M16_EXTENSION_VERSION', 'severity', 'ERROR', 'object_identity', 'pg_react',
            'message', 'pg_react extension version is not 0.13.0',
            'hint', 'Install matching files and run ALTER EXTENSION pg_react UPDATE.')
        WHERE NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_react' AND extversion = '0.13.0')
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M15_TRICKLE_VERSION', 'severity', 'ERROR', 'object_identity', 'pg_trickle',
            'message', 'pg_trickle extension version is not 0.81.0',
            'hint', 'Install the supported pg_trickle 0.81.0 extension.')
        WHERE NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_trickle' AND extversion = '0.81.0')
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M15_ROLE_CONFIGURATION', 'severity', 'WARNING', 'object_identity', 'pgreact_api',
            'message', 'application facade roles are not configured',
            'hint', 'The extension owner must call pgreact_api.configure_roles with five distinct roles.')
        WHERE (SELECT count(*) FROM pgreact_internal.application_roles) <> 4
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M15_MANAGED_CONFIGURATION', 'severity', 'ERROR', 'object_identity', current_database(),
            'message', 'this database is not configured for a managed worker',
            'hint', 'Preload pg_react, add this database to pg_react.databases, and restart PostgreSQL.')
        WHERE NOT current_database() = ANY (regexp_split_to_array(
            current_setting('pg_react.databases', true), '\\s*,\\s*'))
        UNION ALL
        SELECT jsonb_build_object(
            'code', 'M15_MANAGED_PROCESS', 'severity', 'ERROR', 'object_identity', current_database(),
            'message', CASE WHEN process.database_oid IS NULL THEN 'managed worker has not attached'
                            ELSE 'managed worker state is ' || process.state END,
            'hint', 'Inspect pgreact_api.managed_status(), PostgreSQL logs, preload settings, and worker role connectivity.')
        FROM (SELECT 1) singleton
        LEFT JOIN pgreact_internal.managed_processes process
          ON process.database_oid = (SELECT oid FROM pg_database WHERE datname = current_database())
        WHERE process.database_oid IS NULL OR process.state <> 'ready'
           OR process.heartbeat_at < clock_timestamp() - interval '10 seconds'
    ), ordered AS (
        SELECT diagnostic FROM diagnostics
        ORDER BY CASE diagnostic ->> 'severity' WHEN 'ERROR' THEN 1 WHEN 'WARNING' THEN 2 ELSE 3 END,
                 diagnostic ->> 'code', diagnostic ->> 'object_identity'
    )
    SELECT jsonb_build_object(
        'contract_version', 5,
        'status', CASE WHEN EXISTS (SELECT 1 FROM ordered WHERE diagnostic ->> 'severity' = 'ERROR')
                       THEN 'attention' ELSE 'ready' END,
        'diagnostics', COALESCE((SELECT jsonb_agg(diagnostic) FROM ordered), '[]'::jsonb))
$$;

REVOKE ALL ON ALL TABLES IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_internal FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pgreact_internal.derivation_program_graph(jsonb) TO PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_api FROM PUBLIC;

DO $$
DECLARE
    author_role regrole;
    operator_role regrole;
    worker_role regrole;
    reader_role regrole;
    advanced_reader_role regrole;
BEGIN
    SELECT role_oid::regrole INTO author_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'author';
    SELECT role_oid::regrole INTO operator_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'operator';
    SELECT role_oid::regrole INTO worker_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'worker';
    SELECT role_oid::regrole INTO reader_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'reader';
    SELECT role_oid::regrole INTO advanced_reader_role
    FROM pgreact_internal.advanced_readers;
    IF author_role IS NOT NULL AND operator_role IS NOT NULL
       AND worker_role IS NOT NULL AND reader_role IS NOT NULL
       AND advanced_reader_role IS NOT NULL THEN
        PERFORM pgreact_api.configure_roles(
            author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    END IF;
END
$$;

COMMENT ON EXTENSION pg_react IS
    'M16 typed COUNT, SUM, MIN, and MAX over stable lower strata';

-- M17 fixed-duration event-time windows. Windowed aggregates reuse the M16
-- aggregate engine through typed materialized inputs; this catalog owns the
-- temporal contract that M16 does not have.

CREATE TABLE pgreact_internal.window_programs (
    program_version_id uuid PRIMARY KEY,
    program_name text NOT NULL,
    program_version integer NOT NULL CHECK (program_version > 0),
    owner_oid oid NOT NULL,
    public_definition jsonb NOT NULL,
    input_relation_name text NOT NULL,
    condition_relation_name text NOT NULL,
    input_definition_digest bytea NOT NULL,
    input_row_signature bytea NOT NULL,
    condition_definition_digest bytea NOT NULL,
    condition_row_signature bytea NOT NULL,
    event_time_column name NOT NULL,
    duration_us bigint NOT NULL CHECK (duration_us > 0),
    allowed_lateness_us bigint NOT NULL CHECK (allowed_lateness_us >= 0),
    group_columns name[] NOT NULL CHECK (cardinality(group_columns) BETWEEN 1 AND 3),
    window_column name NOT NULL,
    helper_input_name text NOT NULL,
    helper_keys_name text NOT NULL,
    helper_input_store_name text NOT NULL,
    helper_keys_store_name text NOT NULL,
    max_facts bigint NOT NULL CHECK (max_facts > 0),
    lower_frontier bigint NOT NULL DEFAULT 0 CHECK (lower_frontier >= 0),
    observed_frontier bigint NOT NULL DEFAULT 0 CHECK (observed_frontier >= lower_frontier),
    requested_watermark timestamptz NOT NULL DEFAULT '-infinity',
    complete_watermark timestamptz NOT NULL DEFAULT '-infinity',
    history_floor timestamptz NOT NULL DEFAULT '-infinity',
    barrier text CHECK (barrier IS NULL OR barrier = 'LATE_INPUT'),
    active boolean NOT NULL DEFAULT true,
    last_source_fingerprint bytea NOT NULL DEFAULT sha256(''::bytea),
    last_observed_fingerprint bytea NOT NULL DEFAULT sha256(''::bytea),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (program_name, program_version)
);

CREATE UNIQUE INDEX window_program_one_active
    ON pgreact_internal.window_programs (program_name) WHERE active;

CREATE TABLE pgreact_internal.window_rules (
    program_version_id uuid NOT NULL REFERENCES pgreact_internal.window_programs ON DELETE CASCADE,
    rule_version_id uuid NOT NULL,
    rule_name text NOT NULL,
    rule_version integer NOT NULL CHECK (rule_version > 0),
    target_relation text NOT NULL,
    aggregate_function text NOT NULL CHECK (aggregate_function IN ('COUNT_STAR','COUNT','SUM','MIN','MAX')),
    value_expression name,
    comparison text NOT NULL CHECK (comparison IN ('=','<','<=','>','>=')),
    typed_threshold text NOT NULL,
    PRIMARY KEY (program_version_id, rule_version_id),
    UNIQUE (program_version_id, rule_name)
);

CREATE TABLE pgreact_internal.window_source_rows (
    program_version_id uuid NOT NULL REFERENCES pgreact_internal.window_programs ON DELETE CASCADE,
    row_data jsonb NOT NULL,
    public_window_key jsonb NOT NULL,
    event_time timestamptz NOT NULL,
    window_ordinal bigint NOT NULL,
    occurrences bigint NOT NULL CHECK (occurrences > 0),
    PRIMARY KEY (program_version_id, row_data, public_window_key, event_time, window_ordinal)
);

CREATE TABLE pgreact_internal.window_identities (
    program_version_id uuid NOT NULL REFERENCES pgreact_internal.window_programs ON DELETE CASCADE,
    public_window_key jsonb NOT NULL,
    canonical_window_key bytea NOT NULL,
    window_ordinal bigint NOT NULL,
    window_start timestamptz NOT NULL,
    window_end timestamptz NOT NULL,
    lateness_boundary timestamptz NOT NULL,
    final boolean NOT NULL DEFAULT false,
    PRIMARY KEY (program_version_id, public_window_key)
);

CREATE INDEX window_identity_boundary
    ON pgreact_internal.window_identities (program_version_id, lateness_boundary, canonical_window_key);

CREATE TABLE pgreact_internal.window_corrections (
    correction_order bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    correction_identity text NOT NULL UNIQUE,
    program_version_id uuid NOT NULL REFERENCES pgreact_internal.window_programs ON DELETE CASCADE,
    program_name text NOT NULL,
    program_version integer NOT NULL,
    rule_version_id uuid NOT NULL,
    rule_name text NOT NULL,
    rule_version integer NOT NULL,
    target_relation text NOT NULL,
    public_window_key jsonb NOT NULL,
    public_group_key jsonb NOT NULL,
    window_ordinal bigint NOT NULL,
    canonical_window_key bytea NOT NULL,
    lower_frontier bigint NOT NULL CHECK (lower_frontier > 0),
    before_value text,
    after_value text,
    before_truth boolean,
    after_truth boolean,
    support_generation integer NOT NULL CHECK (support_generation >= 0),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE INDEX window_correction_history
    ON pgreact_internal.window_corrections
       (program_version_id, window_ordinal, lower_frontier, rule_name);

CREATE TABLE pgreact_internal.window_finalizations (
    finalization_identity text PRIMARY KEY,
    program_version_id uuid NOT NULL REFERENCES pgreact_internal.window_programs ON DELETE CASCADE,
    public_window_key jsonb NOT NULL,
    canonical_window_key bytea NOT NULL,
    lateness_boundary timestamptz NOT NULL,
    finalized_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (program_version_id, public_window_key)
);

CREATE TABLE pgreact_internal.window_lifecycle (
    lifecycle_order bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    program_version_id uuid NOT NULL REFERENCES pgreact_internal.window_programs ON DELETE CASCADE,
    lower_frontier bigint NOT NULL,
    public_window_key jsonb NOT NULL,
    canonical_window_key bytea NOT NULL,
    rule_name text NOT NULL,
    event_kind text NOT NULL CHECK (event_kind IN ('ACTIVATE','DEACTIVATE')),
    support_generation integer NOT NULL CHECK (support_generation > 0),
    UNIQUE (program_version_id, lower_frontier, public_window_key, rule_name, event_kind)
);

CREATE TABLE pgreact_internal.window_diagnostics (
    diagnostic_order bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    contract_version integer NOT NULL DEFAULT 6 CHECK (contract_version = 6),
    code text NOT NULL,
    severity text NOT NULL CHECK (severity IN ('ERROR','WARNING','INFO')),
    object_identity text NOT NULL,
    sqlstate text NOT NULL CHECK (length(sqlstate) = 5),
    message text NOT NULL,
    hint text NOT NULL,
    details jsonb NOT NULL DEFAULT '{}'::jsonb,
    program_version_id uuid REFERENCES pgreact_internal.window_programs ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE pgreact_internal.window_audits (
    audit_order bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    program_version_id uuid REFERENCES pgreact_internal.window_programs ON DELETE SET NULL,
    operation text NOT NULL,
    actor name NOT NULL DEFAULT session_user,
    details jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE FUNCTION pgreact_internal.fixed_interval_us(value text, allow_zero boolean)
RETURNS bigint
LANGUAGE plpgsql
IMMUTABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE parsed interval; micros numeric;
BEGIN
    BEGIN
        parsed := value::interval;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'M17_WINDOW_INTERVAL_INVALID: %', value USING ERRCODE = '22023';
    END;
    IF extract(year FROM parsed) <> 0 OR extract(month FROM parsed) <> 0 THEN
        RAISE EXCEPTION 'M17_WINDOW_INTERVAL_INVALID: % is not fixed-duration', value
            USING ERRCODE = '22023';
    END IF;
    micros := extract(epoch FROM parsed)::numeric * 1000000;
    IF micros <> trunc(micros) OR micros > 9223372036854775807
       OR micros < (CASE WHEN allow_zero THEN 0 ELSE 1 END) THEN
        RAISE EXCEPTION 'M17_WINDOW_INTERVAL_INVALID: % is outside the supported range', value
            USING ERRCODE = '22023';
    END IF;
    RETURN micros::bigint;
END
$$;

CREATE FUNCTION pgreact_internal.window_ordinal(value timestamptz, duration_us bigint)
RETURNS bigint
LANGUAGE plpgsql
IMMUTABLE
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE micros numeric; result numeric;
BEGIN
    IF value IS NULL THEN
        RAISE EXCEPTION 'M17_EVENT_TIME_NULL: event time must be non-null' USING ERRCODE = '22004';
    END IF;
    IF NOT isfinite(value) THEN
        RAISE EXCEPTION 'M17_EVENT_TIME_INFINITE: event time must be finite' USING ERRCODE = '22008';
    END IF;
    micros := extract(epoch FROM value)::numeric * 1000000;
    result := floor(micros / duration_us::numeric);
    IF result < -9223372036854775808 OR result > 9223372036854775807 THEN
        RAISE EXCEPTION 'M17_WINDOW_ORDINAL_RANGE: event time is outside the signed ordinal range'
            USING ERRCODE = '22008';
    END IF;
    RETURN result::bigint;
END
$$;

CREATE FUNCTION pgreact_internal.window_bound(window_ordinal bigint, duration_us bigint)
RETURNS timestamptz
LANGUAGE plpgsql
IMMUTABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE micros numeric := window_ordinal::numeric * duration_us::numeric; result timestamptz;
BEGIN
    BEGIN
        result := 'epoch'::timestamptz + (micros::text || ' microseconds')::interval;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'M17_WINDOW_ORDINAL_RANGE: window bound is not a finite timestamptz'
            USING ERRCODE = '22008';
    END;
    IF NOT isfinite(result) THEN
        RAISE EXCEPTION 'M17_WINDOW_ORDINAL_RANGE: window bound is not finite'
            USING ERRCODE = '22008';
    END IF;
    RETURN result;
END
$$;

CREATE FUNCTION pgreact_internal.window_key_bytes(public_key jsonb)
RETURNS bytea
LANGUAGE SQL
IMMUTABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT sha256(convert_to($1::text, 'UTF8'))
$$;

ALTER FUNCTION pgreact_api.validate_program(jsonb) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.validate_program(jsonb) RENAME TO validate_program_m16;
ALTER FUNCTION pgreact_api.preview_program(jsonb) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.preview_program(jsonb) RENAME TO preview_program_m16;
ALTER FUNCTION pgreact_api.deploy_program(jsonb, text) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.deploy_program(jsonb, text) RENAME TO deploy_program_m16;

CREATE FUNCTION pgreact_internal.is_window_program(definition jsonb)
RETURNS boolean
LANGUAGE SQL
IMMUTABLE
RETURNS NULL ON NULL INPUT
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT EXISTS (
        SELECT 1 FROM jsonb_array_elements(CASE
            WHEN jsonb_typeof($1 -> 'rules') = 'array' THEN $1 -> 'rules' ELSE '[]'::jsonb END) rule
        WHERE (rule -> 'aggregate_input') ? 'window')
$$;

CREATE FUNCTION pgreact_internal.normalized_window_program(definition jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE result jsonb := pgreact_api.infer_program(definition); item record; window_value jsonb;
BEGIN
    FOR item IN SELECT value, ordinal FROM jsonb_array_elements(result -> 'rules')
        WITH ORDINALITY rule(value, ordinal)
    LOOP
        IF NOT (item.value -> 'aggregate_input') ? 'window' THEN CONTINUE; END IF;
        window_value := item.value #> '{aggregate_input,window}';
        result := jsonb_set(result,
            ARRAY['rules',(item.ordinal - 1)::text,'aggregate_input','window'],
            jsonb_build_object(
                'event_time', window_value ->> 'event_time',
                'duration_us', pgreact_internal.fixed_interval_us(window_value ->> 'duration', false),
                'allowed_lateness_us', pgreact_internal.fixed_interval_us(
                    window_value ->> 'allowed_lateness', true),
                'alignment', 'UTC_EPOCH'));
    END LOOP;
    RETURN result;
END
$$;

CREATE FUNCTION pgreact_api.validate_program(definition jsonb)
RETURNS TABLE(
    contract_version integer, code text, severity text,
    object_identity text, message text, hint text, details jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    item record;
    aggregate_item jsonb;
    window_item jsonb;
    first_relation text;
    first_condition text;
    first_event name;
    duration_value bigint;
    lateness_value bigint;
    first_duration bigint;
    first_lateness bigint;
    input_oid oid;
    condition_oid oid;
    target_spec pgreact_internal.keyed_derived_relations%ROWTYPE;
    event_attribute record;
    value_attribute record;
    function_name text;
    result_type oid;
    group_column name;
    rule_count integer;
BEGIN
    IF NOT pgreact_internal.is_window_program(definition) THEN
        RETURN QUERY SELECT * FROM pgreact_internal.validate_program_m16(definition);
        RETURN;
    END IF;
    IF jsonb_typeof(definition) IS DISTINCT FROM 'object'
       OR jsonb_typeof(definition -> 'rules') IS DISTINCT FROM 'array'
       OR jsonb_array_length(definition -> 'rules') = 0 THEN
        RETURN QUERY SELECT 6, 'M17_PROGRAM_INVALID', 'ERROR', 'program',
            'windowed program must be an object with at least one rule',
            'Declare one or more rules sharing one timed aggregate input.', '{}'::jsonb;
        RETURN;
    END IF;
    rule_count := jsonb_array_length(definition -> 'rules');
    IF COALESCE((definition ->> 'max_facts')::bigint, 0) < rule_count THEN
        RETURN QUERY SELECT 6, 'M17_RESOURCE_LIMIT', 'ERROR', definition ->> 'name',
            'max_facts cannot hold one state for every window rule',
            'Raise max_facts to at least the number of rules.',
            jsonb_build_object('required', rule_count);
        RETURN;
    END IF;
    FOR item IN SELECT value, ordinal FROM jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY rules(value, ordinal)
    LOOP
        aggregate_item := item.value -> 'aggregate_input';
        window_item := aggregate_item -> 'window';
        IF jsonb_typeof(aggregate_item) IS DISTINCT FROM 'object'
           OR jsonb_typeof(window_item) IS DISTINCT FROM 'object'
           OR NOT aggregate_item ?& ARRAY['relation','key','comparison','threshold','window']
           OR (aggregate_item ? 'function') <> (aggregate_item ? 'expression')
           OR (SELECT count(*) FROM jsonb_object_keys(aggregate_item)) <>
              (CASE WHEN aggregate_item ? 'function' THEN 7 ELSE 5 END)
           OR NOT window_item ?& ARRAY['event_time','duration','allowed_lateness']
           OR (SELECT count(*) FROM jsonb_object_keys(window_item)) <> 3 THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_DECLARATION_INVALID', 'ERROR',
                COALESCE(item.value ->> 'name', item.ordinal::text),
                'windowed aggregate_input has unsupported or missing members',
                'Use relation, key, comparison, threshold, optional function/expression, and one event_time/duration/allowed_lateness window.',
                '{}'::jsonb;
            RETURN;
        END IF;
        BEGIN
            duration_value := pgreact_internal.fixed_interval_us(window_item ->> 'duration', false);
            lateness_value := pgreact_internal.fixed_interval_us(
                window_item ->> 'allowed_lateness', true);
        EXCEPTION WHEN SQLSTATE '22023' THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_INTERVAL_INVALID', 'ERROR',
                item.value ->> 'name', 'window duration or allowed lateness is invalid',
                'Use fixed integral microsecond intervals; duration must be positive and lateness nonnegative.',
                jsonb_build_object('duration', window_item -> 'duration',
                                   'allowed_lateness', window_item -> 'allowed_lateness');
            RETURN;
        END;
        IF item.ordinal = 1 THEN
            first_relation := aggregate_item ->> 'relation';
            first_condition := item.value ->> 'definition';
            first_event := (window_item ->> 'event_time')::name;
            first_duration := duration_value;
            first_lateness := lateness_value;
        ELSIF first_relation IS DISTINCT FROM aggregate_item ->> 'relation'
              OR first_condition IS DISTINCT FROM item.value ->> 'definition'
              OR first_event IS DISTINCT FROM (window_item ->> 'event_time')::name
              OR first_duration IS DISTINCT FROM duration_value
              OR first_lateness IS DISTINCT FROM lateness_value THEN
            RETURN QUERY SELECT 6, 'M17_MULTIPLE_WINDOWS', 'ERROR', definition ->> 'name',
                'all windowed rules in one program must share one logical timed input',
                'Use one relation, event-time column, duration, lateness, and group source.', '{}'::jsonb;
            RETURN;
        END IF;
        input_oid := to_regclass(aggregate_item ->> 'relation');
        condition_oid := to_regclass(item.value ->> 'definition');
        IF input_oid IS NULL OR condition_oid IS NULL THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_RELATION_UNRESOLVED', 'ERROR', item.value ->> 'name',
                'window input or group source does not resolve',
                'Use schema-qualified existing relations.',
                jsonb_build_object('input', aggregate_item -> 'relation',
                                   'condition', item.value -> 'definition');
            RETURN;
        END IF;
        IF cardinality(parse_ident(aggregate_item ->> 'relation', true)) <> 2
           OR cardinality(parse_ident(item.value ->> 'definition', true)) <> 2 THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_RELATION_UNQUALIFIED', 'ERROR', item.value ->> 'name',
                'window input and group source must be schema-qualified',
                'Qualify both relations with their schema.', '{}'::jsonb;
            RETURN;
        END IF;
        IF NOT has_table_privilege(session_user, input_oid, 'SELECT')
           OR NOT has_table_privilege(session_user, condition_oid, 'SELECT') THEN
            RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_UNAUTHORIZED', 'ERROR', item.value ->> 'name',
                'program author cannot read the timed input or group source',
                'Grant SELECT on both relations to the author.', '{}'::jsonb;
            RETURN;
        END IF;
        IF EXISTS (SELECT 1 FROM pg_class WHERE oid IN (input_oid, condition_oid) AND relrowsecurity) THEN
            RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_RLS_UNSUPPORTED', 'ERROR', item.value ->> 'name',
                'row-level-security sources are outside the supported window boundary',
                'Use an authorized non-RLS projection.', '{}'::jsonb;
            RETURN;
        END IF;
        SELECT attnum, atttypid INTO event_attribute
        FROM pg_attribute
        WHERE attrelid = input_oid AND attname = (window_item ->> 'event_time')::name
          AND attnum > 0 AND NOT attisdropped;
        IF NOT FOUND OR event_attribute.atttypid IS DISTINCT FROM 'timestamptz'::regtype::oid THEN
            RETURN QUERY SELECT 6, 'M17_EVENT_TIME_TYPE', 'ERROR', item.value ->> 'name',
                'event_time must name one direct timestamptz column',
                'Project a finite non-null timestamptz column and name it directly.',
                jsonb_build_object('event_time', window_item -> 'event_time');
            RETURN;
        END IF;
        SELECT spec.* INTO target_spec FROM pgreact_internal.keyed_derived_relations spec
        WHERE spec.public_name = item.value ->> 'target';
        IF NOT FOUND OR cardinality(target_spec.key_columns) NOT BETWEEN 2 AND 4
           OR target_spec.key_types[cardinality(target_spec.key_types)] <> 'bigint'::regtype THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_KEY_INVALID', 'ERROR', item.value ->> 'name',
                'window target key must append one bigint ordinal to one to three group components',
                'Declare the target with group keys followed by a bigint window ordinal.', '{}'::jsonb;
            RETURN;
        END IF;
        IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = input_oid
                   AND attname = target_spec.key_columns[cardinality(target_spec.key_columns)]
                   AND attnum > 0 AND NOT attisdropped) THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_KEY_AMBIGUOUS', 'ERROR', item.value ->> 'name',
                'timed input already exposes the reserved target window-ordinal column',
                'Rename that source column or the target ordinal column.', '{}'::jsonb;
            RETURN;
        END IF;
        FOREACH group_column IN ARRAY target_spec.key_columns[1:cardinality(target_spec.key_columns)-1]
        LOOP
            IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = input_oid
                           AND attname = group_column AND attnum > 0 AND NOT attisdropped)
               OR NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = condition_oid
                              AND attname = group_column AND attnum > 0 AND NOT attisdropped) THEN
                RETURN QUERY SELECT 6, 'M17_WINDOW_KEY_UNBOUND', 'ERROR', item.value ->> 'name',
                    'group key is not directly present in both source relations',
                    'Expose every target group-key column from the timed input and group source.',
                    jsonb_build_object('column', group_column);
                RETURN;
            END IF;
        END LOOP;
        function_name := COALESCE(aggregate_item ->> 'function', 'COUNT_STAR');
        IF function_name NOT IN ('COUNT','SUM','MIN','MAX','COUNT_STAR')
           OR (function_name = 'COUNT' AND aggregate_item ->> 'expression' = '*') THEN
            RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_FUNCTION_UNSUPPORTED', 'ERROR', item.value ->> 'name',
                'aggregate function is outside the M16 allow-list',
                'Use inherited COUNT(*) or COUNT, SUM, MIN, or MAX over one named column.',
                jsonb_build_object('function', function_name);
            RETURN;
        END IF;
        IF function_name <> 'COUNT_STAR' THEN
            SELECT attnum, atttypid, attcollation INTO value_attribute
            FROM pg_attribute WHERE attrelid = input_oid
              AND attname = (aggregate_item ->> 'expression')::name
              AND attnum > 0 AND NOT attisdropped;
            result_type := pgreact_internal.aggregate_result_type(function_name, value_attribute.atttypid);
            IF NOT FOUND OR result_type IS NULL THEN
                RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_TYPE_UNSUPPORTED', 'ERROR', item.value ->> 'name',
                    'aggregate expression type is unsupported',
                    'Use one M16-supported direct column and aggregate function.',
                    jsonb_build_object('expression', aggregate_item -> 'expression');
                RETURN;
            END IF;
        ELSIF (aggregate_item ->> 'threshold')::bigint < 0 THEN
            RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_THRESHOLD_INVALID', 'ERROR', item.value ->> 'name',
                'COUNT(*) threshold must be nonnegative', 'Use a nonnegative bigint threshold.', '{}'::jsonb;
            RETURN;
        END IF;
    END LOOP;
    RETURN QUERY SELECT 6, 'PROGRAM_VALID', 'INFO', definition ->> 'name',
        'windowed program is valid', 'Preview and deploy this exact definition.',
        jsonb_build_object('normalized_definition',
                           pgreact_internal.normalized_window_program(definition));
END
$$;

CREATE FUNCTION pgreact_internal.window_plan_digest(definition jsonb)
RETURNS text
LANGUAGE SQL
STABLE
STRICT
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT encode(sha256(convert_to(
        pgreact_internal.normalized_window_program($1)::text || ':' || session_user || ':' ||
        encode(pgreact_internal.source_closure_digest(
            to_regclass($1 #>> '{rules,0,definition}')), 'hex') || ':' ||
        encode(pgreact_internal.source_closure_digest(
            to_regclass($1 #>> '{rules,0,aggregate_input,relation}')), 'hex'), 'UTF8')), 'hex')
$$;

CREATE FUNCTION pgreact_api.preview_program(definition jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE diagnostic record;
BEGIN
    IF NOT pgreact_internal.is_window_program(definition) THEN
        RETURN pgreact_internal.preview_program_m16(definition);
    END IF;
    SELECT * INTO diagnostic FROM pgreact_api.validate_program(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M17_PROGRAM_INVALID: % for %', diagnostic.code, diagnostic.object_identity
            USING HINT = diagnostic.hint;
    END IF;
    RETURN jsonb_build_object(
        'contract_version', 6,
        'program', pgreact_internal.normalized_window_program(definition),
        'plan_digest', pgreact_internal.window_plan_digest(definition));
END
$$;

CREATE FUNCTION pgreact_api.deploy_program(definition jsonb, expected_plan_digest text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    diagnostic record;
    actual_digest text;
    rewritten jsonb := definition;
    first_rule jsonb := definition #> '{rules,0}';
    window_item jsonb := definition #> '{rules,0,aggregate_input,window}';
    target_spec pgreact_internal.keyed_derived_relations%ROWTYPE;
    old_program pgreact_internal.window_programs%ROWTYPE;
    has_old boolean := false;
    deployed uuid;
    helper_suffix text := md5((definition ->> 'name') || '@' || (definition ->> 'version'));
    helper_input text := format('pgreact_runtime.m17_input_%s', helper_suffix);
    helper_keys text := format('pgreact_runtime.m17_keys_%s', helper_suffix);
    helper_input_store text := format('pgreact_runtime.m17_input_store_%s', helper_suffix);
    helper_keys_store text := format('pgreact_runtime.m17_keys_store_%s', helper_suffix);
    group_columns name[];
    group_list text;
    join_list text;
    window_column name;
    item record;
    rule_version_id uuid;
    function_name text;
    input_name text := first_rule #>> '{aggregate_input,relation}';
    condition_name text := first_rule ->> 'definition';
    input_oid oid;
    condition_oid oid;
    duration_value bigint;
    lateness_value bigint;
BEGIN
    IF NOT pgreact_internal.is_window_program(definition) THEN
        RETURN pgreact_internal.deploy_program_m16(definition, expected_plan_digest);
    END IF;
    SELECT * INTO diagnostic FROM pgreact_api.validate_program(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M17_PROGRAM_INVALID: % for %', diagnostic.code, diagnostic.object_identity
            USING HINT = diagnostic.hint;
    END IF;
    actual_digest := pgreact_internal.window_plan_digest(definition);
    IF expected_plan_digest IS NOT NULL AND expected_plan_digest <> actual_digest THEN
        RAISE EXCEPTION 'M17_PROGRAM_PREVIEW_STALE'
            USING ERRCODE = '55000',
                  HINT = 'Preview the program again after DDL or deployment changes.';
    END IF;
    SELECT spec.* INTO STRICT target_spec
    FROM pgreact_internal.keyed_derived_relations spec
    WHERE spec.public_name = first_rule ->> 'target';
    group_columns := target_spec.key_columns[1:cardinality(target_spec.key_columns)-1];
    window_column := target_spec.key_columns[cardinality(target_spec.key_columns)];
    SELECT string_agg(format('%I', value), ', ' ORDER BY ordinal),
           string_agg(format('%I', value), ', ' ORDER BY ordinal)
    INTO group_list, join_list
    FROM unnest(group_columns) WITH ORDINALITY column_name(value, ordinal);
    input_oid := to_regclass(input_name);
    condition_oid := to_regclass(condition_name);
    duration_value := pgreact_internal.fixed_interval_us(window_item ->> 'duration', false);
    lateness_value := pgreact_internal.fixed_interval_us(
        window_item ->> 'allowed_lateness', true);
    SELECT prior.* INTO old_program
    FROM pgreact_internal.window_programs prior
    WHERE prior.program_name = definition ->> 'name' AND prior.active
    FOR UPDATE;
    has_old := FOUND;

    EXECUTE format('DROP VIEW IF EXISTS %s CASCADE', helper_input);
    EXECUTE format('DROP VIEW IF EXISTS %s CASCADE', helper_keys);
    EXECUTE format('DROP TABLE IF EXISTS %s CASCADE', helper_input_store);
    EXECUTE format('DROP TABLE IF EXISTS %s CASCADE', helper_keys_store);
    EXECUTE format(
        'CREATE TABLE %s AS SELECT source.*, 0::bigint AS %I FROM %s source WITH NO DATA',
        helper_input_store, window_column, input_oid::regclass);
    EXECUTE format(
        'CREATE TABLE %s AS SELECT %s, %I FROM %s WITH NO DATA',
        helper_keys_store, group_list, window_column, helper_input_store);
    EXECUTE format('CREATE VIEW %s AS SELECT * FROM %s', helper_input, helper_input_store);
    EXECUTE format('CREATE VIEW %s AS SELECT * FROM %s', helper_keys, helper_keys_store);
    EXECUTE format('ALTER TABLE %s OWNER TO %I', helper_input_store, session_user);
    EXECUTE format('ALTER TABLE %s OWNER TO %I', helper_keys_store, session_user);
    EXECUTE format('ALTER VIEW %s OWNER TO %I', helper_input, session_user);
    EXECUTE format('ALTER VIEW %s OWNER TO %I', helper_keys, session_user);
    EXECUTE format('ALTER TABLE %s ADD PRIMARY KEY (%s, %I)',
                   helper_keys_store, group_list, window_column);
    IF has_old THEN
        EXECUTE format('INSERT INTO %s SELECT * FROM %s',
                       helper_keys_store, old_program.helper_keys_name);
        EXECUTE format(
            'INSERT INTO %s SELECT source.*, pgreact_internal.window_ordinal(source.%I, $1) '
            'FROM %s source JOIN %s condition USING (%s)',
            helper_input_store, (window_item ->> 'event_time')::name,
            input_oid::regclass, condition_oid::regclass, join_list)
        USING duration_value;
    END IF;

    FOR item IN SELECT value, ordinal FROM jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY rules(value, ordinal)
    LOOP
        rewritten := jsonb_set(rewritten,
            ARRAY['rules',(item.ordinal - 1)::text,'definition'], to_jsonb(helper_keys));
        rewritten := jsonb_set(rewritten,
            ARRAY['rules',(item.ordinal - 1)::text,'aggregate_input'],
            ((item.value -> 'aggregate_input') - 'window') || jsonb_build_object('relation', helper_input));
    END LOOP;
    deployed := pgreact_internal.deploy_program_m16(rewritten, NULL);
    IF has_old THEN
        UPDATE pgreact_internal.window_programs SET active = false
        WHERE program_version_id = old_program.program_version_id;
    END IF;
    INSERT INTO pgreact_internal.window_programs (
        program_version_id, program_name, program_version, owner_oid, public_definition,
        input_relation_name, condition_relation_name,
        input_definition_digest, input_row_signature,
        condition_definition_digest, condition_row_signature,
        event_time_column, duration_us, allowed_lateness_us, group_columns, window_column,
        helper_input_name, helper_keys_name, helper_input_store_name, helper_keys_store_name,
        max_facts,
        lower_frontier, observed_frontier, requested_watermark, complete_watermark,
        history_floor, last_source_fingerprint, last_observed_fingerprint)
    VALUES (
        deployed, definition ->> 'name', (definition ->> 'version')::integer,
        (SELECT oid FROM pg_roles WHERE rolname = session_user), definition,
        input_name, condition_name,
        pgreact_internal.source_closure_digest(input_oid),
        pgreact_internal.source_row_signature(input_oid),
        pgreact_internal.source_closure_digest(condition_oid),
        pgreact_internal.source_row_signature(condition_oid),
        (window_item ->> 'event_time')::name, duration_value, lateness_value,
        group_columns, window_column, helper_input, helper_keys,
        helper_input_store, helper_keys_store,
        (definition ->> 'max_facts')::bigint,
        CASE WHEN has_old THEN old_program.lower_frontier ELSE 0 END,
        CASE WHEN has_old THEN old_program.observed_frontier ELSE 0 END,
        CASE WHEN has_old THEN old_program.requested_watermark ELSE '-infinity' END,
        CASE WHEN has_old THEN old_program.complete_watermark ELSE '-infinity' END,
        CASE WHEN has_old THEN old_program.history_floor ELSE '-infinity' END,
        CASE WHEN has_old THEN old_program.last_source_fingerprint ELSE sha256(''::bytea) END,
        CASE WHEN has_old THEN old_program.last_observed_fingerprint ELSE sha256(''::bytea) END);

    FOR item IN SELECT value, ordinal FROM jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY rules(value, ordinal)
    LOOP
        SELECT version.rule_version_id INTO STRICT rule_version_id
        FROM pgreact_internal.rules rule
        JOIN pgreact_internal.rule_versions version USING (rule_id)
        WHERE rule.rule_name = item.value ->> 'name' AND version.state = 'ACTIVE';
        function_name := COALESCE(item.value #>> '{aggregate_input,function}', 'COUNT_STAR');
        INSERT INTO pgreact_internal.window_rules (
            program_version_id, rule_version_id, rule_name, rule_version,
            target_relation, aggregate_function, value_expression, comparison, typed_threshold)
        VALUES (
            deployed, rule_version_id, item.value ->> 'name',
            (item.value ->> 'version')::integer, item.value ->> 'target', function_name,
            (item.value #>> '{aggregate_input,expression}')::name,
            item.value #>> '{aggregate_input,comparison}',
            item.value #>> '{aggregate_input,threshold}');
    END LOOP;
    IF has_old THEN
        INSERT INTO pgreact_internal.window_source_rows
        SELECT deployed, row_data, public_window_key, event_time, window_ordinal, occurrences
        FROM pgreact_internal.window_source_rows
        WHERE program_version_id = old_program.program_version_id;
        INSERT INTO pgreact_internal.window_identities
        SELECT deployed, public_window_key, canonical_window_key, window_ordinal,
               window_start, window_end, lateness_boundary, final
        FROM pgreact_internal.window_identities
        WHERE program_version_id = old_program.program_version_id;
        PERFORM pgreact_internal.seed_window_corrections(deployed);
    END IF;
    INSERT INTO pgreact_internal.window_audits(program_version_id, operation, details)
    VALUES (deployed, 'DEPLOY', jsonb_build_object(
        'program', definition ->> 'name', 'version', (definition ->> 'version')::integer,
        'replacement', has_old));
    RETURN deployed;
END
$$;

CREATE FUNCTION pgreact_internal.begin_window_stage()
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    CREATE TEMP TABLE IF NOT EXISTS m17_current_rows (
        program_version_id uuid NOT NULL,
        row_data jsonb NOT NULL,
        public_window_key jsonb NOT NULL,
        event_time timestamptz NOT NULL,
        window_ordinal bigint NOT NULL,
        occurrences bigint NOT NULL,
        PRIMARY KEY (program_version_id, row_data, public_window_key, event_time, window_ordinal)
    ) ON COMMIT DELETE ROWS;
    CREATE TEMP TABLE IF NOT EXISTS m17_affected_windows (
        program_version_id uuid NOT NULL,
        public_window_key jsonb NOT NULL,
        window_ordinal bigint NOT NULL,
        canonical_window_key bytea NOT NULL,
        PRIMARY KEY (program_version_id, public_window_key)
    ) ON COMMIT DELETE ROWS;
    TRUNCATE m17_current_rows, m17_affected_windows;
END
$$;

CREATE FUNCTION pgreact_internal.load_window_rows(target_program uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    group_arguments text;
    join_list text;
    sql text;
BEGIN
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE program_version_id = target_program;
    IF program.input_definition_digest IS DISTINCT FROM
           pgreact_internal.source_closure_digest(to_regclass(program.input_relation_name))
       OR program.input_row_signature IS DISTINCT FROM
           pgreact_internal.source_row_signature(to_regclass(program.input_relation_name))
       OR program.condition_definition_digest IS DISTINCT FROM
           pgreact_internal.source_closure_digest(to_regclass(program.condition_relation_name))
       OR program.condition_row_signature IS DISTINCT FROM
           pgreact_internal.source_row_signature(to_regclass(program.condition_relation_name)) THEN
        RAISE EXCEPTION 'M17_SOURCE_DRIFT: timed input or group source changed for %',
            program.program_name USING ERRCODE = '55000',
            HINT = 'Replace the complete program through its public API.';
    END IF;
    DELETE FROM m17_current_rows WHERE program_version_id = target_program;
    SELECT string_agg(format('to_jsonb(current_row.%I)', value), ', ' ORDER BY ordinal),
           string_agg(format('%I', value), ', ' ORDER BY ordinal)
    INTO group_arguments, join_list
    FROM unnest(program.group_columns) WITH ORDINALITY column_name(value, ordinal);
    group_arguments := group_arguments || format(', to_jsonb(current_row.%I)', program.window_column);
    sql := format(
        'INSERT INTO pg_temp.m17_current_rows '
        '(program_version_id,row_data,public_window_key,event_time,window_ordinal,occurrences) '
        'SELECT $1, row_data, public_window_key, event_time, window_ordinal, count(*) '
        'FROM (SELECT to_jsonb(current_row) AS row_data, jsonb_build_array(%s) AS public_window_key, '
        'current_row.%I AS event_time, current_row.%I AS window_ordinal '
        'FROM (SELECT source.*, pgreact_internal.window_ordinal(source.%I, $2) AS %I '
        'FROM %s source JOIN %s condition USING (%s)) current_row) rows '
        'GROUP BY row_data, public_window_key, event_time, window_ordinal',
        group_arguments, program.event_time_column, program.window_column,
        program.event_time_column, program.window_column,
        to_regclass(program.input_relation_name), to_regclass(program.condition_relation_name), join_list);
    EXECUTE sql USING target_program, program.duration_us;
END
$$;

CREATE FUNCTION pgreact_internal.staged_window_fingerprint(target_program uuid)
RETURNS bytea
LANGUAGE SQL
STABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT sha256(convert_to(COALESCE(string_agg(
        row_data::text || ':' || public_window_key::text || ':' ||
        event_time::text || ':' || occurrences::text, E'\n'
        ORDER BY public_window_key::text, event_time, row_data::text), ''), 'UTF8'))
    FROM pg_temp.m17_current_rows WHERE program_version_id = $1
$$;

CREATE FUNCTION pgreact_internal.stage_differs(target_program uuid)
RETURNS boolean
LANGUAGE SQL
STABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT EXISTS (
        SELECT 1
        FROM pg_temp.m17_current_rows current_row
        FULL JOIN pgreact_internal.window_source_rows previous
          ON previous.program_version_id = $1
         AND current_row.program_version_id = previous.program_version_id
         AND current_row.row_data = previous.row_data
         AND current_row.public_window_key = previous.public_window_key
         AND current_row.event_time = previous.event_time
         AND current_row.window_ordinal = previous.window_ordinal
        WHERE COALESCE(current_row.program_version_id, previous.program_version_id) = $1
          AND current_row.occurrences IS DISTINCT FROM previous.occurrences)
$$;

CREATE FUNCTION pgreact_internal.prepare_window_program(target_program uuid)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    fingerprint bytea;
    affected_count bigint;
    state_count bigint;
    rule_count bigint;
    late record;
    group_list text;
    join_list text;
BEGIN
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE program_version_id = target_program FOR UPDATE;
    PERFORM pgreact_internal.load_window_rows(target_program);
    fingerprint := pgreact_internal.staged_window_fingerprint(target_program);
    IF program.barrier IS NOT NULL THEN
        IF fingerprint IS DISTINCT FROM program.last_observed_fingerprint THEN
            UPDATE pgreact_internal.window_programs
            SET observed_frontier = observed_frontier + 1,
                last_observed_fingerprint = fingerprint
            WHERE program_version_id = target_program;
        END IF;
        RETURN 'barrier';
    END IF;
    IF NOT pgreact_internal.stage_differs(target_program) THEN
        RETURN 'unchanged';
    END IF;
    IF fingerprint IS DISTINCT FROM program.last_observed_fingerprint THEN
        program.observed_frontier := program.observed_frontier + 1;
    END IF;
    WITH changed AS (
        SELECT current_row.public_window_key AS current_key,
               current_row.window_ordinal AS current_ordinal,
               current_row.event_time AS current_time,
               previous.public_window_key AS previous_key,
               previous.window_ordinal AS previous_ordinal,
               previous.event_time AS previous_time
        FROM pg_temp.m17_current_rows current_row
        FULL JOIN pgreact_internal.window_source_rows previous
          ON previous.program_version_id = target_program
         AND current_row.program_version_id = previous.program_version_id
         AND current_row.row_data = previous.row_data
         AND current_row.public_window_key = previous.public_window_key
         AND current_row.event_time = previous.event_time
         AND current_row.window_ordinal = previous.window_ordinal
        WHERE COALESCE(current_row.program_version_id, previous.program_version_id) = target_program
          AND current_row.occurrences IS DISTINCT FROM previous.occurrences
    ), affected AS (
        SELECT current_key AS public_window_key, current_ordinal AS window_ordinal
        FROM changed WHERE current_key IS NOT NULL
        UNION
        SELECT previous_key, previous_ordinal FROM changed WHERE previous_key IS NOT NULL
    )
    INSERT INTO pg_temp.m17_affected_windows
    SELECT target_program, public_window_key, window_ordinal,
           pgreact_internal.window_key_bytes(public_window_key)
    FROM affected ON CONFLICT DO NOTHING;

    SELECT affected.public_window_key, affected.window_ordinal,
           COALESCE(current_row.event_time, previous.event_time) AS event_time,
           pgreact_internal.window_bound(affected.window_ordinal, program.duration_us)
             + ((program.duration_us + program.allowed_lateness_us)::text || ' microseconds')::interval
             AS lateness_boundary
    INTO late
    FROM pg_temp.m17_affected_windows affected
    LEFT JOIN LATERAL (
        SELECT event_time FROM pg_temp.m17_current_rows row_value
        WHERE row_value.program_version_id = target_program
          AND row_value.public_window_key = affected.public_window_key
          AND NOT EXISTS (
              SELECT 1 FROM pgreact_internal.window_source_rows previous_row
              WHERE previous_row.program_version_id = target_program
                AND previous_row.row_data = row_value.row_data
                AND previous_row.public_window_key = row_value.public_window_key
                AND previous_row.event_time = row_value.event_time
                AND previous_row.window_ordinal = row_value.window_ordinal
                AND previous_row.occurrences = row_value.occurrences)
        ORDER BY event_time LIMIT 1) current_row ON true
    LEFT JOIN LATERAL (
        SELECT event_time FROM pgreact_internal.window_source_rows row_value
        WHERE row_value.program_version_id = target_program
          AND row_value.public_window_key = affected.public_window_key
          AND NOT EXISTS (
              SELECT 1 FROM pg_temp.m17_current_rows current_value
              WHERE current_value.program_version_id = target_program
                AND current_value.row_data = row_value.row_data
                AND current_value.public_window_key = row_value.public_window_key
                AND current_value.event_time = row_value.event_time
                AND current_value.window_ordinal = row_value.window_ordinal
                AND current_value.occurrences = row_value.occurrences)
        ORDER BY event_time LIMIT 1) previous ON true
    WHERE affected.program_version_id = target_program
      AND pgreact_internal.window_bound(affected.window_ordinal, program.duration_us)
            + ((program.duration_us + program.allowed_lateness_us)::text || ' microseconds')::interval
          <= program.complete_watermark
    ORDER BY affected.canonical_window_key LIMIT 1;
    IF FOUND THEN
        UPDATE pgreact_internal.window_programs
        SET barrier = 'LATE_INPUT', observed_frontier = program.observed_frontier,
            last_observed_fingerprint = fingerprint
        WHERE program_version_id = target_program;
        INSERT INTO pgreact_internal.window_diagnostics (
            code,severity,object_identity,sqlstate,message,hint,details,program_version_id)
        VALUES (
            'M17_INPUT_FINALIZED','ERROR',
            program.program_name || '/' || program.input_relation_name || '.' || program.event_time_column,
            '55000', 'timed input changed finalized window ' ||
                replace(late.public_window_key::text, ' ', ''),
            'Restore the authoritative input to the finalized aggregate, then reconcile the program.',
            jsonb_build_object(
                'complete_watermark', to_char(program.complete_watermark AT TIME ZONE 'UTC',
                    'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
                'event_time', to_char(late.event_time AT TIME ZONE 'UTC',
                    'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
                'lateness_boundary', to_char(late.lateness_boundary AT TIME ZONE 'UTC',
                    'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
                'lower_frontier', program.observed_frontier,
                'window_key', late.public_window_key), target_program);
        RETURN 'late';
    END IF;
    SELECT count(*) INTO affected_count FROM pg_temp.m17_affected_windows
    WHERE program_version_id = target_program;
    SELECT count(*) INTO rule_count FROM pgreact_internal.window_rules
    WHERE program_version_id = target_program;
    SELECT count(*) INTO state_count FROM (
        SELECT public_window_key FROM pgreact_internal.window_identities
        WHERE program_version_id = target_program
        UNION
        SELECT public_window_key FROM pg_temp.m17_current_rows
        WHERE program_version_id = target_program) states;
    IF state_count * rule_count > program.max_facts
       OR affected_count * rule_count > program.max_facts THEN
        RAISE EXCEPTION 'M17_RESOURCE_LIMIT: window states or corrections require %, max_facts is %',
            greatest(state_count * rule_count, affected_count * rule_count), program.max_facts
            USING ERRCODE = '54000';
    END IF;
    SELECT string_agg(format('%I', value), ', ' ORDER BY ordinal),
           string_agg(format('%I', value), ', ' ORDER BY ordinal)
    INTO group_list, join_list
    FROM unnest(program.group_columns) WITH ORDINALITY column_name(value, ordinal);
    EXECUTE format('TRUNCATE %s', program.helper_input_store_name);
    EXECUTE format(
        'INSERT INTO %s SELECT source.*, pgreact_internal.window_ordinal(source.%I, $1) '
        'FROM %s source JOIN %s condition USING (%s)',
        program.helper_input_store_name, program.event_time_column,
        to_regclass(program.input_relation_name), to_regclass(program.condition_relation_name), join_list)
    USING program.duration_us;
    EXECUTE format(
        'INSERT INTO %s SELECT DISTINCT %s, %I FROM %s ON CONFLICT DO NOTHING',
        program.helper_keys_store_name, group_list, program.window_column,
        program.helper_input_store_name);
    INSERT INTO pgreact_internal.window_identities (
        program_version_id,public_window_key,canonical_window_key,window_ordinal,
        window_start,window_end,lateness_boundary)
    SELECT target_program, affected.public_window_key, affected.canonical_window_key,
           affected.window_ordinal,
           pgreact_internal.window_bound(affected.window_ordinal, program.duration_us),
           pgreact_internal.window_bound(affected.window_ordinal, program.duration_us)
             + (program.duration_us::text || ' microseconds')::interval,
           pgreact_internal.window_bound(affected.window_ordinal, program.duration_us)
             + ((program.duration_us + program.allowed_lateness_us)::text || ' microseconds')::interval
    FROM pg_temp.m17_affected_windows affected
    WHERE affected.program_version_id = target_program
    ON CONFLICT (program_version_id, public_window_key) DO NOTHING;
    UPDATE pgreact_internal.window_programs
    SET observed_frontier = program.observed_frontier,
        last_observed_fingerprint = fingerprint
    WHERE program_version_id = target_program;
    RETURN 'changed';
END
$$;

CREATE FUNCTION pgreact_internal.append_window_corrections(target_program uuid, seed boolean)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    state record;
    previous record;
    old_generation integer;
    next_generation integer;
    inserted_count bigint := 0;
    row_count bigint;
BEGIN
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE program_version_id = target_program;
    FOR state IN
        SELECT rules.rule_version_id, rules.rule_name, rules.rule_version,
               rules.target_relation, identity.public_window_key,
               identity.public_window_key -
                   (jsonb_array_length(identity.public_window_key) - 1) AS public_group_key,
               identity.window_ordinal,
               evidence.canonical_group_key, evidence.exact_value, evidence.truth_result
        FROM pgreact_internal.window_rules rules
        JOIN pgreact_internal.aggregate_dependency_evidence evidence
          ON evidence.program_version_id = rules.program_version_id
         AND evidence.rule_version_id = rules.rule_version_id AND evidence.active
        JOIN pgreact_internal.window_identities identity
          ON identity.program_version_id = rules.program_version_id
         AND identity.public_window_key = evidence.public_group_key
        JOIN pg_temp.m17_affected_windows affected
          ON affected.program_version_id = identity.program_version_id
         AND affected.public_window_key = identity.public_window_key
        WHERE rules.program_version_id = target_program
        ORDER BY
            (identity.public_window_key -
                (jsonb_array_length(identity.public_window_key) - 1))::text,
            identity.window_ordinal,
            rules.rule_name
    LOOP
        UPDATE pgreact_internal.window_identities
        SET canonical_window_key = state.canonical_group_key
        WHERE program_version_id = target_program
          AND public_window_key = state.public_window_key;
        SELECT correction.after_value, correction.after_truth,
               correction.support_generation
        INTO previous
        FROM pgreact_internal.window_corrections correction
        WHERE correction.program_version_id = target_program
          AND correction.rule_name = state.rule_name
          AND correction.public_window_key = state.public_window_key
        ORDER BY correction.lower_frontier DESC, correction.correction_order DESC LIMIT 1;
        old_generation := COALESCE(previous.support_generation, 0);
        IF seed AND NOT FOUND THEN
            SELECT correction.support_generation INTO old_generation
            FROM pgreact_internal.window_corrections correction
            JOIN pgreact_internal.window_programs prior
              ON prior.program_version_id = correction.program_version_id
            WHERE prior.program_name = program.program_name
              AND prior.program_version < program.program_version
              AND correction.rule_name = state.rule_name
              AND correction.public_window_key = state.public_window_key
            ORDER BY prior.program_version DESC, correction.lower_frontier DESC,
                     correction.correction_order DESC LIMIT 1;
            old_generation := COALESCE(old_generation, 0);
        END IF;
        next_generation := CASE
            WHEN state.truth_result IS TRUE AND previous.after_truth IS NOT TRUE AND NOT seed
                THEN old_generation + 1
            WHEN state.truth_result IS TRUE AND seed AND old_generation = 0 THEN 1
            ELSE old_generation
        END;
        INSERT INTO pgreact_internal.window_corrections (
            correction_identity,program_version_id,program_name,program_version,
            rule_version_id,rule_name,rule_version,target_relation,
            public_window_key,public_group_key,window_ordinal,
            canonical_window_key,lower_frontier,
            before_value,after_value,before_truth,after_truth,support_generation)
        VALUES (
            format('%s@%s/%s@%s/%s/F%s', program.program_name, program.program_version,
                   state.rule_name, state.rule_version,
                   replace(state.public_window_key::text, ' ', ''),
                   program.observed_frontier),
            target_program,program.program_name,program.program_version,
            state.rule_version_id,state.rule_name,state.rule_version,state.target_relation,
            state.public_window_key,state.public_group_key,state.window_ordinal,
            state.canonical_group_key,program.observed_frontier,
            CASE WHEN seed THEN NULL ELSE previous.after_value END,state.exact_value,
            CASE WHEN seed THEN NULL ELSE previous.after_truth END,state.truth_result,next_generation)
        ON CONFLICT (correction_identity) DO NOTHING;
        GET DIAGNOSTICS row_count = ROW_COUNT;
        IF row_count = 0 THEN CONTINUE; END IF;
        IF NOT seed AND state.truth_result IS TRUE AND previous.after_truth IS NOT TRUE THEN
            INSERT INTO pgreact_internal.window_lifecycle (
                program_version_id,lower_frontier,public_window_key,canonical_window_key,
                rule_name,event_kind,support_generation)
            VALUES (target_program,program.observed_frontier,state.public_window_key,
                    state.canonical_group_key,state.rule_name,'ACTIVATE',next_generation);
        ELSIF NOT seed AND previous.after_truth IS TRUE AND state.truth_result IS NOT TRUE THEN
            INSERT INTO pgreact_internal.window_lifecycle (
                program_version_id,lower_frontier,public_window_key,canonical_window_key,
                rule_name,event_kind,support_generation)
            VALUES (target_program,program.observed_frontier,state.public_window_key,
                    state.canonical_group_key,state.rule_name,'DEACTIVATE',old_generation);
        END IF;
        inserted_count := inserted_count + row_count;
    END LOOP;
    RETURN inserted_count;
END
$$;

CREATE FUNCTION pgreact_internal.seed_window_corrections(target_program uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    PERFORM pgreact_internal.begin_window_stage();
    INSERT INTO pg_temp.m17_affected_windows
    SELECT program_version_id, public_window_key, window_ordinal, canonical_window_key
    FROM pgreact_internal.window_identities WHERE program_version_id = target_program;
    IF EXISTS (SELECT 1 FROM pg_temp.m17_affected_windows
               WHERE program_version_id = target_program)
       AND (SELECT observed_frontier FROM pgreact_internal.window_programs
            WHERE program_version_id = target_program) > 0 THEN
        PERFORM pgreact_internal.append_window_corrections(target_program, true);
    END IF;
END
$$;

CREATE FUNCTION pgreact_internal.finish_window_program(target_program uuid)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE fingerprint bytea; correction_count bigint;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_temp.m17_affected_windows
                   WHERE program_version_id = target_program) THEN
        RETURN 0;
    END IF;
    correction_count := pgreact_internal.append_window_corrections(target_program, false);
    fingerprint := pgreact_internal.staged_window_fingerprint(target_program);
    DELETE FROM pgreact_internal.window_source_rows WHERE program_version_id = target_program;
    INSERT INTO pgreact_internal.window_source_rows
    SELECT program_version_id,row_data,public_window_key,event_time,window_ordinal,occurrences
    FROM pg_temp.m17_current_rows WHERE program_version_id = target_program;
    UPDATE pgreact_internal.window_programs
    SET lower_frontier = observed_frontier,
        last_source_fingerprint = fingerprint,
        last_observed_fingerprint = fingerprint
    WHERE program_version_id = target_program;
    RETURN correction_count;
END
$$;

CREATE FUNCTION pgreact_internal.advance_window_watermark(target_program uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    boundary timestamptz;
    identity_count bigint;
    batch_limit integer := current_setting('pg_react.batch_size')::integer;
    finalized jsonb;
BEGIN
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE program_version_id = target_program FOR UPDATE;
    IF program.barrier IS NOT NULL OR program.complete_watermark >= program.requested_watermark THEN
        RETURN jsonb_build_object('status', CASE WHEN program.barrier IS NULL THEN 'complete' ELSE 'blocked' END,
                                  'finalized', '[]'::jsonb);
    END IF;
    SELECT min(lateness_boundary) INTO boundary
    FROM pgreact_internal.window_identities
    WHERE program_version_id = target_program AND NOT final
      AND lateness_boundary > program.complete_watermark
      AND lateness_boundary <= program.requested_watermark;
    IF boundary IS NULL THEN
        UPDATE pgreact_internal.window_programs
        SET complete_watermark = requested_watermark
        WHERE program_version_id = target_program;
        RETURN jsonb_build_object('status','complete','finalized','[]'::jsonb);
    END IF;
    SELECT count(*) INTO identity_count FROM pgreact_internal.window_identities
    WHERE program_version_id = target_program AND NOT final AND lateness_boundary = boundary;
    IF identity_count > batch_limit THEN
        INSERT INTO pgreact_internal.window_diagnostics (
            code,severity,object_identity,sqlstate,message,hint,details,program_version_id)
        VALUES ('M17_WATERMARK_BATCH_LIMIT','ERROR',program.program_name,'54000',
            'earliest lateness boundary exceeds pg_react.batch_size',
            'Raise pg_react.batch_size to at least the required minimum and retry.',
            jsonb_build_object('required_minimum',identity_count,'batch_size',batch_limit,
                               'lateness_boundary',boundary),target_program);
        RETURN jsonb_build_object('status','failed','code','M17_WATERMARK_BATCH_LIMIT',
                                  'finalized','[]'::jsonb);
    END IF;
    IF current_setting('pg_react.m17_fail_watermark', true) = 'on' THEN
        INSERT INTO pgreact_internal.window_diagnostics (
            code,severity,object_identity,sqlstate,message,hint,details,program_version_id)
        VALUES ('M17_WATERMARK_BATCH_FAILED','ERROR',program.program_name,'XX000',
            'injected watermark advancement failure',
            'Clear pg_react.m17_fail_watermark and repeat the requested target.',
            jsonb_build_object('complete_watermark',program.complete_watermark,
                               'requested_watermark',program.requested_watermark),target_program);
        RETURN jsonb_build_object('status','failed','code','M17_WATERMARK_BATCH_FAILED',
                                  'finalized','[]'::jsonb);
    END IF;
    WITH finalized_rows AS (
        UPDATE pgreact_internal.window_identities
        SET final = true
        WHERE program_version_id = target_program AND NOT final AND lateness_boundary = boundary
        RETURNING public_window_key,canonical_window_key,lateness_boundary
    ), recorded AS (
        INSERT INTO pgreact_internal.window_finalizations (
            finalization_identity,program_version_id,public_window_key,
            canonical_window_key,lateness_boundary)
        SELECT replace(public_window_key::text, ' ', '') || '@' ||
               to_char(lateness_boundary AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
               target_program,public_window_key,canonical_window_key,lateness_boundary
        FROM finalized_rows ON CONFLICT DO NOTHING
        RETURNING public_window_key,canonical_window_key
    )
    SELECT COALESCE(jsonb_agg(public_window_key ORDER BY canonical_window_key),'[]'::jsonb)
    INTO finalized FROM recorded;
    UPDATE pgreact_internal.window_programs SET complete_watermark = boundary
    WHERE program_version_id = target_program;
    RETURN jsonb_build_object(
        'status',CASE WHEN boundary = program.requested_watermark THEN 'complete' ELSE 'pending' END,
        'finalized',finalized);
END
$$;

ALTER FUNCTION pgreact_api.run(timestamptz) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.run(timestamptz) RENAME TO run_m16;

CREATE FUNCTION pgreact_api.run(sampled_time timestamptz DEFAULT clock_timestamp())
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    result jsonb;
    program record;
    prepare_status text;
    summaries jsonb := '[]'::jsonb;
    advance_result jsonb;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pgreact_internal.window_programs WHERE active) THEN
        RETURN pgreact_internal.run_m16(sampled_time);
    END IF;
    PERFORM pg_advisory_xact_lock(5788046901200000);
    PERFORM pgreact_internal.begin_window_stage();
    FOR program IN SELECT program_version_id,program_name
        FROM pgreact_internal.window_programs WHERE active ORDER BY program_name
    LOOP
        prepare_status := pgreact_internal.prepare_window_program(program.program_version_id);
        summaries := summaries || jsonb_build_array(jsonb_build_object(
            'program',program.program_name,'maintenance',prepare_status));
    END LOOP;
    result := pgreact_internal.run_m16(sampled_time);
    FOR program IN SELECT program_version_id,program_name
        FROM pgreact_internal.window_programs WHERE active AND barrier IS NULL ORDER BY program_name
    LOOP
        PERFORM pgreact_internal.finish_window_program(program.program_version_id);
        advance_result := pgreact_internal.advance_window_watermark(program.program_version_id);
        summaries := summaries || jsonb_build_array(
            jsonb_build_object('program',program.program_name,'watermark',advance_result));
    END LOOP;
    RETURN jsonb_set(result, '{contract_version}', '6'::jsonb)
        || jsonb_build_object('windows',summaries);
END
$$;

CREATE FUNCTION pgreact_api.request_watermark(
    program_name text,
    input_relation text,
    event_time_column name,
    target timestamptz
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE program pgreact_internal.window_programs%ROWTYPE;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M17_WATERMARK_UNAUTHORIZED: % is not the configured operator', session_user
            USING ERRCODE = '42501';
    END IF;
    IF pg_is_in_recovery() THEN
        RAISE EXCEPTION 'M17_WATERMARK_STANDBY: watermark requests require a writable primary'
            USING ERRCODE = '25006';
    END IF;
    IF target IS NULL OR NOT isfinite(target) THEN
        RAISE EXCEPTION 'M17_WATERMARK_TARGET_INVALID: target must be finite and non-null'
            USING ERRCODE = '22008';
    END IF;
    IF cardinality(parse_ident(input_relation, true)) <> 2 THEN
        RAISE EXCEPTION 'M17_WATERMARK_INPUT_UNQUALIFIED: %', input_relation
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO program FROM pgreact_internal.window_programs
    WHERE window_programs.program_name = request_watermark.program_name
      AND active FOR UPDATE;
    IF NOT FOUND OR to_regclass(program.input_relation_name) IS DISTINCT FROM to_regclass(input_relation)
       OR program.event_time_column IS DISTINCT FROM request_watermark.event_time_column THEN
        RAISE EXCEPTION 'M17_WATERMARK_INPUT_UNKNOWN: %.%', input_relation, event_time_column
            USING ERRCODE = '22023';
    END IF;
    IF target < program.requested_watermark THEN
        RAISE EXCEPTION 'M17_WATERMARK_BACKWARD: target % precedes requested watermark %',
            target, program.requested_watermark USING ERRCODE = '22023';
    END IF;
    IF target = program.requested_watermark THEN RETURN; END IF;
    UPDATE pgreact_internal.window_programs SET requested_watermark = target
    WHERE program_version_id = program.program_version_id;
    INSERT INTO pgreact_internal.window_audits(program_version_id,operation,details)
    VALUES (program.program_version_id,'REQUEST_WATERMARK',
            jsonb_build_object('previous',program.requested_watermark,'target',target));
END
$$;

CREATE FUNCTION pgreact_api.watermark_status(program_name text)
RETURNS TABLE(
    input_relation text,
    event_time_column name,
    requested_watermark timestamptz,
    complete_watermark timestamptz,
    history_floor timestamptz,
    status text,
    barrier text
)
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT input_relation_name,event_time_column,requested_watermark,complete_watermark,
           history_floor,
           CASE WHEN barrier IS NOT NULL THEN 'blocked'
                WHEN complete_watermark < requested_watermark THEN 'pending' ELSE 'complete' END,
           barrier
    FROM pgreact_internal.window_programs
    WHERE window_programs.program_name = $1 AND active
$$;

CREATE FUNCTION pgreact_api.export_window_state(program_name text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE program pgreact_internal.window_programs%ROWTYPE;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M17_RECOVERY_UNAUTHORIZED: % is not the configured operator',session_user
            USING ERRCODE='42501';
    END IF;
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE window_programs.program_name=export_window_state.program_name AND active;
    RETURN jsonb_build_object(
        'contract_version',6,
        'program',jsonb_build_object(
            'name',program.program_name,'version',program.program_version,
            'lower_frontier',program.lower_frontier,'observed_frontier',program.observed_frontier,
            'engine_frontier',(SELECT frontier FROM pgreact_internal.derivation_program_versions
                               WHERE program_version_id=program.program_version_id),
            'requested_watermark',program.requested_watermark,
            'complete_watermark',program.complete_watermark,
            'history_floor',program.history_floor,'barrier',program.barrier,
            'source_fingerprint',encode(program.last_source_fingerprint,'hex'),
            'observed_fingerprint',encode(program.last_observed_fingerprint,'hex')),
        'source_rows',COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'row_data',row_data,'public_window_key',public_window_key,
            'event_time',event_time,'window_ordinal',window_ordinal,'occurrences',occurrences)
            ORDER BY public_window_key,event_time,row_data::text)
            FROM pgreact_internal.window_source_rows
            WHERE program_version_id=program.program_version_id),'[]'::jsonb),
        'identities',COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'public_window_key',public_window_key,
            'canonical_window_key',encode(canonical_window_key,'hex'),
            'window_ordinal',window_ordinal,'window_start',window_start,'window_end',window_end,
            'lateness_boundary',lateness_boundary,'final',final)
            ORDER BY window_ordinal,public_window_key)
            FROM pgreact_internal.window_identities
            WHERE program_version_id=program.program_version_id),'[]'::jsonb),
        'evidence',COALESCE((SELECT jsonb_agg(to_jsonb(evidence)
            ORDER BY rule_name,window_ordinal)
            FROM pgreact.window_evidence evidence
            WHERE evidence.program_name=program.program_name),'[]'::jsonb),
        'corrections',COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'correction_order',correction_order,'correction_identity',correction_identity,
            'rule_name',rule_name,'rule_version',rule_version,'target_relation',target_relation,
            'public_window_key',public_window_key,'public_group_key',public_group_key,
            'window_ordinal',window_ordinal,'canonical_window_key',encode(canonical_window_key,'hex'),
            'lower_frontier',lower_frontier,'before_value',before_value,'after_value',after_value,
            'before_truth',before_truth,'after_truth',after_truth,
            'support_generation',support_generation,'created_at',created_at)
            ORDER BY correction_order)
            FROM pgreact_internal.window_corrections
            WHERE program_version_id=program.program_version_id),'[]'::jsonb),
        'finalizations',COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'finalization_identity',finalization_identity,'public_window_key',public_window_key,
            'canonical_window_key',encode(canonical_window_key,'hex'),
            'lateness_boundary',lateness_boundary,'finalized_at',finalized_at)
            ORDER BY lateness_boundary,public_window_key)
            FROM pgreact_internal.window_finalizations
            WHERE program_version_id=program.program_version_id),'[]'::jsonb),
        'lifecycle',COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'lifecycle_order',lifecycle_order,'lower_frontier',lower_frontier,
            'public_window_key',public_window_key,
            'canonical_window_key',encode(canonical_window_key,'hex'),
            'rule_name',rule_name,'event_kind',event_kind,
            'support_generation',support_generation) ORDER BY lifecycle_order)
            FROM pgreact_internal.window_lifecycle
            WHERE program_version_id=program.program_version_id),'[]'::jsonb),
        'diagnostics',COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'diagnostic_order',diagnostic_order,'contract_version',contract_version,'code',code,
            'severity',severity,'object_identity',object_identity,'sqlstate',sqlstate,
            'message',message,'hint',hint,'details',details,'created_at',created_at)
            ORDER BY diagnostic_order)
            FROM pgreact_internal.window_diagnostics
            WHERE program_version_id=program.program_version_id),'[]'::jsonb),
        'audits',COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'audit_order',audit_order,'operation',operation,'actor',actor,
            'details',details,'created_at',created_at) ORDER BY audit_order)
            FROM pgreact_internal.window_audits
            WHERE program_version_id=program.program_version_id),'[]'::jsonb));
END
$$;

CREATE FUNCTION pgreact_api.restore_window_state(recovery_state jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    item jsonb;
    rule_id uuid;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M17_RECOVERY_UNAUTHORIZED: % is not the configured operator',session_user
            USING ERRCODE='42501';
    END IF;
    IF recovery_state ->> 'contract_version' <> '6'
       OR jsonb_typeof(recovery_state -> 'program') IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M17_RECOVERY_STATE_INVALID: expected contract version 6'
            USING ERRCODE='22023';
    END IF;
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE window_programs.program_name=recovery_state #>> '{program,name}' AND active FOR UPDATE;
    IF program.program_version <> (recovery_state #>> '{program,version}')::integer THEN
        RAISE EXCEPTION 'M17_RECOVERY_STATE_INVALID: active program version differs'
            USING ERRCODE='22023';
    END IF;
    PERFORM pg_advisory_xact_lock(5788046901200000);
    DELETE FROM pgreact_internal.window_corrections WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_finalizations WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_lifecycle WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_diagnostics WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_audits WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_source_rows WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_identities WHERE program_version_id=program.program_version_id;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'source_rows') value LOOP
        INSERT INTO pgreact_internal.window_source_rows VALUES (
            program.program_version_id,item -> 'row_data',item -> 'public_window_key',
            (item ->> 'event_time')::timestamptz,(item ->> 'window_ordinal')::bigint,
            (item ->> 'occurrences')::bigint);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'identities') value LOOP
        INSERT INTO pgreact_internal.window_identities VALUES (
            program.program_version_id,item -> 'public_window_key',
            decode(item ->> 'canonical_window_key','hex'),(item ->> 'window_ordinal')::bigint,
            (item ->> 'window_start')::timestamptz,(item ->> 'window_end')::timestamptz,
            (item ->> 'lateness_boundary')::timestamptz,(item ->> 'final')::boolean);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'corrections') value LOOP
        SELECT rules.rule_version_id INTO STRICT rule_id FROM pgreact_internal.window_rules rules
        WHERE rules.program_version_id=program.program_version_id
          AND rules.rule_name=item ->> 'rule_name';
        INSERT INTO pgreact_internal.window_corrections (
            correction_order,correction_identity,program_version_id,program_name,program_version,
            rule_version_id,rule_name,rule_version,target_relation,public_window_key,
            public_group_key,window_ordinal,canonical_window_key,lower_frontier,
            before_value,after_value,before_truth,after_truth,support_generation,created_at)
        OVERRIDING SYSTEM VALUE VALUES (
            (item ->> 'correction_order')::bigint,item ->> 'correction_identity',
            program.program_version_id,program.program_name,program.program_version,rule_id,
            item ->> 'rule_name',(item ->> 'rule_version')::integer,item ->> 'target_relation',
            item -> 'public_window_key',item -> 'public_group_key',
            (item ->> 'window_ordinal')::bigint,decode(item ->> 'canonical_window_key','hex'),
            (item ->> 'lower_frontier')::bigint,item ->> 'before_value',item ->> 'after_value',
            (item ->> 'before_truth')::boolean,(item ->> 'after_truth')::boolean,
            (item ->> 'support_generation')::integer,(item ->> 'created_at')::timestamptz);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'finalizations') value LOOP
        INSERT INTO pgreact_internal.window_finalizations VALUES (
            item ->> 'finalization_identity',program.program_version_id,
            item -> 'public_window_key',decode(item ->> 'canonical_window_key','hex'),
            (item ->> 'lateness_boundary')::timestamptz,(item ->> 'finalized_at')::timestamptz);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'lifecycle') value LOOP
        INSERT INTO pgreact_internal.window_lifecycle (
            lifecycle_order,program_version_id,lower_frontier,public_window_key,
            canonical_window_key,rule_name,event_kind,support_generation)
        OVERRIDING SYSTEM VALUE VALUES (
            (item ->> 'lifecycle_order')::bigint,program.program_version_id,
            (item ->> 'lower_frontier')::bigint,item -> 'public_window_key',
            decode(item ->> 'canonical_window_key','hex'),item ->> 'rule_name',
            item ->> 'event_kind',(item ->> 'support_generation')::integer);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'diagnostics') value LOOP
        INSERT INTO pgreact_internal.window_diagnostics (
            diagnostic_order,contract_version,code,severity,object_identity,sqlstate,
            message,hint,details,program_version_id,created_at)
        OVERRIDING SYSTEM VALUE VALUES (
            (item ->> 'diagnostic_order')::bigint,(item ->> 'contract_version')::integer,
            item ->> 'code',item ->> 'severity',item ->> 'object_identity',item ->> 'sqlstate',
            item ->> 'message',item ->> 'hint',item -> 'details',program.program_version_id,
            (item ->> 'created_at')::timestamptz);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'audits') value LOOP
        INSERT INTO pgreact_internal.window_audits (
            audit_order,program_version_id,operation,actor,details,created_at)
        OVERRIDING SYSTEM VALUE VALUES (
            (item ->> 'audit_order')::bigint,program.program_version_id,item ->> 'operation',
            (item ->> 'actor')::name,item -> 'details',(item ->> 'created_at')::timestamptz);
    END LOOP;
    UPDATE pgreact_internal.window_programs SET
        lower_frontier=(recovery_state #>> '{program,lower_frontier}')::bigint,
        observed_frontier=(recovery_state #>> '{program,observed_frontier}')::bigint,
        requested_watermark=(recovery_state #>> '{program,requested_watermark}')::timestamptz,
        complete_watermark=(recovery_state #>> '{program,complete_watermark}')::timestamptz,
        history_floor=(recovery_state #>> '{program,history_floor}')::timestamptz,
        barrier=(recovery_state #>> '{program,barrier}')::text,
        last_source_fingerprint=decode(recovery_state #>> '{program,source_fingerprint}','hex'),
        last_observed_fingerprint=decode(recovery_state #>> '{program,observed_fingerprint}','hex')
    WHERE program_version_id=program.program_version_id;
    UPDATE pgreact_internal.derivation_program_versions
    SET frontier=(recovery_state #>> '{program,engine_frontier}')::bigint
    WHERE program_version_id=program.program_version_id;
    PERFORM setval(pg_get_serial_sequence('pgreact_internal.window_corrections','correction_order'),
        COALESCE((SELECT max(correction_order) FROM pgreact_internal.window_corrections),1),true);
    PERFORM setval(pg_get_serial_sequence('pgreact_internal.window_lifecycle','lifecycle_order'),
        COALESCE((SELECT max(lifecycle_order) FROM pgreact_internal.window_lifecycle),1),true);
    PERFORM setval(pg_get_serial_sequence('pgreact_internal.window_diagnostics','diagnostic_order'),
        COALESCE((SELECT max(diagnostic_order) FROM pgreact_internal.window_diagnostics),1),true);
    PERFORM setval(pg_get_serial_sequence('pgreact_internal.window_audits','audit_order'),
        COALESCE((SELECT max(audit_order) FROM pgreact_internal.window_audits),1),true);
END
$$;

CREATE VIEW pgreact.window_evidence AS
SELECT
    program.program_name,
    program.program_version,
    rules.rule_name,
    rules.rule_version,
    rules.target_relation,
    identity.public_window_key,
    identity.window_ordinal,
    program.input_relation_name,
    rules.aggregate_function,
    rules.value_expression,
    aggregate_rule.input_type_name,
    aggregate_rule.result_type_name,
    program.event_time_column,
    program.duration_us,
    'UTC_EPOCH'::text AS alignment,
    identity.window_start,
    identity.window_end,
    program.requested_watermark,
    program.complete_watermark,
    identity.lateness_boundary,
    identity.final AS is_final,
    latest.after_value AS exact_value,
    rules.comparison,
    rules.typed_threshold,
    latest.correction_identity AS last_correction_identity,
    latest.lower_frontier AS last_correction_frontier,
    program.lower_frontier AS program_lower_frontier,
    latest.after_truth AS truth_result,
    COALESCE(latest.support_generation,0) AS support_generation
FROM pgreact_internal.window_programs program
JOIN pgreact_internal.window_rules rules USING (program_version_id)
JOIN pgreact_internal.derivation_program_aggregate_inputs aggregate_rule
  ON aggregate_rule.program_version_id = rules.program_version_id
 AND aggregate_rule.rule_version_id = rules.rule_version_id
JOIN pgreact_internal.window_identities identity
  ON identity.program_version_id = rules.program_version_id
JOIN LATERAL (
    SELECT correction_identity,lower_frontier,support_generation,after_value,after_truth
    FROM pgreact_internal.window_corrections correction
    WHERE correction.program_version_id = rules.program_version_id
      AND correction.rule_version_id = rules.rule_version_id
      AND correction.public_window_key = identity.public_window_key
    ORDER BY correction.lower_frontier DESC,correction.correction_order DESC LIMIT 1
) latest ON true
WHERE program.active;

CREATE VIEW pgreact.window_diagnostics AS
SELECT contract_version,code,severity,object_identity,sqlstate,message,hint,details,created_at
FROM pgreact_internal.window_diagnostics
ORDER BY diagnostic_order;

CREATE FUNCTION pgreact_api.window_corrections(
    program_name text,
    result_limit integer,
    after_cursor text DEFAULT NULL
)
RETURNS TABLE(
    correction_identity text,
    program_version integer,
    rule_name text,
    public_window_key jsonb,
    lower_frontier bigint,
    before_value text,
    after_value text,
    before_truth boolean,
    after_truth boolean,
    support_generation integer,
    next_cursor text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE cursor_row pgreact_internal.window_corrections%ROWTYPE;
BEGIN
    IF result_limit NOT BETWEEN 1 AND 1000 THEN
        RAISE EXCEPTION 'M17_HISTORY_LIMIT: limit must be between 1 and 1000'
            USING ERRCODE = '22023';
    END IF;
    IF after_cursor IS NOT NULL THEN
        SELECT * INTO cursor_row FROM pgreact_internal.window_corrections correction
        WHERE correction.correction_identity = after_cursor
          AND correction.program_name = $1;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'M17_HISTORY_CURSOR: unknown correction cursor'
                USING ERRCODE = '22023';
        END IF;
    END IF;
    RETURN QUERY
    SELECT correction.correction_identity,correction.program_version,correction.rule_name,
           correction.public_window_key,correction.lower_frontier,
           correction.before_value,correction.after_value,
           correction.before_truth,correction.after_truth,correction.support_generation,
           correction.correction_identity
    FROM pgreact_internal.window_corrections correction
    WHERE correction.program_name = window_corrections.program_name
      AND (after_cursor IS NULL OR
           (correction.public_group_key::text,correction.window_ordinal,
            correction.lower_frontier,correction.rule_name,correction.correction_order) >
           (cursor_row.public_group_key::text,cursor_row.window_ordinal,
            cursor_row.lower_frontier,cursor_row.rule_name,cursor_row.correction_order))
    ORDER BY correction.public_group_key::text,correction.window_ordinal,
             correction.lower_frontier,correction.rule_name,correction.correction_order
    LIMIT result_limit;
END
$$;

CREATE FUNCTION pgreact_internal.assert_window_history(target_program uuid)
RETURNS void
LANGUAGE plpgsql
STABLE
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.window_identities identity
        LEFT JOIN pgreact_internal.window_finalizations finalization
          USING (program_version_id,public_window_key)
        WHERE identity.program_version_id = target_program AND identity.final
          AND finalization.finalization_identity IS NULL)
       OR EXISTS (
        SELECT 1 FROM pgreact_internal.window_rules rules
        JOIN pgreact_internal.aggregate_dependency_evidence evidence
          ON evidence.program_version_id = rules.program_version_id
         AND evidence.rule_version_id = rules.rule_version_id AND evidence.active
        LEFT JOIN pgreact_internal.window_corrections correction
          ON correction.program_version_id = rules.program_version_id
         AND correction.rule_version_id = rules.rule_version_id
         AND correction.public_window_key = evidence.public_group_key
        WHERE rules.program_version_id = target_program
        GROUP BY rules.rule_version_id,evidence.public_group_key
        HAVING count(correction.correction_identity) = 0) THEN
        RAISE EXCEPTION 'M17_HISTORY_UNRECOVERABLE: correction or finalization identity is missing'
            USING ERRCODE = '55000',
                  HINT = 'Restore the verified physical backup.';
    END IF;
END
$$;

ALTER FUNCTION pgreact_api.reconcile_program(text) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.reconcile_program(text) RENAME TO reconcile_program_m16;

CREATE FUNCTION pgreact_api.reconcile_program(program_name text)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    fingerprint bytea;
    repaired bigint;
BEGIN
    SELECT * INTO program FROM pgreact_internal.window_programs
    WHERE window_programs.program_name = reconcile_program.program_name AND active FOR UPDATE;
    IF NOT FOUND THEN RETURN pgreact_internal.reconcile_program_m16(program_name); END IF;
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M17_RECONCILE_UNAUTHORIZED: % is not the configured operator', session_user
            USING ERRCODE = '42501';
    END IF;
    PERFORM pg_advisory_xact_lock(5788046901200000);
    PERFORM pgreact_internal.assert_window_history(program.program_version_id);
    IF program.barrier IS NULL THEN
        RETURN pgreact_internal.reconcile_program_m16(program_name);
    END IF;
    PERFORM pgreact_internal.begin_window_stage();
    PERFORM pgreact_internal.load_window_rows(program.program_version_id);
    IF pgreact_internal.stage_differs(program.program_version_id) THEN
        RAISE EXCEPTION 'M17_LATE_INPUT_UNRESOLVED: authoritative input still differs from finalized state'
            USING ERRCODE = '55000',
                  HINT = 'Restore the authoritative input, then reconcile again.';
    END IF;
    fingerprint := pgreact_internal.staged_window_fingerprint(program.program_version_id);
    repaired := pgreact_internal.reconcile_program_m16(program_name);
    UPDATE pgreact_internal.window_programs
    SET observed_frontier = observed_frontier +
            CASE WHEN fingerprint IS DISTINCT FROM last_observed_fingerprint THEN 1 ELSE 0 END,
        lower_frontier = observed_frontier +
            CASE WHEN fingerprint IS DISTINCT FROM last_observed_fingerprint THEN 1 ELSE 0 END,
        last_source_fingerprint = fingerprint,
        last_observed_fingerprint = fingerprint,
        barrier = NULL
    WHERE program_version_id = program.program_version_id;
    INSERT INTO pgreact_internal.window_audits(program_version_id,operation,details)
    VALUES (program.program_version_id,'LATE_INPUT_REPAIRED',
            jsonb_build_object('program',program.program_name));
    RETURN repaired;
END
$$;

CREATE FUNCTION pgreact_api.prune_window_history(program_name text, cutoff timestamptz)
RETURNS TABLE(windows bigint, corrections bigint, blocked bigint)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    deleted_count bigint := 0;
    window_count bigint := 0;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M17_PRUNE_UNAUTHORIZED: % is not the configured operator', session_user
            USING ERRCODE = '42501';
    END IF;
    IF cutoff IS NULL OR NOT isfinite(cutoff) THEN
        RAISE EXCEPTION 'M17_HISTORY_CUTOFF_INVALID: cutoff must be finite'
            USING ERRCODE = '22008';
    END IF;
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE window_programs.program_name = prune_window_history.program_name AND active FOR UPDATE;
    IF cutoff < program.history_floor OR cutoff > program.complete_watermark THEN
        RAISE EXCEPTION 'M17_HISTORY_CUTOFF_INVALID: cutoff is outside the committed recovery horizon'
            USING ERRCODE = '22023';
    END IF;
    IF cutoff = program.history_floor THEN
        RETURN QUERY SELECT 0::bigint,0::bigint,0::bigint;
        RETURN;
    END IF;
    WITH ranked AS (
        SELECT correction.correction_order,correction.public_window_key,
               row_number() OVER (
                   PARTITION BY correction.rule_version_id,correction.public_window_key
                   ORDER BY correction.lower_frontier DESC,correction.correction_order DESC) AS position
        FROM pgreact_internal.window_corrections correction
        JOIN pgreact_internal.window_identities identity
          USING (program_version_id,public_window_key)
        WHERE correction.program_version_id = program.program_version_id
          AND identity.final AND identity.lateness_boundary < cutoff
    ), candidates AS (
        SELECT * FROM ranked WHERE position > 1
    ), deleted AS (
        DELETE FROM pgreact_internal.window_corrections correction
        USING candidates
        WHERE correction.correction_order = candidates.correction_order
        RETURNING candidates.public_window_key)
    SELECT count(*),count(DISTINCT public_window_key) INTO deleted_count,window_count FROM deleted;
    UPDATE pgreact_internal.window_programs SET history_floor = cutoff
    WHERE program_version_id = program.program_version_id;
    INSERT INTO pgreact_internal.window_audits(program_version_id,operation,details)
    VALUES (program.program_version_id,'PRUNE_WINDOW_HISTORY',jsonb_build_object(
        'cutoff',cutoff,'windows',window_count,'corrections',deleted_count,'blocked',0));
    RETURN QUERY SELECT window_count,deleted_count,0::bigint;
END
$$;

ALTER FUNCTION pgreact_api.explain(text,jsonb) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.explain(text,jsonb) RENAME TO explain_m16;

CREATE FUNCTION pgreact_api.explain(target text, semantic_key jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE evidence_row record; known_target boolean;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM pgreact_internal.window_rules rules
        JOIN pgreact_internal.window_programs program USING (program_version_id)
        WHERE program.active AND rules.target_relation = target) INTO known_target;
    IF NOT known_target THEN RETURN pgreact_internal.explain_m16(target,semantic_key); END IF;
    SELECT * INTO evidence_row FROM pgreact.window_evidence evidence
    WHERE evidence.target_relation = target AND evidence.public_window_key = semantic_key;
    IF NOT FOUND OR evidence_row.truth_result IS NOT TRUE THEN
        RETURN jsonb_build_object(
            'contract_version',6,
            'target',jsonb_build_object('kind','fact','name',target,'key',semantic_key),
            'evidence',NULL);
    END IF;
    RETURN jsonb_build_object(
        'contract_version',6,
        'target',jsonb_build_object('kind','fact','name',target,'key',semantic_key),
        'support','G' || evidence_row.support_generation,
        'evidence',to_jsonb(evidence_row));
END
$$;

ALTER FUNCTION pgreact_api.remove_program(text,integer) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.remove_program(text,integer) RENAME TO remove_program_m16;

CREATE FUNCTION pgreact_api.remove_program(program_name text, program_version integer)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE target_program uuid;
BEGIN
    SELECT window_programs.program_version_id INTO target_program
    FROM pgreact_internal.window_programs
    WHERE window_programs.program_name = remove_program.program_name
      AND window_programs.program_version = remove_program.program_version AND active FOR UPDATE;
    PERFORM pgreact_internal.remove_program_m16(program_name,program_version);
    IF target_program IS NOT NULL THEN
        UPDATE pgreact_internal.window_programs SET active = false
        WHERE program_version_id = target_program;
        INSERT INTO pgreact_internal.window_audits(program_version_id,operation,details)
        VALUES (target_program,'REMOVE',jsonb_build_object(
            'program',program_name,'version',program_version));
    END IF;
END
$$;

ALTER FUNCTION pgreact_api.doctor() SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.doctor() RENAME TO doctor_m16;

CREATE FUNCTION pgreact_api.doctor()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    WITH inherited AS (
        SELECT diagnostic
        FROM jsonb_array_elements(pgreact_internal.doctor_m16() -> 'diagnostics') diagnostic
        WHERE diagnostic ->> 'code' <> 'M16_EXTENSION_VERSION'
    ), diagnostics AS (
        SELECT diagnostic FROM inherited
        UNION ALL
        SELECT jsonb_build_object(
            'code','M17_EXTENSION_VERSION','severity','ERROR','object_identity','pg_react',
            'message','pg_react extension version is not 0.14.0',
            'hint','Install matching files and run ALTER EXTENSION pg_react UPDATE.')
        WHERE NOT EXISTS (SELECT 1 FROM pg_extension
                          WHERE extname = 'pg_react' AND extversion = '0.14.0')
        UNION ALL
        SELECT jsonb_build_object(
            'code','M17_LATE_INPUT_BARRIER','severity','ERROR',
            'object_identity',program_name,
            'message','program is blocked by input beyond a finalized window',
            'hint','Restore the authoritative input and call pgreact_api.reconcile_program.')
        FROM pgreact_internal.window_programs WHERE active AND barrier = 'LATE_INPUT'
    ), ordered AS (
        SELECT diagnostic FROM diagnostics
        ORDER BY CASE diagnostic ->> 'severity' WHEN 'ERROR' THEN 1 WHEN 'WARNING' THEN 2 ELSE 3 END,
                 diagnostic ->> 'code',diagnostic ->> 'object_identity'
    )
    SELECT jsonb_build_object(
        'contract_version',CASE WHEN EXISTS (
            SELECT 1 FROM pgreact_internal.window_programs WHERE active) THEN 6 ELSE 5 END,
        'status',CASE WHEN EXISTS (SELECT 1 FROM ordered
                                  WHERE diagnostic ->> 'severity' = 'ERROR')
                      THEN 'attention' ELSE 'ready' END,
        'diagnostics',COALESCE((SELECT jsonb_agg(diagnostic) FROM ordered),'[]'::jsonb))
$$;

ALTER FUNCTION pgreact_api.configure_roles(regrole,regrole,regrole,regrole,regrole)
SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.configure_roles(regrole,regrole,regrole,regrole,regrole)
RENAME TO configure_roles_m16;

CREATE FUNCTION pgreact_api.configure_roles(
    author_role regrole,
    operator_role regrole,
    worker_role regrole,
    reader_role regrole,
    advanced_reader_role regrole
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    PERFORM pgreact_internal.configure_roles_m16(
        author_role,operator_role,worker_role,reader_role,advanced_reader_role);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.request_watermark(text,text,name,timestamptz), '
        'pgreact_api.prune_window_history(text,timestamptz), '
        'pgreact_api.export_window_state(text), pgreact_api.restore_window_state(jsonb), '
        'pgreact_api.watermark_status(text) TO %I', operator_role::text);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.watermark_status(text) TO %I', reader_role::text);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.window_corrections(text,integer,text) TO %I, %I',
        operator_role::text,advanced_reader_role::text);
    EXECUTE format('GRANT SELECT ON pgreact.window_evidence,pgreact.window_diagnostics TO %I, %I',
                   operator_role::text,reader_role::text);
END
$$;

REVOKE ALL ON ALL TABLES IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_internal FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pgreact_internal.derivation_program_graph(jsonb) TO PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_api FROM PUBLIC;
REVOKE ALL ON pgreact.window_evidence,pgreact.window_diagnostics FROM PUBLIC;

DO $$
DECLARE
    author_role regrole;
    operator_role regrole;
    worker_role regrole;
    reader_role regrole;
    advanced_reader_role regrole;
BEGIN
    SELECT role_oid::regrole INTO author_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'author';
    SELECT role_oid::regrole INTO operator_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'operator';
    SELECT role_oid::regrole INTO worker_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'worker';
    SELECT role_oid::regrole INTO reader_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'reader';
    SELECT role_oid::regrole INTO advanced_reader_role
    FROM pgreact_internal.advanced_readers;
    IF author_role IS NOT NULL AND operator_role IS NOT NULL
       AND worker_role IS NOT NULL AND reader_role IS NOT NULL
       AND advanced_reader_role IS NOT NULL THEN
        PERFORM pgreact_api.configure_roles(
            author_role,operator_role,worker_role,reader_role,advanced_reader_role);
    END IF;
END
$$;

COMMENT ON EXTENSION pg_react IS
    'M17 fixed-duration event-time windows, watermarks, corrections, and finalization';

-- M18 changes no engine semantics. The release diagnostic recognizes 0.15.0.
CREATE OR REPLACE FUNCTION pgreact_api.doctor()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    WITH raw_inherited AS (
        SELECT diagnostic
        FROM jsonb_array_elements(pgreact_internal.doctor_m16() -> 'diagnostics') diagnostic
        WHERE diagnostic ->> 'code' <> 'M16_EXTENSION_VERSION'
          AND NOT (diagnostic ->> 'code' = 'M15_MANAGED_PROCESS'
                   AND EXISTS (
                       SELECT 1 FROM pgreact_internal.managed_processes
                       WHERE database_oid = (SELECT oid FROM pg_database
                                              WHERE datname = current_database())
                         AND state = 'ready'
                         AND heartbeat_at >= clock_timestamp() -
                             (current_setting('pg_react.poll_interval_ms')::interval +
                              interval '10 seconds')))
          AND NOT (diagnostic ->> 'code' IN ('SOURCE_DRIFT', 'CONSEQUENCE_DRIFT')
                   AND EXISTS (
                       SELECT 1
                       FROM pgreact.rules stale
                       JOIN pgreact.rules active
                         ON active.rule_name = stale.rule_name
                        AND active.state = 'ACTIVE'
                        AND active.rule_version_id <> stale.rule_version_id
                       WHERE stale.rule_version_id::text =
                             diagnostic ->> 'object_identity'))
    ), resolved AS (
        SELECT diagnostic,
               COALESCE(
                   (SELECT program.program_name
                    FROM pgreact_internal.derivation_program_rules member
                    JOIN pgreact.derivation_programs program USING (program_version_id)
                    WHERE member.rule_version_id::text = diagnostic ->> 'object_identity'),
                   (SELECT rule_name FROM pgreact.rules
                    WHERE rule_version_id::text = diagnostic ->> 'object_identity'),
                   (SELECT program_name FROM pgreact.derivation_programs
                    WHERE program_version_id::text = diagnostic ->> 'object_identity'),
                   diagnostic ->> 'object_identity') AS public_name,
               EXISTS (SELECT 1 FROM pgreact.rules
                       WHERE rule_version_id::text = diagnostic ->> 'object_identity')
               AND NOT EXISTS (
                   SELECT 1 FROM pgreact_internal.derivation_program_rules
                   WHERE rule_version_id::text = diagnostic ->> 'object_identity') AS is_rule
        FROM raw_inherited
    ), inherited AS (
        SELECT diagnostic || jsonb_build_object(
            'object_identity', public_name,
            'message', CASE WHEN diagnostic ->> 'code' = 'M15_MANAGED_PROCESS'
                                  AND EXISTS (
                    SELECT 1 FROM pgreact_internal.managed_processes
                    WHERE database_oid = (SELECT oid FROM pg_database
                                           WHERE datname = current_database())
                      AND heartbeat_at < clock_timestamp() -
                          (current_setting('pg_react.poll_interval_ms')::interval +
                           interval '10 seconds'))
                THEN 'managed worker heartbeat is stale'
                ELSE diagnostic ->> 'message' END,
            'hint', CASE diagnostic ->> 'code'
                WHEN 'SOURCE_DRIFT' THEN CASE WHEN is_rule
                    THEN format('Run SELECT pgreact_api.pause_rule(%L); then replace the rule through pgreact_api.replace_rule.', public_name)
                    ELSE format('Preview and deploy the corrected next version of %L through pgreact_api.preview_program and pgreact_api.deploy_program.', public_name) END
                WHEN 'CONSEQUENCE_DRIFT' THEN
                    format('Run SELECT pgreact_api.pause_rule(%L); then replace the rule through pgreact_api.replace_rule.', public_name)
                WHEN 'M15_MANAGED_PROCESS' THEN
                    format('Restart the pg-react managed worker for database %L; then run SELECT pgreact_api.doctor().', public_name)
                ELSE diagnostic ->> 'hint' END)
            AS diagnostic
        FROM resolved
    ), diagnostics AS (
        SELECT diagnostic FROM inherited
        UNION ALL
        SELECT jsonb_build_object(
            'code','M18_EXTENSION_VERSION','severity','ERROR','object_identity','pg_react',
            'message','pg_react extension version is not 0.15.0',
            'hint','Install matching files and run ALTER EXTENSION pg_react UPDATE.')
        WHERE NOT EXISTS (SELECT 1 FROM pg_extension
                          WHERE extname = 'pg_react' AND extversion = '0.15.0')
        UNION ALL
        SELECT jsonb_build_object(
            'code','M17_LATE_INPUT_BARRIER','severity','ERROR',
            'object_identity',program_name,
            'message','program is blocked by input beyond a finalized window',
            'hint','Restore the authoritative input and call pgreact_api.reconcile_program.')
        FROM pgreact_internal.window_programs WHERE active AND barrier = 'LATE_INPUT'
    ), ordered AS (
        SELECT diagnostic FROM diagnostics
        ORDER BY CASE diagnostic ->> 'severity' WHEN 'ERROR' THEN 1 WHEN 'WARNING' THEN 2 ELSE 3 END,
                 diagnostic ->> 'code',diagnostic ->> 'object_identity'
    )
    SELECT jsonb_build_object(
        'contract_version',CASE WHEN EXISTS (
            SELECT 1 FROM pgreact_internal.window_programs WHERE active) THEN 6 ELSE 5 END,
        'status',CASE WHEN EXISTS (SELECT 1 FROM ordered
                                  WHERE diagnostic ->> 'severity' = 'ERROR')
                      THEN 'attention' ELSE 'ready' END,
        'diagnostics',COALESCE((SELECT jsonb_agg(diagnostic) FROM ordered),'[]'::jsonb))
$$;

-- Maintenance may use the 1,000-row supported batch while public job claims
-- retain their inherited 100-item protocol limit.
CREATE OR REPLACE FUNCTION pgreact_internal.managed_cycle(process_pid integer)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    worker text := format('pg-react-managed/%s/%s', current_database(), process_pid);
    batch_limit integer := current_setting('pg_react.batch_size')::integer;
    claim_limit integer := least(batch_limit, 100);
    pending_limit integer := current_setting('pg_react.max_pending_jobs')::integer;
    pending bigint;
    processed bigint := 0;
    claimed record;
    runtime_state text := 'ready';
    run_result jsonb;
BEGIN
    SELECT count(*) INTO pending
    FROM pgreact_internal.agenda job
    WHERE job.state IN ('PENDING', 'LEASED', 'RETRY_WAIT');
    INSERT INTO pgreact_internal.managed_processes (
        database_oid, database_name, backend_pid, state, protocol, pending_jobs)
    VALUES ((SELECT oid FROM pg_database WHERE datname = current_database()),
            current_database(), process_pid, 'ready', 2, pending)
    ON CONFLICT (database_oid) DO UPDATE
    SET database_name = EXCLUDED.database_name, backend_pid = EXCLUDED.backend_pid,
        state = EXCLUDED.state, protocol = EXCLUDED.protocol,
        pending_jobs = EXCLUDED.pending_jobs, started_at = CASE
            WHEN pgreact_internal.managed_processes.backend_pid = EXCLUDED.backend_pid
            THEN pgreact_internal.managed_processes.started_at ELSE clock_timestamp() END,
        heartbeat_at = clock_timestamp(), detail = NULL;

    IF pg_is_in_recovery() THEN
        runtime_state := 'standby';
    ELSIF NOT pgreact.worker_protocol_compatible(2) THEN
        runtime_state := 'error';
        UPDATE pgreact_internal.managed_processes
        SET state = runtime_state, detail = 'worker protocol 2 is incompatible',
            heartbeat_at = clock_timestamp()
        WHERE database_oid = (SELECT oid FROM pg_database WHERE datname = current_database());
        RETURN jsonb_build_object(
            'state', runtime_state, 'pending_jobs', pending, 'processed_jobs', 0);
    ELSE
        IF pending >= pending_limit THEN
            runtime_state := 'backpressure';
        ELSE
            run_result := pgreact_api.run();
        END IF;
        FOR claimed IN
            SELECT * FROM pgreact_api.claim(worker, claim_limit, interval '60 seconds')
        LOOP
            PERFORM pgreact_api.execute(
                claimed.episode_id, worker, claimed.lease_token);
            processed := processed + 1;
        END LOOP;
    END IF;
    SELECT count(*) INTO pending
    FROM pgreact_internal.agenda job
    WHERE job.state IN ('PENDING', 'LEASED', 'RETRY_WAIT');
    UPDATE pgreact_internal.managed_processes
    SET state = runtime_state, pending_jobs = pending,
        processed_jobs = processed_jobs + processed,
        heartbeat_at = clock_timestamp(), detail = NULL
    WHERE database_oid = (SELECT oid FROM pg_database WHERE datname = current_database());
    RETURN jsonb_build_object(
        'state', runtime_state, 'pending_jobs', pending, 'processed_jobs', processed,
        'run', run_result);
EXCEPTION WHEN OTHERS THEN
    INSERT INTO pgreact_internal.managed_processes (
        database_oid, database_name, backend_pid, state, protocol, detail)
    VALUES ((SELECT oid FROM pg_database WHERE datname = current_database()),
            current_database(), process_pid, 'error', 2, SQLSTATE || ': ' || SQLERRM)
    ON CONFLICT (database_oid) DO UPDATE
    SET backend_pid = EXCLUDED.backend_pid, state = 'error',
        heartbeat_at = clock_timestamp(), detail = EXCLUDED.detail;
    RETURN jsonb_build_object(
        'state', 'error', 'sqlstate', SQLSTATE, 'message', SQLERRM);
END
$$;

-- Program names now receive the same name-first status entry point as rules.
-- Existing rule and all-rules transcripts remain byte-for-byte compatible.
CREATE OR REPLACE FUNCTION pgreact_api.status(name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 5,
        'rules', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'rule', rule.rule_name,
                'condition', COALESCE(spec.public_condition::regclass::text,
                                      rule.source_view_name),
                'key', CASE WHEN spec.rule_version_id IS NULL THEN to_jsonb(rule.key_column)
                            WHEN cardinality(spec.key_columns) = 1 THEN to_jsonb(spec.key_columns[1])
                            ELSE to_jsonb(spec.key_columns) END,
                'state', lower(rule.state),
                'actions', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object(
                        'action', lower(binding.event_kind),
                        'function', COALESCE(proxy.action_oid::regprocedure::text,
                                             binding.function_identity))
                        ORDER BY binding.event_kind)
                    FROM pgreact_internal.consequence_bindings binding
                    LEFT JOIN pgreact_internal.action_proxies proxy
                      ON proxy.proxy_oid = binding.function_oid
                    WHERE binding.rule_version_id = rule.rule_version_id
                ), '[]'::jsonb)) ORDER BY rule.rule_name)
            FROM pgreact.rules rule
            LEFT JOIN pgreact_internal.keyed_rule_versions spec USING (rule_version_id)
            WHERE $1 IS NULL OR rule.rule_name = $1
        ), '[]'::jsonb)
    ) || CASE WHEN $1 IS NOT NULL AND EXISTS (
        SELECT 1 FROM pgreact.derivation_programs WHERE program_name = $1
    ) THEN jsonb_build_object('programs', (
        SELECT jsonb_agg(jsonb_build_object(
            'program', program.program_name,
            'version', program.program_version,
            'state', lower(program.state),
            'frontier', program.frontier,
            'max_iterations', program.max_iterations,
            'max_facts', program.max_facts,
            'last_run', (
                SELECT jsonb_build_object(
                    'status', lower(run.status),
                    'frontier', run.committed_frontier)
                FROM pgreact.derivation_program_runs run
                WHERE run.program_version_id = program.program_version_id
                ORDER BY run.run_id DESC LIMIT 1),
            'watermark', (
                SELECT to_jsonb(watermark)
                FROM pgreact_api.watermark_status(program.program_name) watermark))
            ORDER BY program.program_version)
        FROM pgreact.derivation_programs program
        WHERE program.program_name = $1
    )) ELSE '{}'::jsonb END
$$;

-- M19 selective immediate maintenance.  pg_trickle owns the source CDC and
-- immediate stream-table maintenance; pg-react only opts eligible versions in.

ALTER TABLE pgreact_internal.rule_versions
    ADD COLUMN maintenance_mode text NOT NULL DEFAULT 'SCHEDULED'
        CHECK (maintenance_mode IN ('SCHEDULED', 'IMMEDIATE'));

ALTER TABLE pgreact_internal.derivation_program_versions
    ADD COLUMN maintenance_mode text NOT NULL DEFAULT 'SCHEDULED'
        CHECK (maintenance_mode IN ('SCHEDULED', 'IMMEDIATE'));

CREATE TABLE pgreact_internal.immediate_audits (
    audit_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    object_identity text NOT NULL,
    operation text NOT NULL,
    details jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE FUNCTION pgreact_internal.finalize_match_delta_now(target_version_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE
    version_id uuid := target_version_id;
    version_row pgreact_internal.rule_versions%ROWTYPE;
    buffered record;
    current_count bigint;
    final_bindings jsonb;
    canonical bytea;
    digest bytea;
    activation uuid;
    prior pgreact_internal.activation_state%ROWTYPE;
    next_generation bigint;
    new_event_id bigint;
    event_key text;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = version_id;
    PERFORM pg_advisory_xact_lock(hashtextextended(version_id::text, 5788046901200002));

    FOR buffered IN
        DELETE FROM pgreact_internal.activation_delta_buffer
        WHERE rule_version_id = version_id
          AND xid = pg_catalog.pg_current_xact_id()
        RETURNING *
    LOOP
        EXECUTE format(
            'SELECT count(*), min(to_jsonb(m)::text)::jsonb FROM %s AS m '
            'WHERE (to_jsonb(m) ->> %L)::bigint = $1',
            version_row.match_relid::regclass, version_row.key_column::text
        ) INTO current_count, final_bindings USING buffered.semantic_key;

        IF current_count > 1 THEN
            RAISE EXCEPTION 'pg-react duplicate semantic key % in %',
                buffered.semantic_key, version_row.match_name;
        END IF;

        canonical := pgreact_internal.canonical_bigint_v1(buffered.semantic_key);
        digest := pgreact_internal.activation_digest(version_id, canonical);
        activation := pgreact_internal.activation_uuid(digest);
        SELECT * INTO prior
        FROM pgreact_internal.activation_state
        WHERE rule_version_id = version_id AND activation_id = activation
        FOR UPDATE;
        IF FOUND AND (prior.canonical_key <> canonical OR prior.canonical_key_digest <> digest) THEN
            RAISE EXCEPTION 'pg-react activation UUID collision for semantic key %',
                buffered.semantic_key;
        END IF;

        IF current_count = 1 AND (prior.activation_id IS NULL OR NOT prior.active) THEN
            next_generation := COALESCE(prior.generation, 0) + 1;
            INSERT INTO pgreact_internal.activation_state (
                rule_version_id, activation_id, semantic_key, canonical_key,
                canonical_key_digest, key_codec_version, active, generation,
                current_bindings, last_active_bindings, first_seen_at, last_seen_at
            ) VALUES (
                version_id, activation, buffered.semantic_key, canonical, digest, 1,
                true, next_generation, final_bindings, final_bindings,
                clock_timestamp(), clock_timestamp()
            )
            ON CONFLICT (rule_version_id, activation_id) DO UPDATE SET
                active = true, generation = EXCLUDED.generation,
                current_bindings = EXCLUDED.current_bindings,
                last_active_bindings = EXCLUDED.last_active_bindings,
                last_seen_at = EXCLUDED.last_seen_at, deactivated_at = NULL;
            event_key := encode(sha256(convert_to(
                version_id::text || ':' || activation::text || ':' || next_generation || ':ACTIVATE',
                'UTF8')), 'hex');
            INSERT INTO pgreact_internal.lifecycle_events (
                rule_id, rule_version_id, activation_id, generation, event_kind,
                new_bindings, idempotency_key
            ) VALUES (
                version_row.rule_id, version_id, activation, next_generation,
                'ACTIVATE', final_bindings, event_key
            ) RETURNING event_id INTO new_event_id;
            INSERT INTO pgreact_internal.agenda (
                event_id, rule_id, rule_version_id, activation_id,
                activation_generation, state, new_bindings, idempotency_key
            ) SELECT
                new_event_id, version_row.rule_id, version_id, activation,
                next_generation, 'PENDING', final_bindings, event_key
            WHERE version_row.consequence_oid IS NOT NULL;
        ELSIF current_count = 1 AND prior.active THEN
            UPDATE pgreact_internal.activation_state SET
                current_bindings = final_bindings,
                last_active_bindings = final_bindings,
                last_seen_at = clock_timestamp()
            WHERE rule_version_id = version_id AND activation_id = activation;
        ELSIF current_count = 0 AND prior.active THEN
            UPDATE pgreact_internal.activation_state SET
                active = false, current_bindings = NULL,
                deactivated_at = clock_timestamp(), last_seen_at = clock_timestamp()
            WHERE rule_version_id = version_id AND activation_id = activation;
            event_key := encode(sha256(convert_to(
                version_id::text || ':' || activation::text || ':' || prior.generation || ':DEACTIVATE',
                'UTF8')), 'hex');
            INSERT INTO pgreact_internal.lifecycle_events (
                rule_id, rule_version_id, activation_id, generation, event_kind,
                old_bindings, idempotency_key
            ) VALUES (
                version_row.rule_id, version_id, activation, prior.generation,
                'DEACTIVATE', prior.last_active_bindings, event_key);
        END IF;
    END LOOP;
END
$m19$;

CREATE FUNCTION pgreact_internal.finalize_immediate_match_delta()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
BEGIN
    PERFORM pgreact_internal.finalize_match_delta_now(TG_ARGV[0]::uuid);
    RETURN NULL;
END
$m19$;

CREATE FUNCTION pgreact_internal.mark_immediate_rule(target_version_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id;
    UPDATE pgreact_internal.rule_versions
    SET maintenance_mode = 'IMMEDIATE'
    WHERE rule_version_id = target_version_id;
    EXECUTE format('DROP TRIGGER IF EXISTS pgreact_immediate_finalize ON %s', version_row.match_name);
    EXECUTE format(
        'CREATE TRIGGER pgreact_immediate_finalize AFTER INSERT OR UPDATE OR DELETE ON %s '
        'FOR EACH STATEMENT EXECUTE FUNCTION pgreact_internal.finalize_immediate_match_delta(%L)',
        version_row.match_name, version_row.rule_version_id::text);
    INSERT INTO pgreact_internal.immediate_audits(object_identity, operation, details)
    VALUES (version_row.rule_version_id::text, 'ENABLE_CLOSURE_MEMBER',
            jsonb_build_object('match', version_row.match_name,
                               'refresh', 'ordered pg-react closure refresh'));
END
$m19$;

CREATE FUNCTION pgreact_internal.capture_immediate_fact_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
BEGIN
    CREATE TEMP TABLE IF NOT EXISTS m19_immediate_changed_relations (
        relation_version_id uuid PRIMARY KEY
    ) ON COMMIT DELETE ROWS;
    INSERT INTO m19_immediate_changed_relations(relation_version_id)
    VALUES (COALESCE(NEW.relation_version_id, OLD.relation_version_id))
    ON CONFLICT DO NOTHING;
    RETURN NULL;
END
$m19$;

CREATE FUNCTION pgreact_internal.propagate_immediate_facts_now()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE changed record;
    member record;
BEGIN
    CREATE TEMP TABLE IF NOT EXISTS m19_immediate_changed_relations (
        relation_version_id uuid PRIMARY KEY
    ) ON COMMIT DELETE ROWS;
    LOOP
        SELECT relation_version_id INTO changed
        FROM m19_immediate_changed_relations
        ORDER BY relation_version_id
        LIMIT 1;
        EXIT WHEN NOT FOUND;
        DELETE FROM m19_immediate_changed_relations
        WHERE relation_version_id = changed.relation_version_id;
        FOR member IN
            SELECT DISTINCT version.match_name
            FROM pgreact_internal.derivation_program_inputs input
            JOIN pgreact_internal.derivation_program_rules program_rule
              USING (program_version_id, rule_version_id)
            JOIN pgreact_internal.derivation_program_versions program
              USING (program_version_id)
            JOIN pgreact_internal.rule_versions version
              ON version.rule_version_id = program_rule.rule_version_id
            WHERE input.relation_version_id = changed.relation_version_id
              AND program.state = 'ACTIVE'
              AND program.maintenance_mode = 'IMMEDIATE'
            ORDER BY version.match_name
        LOOP
            PERFORM pgtrickle.refresh_stream_table(member.match_name);
        END LOOP;
    END LOOP;
    TRUNCATE m19_immediate_changed_relations;
END
$m19$;

CREATE FUNCTION pgreact_internal.propagate_immediate_facts()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
BEGIN
    PERFORM pgreact_internal.propagate_immediate_facts_now();
    RETURN NULL;
END
$m19$;

CREATE TRIGGER pgreact_capture_immediate_facts
AFTER INSERT OR UPDATE OR DELETE ON pgreact_internal.derived_facts
FOR EACH ROW EXECUTE FUNCTION pgreact_internal.capture_immediate_fact_change();


CREATE FUNCTION pgreact_api.immediate_capabilities()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
    SELECT jsonb_build_object(
        'contract_version', 7,
        'postgresql', current_setting('server_version_num'),
        'pg_trickle', (SELECT extversion FROM pg_extension WHERE extname = 'pg_trickle'),
        'isolation', 'READ COMMITTED',
        'default', 'SCHEDULED',
        'supported', jsonb_build_object(
            'rules', jsonb_build_array('CONSTRAINT'),
            'queries', jsonb_build_array('one direct key over one base table'),
            'dml', jsonb_build_array('INSERT', 'UPDATE', 'DELETE'),
            'derivations', jsonb_build_array('finite', 'acyclic', 'positive', 'database-local')),
        'rejected', jsonb_build_array(
            'COMMAND', 'OUTBOX', 'MANUAL', 'EXTERNAL', 'JOIN', 'AGGREGATE',
            'WINDOW', 'DEADLINE', 'NEGATION', 'RECURSION', 'RLS',
            'non-READ-COMMITTED', 'unsupported pg_trickle tuple'))
$m19$;

CREATE OR REPLACE FUNCTION pgreact_api.infer_program(definition jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE
    rule_item record;
    inferred_inputs jsonb;
    source_oid oid;
    result jsonb := definition;
BEGIN
    IF jsonb_typeof(definition) IS DISTINCT FROM 'object'
       OR jsonb_typeof(definition -> 'rules') IS DISTINCT FROM 'array' THEN
        RETURN definition;
    END IF;
    FOR rule_item IN
        SELECT value, ordinal
        FROM jsonb_array_elements(definition -> 'rules')
             WITH ORDINALITY rules(value, ordinal)
        ORDER BY ordinal
    LOOP
        IF rule_item.value ? 'inputs' THEN
            RAISE EXCEPTION 'M14_EXPLICIT_INPUTS: inputs are inferred from the definition view'
                USING HINT = 'Remove inputs and reference each positive derived relation from the PostgreSQL view.';
        END IF;
        source_oid := to_regclass(rule_item.value ->> 'definition');
        IF source_oid IS NULL THEN
            CONTINUE;
        END IF;
        WITH RECURSIVE dependencies(relation_oid) AS (
            SELECT source_oid
            UNION
            SELECT dependency.refobjid
            FROM dependencies parent
            JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relation_oid
            JOIN pg_depend dependency
              ON dependency.classid = 'pg_rewrite'::regclass
             AND dependency.objid = rewrite.oid
             AND dependency.refclassid = 'pg_class'::regclass
             AND dependency.deptype = 'n'
        )
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'relation', relation.relation_name,
                'key', version.key_column) ORDER BY relation.relation_name), '[]'::jsonb)
          INTO inferred_inputs
          FROM dependencies dependency
          JOIN pgreact_internal.derived_relation_versions version
            ON version.public_view_oid = dependency.relation_oid
           AND version.state = 'ACTIVE'
          JOIN pgreact_internal.derived_relations relation USING (relation_id);
        result := jsonb_set(result,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'inputs'], inferred_inputs, true);
    END LOOP;
    RETURN result;
END
$m19$;

CREATE FUNCTION pgreact_api.validate_immediate_rule(
    condition regclass,
    semantic_key name
)
RETURNS TABLE(
    contract_version integer, code text, severity text,
    object_identity text, message text, hint text, details jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE
    diagnostic record;
    query_tree text;
    key_attno smallint;
    source_oid oid;
    source_count integer;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact.validate_rule(condition, ARRAY[semantic_key]::name[], NULL::regprocedure) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RETURN QUERY SELECT 7, diagnostic.code, diagnostic.severity,
            diagnostic.object_identity, diagnostic.message, diagnostic.hint,
            diagnostic.details;
        RETURN;
    END IF;

    SELECT attnum INTO key_attno
    FROM pg_attribute
    WHERE attrelid = condition AND attname = semantic_key
      AND attnum > 0 AND NOT attisdropped;
    IF key_attno IS NULL OR NOT pgreact_internal.view_key_is_direct(condition, key_attno) THEN
        RETURN QUERY SELECT 7, 'M19_KEY_NOT_DIRECT', 'ERROR', condition::text,
            'immediate rules require one direct semantic key projected from the source table',
            'Project one stored bigint key unchanged from the source table.',
            jsonb_build_object('semantic_key', semantic_key);
        RETURN;
    END IF;

    query_tree := pgreact_internal.relation_query_tree(condition);
    IF query_tree ~ E':has(Aggs|WindowFuncs|Recursive|SubLinks)[[:space:]]+true'
       OR query_tree ~ E':jointype[[:space:]]+[0-9]'
    THEN
        RETURN QUERY SELECT 7, 'M19_QUERY_UNSUPPORTED', 'ERROR', condition::text,
            'immediate rules require a finite single-table positive query',
            'Use a direct SELECT from one base table; joins, aggregates, windows, recursion, and subqueries remain scheduled.',
            '{}'::jsonb;
        RETURN;
    END IF;

    WITH RECURSIVE dependencies(relid) AS (
        SELECT condition::oid
        UNION
        SELECT dependency.refobjid
        FROM dependencies parent
        JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
        JOIN pg_depend dependency
          ON dependency.classid = 'pg_rewrite'::regclass
         AND dependency.objid = rewrite.oid
         AND dependency.refclassid = 'pg_class'::regclass
         AND dependency.deptype = 'n'
    )
    SELECT count(DISTINCT relation.oid) FILTER (WHERE relation.relkind IN ('r', 'p')),
           min(relation.oid) FILTER (WHERE relation.relkind IN ('r', 'p'))
    INTO source_count, source_oid
    FROM dependencies
    JOIN pg_class relation ON relation.oid = dependencies.relid
    WHERE relation.oid <> condition;
    IF source_count <> 1 THEN
        RETURN QUERY SELECT 7, 'M19_SOURCE_SHAPE', 'ERROR', condition::text,
            'immediate rules require exactly one ordinary base-table source',
            'Keep this version scheduled or replace it with a single-table positive condition.',
            jsonb_build_object('base_table_count', source_count);
        RETURN;
    END IF;

    IF EXISTS (SELECT 1 FROM pg_class WHERE oid = source_oid
               AND (relrowsecurity OR relforcerowsecurity)) THEN
        RETURN QUERY SELECT 7, 'M19_RLS_UNSUPPORTED', 'ERROR', source_oid::regclass::text,
            'RLS-protected sources are outside the immediate capability matrix',
            'Use a non-RLS source or keep this version scheduled.', '{}'::jsonb;
        RETURN;
    END IF;
    IF NOT has_table_privilege(session_user, source_oid, 'TRIGGER') THEN
        RETURN QUERY SELECT 7, 'M19_SOURCE_TRIGGER_PRIVILEGE', 'ERROR', source_oid::regclass::text,
            'the immediate author must be able to maintain the source table with PostgreSQL triggers',
            'Grant TRIGGER on the source table or keep this version scheduled.', '{}'::jsonb;
        RETURN;
    END IF;
    IF (SELECT extversion FROM pg_extension WHERE extname = 'pg_trickle') IS DISTINCT FROM '0.81.0' THEN
        RETURN QUERY SELECT 7, 'M19_TRICKLE_CAPABILITY', 'ERROR', 'pg_trickle',
            'the pinned pg_trickle immediate-maintenance capability is unavailable',
            'Install pg_trickle 0.81.0 on the supported PostgreSQL 18.3 tuple.', '{}'::jsonb;
        RETURN;
    END IF;
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RETURN QUERY SELECT 7, 'M19_ISOLATION_UNSUPPORTED', 'ERROR', current_setting('transaction_isolation'),
            'immediate maintenance requires READ COMMITTED',
            'Run the source transaction at READ COMMITTED.', '{}'::jsonb;
        RETURN;
    END IF;
    IF COALESCE(current_setting('pg_trickle.user_triggers', true), '') <> 'auto' THEN
        RETURN QUERY SELECT 7, 'M19_TRIGGER_CAPABILITY', 'ERROR', 'pg_trickle.user_triggers',
            'the pinned immediate-maintenance trigger capability is not enabled',
            'Set pg_trickle.user_triggers=auto and restart PostgreSQL.', '{}'::jsonb;
        RETURN;
    END IF;

    RETURN QUERY SELECT 7, 'OK', 'INFO', condition::text,
        'constraint rule is eligible for PostgreSQL-native immediate maintenance',
        'Call pgreact_api.author_immediate_rule to opt this version in.',
        jsonb_build_object('maintenance_mode', 'IMMEDIATE', 'source_table', source_oid::regclass::text,
                           'visibility', 'same transaction after each supported source statement',
                           'consequence_boundary', 'committed asynchronous agenda');
EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT 7, 'M19_IMMEDIATE_VALIDATION', 'ERROR', condition::text,
        SQLERRM, 'Correct the named object or keep this version scheduled.', '{}'::jsonb;
END
$m19$;

CREATE FUNCTION pgreact_internal.enable_immediate_rule(target_version_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE;
    source_oid oid;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id;
    PERFORM pg_advisory_xact_lock(hashtextextended(version_row.rule_version_id::text, 5788046901200002));
    IF version_row.state <> 'ACTIVE' THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_STATE: rule version % is not active', target_version_id;
    END IF;
    UPDATE pgreact_internal.rule_versions
    SET maintenance_mode = 'IMMEDIATE'
    WHERE rule_version_id = target_version_id;
    PERFORM pgtrickle.set_stream_table_refresh_policy(version_row.match_name, 'IMMEDIATE');
    EXECUTE format('DROP TRIGGER IF EXISTS pgreact_immediate_finalize ON %s', version_row.match_name);
    EXECUTE format(
        'CREATE TRIGGER pgreact_immediate_finalize AFTER INSERT OR UPDATE OR DELETE ON %s '
        'FOR EACH STATEMENT EXECUTE FUNCTION pgreact_internal.finalize_immediate_match_delta(%L)',
        version_row.match_name, version_row.rule_version_id::text);
    IF NOT EXISTS (
        SELECT 1 FROM pgtrickle.pgt_stream_tables stream
        WHERE stream.pgt_relid = version_row.match_relid
          AND stream.refresh_mode = 'IMMEDIATE'
    ) THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_CAPABILITY: pg_trickle did not enable IMMEDIATE for %', version_row.match_name;
    END IF;
    WITH RECURSIVE dependencies(relid) AS (
        SELECT version_row.source_view_oid
        UNION
        SELECT dependency.refobjid
        FROM dependencies parent
        JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
        JOIN pg_depend dependency
          ON dependency.classid = 'pg_rewrite'::regclass
         AND dependency.objid = rewrite.oid
         AND dependency.refclassid = 'pg_class'::regclass
         AND dependency.deptype = 'n'
    )
    SELECT min(relation.oid) FILTER (WHERE relation.relkind IN ('r', 'p'))
    INTO source_oid
    FROM dependencies
    JOIN pg_class relation ON relation.oid = dependencies.relid;
    IF source_oid IS NOT NULL THEN
        EXECUTE format('DROP TRIGGER IF EXISTS zz_pgreact_immediate_propagate ON %s', source_oid::regclass);
        EXECUTE format(
            'CREATE TRIGGER zz_pgreact_immediate_propagate AFTER INSERT OR UPDATE OR DELETE ON %s '
            'FOR EACH STATEMENT EXECUTE FUNCTION pgreact_internal.propagate_immediate_facts()',
            source_oid::regclass);
    END IF;
    INSERT INTO pgreact_internal.immediate_audits(object_identity, operation, details)
    VALUES (version_row.rule_version_id::text, 'ENABLE_RULE',
            jsonb_build_object('rule', version_row.source_view_name,
                               'match', version_row.match_name,
                               'lock', 'rule-version advisory xact lock',
                               'visibility', 'READ COMMITTED same transaction'));
END
$m19$;

CREATE FUNCTION pgreact_api.author_immediate_rule(
    rule_name text,
    condition regclass,
    semantic_key name
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE target_version uuid;
    diagnostic record;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_immediate_rule(condition, semantic_key) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_INVALID: % for %: %', diagnostic.code,
            diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    target_version := pgreact_api.author_rule(
        rule_name => rule_name, condition => condition,
        semantic_key => semantic_key, kind => 'CONSTRAINT');
    PERFORM pgreact_internal.enable_immediate_rule(target_version);
    RETURN target_version;
END
$m19$;

CREATE FUNCTION pgreact_api.replace_immediate_rule(
    rule_name text,
    condition regclass,
    semantic_key name
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE target_version uuid;
    prior_version uuid;
    diagnostic record;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_immediate_rule(condition, semantic_key) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_INVALID: % for %: %', diagnostic.code,
            diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    SELECT version.rule_version_id INTO prior_version
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    WHERE rule.rule_name = replace_immediate_rule.rule_name
      AND version.state IN ('ACTIVE', 'PAUSED')
    ORDER BY version.created_at DESC
    LIMIT 1;
    IF prior_version IS NULL THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_NOT_FOUND: %', rule_name;
    END IF;
    target_version := pgreact.replace_rule(
        prior_version, condition, ARRAY[semantic_key]::name[], NULL,
        'SEED_CURRENT', NULL, NULL, 'DRAIN_OLD');
    PERFORM pgreact_internal.enable_immediate_rule(target_version);
    RETURN target_version;
END
$m19$;

CREATE FUNCTION pgreact_api.validate_immediate_program(definition jsonb)
RETURNS TABLE(
    contract_version integer, code text, severity text,
    object_identity text, message text, hint text, details jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE diagnostic record;
    item jsonb;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_program(definition) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RETURN QUERY SELECT 7, diagnostic.code, diagnostic.severity,
            diagnostic.object_identity, diagnostic.message, diagnostic.hint,
            diagnostic.details;
        RETURN;
    END IF;
    IF jsonb_typeof(definition -> 'rules') IS DISTINCT FROM 'array'
       OR jsonb_array_length(definition -> 'rules') = 0 THEN
        RETURN QUERY SELECT 7, 'M19_PROGRAM_EMPTY', 'ERROR',
            COALESCE(definition ->> 'name', 'program'),
            'an immediate derivation program must contain at least one rule',
            'Provide one or more positive finite derivation rules.', '{}'::jsonb;
        RETURN;
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(definition -> 'rules') LOOP
        IF jsonb_array_length(COALESCE(item -> 'negative_inputs', '[]'::jsonb)) > 0 THEN
            RETURN QUERY SELECT 7, 'M19_NEGATION_UNSUPPORTED', 'ERROR', item ->> 'name',
                'immediate derivations are positive only',
                'Remove negative inputs or deploy the program in scheduled mode.', '{}'::jsonb;
            RETURN;
        END IF;
        IF item ? 'aggregate_input' THEN
            RETURN QUERY SELECT 7, 'M19_AGGREGATE_UNSUPPORTED', 'ERROR', item ->> 'name',
                'aggregates are outside the immediate derivation closure',
                'Keep aggregate rules scheduled.', '{}'::jsonb;
            RETURN;
        END IF;
        IF item ? 'window' OR item ? 'deadline' THEN
            RETURN QUERY SELECT 7, 'M19_TEMPORAL_UNSUPPORTED', 'ERROR', item ->> 'name',
                'temporal rules are outside the immediate derivation closure',
                'Keep window and deadline rules scheduled.', '{}'::jsonb;
            RETURN;
        END IF;
    END LOOP;
    IF (SELECT extversion FROM pg_extension WHERE extname = 'pg_trickle') IS DISTINCT FROM '0.81.0'
       OR current_setting('transaction_isolation') <> 'read committed'
       OR COALESCE(current_setting('pg_trickle.user_triggers', true), '') <> 'auto'
    THEN
        RETURN QUERY SELECT 7, 'M19_TRICKLE_CAPABILITY', 'ERROR', 'pg_trickle',
            'the pinned immediate-maintenance capability is unavailable',
            'Use PostgreSQL 18.3, pg_trickle 0.81.0, READ COMMITTED, and pg_trickle.user_triggers=auto.', '{}'::jsonb;
        RETURN;
    END IF;
    RETURN QUERY SELECT 7, 'OK', 'INFO', definition ->> 'name',
        'program is eligible for a finite positive immediate closure',
        'Call pgreact_api.deploy_immediate_program with the preview digest.',
        jsonb_build_object('maintenance_mode', 'IMMEDIATE', 'closure', 'finite acyclic positive',
                           'downstream_boundary', 'scheduled consumers remain asynchronous');
EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT 7, 'M19_PROGRAM_VALIDATION', 'ERROR',
        COALESCE(definition ->> 'name', 'program'), SQLERRM,
        'Correct the program or deploy it in scheduled mode.', '{}'::jsonb;
END
$m19$;

CREATE FUNCTION pgreact_api.preview_immediate_program(definition jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE diagnostic record;
    preview jsonb;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_immediate_program(definition) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M19_PROGRAM_INVALID: % for %: %', diagnostic.code,
            diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    preview := pgreact_api.preview_program(definition);
    RETURN preview || jsonb_build_object(
        'contract_version', 7,
        'maintenance_mode', 'IMMEDIATE',
        'visibility', 'same transaction after each supported source statement',
        'consequence_boundary', 'committed asynchronous agenda');
END
$m19$;

CREATE FUNCTION pgreact_api.deploy_immediate_program(
    definition jsonb,
    expected_plan_digest text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE diagnostic record;
    target_program uuid;
    member record;
    program_name text := definition ->> 'name';
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_immediate_program(definition) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M19_PROGRAM_INVALID: % for %: %', diagnostic.code,
            diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(program_name, 5788046901200003));
    target_program := pgreact_api.deploy_program(definition, expected_plan_digest);
    UPDATE pgreact_internal.derivation_program_versions
    SET maintenance_mode = 'IMMEDIATE'
    WHERE program_version_id = target_program;
    -- Convert the whole closure before re-enabling its triggers; otherwise a
    -- downstream full refresh can observe an upstream mode transition.
    PERFORM set_config('session_replication_role', 'replica', true);
    FOR member IN
        SELECT version.rule_version_id, version.match_name
        FROM pgreact_internal.derivation_program_rules program_rule
        JOIN pgreact_internal.rule_versions version
          ON version.rule_version_id = program_rule.rule_version_id
        WHERE program_rule.program_version_id = target_program
        ORDER BY program_rule.rule_order DESC
    LOOP
        IF NOT EXISTS (
            SELECT 1
            FROM pgreact_internal.derivation_program_inputs input
            WHERE input.program_version_id = target_program
              AND input.rule_version_id = member.rule_version_id
        ) THEN
            PERFORM pgreact_internal.enable_immediate_rule(member.rule_version_id);
        ELSE
            -- ponytail: pg_trickle 0.81 cannot nest IMMEDIATE stream refreshes;
            -- roots stay native, downstream members use ordered closure refresh.
            PERFORM pgreact_internal.mark_immediate_rule(member.rule_version_id);
        END IF;
    END LOOP;
    PERFORM set_config('session_replication_role', 'origin', true);
    INSERT INTO pgreact_internal.immediate_audits(object_identity, operation, details)
    VALUES (program_name, 'ENABLE_PROGRAM',
            jsonb_build_object('program_version_id', target_program,
                               'closure', 'finite acyclic positive',
                               'lock', 'program advisory xact lock'));
    RETURN target_program;
END
$m19$;

ALTER FUNCTION pgreact_api.status(text) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.status(text) RENAME TO status_m18;

CREATE FUNCTION pgreact_api.status(name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE result jsonb;
BEGIN
    result := pgreact_internal.status_m18(name);
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.rule_versions version
        JOIN pgreact_internal.rules rule USING (rule_id)
        WHERE version.maintenance_mode = 'IMMEDIATE'
          AND (name IS NULL OR rule.rule_name = name)
    ) THEN
        result := jsonb_set(result, '{rules}', (
            SELECT jsonb_agg(
                CASE WHEN version.maintenance_mode = 'IMMEDIATE'
                     THEN item.value || jsonb_build_object('maintenance_mode', 'IMMEDIATE')
                     ELSE item.value END
                ORDER BY item.ordinality)
            FROM jsonb_array_elements(result -> 'rules') WITH ORDINALITY item
            LEFT JOIN pgreact_internal.rules rule ON rule.rule_name = item.value ->> 'rule'
            LEFT JOIN pgreact_internal.rule_versions version ON version.rule_id = rule.rule_id
                AND version.state <> 'REMOVED'
        ), true);
        result := jsonb_set(result, '{contract_version}', '7'::jsonb, true);
    END IF;
    IF name IS NOT NULL AND EXISTS (
        SELECT 1 FROM pgreact_internal.derivation_programs program
        JOIN pgreact_internal.derivation_program_versions version USING (program_id)
        WHERE program.program_name = name AND version.state = 'ACTIVE'
          AND version.maintenance_mode = 'IMMEDIATE'
    ) THEN
        result := jsonb_set(result, '{programs}', (
            SELECT jsonb_agg(
                CASE WHEN version.maintenance_mode = 'IMMEDIATE'
                     THEN item.value || jsonb_build_object('maintenance_mode', 'IMMEDIATE')
                     ELSE item.value END
                ORDER BY item.ordinality)
            FROM jsonb_array_elements(result -> 'programs') WITH ORDINALITY item
            LEFT JOIN pgreact_internal.derivation_programs program
              ON program.program_name = item.value ->> 'program'
            LEFT JOIN pgreact_internal.derivation_program_versions version
              ON version.program_id = program.program_id AND version.state = 'ACTIVE'
        ), true);
        result := jsonb_set(result, '{contract_version}', '7'::jsonb, true);
    END IF;
    RETURN result;
END
$m19$;

ALTER FUNCTION pgreact_api.matches(text) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.matches(text) RENAME TO matches_m18;

CREATE FUNCTION pgreact_api.matches(name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE result jsonb;
BEGIN
    result := pgreact_internal.matches_m18(name);
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.rules rule
        JOIN pgreact_internal.rule_versions version USING (rule_id)
        WHERE version.maintenance_mode = 'IMMEDIATE'
          AND (name IS NULL OR rule.rule_name = name)
    ) THEN
        result := jsonb_set(result, '{matches}', (
            SELECT COALESCE(jsonb_agg(
                CASE WHEN EXISTS (
                    SELECT 1 FROM pgreact_internal.rules rule
                    JOIN pgreact_internal.rule_versions version USING (rule_id)
                    WHERE rule.rule_name = item.value ->> 'rule'
                      AND version.maintenance_mode = 'IMMEDIATE')
                    THEN item.value || jsonb_build_object('maintenance_mode', 'IMMEDIATE')
                    ELSE item.value END
                ORDER BY item.ordinality), '[]'::jsonb)
            FROM (
                SELECT DISTINCT ON (item.value ->> 'rule', item.value ->> 'key')
                    item.value, item.ordinality
                FROM jsonb_array_elements(result -> 'matches') WITH ORDINALITY item
                WHERE name IS NULL OR item.value ->> 'rule' = name
                ORDER BY item.value ->> 'rule', item.value ->> 'key', item.ordinality
            ) item), true);
        result := jsonb_set(result, '{contract_version}', '7'::jsonb, true);
    END IF;
    RETURN result;
END
$m19$;

ALTER FUNCTION pgreact_api.explain(text, jsonb) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.explain(text, jsonb) RENAME TO explain_m18;

CREATE FUNCTION pgreact_api.explain(target text, semantic_key jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE result jsonb;
    immediate boolean;
BEGIN
    result := pgreact_internal.explain_m18(target, semantic_key);
    SELECT EXISTS (
        SELECT 1 FROM pgreact_internal.rules rule
        JOIN pgreact_internal.rule_versions version USING (rule_id)
        WHERE rule.rule_name = target AND version.maintenance_mode = 'IMMEDIATE'
    ) OR EXISTS (
        SELECT 1
        FROM pgreact_internal.keyed_derived_relations derived
        JOIN pgreact_internal.derivation_program_rules member
          ON member.target_relation_version_id = derived.relation_version_id
        JOIN pgreact_internal.derivation_program_versions program
          ON program.program_version_id = member.program_version_id
         AND program.state = 'ACTIVE' AND program.maintenance_mode = 'IMMEDIATE'
        WHERE derived.public_name = target
    ) INTO immediate;
    IF immediate THEN
        RETURN result || jsonb_build_object(
            'contract_version', 7,
            'maintenance_mode', 'IMMEDIATE',
            'visibility', 'same transaction after each supported source statement',
            'consequence_boundary', 'committed asynchronous agenda');
    END IF;
    RETURN result;
END
$m19$;

ALTER FUNCTION pgreact_api.doctor() SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.doctor() RENAME TO doctor_m18;

CREATE FUNCTION pgreact_api.doctor()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
DECLARE result jsonb;
    diagnostics jsonb;
    immediate boolean;
BEGIN
    result := pgreact_internal.doctor_m18();
    SELECT EXISTS (SELECT 1 FROM pgreact_internal.rule_versions
                   WHERE maintenance_mode = 'IMMEDIATE')
        OR EXISTS (SELECT 1 FROM pgreact_internal.derivation_program_versions
                   WHERE maintenance_mode = 'IMMEDIATE' AND state = 'ACTIVE')
    INTO immediate;
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.ordinality), '[]'::jsonb)
    INTO diagnostics
    FROM jsonb_array_elements(COALESCE(result -> 'diagnostics', '[]'::jsonb))
         WITH ORDINALITY item
    WHERE item.value ->> 'code' <> 'M18_EXTENSION_VERSION';
    diagnostics := diagnostics || CASE WHEN EXISTS (
        SELECT 1 FROM pg_extension WHERE extname = 'pg_react' AND extversion = '0.16.0')
        THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object(
            'code', 'M19_EXTENSION_VERSION', 'severity', 'ERROR', 'object_identity', 'pg_react',
            'message', 'pg_react extension version is not 0.16.0',
            'hint', 'Install matching files and run ALTER EXTENSION pg_react UPDATE.')) END;
    diagnostics := diagnostics || CASE WHEN EXISTS (
        SELECT 1
        FROM pgreact_internal.rule_versions version
        LEFT JOIN pgtrickle.pgt_stream_tables stream ON stream.pgt_relid = version.match_relid
        WHERE version.maintenance_mode = 'IMMEDIATE'
          AND stream.refresh_mode IS DISTINCT FROM 'IMMEDIATE'
          AND NOT EXISTS (
              SELECT 1
              FROM pgreact_internal.derivation_program_rules program_rule
              JOIN pgreact_internal.derivation_program_versions program
                USING (program_version_id)
              JOIN pgreact_internal.derivation_program_inputs input
                USING (program_version_id, rule_version_id)
              WHERE program_rule.rule_version_id = version.rule_version_id
                AND program.state = 'ACTIVE'
                AND program.maintenance_mode = 'IMMEDIATE'))
        THEN jsonb_build_array(jsonb_build_object(
            'code', 'M19_IMMEDIATE_STREAM_MODE', 'severity', 'ERROR',
            'object_identity', 'pgreact',
            'message', 'an immediate rule is not backed by an IMMEDIATE pg_trickle stream',
            'hint', 'Reconcile or replace the immediate rule through the public API.'))
        ELSE '[]'::jsonb END;
    result := jsonb_set(result, '{diagnostics}', diagnostics, true);
    result := jsonb_set(result, '{contract_version}', CASE WHEN immediate THEN '7'::jsonb ELSE result -> 'contract_version' END, true);
    result := jsonb_set(result, '{status}', CASE WHEN EXISTS (
        SELECT 1 FROM jsonb_array_elements(diagnostics) item
        WHERE item ->> 'severity' = 'ERROR') THEN '"attention"'::jsonb ELSE '"ready"'::jsonb END, true);
    RETURN result;
END
$m19$;

ALTER FUNCTION pgreact_api.configure_roles(regrole, regrole, regrole, regrole, regrole)
    SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.configure_roles(regrole, regrole, regrole, regrole, regrole)
    RENAME TO configure_roles_m18;

CREATE FUNCTION pgreact_api.configure_roles(
    author_role regrole,
    operator_role regrole,
    worker_role regrole,
    reader_role regrole,
    advanced_reader_role regrole
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m19$
BEGIN
    PERFORM pgreact_internal.configure_roles_m18(
        author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.immediate_capabilities(), '
        'pgreact_api.validate_immediate_rule(regclass,name), '
        'pgreact_api.author_immediate_rule(text,regclass,name), '
        'pgreact_api.replace_immediate_rule(text,regclass,name), '
        'pgreact_api.validate_immediate_program(jsonb), '
        'pgreact_api.preview_immediate_program(jsonb), '
        'pgreact_api.deploy_immediate_program(jsonb,text) TO %I', author_role::text);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.immediate_capabilities(), '
        'pgreact_api.status(text), pgreact_api.matches(text), '
        'pgreact_api.explain(text,jsonb), pgreact_api.doctor() TO %I', reader_role::text);
END
$m19$;

DO $m19$
DECLARE
    author_role regrole;
    operator_role regrole;
    worker_role regrole;
    reader_role regrole;
    advanced_reader_role regrole;
BEGIN
    SELECT role_oid::regrole INTO author_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'author';
    SELECT role_oid::regrole INTO operator_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'operator';
    SELECT role_oid::regrole INTO worker_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'worker';
    SELECT role_oid::regrole INTO reader_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'reader';
    SELECT role_oid::regrole INTO advanced_reader_role
    FROM pgreact_internal.advanced_readers;
    IF author_role IS NOT NULL AND operator_role IS NOT NULL
       AND worker_role IS NOT NULL AND reader_role IS NOT NULL
       AND advanced_reader_role IS NOT NULL THEN
        PERFORM pgreact_api.configure_roles(
            author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    END IF;
END
$m19$;

REVOKE ALL ON ALL TABLES IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_api FROM PUBLIC;

COMMENT ON EXTENSION pg_react IS
    'M19 selective immediate maintenance over the scheduled durable rule engine';
-- M20 explicit, versioned shared conditions over the existing keyed
-- derived-relation and derivation-program machinery.

CREATE TABLE pgreact_internal.shared_conditions (
    condition_id uuid PRIMARY KEY,
    condition_name text NOT NULL UNIQUE,
    owner_oid oid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE pgreact_internal.shared_condition_versions (
    condition_version_id uuid PRIMARY KEY,
    condition_id uuid NOT NULL REFERENCES pgreact_internal.shared_conditions,
    version integer NOT NULL CHECK (version > 0),
    owner_oid oid NOT NULL,
    source_view_oid oid NOT NULL,
    source_view_name text NOT NULL,
    source_definition text NOT NULL,
    source_definition_digest bytea NOT NULL,
    source_row_signature bytea NOT NULL,
    row_type_oid oid NOT NULL,
    row_type_name text NOT NULL,
    key_columns name[] NOT NULL CHECK (cardinality(key_columns) BETWEEN 1 AND 4),
    key_types regtype[] NOT NULL,
    key_collations regcollation[] NOT NULL,
    relation_version_id uuid NOT NULL
        REFERENCES pgreact_internal.derived_relation_versions,
    program_version_id uuid NOT NULL
        REFERENCES pgreact_internal.derivation_program_versions,
    maintenance_mode text NOT NULL CHECK (maintenance_mode IN ('SCHEDULED', 'IMMEDIATE')),
    state text NOT NULL CHECK (state IN ('ACTIVE', 'REMOVED')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (condition_id, version)
);

CREATE UNIQUE INDEX shared_condition_one_active_version
    ON pgreact_internal.shared_condition_versions (condition_id)
    WHERE state = 'ACTIVE';

CREATE TABLE pgreact_internal.shared_condition_consumers (
    condition_version_id uuid NOT NULL
        REFERENCES pgreact_internal.shared_condition_versions,
    consumer_kind text NOT NULL CHECK (consumer_kind IN ('RULE', 'PROGRAM')),
    consumer_name text NOT NULL,
    consumer_version_id uuid NOT NULL,
    owner_oid oid NOT NULL,
    registered_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (condition_version_id, consumer_kind, consumer_name)
);

CREATE TABLE pgreact_internal.shared_condition_grants (
    condition_id uuid NOT NULL REFERENCES pgreact_internal.shared_conditions,
    role_oid oid NOT NULL,
    granted_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (condition_id, role_oid)
);

CREATE FUNCTION pgreact_internal.condition_keys(definition jsonb)
RETURNS name[]
LANGUAGE SQL
IMMUTABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT CASE jsonb_typeof($1 -> 'key')
        WHEN 'string' THEN ARRAY[($1 ->> 'key')::name]
        WHEN 'array' THEN ARRAY(
            SELECT value::name FROM jsonb_array_elements_text($1 -> 'key'))
        ELSE NULL::name[]
    END
$$;

CREATE FUNCTION pgreact_internal.condition_program(definition jsonb, target_version integer)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $$
#variable_conflict use_variable
DECLARE
    condition_name text := definition ->> 'name';
    source_name text := definition ->> 'source';
    keys name[] := pgreact_internal.condition_keys(definition);
    program_name text := '__pgreact.condition.' || condition_name;
BEGIN
    RETURN jsonb_build_object(
        'name', program_name,
        'version', target_version,
        'max_iterations', 8,
        'max_facts', 100000,
        'rules', jsonb_build_array(jsonb_build_object(
            'name', program_name || '.maintain',
            'definition', source_name,
            'key', keys[1],
            'target', condition_name,
            'version', target_version)));
END
$$;

CREATE FUNCTION pgreact_api.validate_shared_condition(definition jsonb)
RETURNS TABLE(
    contract_version integer, code text, severity text,
    object_identity text, message text, hint text, details jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
#variable_conflict use_variable
DECLARE
    source_oid oid;
    target_oid oid;
    row_type_oid oid;
    row_relid oid;
    row_owner oid;
    source_owner oid;
    keys name[];
    key_types regtype[];
    key_collations regcollation[];
    source_signature bytea;
    mode text := upper(COALESCE(definition ->> 'maintenance_mode', 'SCHEDULED'));
    condition_name text := definition ->> 'name';
BEGIN
    IF jsonb_typeof(definition) IS DISTINCT FROM 'object'
       OR condition_name IS NULL
       OR definition ->> 'source' IS NULL
       OR definition ->> 'row_type' IS NULL
       OR pgreact_internal.condition_keys(definition) IS NULL THEN
        RETURN QUERY SELECT 8, 'M20_DEFINITION_SHAPE', 'ERROR',
            COALESCE(condition_name, 'condition'),
            'shared condition definitions require name, source, row_type, and key',
            'Use a schema-qualified relation, an owned composite row type, and one to four named key columns.',
            '{}'::jsonb;
        RETURN;
    END IF;
    keys := pgreact_internal.condition_keys(definition);
    IF cardinality(keys) NOT BETWEEN 1 AND 4
       OR array_position(keys, NULL) IS NOT NULL
       OR (SELECT count(DISTINCT key) FROM unnest(keys) key) <> cardinality(keys) THEN
        RETURN QUERY SELECT 8, 'M20_KEY_ARITY', 'ERROR', condition_name,
            'shared condition keys require one to four distinct columns',
            'Use one to four non-null, distinct key names.', '{}'::jsonb;
        RETURN;
    END IF;
    IF mode NOT IN ('SCHEDULED', 'IMMEDIATE') THEN
        RETURN QUERY SELECT 8, 'M20_MAINTENANCE_MODE', 'ERROR', condition_name,
            'shared condition maintenance_mode is unsupported',
            'Choose SCHEDULED or IMMEDIATE.', jsonb_build_object('maintenance_mode', mode);
        RETURN;
    END IF;
    source_oid := to_regclass(definition ->> 'source');
    IF source_oid IS NULL THEN
        RETURN QUERY SELECT 8, 'M20_SOURCE_NOT_FOUND', 'ERROR', definition ->> 'source',
            'the shared condition source relation does not exist',
            'Create the schema-qualified source view before previewing the condition.', '{}'::jsonb;
        RETURN;
    END IF;
    IF (SELECT relkind FROM pg_class WHERE oid = source_oid) NOT IN ('v', 'm') THEN
        RETURN QUERY SELECT 8, 'M20_SOURCE_KIND', 'ERROR', source_oid::regclass::text,
            'shared condition sources must be views or materialized views',
            'Expose the SQL condition through a view.', '{}'::jsonb;
        RETURN;
    END IF;
    SELECT relowner INTO source_owner FROM pg_class WHERE oid = source_oid;
    IF source_owner <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RETURN QUERY SELECT 8, 'M20_SOURCE_OWNER', 'ERROR', source_oid::regclass::text,
            'the condition author must own the source view',
            'Use the source view owner to declare the shared condition.', '{}'::jsonb;
        RETURN;
    END IF;
    row_type_oid := to_regtype(definition ->> 'row_type');
    SELECT typrelid, typowner INTO row_relid, row_owner
    FROM pg_type WHERE oid = row_type_oid;
    IF row_type_oid IS NULL OR row_relid = 0 OR row_owner <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RETURN QUERY SELECT 8, 'M20_ROW_TYPE', 'ERROR', COALESCE(definition ->> 'row_type', 'row_type'),
            'the condition row_type must be an owned composite type',
            'Create and own a composite type matching the source view columns.', '{}'::jsonb;
        RETURN;
    END IF;
    IF pgreact_internal.source_row_signature(source_oid)
       IS DISTINCT FROM pgreact_internal.source_row_signature(row_relid) THEN
        RETURN QUERY SELECT 8, 'M20_SCHEMA_MISMATCH', 'ERROR', condition_name,
            'the source view columns do not match row_type',
            'Keep column names, order, types, and collations identical.',
            jsonb_build_object('source', source_oid::regclass::text,
                               'row_type', row_type_oid::regtype::text);
        RETURN;
    END IF;
    SELECT array_agg(attribute.atttypid::regtype ORDER BY key.ordinality),
           array_agg(attribute.attcollation::regcollation ORDER BY key.ordinality)
    INTO key_types, key_collations
    FROM unnest(keys) WITH ORDINALITY key(key_name, ordinality)
    LEFT JOIN pg_attribute attribute
      ON attribute.attrelid = row_relid AND attribute.attname = key.key_name
     AND attribute.attnum > 0 AND NOT attribute.attisdropped;
    IF COALESCE(cardinality(key_types), 0) <> cardinality(keys)
       OR EXISTS (SELECT 1 FROM unnest(COALESCE(key_types, ARRAY[]::regtype[])) key_type
                 WHERE key_type IS NULL) THEN
        RETURN QUERY SELECT 8, 'M20_KEY_NOT_FOUND', 'ERROR', condition_name,
            'every shared condition key must be a row_type attribute',
            'Use key columns present in the source view and row_type.',
            jsonb_build_object('key', keys);
        RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(key_types) key_type
               WHERE key_type NOT IN ('bigint'::regtype, 'uuid'::regtype, 'text'::regtype)) THEN
        RETURN QUERY SELECT 8, 'M20_KEY_TYPE', 'ERROR', condition_name,
            'shared condition keys use unsupported types',
            'Use bigint, uuid, or deterministic-C-collated text keys.',
            jsonb_build_object('key_types', key_types);
        RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_attribute attribute
               JOIN pg_collation key_collation ON key_collation.oid = attribute.attcollation
               WHERE attribute.attrelid = row_relid
                 AND attribute.attname = ANY(keys)
                 AND attribute.atttypid = 'text'::regtype
                 AND (NOT key_collation.collisdeterministic OR key_collation.collname NOT IN ('C', 'default'))) THEN
        RETURN QUERY SELECT 8, 'M20_KEY_COLLATION', 'ERROR', condition_name,
            'text keys require a deterministic C collation',
            'Use COLLATE "C" for text semantic keys.', '{}'::jsonb;
        RETURN;
    END IF;
    IF EXISTS (
        WITH RECURSIVE dependencies(relid) AS (
            SELECT source_oid
            UNION
            SELECT dependency.refobjid
            FROM dependencies parent
            JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
            JOIN pg_depend dependency
              ON dependency.classid = 'pg_rewrite'::regclass
             AND dependency.objid = rewrite.oid
             AND dependency.refclassid = 'pg_class'::regclass
             AND dependency.deptype = 'n')
        SELECT 1 FROM dependencies
        JOIN pg_class relation ON relation.oid = dependencies.relid
        WHERE relation.relrowsecurity) THEN
        RETURN QUERY SELECT 8, 'M20_RLS_UNSUPPORTED', 'ERROR', condition_name,
            'shared condition sources may not depend on row-level-security relations',
            'Expose an authorized, non-RLS source view for this condition.', '{}'::jsonb;
        RETURN;
    END IF;
    target_oid := to_regclass(condition_name);
    IF target_oid IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pgreact_internal.shared_conditions
        WHERE shared_conditions.condition_name = condition_name) THEN
        RETURN QUERY SELECT 8, 'M20_RELATION_EXISTS', 'ERROR', condition_name,
            'the shared condition public relation already exists',
            'Choose a new condition name or remove the unrelated relation first.', '{}'::jsonb;
        RETURN;
    END IF;
    IF target_oid IS NOT NULL AND EXISTS (
        WITH RECURSIVE dependencies(relid) AS (
            SELECT source_oid
            UNION
            SELECT dependency.refobjid
            FROM dependencies parent
            JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
            JOIN pg_depend dependency
              ON dependency.classid = 'pg_rewrite'::regclass
             AND dependency.objid = rewrite.oid
             AND dependency.refclassid = 'pg_class'::regclass
             AND dependency.deptype = 'n')
        SELECT 1 FROM dependencies WHERE relid = target_oid) THEN
        RETURN QUERY SELECT 8, 'M20_CONDITION_CYCLE', 'ERROR', condition_name,
            'a shared condition cannot depend on its own public relation',
            'Remove the self-reference from the source view.', '{}'::jsonb;
        RETURN;
    END IF;
    source_signature := pgreact_internal.source_row_signature(source_oid);
    RETURN QUERY SELECT 8, 'OK', 'INFO', condition_name,
        'shared condition definition is valid',
        'Preview the condition before deployment.',
        jsonb_build_object('source', source_oid::regclass::text,
                           'row_type', row_type_oid::regtype::text,
                           'key_columns', keys,
                           'key_types', key_types,
                           'maintenance_mode', mode,
                           'source_row_signature', encode(source_signature, 'hex'));
EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT 8, 'M20_VALIDATION', 'ERROR',
        COALESCE(condition_name, 'condition'), SQLERRM,
        'Correct the shared condition definition and validate again.', '{}'::jsonb;
END
$$;

CREATE FUNCTION pgreact_api.preview_shared_condition(definition jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    diagnostic record;
    normalized jsonb := definition;
    source_oid oid;
    source_digest text;
    next_version integer;
    expected_version integer;
    plan_digest text;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_shared_condition(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M20_CONDITION_INVALID: % for %: %', diagnostic.code,
            diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    SELECT COALESCE(max(version), 0) + 1 INTO next_version
    FROM pgreact_internal.shared_condition_versions version
    JOIN pgreact_internal.shared_conditions condition USING (condition_id)
    WHERE condition.condition_name = definition ->> 'name';
    expected_version := COALESCE((definition ->> 'version')::integer, next_version);
    IF expected_version <> next_version THEN
        RAISE EXCEPTION 'M20_VERSION_ORDER: expected version %, received %',
            next_version, expected_version;
    END IF;
    normalized := jsonb_set(definition, '{version}', to_jsonb(next_version), true);
    source_oid := to_regclass(normalized ->> 'source');
    source_digest := encode(pgreact_internal.source_closure_digest(source_oid), 'hex');
    plan_digest := encode(sha256(convert_to(
        normalized::text || ':' || session_user || ':' || source_digest, 'UTF8')), 'hex');
    RETURN jsonb_build_object(
        'contract_version', 8,
        'condition', normalized,
        'relation', normalized ->> 'name',
        'version', next_version,
        'maintenance_mode', upper(COALESCE(normalized ->> 'maintenance_mode', 'SCHEDULED')),
        'source_digest', source_digest,
        'consumers', '[]'::jsonb,
        'program', pgreact_internal.condition_program(normalized, next_version),
        'plan_digest', plan_digest);
END
$$;

CREATE FUNCTION pgreact_internal.refresh_shared_condition_consumers(target_version_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    condition_relation uuid;
BEGIN
    SELECT relation_version_id INTO STRICT condition_relation
    FROM pgreact_internal.shared_condition_versions
    WHERE condition_version_id = target_version_id;
    DELETE FROM pgreact_internal.shared_condition_consumers
    WHERE condition_version_id = target_version_id;
    INSERT INTO pgreact_internal.shared_condition_consumers(
        condition_version_id, consumer_kind, consumer_name,
        consumer_version_id, owner_oid)
    SELECT target_version_id, 'RULE', rule.rule_name,
           version.rule_version_id, version.owner_oid
    FROM pgreact_internal.rule_versions version
    LEFT JOIN pgreact_internal.keyed_rule_versions keyed
      ON version.rule_version_id = keyed.rule_version_id
    JOIN pgreact_internal.rules rule USING (rule_id)
    WHERE (version.source_view_oid = (
               SELECT condition.condition_name::regclass
               FROM pgreact_internal.shared_condition_versions version
               JOIN pgreact_internal.shared_conditions condition
                 USING (condition_id)
               WHERE version.condition_version_id = target_version_id)
           OR keyed.public_condition = (
               SELECT condition.condition_name::regclass
               FROM pgreact_internal.shared_condition_versions version
               JOIN pgreact_internal.shared_conditions condition
                 USING (condition_id)
               WHERE version.condition_version_id = target_version_id))
      AND version.state IN ('ACTIVE', 'PAUSED');
    INSERT INTO pgreact_internal.shared_condition_consumers(
        condition_version_id, consumer_kind, consumer_name,
        consumer_version_id, owner_oid)
    SELECT DISTINCT target_version_id, 'PROGRAM', program.program_name,
           program_version.program_version_id, program_version.owner_oid
    FROM pgreact_internal.derivation_program_inputs input
    JOIN pgreact_internal.derivation_program_versions program_version
      ON program_version.program_version_id = input.program_version_id
    JOIN pgreact_internal.derivation_programs program
      USING (program_id)
    WHERE input.relation_version_id = condition_relation
      AND program_version.state = 'ACTIVE';
END
$$;

CREATE FUNCTION pgreact_api.deploy_shared_condition(
    definition jsonb,
    expected_plan_digest text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    preview jsonb;
    normalized jsonb;
    condition_row pgreact_internal.shared_conditions%ROWTYPE;
    prior pgreact_internal.shared_condition_versions%ROWTYPE;
    source_oid oid;
    row_type_oid oid;
    relation_version uuid;
    program_version uuid;
    condition_version uuid := gen_random_uuid();
    target_version integer;
    actual_plan_digest text;
    program_definition jsonb;
    program_preview jsonb;
    program_name text;
    mode text;
    keys name[];
    key_types regtype[];
    key_collations regcollation[];
    source_definition text;
    source_signature bytea;
    source_digest bytea;
    condition_owner oid := (SELECT oid FROM pg_roles WHERE rolname = session_user);
    incompatible boolean := false;
    consumer_count bigint;
    has_prior boolean := false;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(
        COALESCE(definition ->> 'name', 'condition'), 5788046901200004));
    preview := pgreact_api.preview_shared_condition(definition);
    normalized := preview -> 'condition';
    target_version := (normalized ->> 'version')::integer;
    actual_plan_digest := preview ->> 'plan_digest';
    IF expected_plan_digest IS NOT NULL AND expected_plan_digest <> actual_plan_digest THEN
        RAISE EXCEPTION 'M20_CONDITION_PREVIEW_STALE'
            USING HINT = 'Preview the shared condition again after source or deployment changes.';
    END IF;
    SELECT * INTO condition_row
    FROM pgreact_internal.shared_conditions
    WHERE condition_name = normalized ->> 'name'
    FOR UPDATE;
    IF FOUND AND condition_row.owner_oid <> condition_owner THEN
        RAISE EXCEPTION 'M20_CONDITION_OWNER: % is not owned by %',
            normalized ->> 'name', session_user;
    END IF;
    IF NOT FOUND THEN
        INSERT INTO pgreact_internal.shared_conditions(condition_id, condition_name, owner_oid)
        VALUES (condition_version, normalized ->> 'name', condition_owner)
        RETURNING * INTO condition_row;
        relation_version := pgreact_api.declare_derived_relation(
            normalized ->> 'name', (normalized ->> 'row_type')::regtype,
            pgreact_internal.condition_keys(normalized), 1);
        EXECUTE format('ALTER VIEW %s OWNER TO %I',
                       normalized ->> 'name', session_user);
    ELSE
        has_prior := true;
        SELECT * INTO STRICT prior
        FROM pgreact_internal.shared_condition_versions
        WHERE condition_id = condition_row.condition_id AND state = 'ACTIVE'
        FOR UPDATE;
        PERFORM pgreact_internal.refresh_shared_condition_consumers(prior.condition_version_id);
        SELECT count(*) INTO consumer_count
        FROM pgreact_internal.shared_condition_consumers
        WHERE condition_version_id = prior.condition_version_id;
        source_oid := to_regclass(normalized ->> 'source');
        row_type_oid := (normalized ->> 'row_type')::regtype;
        keys := pgreact_internal.condition_keys(normalized);
        SELECT array_agg(attribute.atttypid::regtype ORDER BY key.ordinality),
               array_agg(attribute.attcollation::regcollation ORDER BY key.ordinality)
        INTO key_types, key_collations
        FROM unnest(keys) WITH ORDINALITY key(key_name, ordinality)
        JOIN pg_attribute attribute
          ON attribute.attrelid = (SELECT typrelid FROM pg_type WHERE oid = row_type_oid)
         AND attribute.attname = key.key_name
         AND attribute.attnum > 0 AND NOT attribute.attisdropped;
        incompatible := prior.row_type_oid <> row_type_oid
            OR prior.key_columns <> keys
            OR prior.key_types <> key_types
            OR prior.key_collations <> key_collations
            OR prior.maintenance_mode <> upper(COALESCE(normalized ->> 'maintenance_mode', 'SCHEDULED'))
            OR prior.source_row_signature <> pgreact_internal.source_row_signature(source_oid);
        IF incompatible AND consumer_count > 0 THEN
            RAISE EXCEPTION 'M20_INCOMPATIBLE_REPLACEMENT: % has live consumers',
                normalized ->> 'name'
                USING HINT = 'Deploy a compatible schema or remove/replace every consumer atomically.';
        END IF;
        relation_version := prior.relation_version_id;
    END IF;
    source_oid := to_regclass(normalized ->> 'source');
    row_type_oid := (normalized ->> 'row_type')::regtype;
    keys := pgreact_internal.condition_keys(normalized);
    SELECT array_agg(attribute.atttypid::regtype ORDER BY key.ordinality),
           array_agg(attribute.attcollation::regcollation ORDER BY key.ordinality)
    INTO key_types, key_collations
    FROM unnest(keys) WITH ORDINALITY key(key_name, ordinality)
    JOIN pg_attribute attribute
      ON attribute.attrelid = (SELECT typrelid FROM pg_type WHERE oid = row_type_oid)
     AND attribute.attname = key.key_name
     AND attribute.attnum > 0 AND NOT attribute.attisdropped;
    source_definition := COALESCE(pg_get_viewdef(source_oid, true), source_oid::regclass::text);
    source_signature := pgreact_internal.source_row_signature(source_oid);
    source_digest := pgreact_internal.source_closure_digest(source_oid);
    mode := upper(COALESCE(normalized ->> 'maintenance_mode', 'SCHEDULED'));
    program_definition := pgreact_internal.condition_program(normalized, target_version);
    program_name := program_definition ->> 'name';
    IF mode = 'IMMEDIATE' THEN
        program_preview := pgreact_api.preview_immediate_program(program_definition);
        program_version := pgreact_api.deploy_immediate_program(
            program_definition, program_preview ->> 'plan_digest');
    ELSE
        program_preview := pgreact_api.preview_program(program_definition);
        program_version := pgreact_api.deploy_program(
            program_definition, program_preview ->> 'plan_digest');
    END IF;
    IF has_prior THEN
        UPDATE pgreact_internal.shared_condition_versions
        SET state = 'REMOVED'
        WHERE condition_version_id = prior.condition_version_id;
    END IF;
    INSERT INTO pgreact_internal.shared_condition_versions(
        condition_version_id, condition_id, version, owner_oid,
        source_view_oid, source_view_name, source_definition,
        source_definition_digest, source_row_signature, row_type_oid,
        row_type_name, key_columns, key_types, key_collations,
        relation_version_id, program_version_id, maintenance_mode, state)
    SELECT condition_version, condition_row.condition_id, target_version, condition_owner,
           source_oid, source_oid::regclass::text, source_definition,
           source_digest, source_signature,
           row_type_oid, normalized ->> 'row_type',
           keys, key_types, key_collations, relation_version, program_version,
           mode, 'ACTIVE';
    PERFORM pgreact_internal.refresh_shared_condition_consumers(condition_version);
    RETURN condition_version;
END
$$;

CREATE FUNCTION pgreact_api.register_shared_condition_consumer(
    condition_name text,
    consumer_kind text,
    consumer_name text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    condition_version pgreact_internal.shared_condition_versions%ROWTYPE;
    consumer_version uuid;
    consumer_owner oid;
    normalized_kind text := upper(consumer_kind);
    target_relation uuid;
BEGIN
    SELECT version.* INTO STRICT condition_version
    FROM pgreact_internal.shared_conditions condition
    JOIN pgreact_internal.shared_condition_versions version USING (condition_id)
    WHERE condition.condition_name = register_shared_condition_consumer.condition_name
      AND version.state = 'ACTIVE';
    PERFORM pgreact_internal.refresh_shared_condition_consumers(condition_version.condition_version_id);
    IF normalized_kind = 'RULE' THEN
        SELECT version.rule_version_id, version.owner_oid INTO consumer_version, consumer_owner
        FROM pgreact_internal.rules rule
        JOIN pgreact_internal.rule_versions version USING (rule_id)
        WHERE rule.rule_name = consumer_name AND version.state IN ('ACTIVE', 'PAUSED')
        ORDER BY version.created_at DESC LIMIT 1;
        IF consumer_version IS NULL THEN
            RAISE EXCEPTION 'M20_CONSUMER_NOT_FOUND: rule %', consumer_name;
        END IF;
        IF NOT EXISTS (
            SELECT 1
            FROM pgreact_internal.rule_versions version
            LEFT JOIN pgreact_internal.keyed_rule_versions keyed
              ON keyed.rule_version_id = version.rule_version_id
            WHERE version.rule_version_id = consumer_version
              AND (version.source_view_oid = register_shared_condition_consumer.condition_name::regclass
                   OR keyed.public_condition = (
                       register_shared_condition_consumer.condition_name::regclass))) THEN
            RAISE EXCEPTION 'M20_CONSUMER_DEPENDENCY: rule % does not consume %',
                consumer_name, condition_name;
        END IF;
    ELSIF normalized_kind = 'PROGRAM' THEN
        SELECT version.program_version_id, version.owner_oid INTO consumer_version, consumer_owner
        FROM pgreact_internal.derivation_programs program
        JOIN pgreact_internal.derivation_program_versions version USING (program_id)
        WHERE program.program_name = consumer_name AND version.state = 'ACTIVE';
        IF consumer_version IS NULL THEN
            RAISE EXCEPTION 'M20_CONSUMER_NOT_FOUND: program %', consumer_name;
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM pgreact_internal.derivation_program_inputs input
            WHERE input.program_version_id = consumer_version
              AND input.relation_version_id = condition_version.relation_version_id) THEN
            RAISE EXCEPTION 'M20_CONSUMER_DEPENDENCY: program % does not consume %',
                consumer_name, condition_name;
        END IF;
    ELSE
        RAISE EXCEPTION 'M20_CONSUMER_KIND: use RULE or PROGRAM';
    END IF;
    IF consumer_owner <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RAISE EXCEPTION 'M20_CONSUMER_OWNER: % does not own %', session_user, consumer_name;
    END IF;
    IF condition_version.maintenance_mode = 'IMMEDIATE' AND (
        (normalized_kind = 'RULE' AND EXISTS (
            SELECT 1 FROM pgreact_internal.rule_versions version
            WHERE version.rule_version_id = consumer_version
              AND version.maintenance_mode <> 'IMMEDIATE'))
        OR (normalized_kind = 'PROGRAM' AND EXISTS (
            SELECT 1 FROM pgreact_internal.derivation_program_versions version
            WHERE version.program_version_id = consumer_version
              AND version.maintenance_mode <> 'IMMEDIATE'))
    ) THEN
        RAISE EXCEPTION 'M20_IMMEDIATE_CLOSURE: % must consume % in IMMEDIATE mode',
            consumer_name, condition_name
            USING HINT = 'Deploy the complete consumer closure with the M19 immediate capability contract.';
    END IF;
    EXECUTE format('GRANT SELECT ON %s TO %I',
                   condition_name::regclass, session_user);
    INSERT INTO pgreact_internal.shared_condition_consumers(
        condition_version_id, consumer_kind, consumer_name,
        consumer_version_id, owner_oid)
    VALUES (condition_version.condition_version_id, normalized_kind,
            consumer_name, consumer_version, consumer_owner)
    ON CONFLICT ON CONSTRAINT shared_condition_consumers_pkey DO UPDATE
    SET consumer_version_id = EXCLUDED.consumer_version_id,
        owner_oid = EXCLUDED.owner_oid,
        registered_at = clock_timestamp();
END
$$;

CREATE FUNCTION pgreact_api.grant_shared_condition_reader(
    condition_name text,
    reader_role regrole
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    condition_id uuid;
    owner_oid oid;
BEGIN
    SELECT condition.condition_id, condition.owner_oid INTO STRICT condition_id, owner_oid
    FROM pgreact_internal.shared_conditions condition
    WHERE condition.condition_name = grant_shared_condition_reader.condition_name;
    IF owner_oid <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RAISE EXCEPTION 'M20_CONDITION_OWNER: % is not owned by %', condition_name, session_user;
    END IF;
    EXECUTE format('GRANT SELECT ON %s TO %I', condition_name::regclass, reader_role::text);
    INSERT INTO pgreact_internal.shared_condition_grants(condition_id, role_oid)
    VALUES (condition_id, reader_role::oid)
    ON CONFLICT DO NOTHING;
END
$$;

CREATE FUNCTION pgreact_api.remove_shared_condition(condition_name text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    condition_row pgreact_internal.shared_conditions%ROWTYPE;
    version_row pgreact_internal.shared_condition_versions%ROWTYPE;
    consumers bigint;
BEGIN
    SELECT condition.* INTO STRICT condition_row
    FROM pgreact_internal.shared_conditions condition
    WHERE condition.condition_name = remove_shared_condition.condition_name FOR UPDATE;
    IF condition_row.owner_oid <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RAISE EXCEPTION 'M20_CONDITION_OWNER: % is not owned by %', condition_name, session_user;
    END IF;
    SELECT * INTO STRICT version_row FROM pgreact_internal.shared_condition_versions
    WHERE condition_id = condition_row.condition_id AND state = 'ACTIVE' FOR UPDATE;
    PERFORM pgreact_internal.refresh_shared_condition_consumers(version_row.condition_version_id);
    SELECT count(*) INTO consumers FROM pgreact_internal.shared_condition_consumers
    WHERE condition_version_id = version_row.condition_version_id;
    IF consumers > 0 THEN
        RAISE EXCEPTION 'M20_CONDITION_IN_USE: % has % active consumers', condition_name, consumers
            USING HINT = 'Remove or replace consumers before removing the shared condition.';
    END IF;
    PERFORM pgreact_api.remove_program(
        '__pgreact.condition.' || condition_name, version_row.version);
    EXECUTE format('DROP VIEW %s', condition_name::regclass);
    DELETE FROM pgreact_internal.keyed_derived_relations
    WHERE relation_version_id = version_row.relation_version_id;
    UPDATE pgreact_internal.derived_relation_versions
    SET state = 'REMOVED'
    WHERE relation_version_id = version_row.relation_version_id;
    UPDATE pgreact_internal.shared_condition_versions
    SET state = 'REMOVED'
    WHERE condition_version_id = version_row.condition_version_id;
END
$$;

CREATE FUNCTION pgreact_api.reconcile_shared_condition(condition_name text)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE target_program uuid;
BEGIN
    SELECT version.program_version_id INTO STRICT target_program
    FROM pgreact_internal.shared_conditions condition
    JOIN pgreact_internal.shared_condition_versions version USING (condition_id)
    WHERE condition.condition_name = reconcile_shared_condition.condition_name
      AND version.state = 'ACTIVE';
    RETURN pgreact.reconcile_derivation_program(target_program);
EXCEPTION WHEN no_data_found THEN
    RAISE EXCEPTION 'M20_CONDITION_NOT_ACTIVE: %', condition_name
        USING HINT = 'Name an active shared condition.';
END
$$;

CREATE FUNCTION pgreact_api.shared_condition_cost(condition_name text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    relation_name text;
    relation_version uuid;
    rows bigint;
    consumers bigint;
BEGIN
    SELECT keyed.public_name, version.relation_version_id
    INTO STRICT relation_name, relation_version
    FROM pgreact_internal.shared_conditions condition
    JOIN pgreact_internal.shared_condition_versions version USING (condition_id)
    JOIN pgreact_internal.keyed_derived_relations keyed
      ON keyed.relation_version_id = version.relation_version_id
    WHERE condition.condition_name = shared_condition_cost.condition_name
      AND version.state = 'ACTIVE';
    EXECUTE format('SELECT count(*) FROM %s', relation_name::regclass) INTO rows;
    SELECT count(*) INTO consumers FROM pgreact_internal.shared_condition_consumers
    WHERE condition_version_id = (
        SELECT condition_version_id FROM pgreact_internal.shared_condition_versions
        WHERE relation_version_id = relation_version AND state = 'ACTIVE');
    RETURN jsonb_build_object(
        'condition', condition_name, 'rows', rows, 'consumers', consumers,
        'fan_out_limit', 1000,
        'admission', CASE WHEN consumers <= 1000 THEN 'accepted' ELSE 'rejected' END);
END
$$;

CREATE FUNCTION pgreact_api.shared_condition_status(condition_name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE result jsonb;
BEGIN
    IF condition_name IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pgreact_internal.shared_conditions
        WHERE shared_conditions.condition_name = shared_condition_status.condition_name) THEN
        RAISE EXCEPTION 'M20_CONDITION_NOT_FOUND: %', condition_name;
    END IF;
    SELECT jsonb_agg(jsonb_build_object(
        'condition', condition.condition_name,
        'version', version.version,
        'owner', pg_get_userbyid(condition.owner_oid),
        'source', version.source_view_name,
        'relation', keyed.public_name,
        'row_type', version.row_type_name,
        'key', CASE WHEN cardinality(version.key_columns) = 1
                    THEN to_jsonb(version.key_columns[1])
                    ELSE to_jsonb(version.key_columns) END,
        'maintenance_mode', version.maintenance_mode,
        'state', lower(version.state),
        'drift', version.source_view_oid IS NULL
            OR pgreact_internal.source_closure_digest(version.source_view_oid)
               IS DISTINCT FROM version.source_definition_digest,
        'frontier', COALESCE(program.frontier, 0),
        'consumers', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'kind', lower(consumer.consumer_kind),
                'name', consumer.consumer_name,
                'version_id', consumer.consumer_version_id)
                ORDER BY consumer.consumer_kind, consumer.consumer_name)
            FROM pgreact_internal.shared_condition_consumers consumer
            WHERE consumer.condition_version_id = version.condition_version_id), '[]'::jsonb),
        'cost', CASE WHEN version.state = 'ACTIVE'
                     THEN pgreact_api.shared_condition_cost(condition.condition_name)
                     ELSE jsonb_build_object('admission', 'removed') END
    ) ORDER BY condition.condition_name)
    INTO result
    FROM pgreact_internal.shared_conditions condition
    JOIN LATERAL (
        SELECT version.* FROM pgreact_internal.shared_condition_versions version
        WHERE version.condition_id = condition.condition_id
        ORDER BY (version.state = 'ACTIVE') DESC, version.version DESC LIMIT 1
    ) version ON true
    LEFT JOIN pgreact_internal.keyed_derived_relations keyed
      ON keyed.relation_version_id = version.relation_version_id
    LEFT JOIN pgreact_internal.derivation_program_versions program
      ON program.program_version_id = version.program_version_id
    WHERE shared_condition_status.condition_name IS NULL
       OR condition.condition_name = shared_condition_status.condition_name;
    RETURN jsonb_build_object('contract_version', 8, 'conditions', COALESCE(result, '[]'::jsonb));
END
$$;

CREATE FUNCTION pgreact_api.shared_condition_matches(condition_name text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE relation_name text;
    result jsonb;
BEGIN
    SELECT keyed.public_name INTO STRICT relation_name
    FROM pgreact_internal.shared_conditions condition
    JOIN pgreact_internal.shared_condition_versions version USING (condition_id)
    JOIN pgreact_internal.keyed_derived_relations keyed
      ON keyed.relation_version_id = version.relation_version_id
    WHERE condition.condition_name = shared_condition_matches.condition_name
      AND version.state = 'ACTIVE';
    IF NOT has_table_privilege(session_user, relation_name::regclass, 'SELECT') THEN
        RAISE EXCEPTION 'M20_CONDITION_FORBIDDEN: %', condition_name;
    END IF;
    EXECUTE format(
        'SELECT jsonb_build_object(''contract_version'', 8, ''condition'', %L, ''matches'', '
        'COALESCE(jsonb_agg(to_jsonb(value) ORDER BY to_jsonb(value)::text), ''[]''::jsonb)) FROM %s value',
        condition_name, relation_name::regclass) INTO result;
    RETURN result;
END
$$;

ALTER FUNCTION pgreact_api.status(text) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.status(text) RENAME TO status_m19;
ALTER FUNCTION pgreact_api.explain(text, jsonb) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.explain(text, jsonb) RENAME TO explain_m19;
ALTER FUNCTION pgreact_api.doctor() SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.doctor() RENAME TO doctor_m19;
ALTER FUNCTION pgreact_api.configure_roles(regrole, regrole, regrole, regrole, regrole)
    SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.configure_roles(regrole, regrole, regrole, regrole, regrole)
    RENAME TO configure_roles_m19;

CREATE FUNCTION pgreact_api.status(name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE result jsonb;
BEGIN
    IF EXISTS (SELECT 1 FROM pgreact_internal.shared_conditions
               WHERE condition_name = name) THEN
        RETURN pgreact_api.shared_condition_status(name);
    END IF;
    result := pgreact_internal.status_m19(name);
    IF name IS NULL AND EXISTS (SELECT 1 FROM pgreact_internal.shared_conditions) THEN
        result := jsonb_set(result, '{conditions}',
            pgreact_api.shared_condition_status() -> 'conditions', true);
        result := jsonb_set(result, '{contract_version}', '8'::jsonb, true);
    END IF;
    RETURN result;
END
$$;

CREATE FUNCTION pgreact_api.explain(target text, semantic_key jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE result jsonb;
    condition_version uuid;
BEGIN
    result := pgreact_internal.explain_m19(target, semantic_key);
    SELECT version.condition_version_id INTO condition_version
    FROM pgreact_internal.shared_conditions condition
    JOIN pgreact_internal.shared_condition_versions version USING (condition_id)
    JOIN pgreact_internal.keyed_derived_relations keyed
      ON keyed.relation_version_id = version.relation_version_id
    WHERE keyed.public_name = target AND version.state = 'ACTIVE';
    IF condition_version IS NOT NULL THEN
        result := result || jsonb_build_object(
            'contract_version', 8,
            'shared_condition', jsonb_build_object(
                'name', target, 'version',
                (SELECT version FROM pgreact_internal.shared_condition_versions
                 WHERE condition_version_id = condition_version),
                'boundary', 'named shared condition'));
    END IF;
    RETURN result;
END
$$;

CREATE FUNCTION pgreact_api.shared_condition_explain(
    condition_name text,
    semantic_key jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE relation_name text;
    result jsonb;
BEGIN
    SELECT keyed.public_name INTO STRICT relation_name
    FROM pgreact_internal.shared_conditions condition
    JOIN pgreact_internal.shared_condition_versions version USING (condition_id)
    JOIN pgreact_internal.keyed_derived_relations keyed
      ON keyed.relation_version_id = version.relation_version_id
    WHERE condition.condition_name = shared_condition_explain.condition_name
      AND version.state = 'ACTIVE';
    IF NOT has_table_privilege(session_user, relation_name::regclass, 'SELECT') THEN
        RAISE EXCEPTION 'M20_CONDITION_FORBIDDEN: %', condition_name;
    END IF;
    result := pgreact_internal.explain_m19(relation_name, semantic_key);
    RETURN result || jsonb_build_object(
        'contract_version', 8,
        'shared_condition', jsonb_build_object(
            'name', condition_name, 'boundary', 'named shared condition'));
END
$$;

CREATE FUNCTION pgreact_api.doctor()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE result jsonb;
    diagnostics jsonb;
BEGIN
    result := pgreact_internal.doctor_m19();
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.ordinality), '[]'::jsonb)
    INTO diagnostics
    FROM jsonb_array_elements(COALESCE(result -> 'diagnostics', '[]'::jsonb))
         WITH ORDINALITY item
    WHERE item.value ->> 'code' <> 'M19_EXTENSION_VERSION';
    diagnostics := diagnostics || CASE WHEN EXISTS (
        SELECT 1 FROM pg_extension
        WHERE extname = 'pg_react' AND extversion = '0.17.0')
        THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object(
            'code', 'M20_EXTENSION_VERSION', 'severity', 'ERROR',
            'object_identity', 'pg_react',
            'message', 'pg_react extension version is not 0.17.0',
            'hint', 'Install matching files and run ALTER EXTENSION pg_react UPDATE.')) END;
    diagnostics := diagnostics || COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'code', 'M20_CONDITION_DRIFT', 'severity', 'ERROR',
            'object_identity', condition.condition_name,
            'message', 'shared condition source definition has drifted',
            'hint', 'Reconcile or replace the shared condition through the public API.')
        )
        FROM pgreact_internal.shared_conditions condition
        JOIN pgreact_internal.shared_condition_versions version USING (condition_id)
        WHERE version.state = 'ACTIVE'
          AND (version.source_view_oid IS NULL
               OR pgreact_internal.source_closure_digest(version.source_view_oid)
                  IS DISTINCT FROM version.source_definition_digest)), '[]'::jsonb);
    result := jsonb_set(result, '{diagnostics}', diagnostics, true);
    result := jsonb_set(result, '{status}', CASE WHEN EXISTS (
        SELECT 1 FROM jsonb_array_elements(diagnostics) item
        WHERE item ->> 'severity' = 'ERROR')
        THEN '"attention"'::jsonb ELSE '"ready"'::jsonb END, true);
    IF EXISTS (SELECT 1 FROM pgreact_internal.shared_conditions) THEN
        result := jsonb_set(result, '{contract_version}', '8'::jsonb, true);
    END IF;
    RETURN result;
END
$$;

CREATE FUNCTION pgreact_api.configure_roles(
    author_role regrole,
    operator_role regrole,
    worker_role regrole,
    reader_role regrole,
    advanced_reader_role regrole
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    PERFORM pgreact_internal.configure_roles_m19(
        author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.validate_shared_condition(jsonb), '
        'pgreact_api.preview_shared_condition(jsonb), '
        'pgreact_api.deploy_shared_condition(jsonb,text), '
        'pgreact_api.register_shared_condition_consumer(text,text,text), '
        'pgreact_api.grant_shared_condition_reader(text,regrole), '
        'pgreact_api.remove_shared_condition(text), '
        'pgreact_api.reconcile_shared_condition(text) TO %I', author_role::text);
    EXECUTE format(
        'GRANT EXECUTE ON FUNCTION pgreact_api.status(text), '
        'pgreact_api.shared_condition_status(text), '
        'pgreact_api.shared_condition_cost(text), '
        'pgreact_api.shared_condition_matches(text), '
        'pgreact_api.shared_condition_explain(text,jsonb), '
        'pgreact_api.explain(text,jsonb), pgreact_api.doctor() TO %I', reader_role::text);
END
$$;

DO $$
DECLARE
    author_role regrole;
    operator_role regrole;
    worker_role regrole;
    reader_role regrole;
    advanced_reader_role regrole;
BEGIN
    SELECT role_oid::regrole INTO author_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'author';
    SELECT role_oid::regrole INTO operator_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'operator';
    SELECT role_oid::regrole INTO worker_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'worker';
    SELECT role_oid::regrole INTO reader_role
    FROM pgreact_internal.application_roles WHERE role_kind = 'reader';
    SELECT role_oid::regrole INTO advanced_reader_role
    FROM pgreact_internal.advanced_readers;
    IF author_role IS NOT NULL AND operator_role IS NOT NULL
       AND worker_role IS NOT NULL AND reader_role IS NOT NULL
       AND advanced_reader_role IS NOT NULL THEN
        PERFORM pgreact_api.configure_roles(
            author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    END IF;
END
$$;

REVOKE ALL ON ALL TABLES IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_api FROM PUBLIC;

COMMENT ON EXTENSION pg_react IS
    'M20 explicit versioned shared conditions over the durable rule and derivation engine';
-- M21 retention and catalog scale.  Retention is disabled until an operator
-- explicitly configures and enables one policy.

CREATE TABLE pgreact_internal.retention_policies (
    singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
    policy_version bigint NOT NULL DEFAULT 1 CHECK (policy_version > 0),
    enabled boolean NOT NULL DEFAULT false,
    full_detail_horizon interval NOT NULL DEFAULT interval '0 seconds'
        CHECK (full_detail_horizon >= interval '0 seconds' AND full_detail_horizon <= interval '100 years'),
    minimum_audit_horizon interval NOT NULL DEFAULT interval '1 year'
        CHECK (minimum_audit_horizon >= interval '0 seconds' AND minimum_audit_horizon <= interval '100 years'),
    replay_horizon interval NOT NULL DEFAULT interval '1 year'
        CHECK (replay_horizon >= interval '0 seconds' AND replay_horizon <= interval '100 years'),
    rollback_horizon interval NOT NULL DEFAULT interval '1 year'
        CHECK (rollback_horizon >= interval '0 seconds' AND rollback_horizon <= interval '100 years'),
    deduplication_horizon interval NOT NULL DEFAULT interval '1 year'
        CHECK (deduplication_horizon >= interval '0 seconds' AND deduplication_horizon <= interval '100 years'),
    explanation_horizon interval NOT NULL DEFAULT interval '1 year'
        CHECK (explanation_horizon >= interval '0 seconds' AND explanation_horizon <= interval '100 years'),
    reconciliation_horizon interval NOT NULL DEFAULT interval '1 year'
        CHECK (reconciliation_horizon >= interval '0 seconds' AND reconciliation_horizon <= interval '100 years'),
    recovery_horizon interval NOT NULL DEFAULT interval '1 year'
        CHECK (recovery_horizon >= interval '0 seconds' AND recovery_horizon <= interval '100 years'),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_by name NOT NULL DEFAULT session_user
);
INSERT INTO pgreact_internal.retention_policies (singleton) VALUES (true);

CREATE TABLE pgreact_internal.retention_families (
    family text PRIMARY KEY,
    relation_name text NOT NULL,
    time_column text,
    classification text NOT NULL,
    lost_capabilities text[] NOT NULL,
    remediation text NOT NULL,
    layout text NOT NULL DEFAULT 'inherited' CHECK (layout IN ('inherited','partitioned','indexed')),
    benchmark_status text NOT NULL DEFAULT 'not_shipped',
    layout_evidence text NOT NULL DEFAULT 'No M18/M21 benchmark-backed advantage over the inherited layout.',
    enabled boolean NOT NULL DEFAULT true
);
INSERT INTO pgreact_internal.retention_families
    (family, relation_name, time_column, classification, lost_capabilities, remediation)
VALUES
    ('lifecycle_events', 'pgreact_internal.lifecycle_events', 'transitioned_at', 'lifecycle history',
     ARRAY['replay','explanation detail'], 'restore a verified backup containing the requested history'),
    ('executions', 'pgreact_internal.executions', 'finished_at', 'execution attempts',
     ARRAY['attempt detail'], 'inspect the retained execution audit or restore a verified backup'),
    ('agenda', 'pgreact_internal.agenda', 'completed_at', 'terminal work',
     ARRAY['replay','work detail'], 'restore a verified backup containing the terminal episode'),
    ('runtime_events', 'pgreact_internal.runtime_events', 'occurred_at', 'runtime history',
     ARRAY['runtime detail'], 'inspect the retained batch audit or restore a verified backup'),
    ('reconciliation_audit', 'pgreact_internal.reconciliation_audit', 'completed_at', 'reconciliation history',
     ARRAY['reconciliation detail'], 'restore a verified backup containing the reconciliation record'),
    ('metadata_rebuild_audits', 'pgreact_internal.metadata_rebuild_audits', 'completed_at', 'metadata maintenance',
     ARRAY['rebuild detail'], 'restore a verified backup containing the maintenance record'),
    ('derived_support_inputs', 'pgreact_internal.derived_support_inputs', NULL, 'support detail',
     ARRAY['support input detail'], 'inspect the surviving support identity or restore a verified backup'),
    ('derived_supports', 'pgreact_internal.derived_supports', 'invalidated_at', 'inactive support history',
     ARRAY['support detail','explanation detail'], 'restore a verified backup containing the support history'),
    ('derived_repair_diagnostics', 'pgreact_internal.derived_repair_diagnostics', NULL, 'derived repair detail',
     ARRAY['repair detail'], 'inspect the retained reconciliation audit or restore a verified backup'),
    ('derived_reconciliations', 'pgreact_internal.derived_reconciliations', 'completed_at', 'derived reconciliation history',
     ARRAY['reconciliation detail'], 'restore a verified backup containing the reconciliation record'),
    ('derivation_program_repair_diagnostics', 'pgreact_internal.derivation_program_repair_diagnostics', NULL, 'program repair detail',
     ARRAY['repair detail'], 'inspect the retained reconciliation audit or restore a verified backup'),
    ('derivation_program_iterations', 'pgreact_internal.derivation_program_iterations', 'completed_at', 'program iteration history',
     ARRAY['iteration detail'], 'restore a verified backup containing the iteration history'),
    ('derivation_program_runs', 'pgreact_internal.derivation_program_runs', 'completed_at', 'program run history',
     ARRAY['run detail'], 'restore a verified backup containing the run history'),
    ('negative_dependency_evidence', 'pgreact_internal.negative_dependency_evidence', 'invalidated_at', 'negative evidence history',
     ARRAY['negative evidence detail'], 'restore a verified backup containing the evidence'),
    ('aggregate_dependency_evidence', 'pgreact_internal.aggregate_dependency_evidence', 'invalidated_at', 'aggregate evidence history',
     ARRAY['aggregate evidence detail'], 'restore a verified backup containing the evidence'),
    ('window_corrections', 'pgreact_internal.window_corrections', 'created_at', 'window correction history',
     ARRAY['correction detail'], 'restore a verified backup containing the correction'),
    ('window_diagnostics', 'pgreact_internal.window_diagnostics', 'created_at', 'window diagnostics',
