     ARRAY['clock history detail'], 'restore a verified backup containing the clock history');

CREATE TABLE pgreact_internal.retention_batches (
    batch_id uuid PRIMARY KEY,
    policy_version bigint NOT NULL,
    requested_cutoff timestamptz NOT NULL,
    effective_cutoff timestamptz NOT NULL,
    requested_by name NOT NULL DEFAULT session_user,
    state text NOT NULL CHECK (state IN ('RUNNING','COMPLETED','PARTIAL','FAILED')),
    family_counts jsonb NOT NULL DEFAULT '{}'::jsonb,
    protected_reasons jsonb NOT NULL DEFAULT '{}'::jsonb,
    started_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    finished_at timestamptz,
    error jsonb
);
CREATE INDEX retention_batches_recent_idx
    ON pgreact_internal.retention_batches (started_at DESC);

CREATE TABLE pgreact_internal.retention_tombstones (
    tombstone_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    family text NOT NULL REFERENCES pgreact_internal.retention_families,
    historical_identity text NOT NULL,
    outcome text NOT NULL,
    detail_digest bytea NOT NULL,
    policy_version bigint NOT NULL,
    batch_id uuid NOT NULL REFERENCES pgreact_internal.retention_batches,
    pruned_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (family, historical_identity)
);
CREATE INDEX retention_tombstones_family_idx
    ON pgreact_internal.retention_tombstones (family, pruned_at DESC);

CREATE FUNCTION pgreact_internal.retention_policy_json()
RETURNS jsonb
LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
    SELECT jsonb_build_object(
        'policy_version', policy_version,
        'enabled', enabled,
        'full_detail_horizon', full_detail_horizon::text,
        'minimum_audit_horizon', minimum_audit_horizon::text,
        'replay_horizon', replay_horizon::text,
        'rollback_horizon', rollback_horizon::text,
        'deduplication_horizon', deduplication_horizon::text,
        'explanation_horizon', explanation_horizon::text,
        'reconciliation_horizon', reconciliation_horizon::text,
        'recovery_horizon', recovery_horizon::text,
        'updated_at', updated_at,
        'updated_by', updated_by)
    FROM pgreact_internal.retention_policies
    WHERE singleton
$$;

CREATE FUNCTION pgreact_internal.retention_record_tombstone(
    target_family text, target_identity text, target_outcome text,
    target_detail jsonb, target_policy_version bigint, target_batch_id uuid)
RETURNS void
LANGUAGE SQL SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
    INSERT INTO pgreact_internal.retention_tombstones
        (family, historical_identity, outcome, detail_digest, policy_version, batch_id)
    VALUES ($1, $2, $3, sha256(convert_to($4::text, 'UTF8')), $5, $6)
    ON CONFLICT (family, historical_identity) DO NOTHING
$$;

CREATE FUNCTION pgreact_internal.retention_preview_data(
    target_cutoff timestamptz, target_batch_size integer)
RETURNS TABLE(
    family text, relation_name text, eligible_rows bigint, eligible_bytes bigint,
    protected_rows bigint, protected_bytes bigint, blocking_reasons jsonb,
    lost_capabilities text[], remediation text, has_more boolean)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE item record; candidate_rows bigint; candidate_bytes bigint;
    rows_ok bigint; bytes_ok bigint;
BEGIN
    IF target_batch_size < 1 THEN RAISE EXCEPTION 'M21_RETENTION_BATCH_SIZE: must be positive'; END IF;
    FOR item IN SELECT * FROM pgreact_internal.retention_families WHERE enabled ORDER BY family LOOP
        candidate_rows := 0; candidate_bytes := 0; rows_ok := 0; bytes_ok := 0;
        IF item.family = 'lifecycle_events' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.lifecycle_events e WHERE e.transitioned_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.lifecycle_events e
            WHERE e.transitioned_at < target_cutoff
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.activation_state s
                              WHERE s.rule_version_id = e.rule_version_id
                                AND s.activation_id = e.activation_id AND s.active)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.agenda a WHERE a.event_id = e.event_id)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.deadline_lifecycle d WHERE d.event_id = e.event_id);
            blocking_reasons := jsonb_build_object(
                'active_state', (SELECT count(*) FROM pgreact_internal.lifecycle_events e
                    WHERE e.transitioned_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.activation_state s
                        WHERE s.rule_version_id=e.rule_version_id AND s.activation_id=e.activation_id AND s.active)),
                'work_reference', (SELECT count(*) FROM pgreact_internal.lifecycle_events e
                    WHERE e.transitioned_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.agenda a WHERE a.event_id=e.event_id)),
                'deadline_reference', (SELECT count(*) FROM pgreact_internal.lifecycle_events e
                    WHERE e.transitioned_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.deadline_lifecycle d WHERE d.event_id=e.event_id)));
        ELSIF item.family = 'executions' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.executions e WHERE e.finished_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes;
            blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'agenda' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(a)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.agenda a
            WHERE a.completed_at < target_cutoff
              AND a.state IN ('COMPLETED','FAILED','SKIPPED','WITHDRAWN','CANCELLED','SUPERSEDED');
            SELECT count(*), COALESCE(sum(pg_column_size(a)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.agenda a
            WHERE a.completed_at < target_cutoff
              AND a.state IN ('COMPLETED','FAILED','SKIPPED','WITHDRAWN','CANCELLED','SUPERSEDED')
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.executions e WHERE e.episode_id=a.episode_id)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.execution_batch_items i WHERE i.episode_id=a.episode_id)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.conflict_leases l WHERE l.episode_id=a.episode_id)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.runtime_events r WHERE r.episode_id=a.episode_id);
            blocking_reasons := jsonb_build_object(
                'active_work', (SELECT count(*) FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND a.state NOT IN ('COMPLETED','FAILED','SKIPPED','WITHDRAWN','CANCELLED','SUPERSEDED')),
                'execution_reference', (SELECT count(*) FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.executions e WHERE e.episode_id=a.episode_id)),
                'batch_reference', (SELECT count(*) FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.execution_batch_items i WHERE i.episode_id=a.episode_id)),
                'runtime_reference', (SELECT count(*) FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.runtime_events r WHERE r.episode_id=a.episode_id)));
        ELSIF item.family = 'runtime_events' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.runtime_events r WHERE r.occurred_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'reconciliation_audit' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.reconciliation_audit r
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('running', 0);
        ELSIF item.family = 'metadata_rebuild_audits' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.metadata_rebuild_audits r
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('running', 0);
        ELSIF item.family = 'derived_support_inputs' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(i)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derived_support_inputs i JOIN pgreact_internal.derived_supports s USING (support_id)
            WHERE NOT s.active AND s.invalidated_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('active_support', 0);
        ELSIF item.family = 'derived_supports' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(s)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derived_supports s WHERE NOT s.active AND s.invalidated_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(s)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.derived_supports s
            WHERE NOT s.active AND s.invalidated_at < target_cutoff
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derived_support_inputs i WHERE i.support_id=s.support_id);
            blocking_reasons := jsonb_build_object('support_inputs', (SELECT count(*) FROM pgreact_internal.derived_supports s
                WHERE NOT s.active AND s.invalidated_at < target_cutoff
                  AND EXISTS (SELECT 1 FROM pgreact_internal.derived_support_inputs i WHERE i.support_id=s.support_id)));
        ELSIF item.family = 'derived_repair_diagnostics' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(d)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derived_repair_diagnostics d JOIN pgreact_internal.derived_reconciliations r USING (reconciliation_id)
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'derived_reconciliations' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derived_reconciliations r WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.derived_reconciliations r
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED'
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derived_repair_diagnostics d WHERE d.reconciliation_id=r.reconciliation_id);
            blocking_reasons := jsonb_build_object('diagnostics', (SELECT count(*) FROM pgreact_internal.derived_reconciliations r
                WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED'
                  AND EXISTS (SELECT 1 FROM pgreact_internal.derived_repair_diagnostics d WHERE d.reconciliation_id=r.reconciliation_id)));
        ELSIF item.family = 'derivation_program_repair_diagnostics' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(d)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derivation_program_repair_diagnostics d
            JOIN pgreact_internal.derivation_program_reconciliations r USING (reconciliation_id)
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'derivation_program_iterations' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(i)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derivation_program_iterations i WHERE i.completed_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'derivation_program_runs' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derivation_program_runs r
            WHERE r.completed_at < target_cutoff AND r.status IN ('COMPLETED','NOOP','FAILED');
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.derivation_program_runs r
            WHERE r.completed_at < target_cutoff AND r.status IN ('COMPLETED','NOOP','FAILED')
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derivation_program_iterations i WHERE i.run_id=r.run_id);
            blocking_reasons := jsonb_build_object('iterations', (SELECT count(*) FROM pgreact_internal.derivation_program_runs r
                WHERE r.completed_at < target_cutoff AND r.status IN ('COMPLETED','NOOP','FAILED')
                  AND EXISTS (SELECT 1 FROM pgreact_internal.derivation_program_iterations i WHERE i.run_id=r.run_id)));
        ELSIF item.family = 'negative_dependency_evidence' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.negative_dependency_evidence e WHERE NOT e.active AND e.invalidated_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('active', 0);
        ELSIF item.family = 'aggregate_dependency_evidence' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.aggregate_dependency_evidence e WHERE NOT e.active AND e.invalidated_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('active', 0);
        ELSIF item.family = 'window_corrections' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(c)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.window_corrections c WHERE c.created_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(c)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.window_corrections c JOIN pgreact_internal.window_programs p USING (program_version_id)
            WHERE c.created_at < target_cutoff AND NOT p.active;
            blocking_reasons := jsonb_build_object('active_program', (SELECT count(*) FROM pgreact_internal.window_corrections c
                JOIN pgreact_internal.window_programs p USING (program_version_id) WHERE c.created_at < target_cutoff AND p.active));
        ELSIF item.family = 'window_diagnostics' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(d)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.window_diagnostics d WHERE d.created_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(d)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.window_diagnostics d JOIN pgreact_internal.window_programs p USING (program_version_id)
            WHERE d.created_at < target_cutoff AND NOT p.active;
            blocking_reasons := jsonb_build_object('active_program', (SELECT count(*) FROM pgreact_internal.window_diagnostics d
                JOIN pgreact_internal.window_programs p USING (program_version_id) WHERE d.created_at < target_cutoff AND p.active));
        ELSIF item.family = 'window_audits' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(a)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.window_audits a WHERE a.created_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(a)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.window_audits a LEFT JOIN pgreact_internal.window_programs p USING (program_version_id)
            WHERE a.created_at < target_cutoff AND (p.program_version_id IS NULL OR NOT p.active);
            blocking_reasons := jsonb_build_object('active_program', (SELECT count(*) FROM pgreact_internal.window_audits a
                JOIN pgreact_internal.window_programs p USING (program_version_id) WHERE a.created_at < target_cutoff AND p.active));
        ELSIF item.family = 'clock_history' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(h)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.clock_history h WHERE h.advanced_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        END IF;
        family := item.family; relation_name := item.relation_name;
        eligible_rows := rows_ok; eligible_bytes := bytes_ok;
        protected_rows := candidate_rows - rows_ok; protected_bytes := candidate_bytes - bytes_ok;
        lost_capabilities := item.lost_capabilities; remediation := item.remediation;
        has_more := rows_ok > target_batch_size;
        RETURN NEXT;
    END LOOP;
END
$$;

CREATE FUNCTION pgreact_internal.retention_apply_family(
    target_family text, target_cutoff timestamptz, target_batch_size integer,
    target_policy_version bigint, target_batch_id uuid)
RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE item record; removed bigint := 0;
BEGIN
    IF target_family = 'runtime_events' THEN
        FOR item IN SELECT r.runtime_event_id, r.event_type, r.occurred_at FROM pgreact_internal.runtime_events r
                    WHERE r.occurred_at < target_cutoff ORDER BY r.runtime_event_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.runtime_event_id::text, item.event_type,
                to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.runtime_events WHERE runtime_event_id=item.runtime_event_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'executions' THEN
        FOR item IN SELECT e.execution_id, e.episode_id, e.status, e.finished_at FROM pgreact_internal.executions e
                    WHERE e.finished_at < target_cutoff ORDER BY e.execution_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.execution_id::text, item.status,
                to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.executions WHERE execution_id=item.execution_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derived_support_inputs' THEN
        FOR item IN SELECT i.support_id, i.input_order FROM pgreact_internal.derived_support_inputs i
                    JOIN pgreact_internal.derived_supports s USING (support_id)
                    WHERE NOT s.active AND s.invalidated_at < target_cutoff
                    ORDER BY i.support_id, i.input_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.support_id::text || ':' || item.input_order,
                'support_input', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derived_support_inputs WHERE support_id=item.support_id AND input_order=item.input_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'negative_dependency_evidence' THEN
        FOR item IN SELECT e.evidence_id, e.active, e.invalidated_at FROM pgreact_internal.negative_dependency_evidence e
                    WHERE NOT e.active AND e.invalidated_at < target_cutoff ORDER BY e.evidence_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.evidence_id::text, 'negative_evidence', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.negative_dependency_evidence WHERE evidence_id=item.evidence_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'aggregate_dependency_evidence' THEN
        FOR item IN SELECT e.evidence_id, e.active, e.invalidated_at FROM pgreact_internal.aggregate_dependency_evidence e
                    WHERE NOT e.active AND e.invalidated_at < target_cutoff ORDER BY e.evidence_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.evidence_id::text, 'aggregate_evidence', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.aggregate_dependency_evidence WHERE evidence_id=item.evidence_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derived_supports' THEN
        FOR item IN SELECT s.support_id, s.active, s.invalidated_at FROM pgreact_internal.derived_supports s
                    WHERE NOT s.active AND s.invalidated_at < target_cutoff
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derived_support_inputs i WHERE i.support_id=s.support_id)
                    ORDER BY s.support_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.support_id::text, 'inactive_support', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derived_supports WHERE support_id=item.support_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derived_repair_diagnostics' THEN
        FOR item IN SELECT d.reconciliation_id, d.diagnostic_order, d.code FROM pgreact_internal.derived_repair_diagnostics d
                    JOIN pgreact_internal.derived_reconciliations r USING (reconciliation_id)
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED'
                    ORDER BY d.reconciliation_id, d.diagnostic_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.reconciliation_id::text || ':' || item.diagnostic_order, item.code, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derived_repair_diagnostics WHERE reconciliation_id=item.reconciliation_id AND diagnostic_order=item.diagnostic_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derived_reconciliations' THEN
        FOR item IN SELECT r.reconciliation_id, r.status, r.completed_at FROM pgreact_internal.derived_reconciliations r
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED'
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derived_repair_diagnostics d WHERE d.reconciliation_id=r.reconciliation_id)
                    ORDER BY r.reconciliation_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.reconciliation_id::text, item.status, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derived_reconciliations WHERE reconciliation_id=item.reconciliation_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derivation_program_repair_diagnostics' THEN
        FOR item IN SELECT d.reconciliation_id, d.diagnostic_order, d.code FROM pgreact_internal.derivation_program_repair_diagnostics d
                    JOIN pgreact_internal.derivation_program_reconciliations r USING (reconciliation_id)
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED'
                    ORDER BY d.reconciliation_id, d.diagnostic_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.reconciliation_id::text || ':' || item.diagnostic_order, item.code, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derivation_program_repair_diagnostics WHERE reconciliation_id=item.reconciliation_id AND diagnostic_order=item.diagnostic_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derivation_program_iterations' THEN
        FOR item IN SELECT i.run_id, i.component_id, i.iteration, i.completed_at FROM pgreact_internal.derivation_program_iterations i
                    WHERE i.completed_at < target_cutoff ORDER BY i.run_id, i.component_id, i.iteration LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.run_id::text || ':' || item.component_id::text || ':' || item.iteration, 'iteration', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derivation_program_iterations WHERE run_id=item.run_id AND component_id=item.component_id AND iteration=item.iteration; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derivation_program_runs' THEN
        FOR item IN SELECT r.run_id, r.status, r.completed_at FROM pgreact_internal.derivation_program_runs r
                    WHERE r.completed_at < target_cutoff AND r.status IN ('COMPLETED','NOOP','FAILED')
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derivation_program_iterations i WHERE i.run_id=r.run_id)
                    ORDER BY r.run_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.run_id::text, item.status, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derivation_program_runs WHERE run_id=item.run_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'window_corrections' THEN
        FOR item IN SELECT c.correction_order, c.correction_identity, c.created_at FROM pgreact_internal.window_corrections c
                    JOIN pgreact_internal.window_programs p USING (program_version_id)
                    WHERE c.created_at < target_cutoff AND NOT p.active ORDER BY c.correction_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.correction_identity, 'window_correction', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.window_corrections WHERE correction_order=item.correction_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'window_diagnostics' THEN
        FOR item IN SELECT d.diagnostic_order, d.code, d.created_at FROM pgreact_internal.window_diagnostics d
                    JOIN pgreact_internal.window_programs p USING (program_version_id)
                    WHERE d.created_at < target_cutoff AND NOT p.active ORDER BY d.diagnostic_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.diagnostic_order::text, item.code, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.window_diagnostics WHERE diagnostic_order=item.diagnostic_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'window_audits' THEN
        FOR item IN SELECT a.audit_order, a.operation, a.created_at FROM pgreact_internal.window_audits a
                    LEFT JOIN pgreact_internal.window_programs p USING (program_version_id)
                    WHERE a.created_at < target_cutoff AND (p.program_version_id IS NULL OR NOT p.active)
                    ORDER BY a.audit_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.audit_order::text, item.operation, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.window_audits WHERE audit_order=item.audit_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'clock_history' THEN
        FOR item IN SELECT h.clock_event_id, h.frontier, h.advanced_at FROM pgreact_internal.clock_history h
                    WHERE h.advanced_at < target_cutoff ORDER BY h.clock_event_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.clock_event_id::text, 'clock_frontier', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.clock_history WHERE clock_event_id=item.clock_event_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'reconciliation_audit' THEN
        FOR item IN SELECT r.reconciliation_id, r.status, r.completed_at FROM pgreact_internal.reconciliation_audit r
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED' ORDER BY r.reconciliation_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.reconciliation_id::text, rtrim(item.status), to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.reconciliation_audit WHERE reconciliation_id=item.reconciliation_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'metadata_rebuild_audits' THEN
        FOR item IN SELECT r.metadata_rebuild_id, r.status, r.completed_at FROM pgreact_internal.metadata_rebuild_audits r
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED' ORDER BY r.metadata_rebuild_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.metadata_rebuild_id::text, item.status, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.metadata_rebuild_audits WHERE metadata_rebuild_id=item.metadata_rebuild_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'agenda' THEN
        FOR item IN SELECT a.episode_id, a.state, a.completed_at FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND a.state IN ('COMPLETED','FAILED','SKIPPED','WITHDRAWN','CANCELLED','SUPERSEDED')
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.executions e WHERE e.episode_id=a.episode_id)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.execution_batch_items i WHERE i.episode_id=a.episode_id)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.conflict_leases l WHERE l.episode_id=a.episode_id)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.runtime_events r WHERE r.episode_id=a.episode_id)
                    ORDER BY a.episode_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.episode_id::text, item.state, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.agenda WHERE episode_id=item.episode_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'lifecycle_events' THEN
        FOR item IN SELECT e.event_id, e.event_kind, e.transitioned_at FROM pgreact_internal.lifecycle_events e
                    WHERE e.transitioned_at < target_cutoff
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.activation_state s WHERE s.rule_version_id=e.rule_version_id AND s.activation_id=e.activation_id AND s.active)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.agenda a WHERE a.event_id=e.event_id)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.deadline_lifecycle d WHERE d.event_id=e.event_id)
                    ORDER BY e.event_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.event_id::text, item.event_kind, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.lifecycle_events WHERE event_id=item.event_id; removed := removed+1;
        END LOOP;
    END IF;
    RETURN removed;
END
$$;

CREATE FUNCTION pgreact_api.retention_configure(
    full_detail_horizon interval, minimum_audit_horizon interval, replay_horizon interval,
    rollback_horizon interval, deduplication_horizon interval, explanation_horizon interval,
    reconciliation_horizon interval, recovery_horizon interval, enabled boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN RAISE EXCEPTION 'M21_RETENTION_FORBIDDEN: operator role required'; END IF;
    IF full_detail_horizon < interval '0 seconds' OR minimum_audit_horizon < interval '0 seconds'
       OR replay_horizon < interval '0 seconds' OR rollback_horizon < interval '0 seconds'
       OR deduplication_horizon < interval '0 seconds' OR explanation_horizon < interval '0 seconds'
       OR reconciliation_horizon < interval '0 seconds' OR recovery_horizon < interval '0 seconds'
       OR full_detail_horizon > interval '100 years' OR minimum_audit_horizon > interval '100 years'
       OR replay_horizon > interval '100 years' OR rollback_horizon > interval '100 years'
       OR deduplication_horizon > interval '100 years' OR explanation_horizon > interval '100 years'
       OR reconciliation_horizon > interval '100 years' OR recovery_horizon > interval '100 years'
    THEN RAISE EXCEPTION 'M21_RETENTION_HORIZON: horizons must be between zero and one hundred years'; END IF;
    UPDATE pgreact_internal.retention_policies SET
        policy_version = policy_version + 1, enabled = retention_configure.enabled,
        full_detail_horizon = retention_configure.full_detail_horizon,
        minimum_audit_horizon = retention_configure.minimum_audit_horizon,
        replay_horizon = retention_configure.replay_horizon,
        rollback_horizon = retention_configure.rollback_horizon,
        deduplication_horizon = retention_configure.deduplication_horizon,
        explanation_horizon = retention_configure.explanation_horizon,
        reconciliation_horizon = retention_configure.reconciliation_horizon,
        recovery_horizon = retention_configure.recovery_horizon,
        updated_at = clock_timestamp(), updated_by = session_user
    WHERE singleton;
    RETURN pgreact_internal.retention_policy_json();
END
$$;

CREATE FUNCTION pgreact_api.retention_remove()
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN RAISE EXCEPTION 'M21_RETENTION_FORBIDDEN: operator role required'; END IF;
    UPDATE pgreact_internal.retention_policies SET enabled=false, policy_version=policy_version+1,
        updated_at=clock_timestamp(), updated_by=session_user WHERE singleton;
    RETURN pgreact_internal.retention_policy_json();
END
$$;

CREATE FUNCTION pgreact_api.retention_preview(requested_cutoff timestamptz, batch_size integer DEFAULT 1000)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE policy_row record; effective_cutoff timestamptz; families jsonb; totals jsonb;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN RAISE EXCEPTION 'M21_RETENTION_FORBIDDEN: operator role required'; END IF;
    IF requested_cutoff >= clock_timestamp() THEN RAISE EXCEPTION 'M21_RETENTION_CUTOFF: cutoff must be in the past'; END IF;
    IF batch_size NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'M21_RETENTION_BATCH_SIZE: must be between 1 and 10000'; END IF;
    SELECT * INTO STRICT policy_row FROM pgreact_internal.retention_policies WHERE singleton;
    effective_cutoff := greatest(requested_cutoff, clock_timestamp() - GREATEST(
        policy_row.full_detail_horizon, policy_row.minimum_audit_horizon,
        policy_row.replay_horizon, policy_row.rollback_horizon,
        policy_row.deduplication_horizon, policy_row.explanation_horizon,
        policy_row.reconciliation_horizon, policy_row.recovery_horizon));
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'family', family, 'relation', relation_name, 'eligible_rows', eligible_rows,
        'eligible_bytes', eligible_bytes, 'protected_rows', protected_rows,
        'protected_bytes', protected_bytes, 'effective_cutoff', effective_cutoff,
        'blocking_reasons', blocking_reasons, 'lost_capabilities', lost_capabilities,
        'remediation', remediation, 'has_more', has_more) ORDER BY family), '[]'::jsonb),
        jsonb_build_object('eligible_rows', COALESCE(sum(eligible_rows),0),
            'eligible_bytes', COALESCE(sum(eligible_bytes),0),
            'protected_rows', COALESCE(sum(protected_rows),0),
            'protected_bytes', COALESCE(sum(protected_bytes),0))
    INTO families, totals FROM pgreact_internal.retention_preview_data(effective_cutoff, batch_size);
    RETURN jsonb_build_object('contract_version', 9, 'policy', pgreact_internal.retention_policy_json(),
        'requested_cutoff', requested_cutoff, 'effective_cutoff', effective_cutoff,
        'batch_size', batch_size, 'mutation', CASE WHEN policy_row.enabled THEN 'enabled' ELSE 'disabled' END,
        'families', families, 'totals', totals,
        'remediation', 'Apply only after reviewing protected reasons, lost capabilities, and the verified-backup boundary.');
END
$$;

CREATE FUNCTION pgreact_api.retention_apply(requested_cutoff timestamptz, batch_size integer DEFAULT 1000)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE policy_row record; effective_cutoff timestamptz; new_batch_id uuid; family_name text;
    removed bigint; total_removed bigint := 0; counts jsonb := '{}'::jsonb; preview jsonb;
    remaining bigint; batch_state text;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN RAISE EXCEPTION 'M21_RETENTION_FORBIDDEN: operator role required'; END IF;
    IF requested_cutoff >= clock_timestamp() THEN RAISE EXCEPTION 'M21_RETENTION_CUTOFF: cutoff must be in the past'; END IF;
    IF batch_size NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'M21_RETENTION_BATCH_SIZE: must be between 1 and 10000'; END IF;
    PERFORM pg_advisory_xact_lock(5788046901200021);
    SELECT * INTO STRICT policy_row FROM pgreact_internal.retention_policies WHERE singleton;
    IF NOT policy_row.enabled THEN RAISE EXCEPTION 'M21_RETENTION_DISABLED: enable a policy before apply'; END IF;
    effective_cutoff := greatest(requested_cutoff, clock_timestamp() - GREATEST(
        policy_row.full_detail_horizon, policy_row.minimum_audit_horizon,
        policy_row.replay_horizon, policy_row.rollback_horizon,
        policy_row.deduplication_horizon, policy_row.explanation_horizon,
        policy_row.reconciliation_horizon, policy_row.recovery_horizon));
    preview := pgreact_api.retention_preview(requested_cutoff, batch_size);
    IF (preview #>> '{totals,eligible_rows}')::bigint = 0 THEN
        RETURN preview || jsonb_build_object('outcome','NOOP','batch_id',NULL);
    END IF;
    new_batch_id := gen_random_uuid();
    INSERT INTO pgreact_internal.retention_batches(
        batch_id,policy_version,requested_cutoff,effective_cutoff,state,protected_reasons)
    VALUES(new_batch_id,policy_row.policy_version,requested_cutoff,effective_cutoff,'RUNNING',
        COALESCE((SELECT jsonb_object_agg(item.value ->> 'family', item.value -> 'blocking_reasons')
                  FROM jsonb_array_elements(preview -> 'families') item), '{}'::jsonb));
    -- ponytail: one database-wide retention lock; use per-family locks if maintenance throughput matters.
    BEGIN
        FOREACH family_name IN ARRAY ARRAY[
            'runtime_events','executions','derived_support_inputs','negative_dependency_evidence',
            'aggregate_dependency_evidence','derived_supports','derived_repair_diagnostics',
            'derived_reconciliations','derivation_program_repair_diagnostics','derivation_program_iterations',
            'derivation_program_runs','window_corrections','window_diagnostics','window_audits',
            'clock_history','reconciliation_audit','metadata_rebuild_audits','agenda','lifecycle_events'] LOOP
            removed := pgreact_internal.retention_apply_family(family_name,effective_cutoff,batch_size,
                policy_row.policy_version,new_batch_id);
            IF removed > 0 THEN total_removed := total_removed + removed; END IF;
            counts := counts || jsonb_build_object(family_name, removed);
        END LOOP;
        SELECT COALESCE(sum(eligible_rows),0) INTO remaining
        FROM pgreact_internal.retention_preview_data(effective_cutoff,batch_size);
        batch_state := CASE WHEN remaining = 0 THEN 'COMPLETED' ELSE 'PARTIAL' END;
        UPDATE pgreact_internal.retention_batches SET state=batch_state, family_counts=counts,
            finished_at=clock_timestamp() WHERE retention_batches.batch_id=new_batch_id;
        RETURN preview || jsonb_build_object('outcome',lower(batch_state),'batch_id',new_batch_id,
            'removed_rows',total_removed,'family_counts',counts,'remaining_eligible_rows',remaining);
    EXCEPTION WHEN OTHERS THEN
        UPDATE pgreact_internal.retention_batches SET state='FAILED', family_counts=counts,
            finished_at=clock_timestamp(), error=jsonb_build_object('sqlstate',SQLSTATE,'message',SQLERRM)
        WHERE retention_batches.batch_id=new_batch_id;
        RETURN jsonb_build_object('contract_version',9,'outcome','failed','batch_id',new_batch_id,
            'family_counts',counts,'error',jsonb_build_object('sqlstate',SQLSTATE,'message',SQLERRM));
    END;
END
$$;

CREATE FUNCTION pgreact_api.retention_status()
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE policy_row record; cutoff timestamptz; backlog jsonb; layouts jsonb; vacuum jsonb;
BEGIN
    SELECT * INTO STRICT policy_row FROM pgreact_internal.retention_policies WHERE singleton;
    cutoff := clock_timestamp() - GREATEST(policy_row.full_detail_horizon, policy_row.minimum_audit_horizon,
        policy_row.replay_horizon, policy_row.rollback_horizon, policy_row.deduplication_horizon,
        policy_row.explanation_horizon, policy_row.reconciliation_horizon, policy_row.recovery_horizon);
    SELECT jsonb_build_object('eligible_rows',COALESCE(sum(eligible_rows),0),
        'eligible_bytes',COALESCE(sum(eligible_bytes),0),
        'protected_rows',COALESCE(sum(protected_rows),0),
        'protected_bytes',COALESCE(sum(protected_bytes),0)) INTO backlog
    FROM pgreact_internal.retention_preview_data(cutoff,10000);
    SELECT COALESCE(jsonb_object_agg(family,jsonb_build_object(
        'relation',relation_name,'layout',layout,'benchmark_status',benchmark_status,
        'evidence',layout_evidence) ORDER BY family),'{}'::jsonb) INTO layouts
    FROM pgreact_internal.retention_families;
    SELECT COALESCE(jsonb_object_agg(relname,jsonb_build_object(
        'live_rows',n_live_tup,'dead_rows',n_dead_tup,'last_vacuum',last_vacuum,
        'last_autovacuum',last_autovacuum,'last_analyze',last_analyze,
        'last_autoanalyze',last_autoanalyze) ORDER BY relname),'{}'::jsonb) INTO vacuum
    FROM pg_stat_all_tables WHERE schemaname='pgreact_internal'
      AND relname IN ('retention_batches','retention_tombstones','retention_policies');
    RETURN jsonb_build_object('contract_version',9,'policy',pgreact_internal.retention_policy_json(),
        'cutoff_for_status',cutoff,'backlog',backlog,
        'last_batch',(SELECT to_jsonb(b) FROM pgreact_internal.retention_batches b ORDER BY b.started_at DESC LIMIT 1),
        'failed_maintenance',(SELECT count(*) FROM pgreact_internal.retention_batches WHERE state='FAILED'),
        'oldest_tombstone',(SELECT min(pruned_at) FROM pgreact_internal.retention_tombstones),
        'oldest_retained_detail',jsonb_build_object(
            'lifecycle_events',(SELECT min(transitioned_at) FROM pgreact_internal.lifecycle_events),
            'executions',(SELECT min(finished_at) FROM pgreact_internal.executions),
            'agenda',(SELECT min(completed_at) FROM pgreact_internal.agenda WHERE completed_at IS NOT NULL),
            'runtime_events',(SELECT min(occurred_at) FROM pgreact_internal.runtime_events)),
        'table_and_index_growth',jsonb_build_object(
            'catalog_bytes',(SELECT COALESCE(sum(pg_total_relation_size(c.oid)),0)
                FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
                WHERE n.nspname='pgreact_internal' AND c.relkind IN ('r','m')),
            'retention_table_bytes',pg_total_relation_size('pgreact_internal.retention_batches'::regclass)
                + pg_total_relation_size('pgreact_internal.retention_tombstones'::regclass),
            'retention_index_bytes',pg_indexes_size('pgreact_internal.retention_batches'::regclass)
                + pg_indexes_size('pgreact_internal.retention_tombstones'::regclass)),
        'vacuum_analyze',vacuum,'layout_decisions',layouts);
END
$$;

CREATE FUNCTION pgreact_api.retention_metrics()
RETURNS jsonb
LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
    SELECT jsonb_build_object('contract_version',9,
        'policy_enabled',(SELECT enabled FROM pgreact_internal.retention_policies WHERE singleton),
        'batches_by_state',COALESCE((SELECT jsonb_object_agg(state,count) FROM
            (SELECT state,count(*) FROM pgreact_internal.retention_batches GROUP BY state) q),'{}'::jsonb),
        'tombstones_by_family',COALESCE((SELECT jsonb_object_agg(family,count) FROM
            (SELECT family,count(*) FROM pgreact_internal.retention_tombstones GROUP BY family) q),'{}'::jsonb),
        'failed_maintenance',(SELECT count(*) FROM pgreact_internal.retention_batches WHERE state='FAILED'),
        'eligible_bytes',(SELECT COALESCE(sum(eligible_bytes),0) FROM pgreact_internal.retention_preview_data(
            clock_timestamp() - interval '1 year',10000)),
        'protected_rows',(SELECT COALESCE(sum(protected_rows),0) FROM pgreact_internal.retention_preview_data(
            clock_timestamp() - interval '1 year',10000)),
        'retention_catalog_bytes',COALESCE(pg_total_relation_size('pgreact_internal.retention_batches'::regclass),0)
            + COALESCE(pg_total_relation_size('pgreact_internal.retention_tombstones'::regclass),0),
        'table_and_index_bytes',jsonb_build_object(
            'tables',pg_total_relation_size('pgreact_internal.retention_batches'::regclass)
                + pg_total_relation_size('pgreact_internal.retention_tombstones'::regclass),
            'indexes',pg_indexes_size('pgreact_internal.retention_batches'::regclass)
                + pg_indexes_size('pgreact_internal.retention_tombstones'::regclass)))
$$;

CREATE FUNCTION pgreact_api.retention_doctor()
RETURNS jsonb
LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
    WITH diagnostics AS (
        SELECT jsonb_build_object('code','M21_EXTENSION_VERSION','severity','ERROR',
            'message','pg_react extension version is not 0.18.0','hint','Install matching extension files and run ALTER EXTENSION UPDATE.') diagnostic
        WHERE NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname='pg_react' AND extversion='0.18.0')
        UNION ALL
        SELECT jsonb_build_object('code','M21_RETENTION_BATCH_FAILED','severity','ERROR',
            'message','a retention batch failed','hint','Inspect retention_audit and retry after resolving the recorded error.')
        WHERE EXISTS (SELECT 1 FROM pgreact_internal.retention_batches WHERE state='FAILED')
        UNION ALL
        SELECT jsonb_build_object('code','M21_RETENTION_DISABLED','severity','INFO',
            'message','retention is disabled by default','hint','Configure and enable one operator-owned retention policy before pruning.')
        WHERE NOT (SELECT enabled FROM pgreact_internal.retention_policies WHERE singleton)
    )
    SELECT jsonb_build_object('contract_version',9,
        'status',CASE WHEN EXISTS (SELECT 1 FROM diagnostics WHERE diagnostic->>'severity'='ERROR') THEN 'attention' ELSE 'ready' END,
        'diagnostics',COALESCE((SELECT jsonb_agg(diagnostic) FROM diagnostics),'[]'::jsonb))
$$;

CREATE FUNCTION pgreact_api.retention_audit(limit_count integer DEFAULT 100)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN RAISE EXCEPTION 'M21_RETENTION_FORBIDDEN: operator role required'; END IF;
    IF limit_count NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'M21_RETENTION_LIMIT: must be between 1 and 1000'; END IF;
    RETURN jsonb_build_object('contract_version',9,
        'batches',COALESCE((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.started_at DESC)
            FROM (SELECT * FROM pgreact_internal.retention_batches ORDER BY started_at DESC LIMIT limit_count) b),'[]'::jsonb),
        'tombstones',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.pruned_at DESC)
            FROM (SELECT * FROM pgreact_internal.retention_tombstones ORDER BY pruned_at DESC LIMIT limit_count) t),'[]'::jsonb));
END
$$;

CREATE FUNCTION pgreact_api.retention_detail(target_family text, target_identity text)
RETURNS jsonb
LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM pgreact_internal.retention_families WHERE family=target_family)
        THEN jsonb_build_object('contract_version',9,'retained',false,
            'diagnostic',jsonb_build_object('code','M21_RETENTION_FAMILY_UNKNOWN',
                'message','the requested retention family is not supported'))
        WHEN EXISTS (SELECT 1 FROM pgreact_internal.retention_tombstones
                     WHERE family=target_family AND historical_identity=target_identity)
        THEN jsonb_build_object('contract_version',9,'retained',false,
            'diagnostic',jsonb_build_object('code','M21_HISTORY_NOT_RETAINED',
                'message','requested historical detail is outside retained coverage',
                'family',target_family,'historical_identity',target_identity,
                'remediation','restore a verified backup or use the surviving audit identity'))
        ELSE jsonb_build_object('contract_version',9,'retained',true,
            'family',target_family,'historical_identity',target_identity)
    END
$$;

REVOKE ALL ON FUNCTION pgreact_api.retention_configure(interval,interval,interval,interval,interval,interval,interval,interval,boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_api.retention_remove() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_api.retention_preview(timestamptz,integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_api.retention_apply(timestamptz,integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_api.retention_status() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_api.retention_metrics() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_api.retention_doctor() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_api.retention_audit(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_api.retention_detail(text,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION pgreact_api.configure_roles(
    author_role regrole, operator_role regrole, worker_role regrole,
    reader_role regrole, advanced_reader_role regrole)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
    PERFORM pgreact_api.configure_roles(author_role, operator_role, worker_role, reader_role);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.retention_configure(interval,interval,interval,interval,interval,interval,interval,interval,boolean), pgreact_api.retention_remove(), pgreact_api.retention_preview(timestamptz,integer), pgreact_api.retention_apply(timestamptz,integer), pgreact_api.retention_audit(integer) TO %I', operator_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.retention_status(), pgreact_api.retention_metrics(), pgreact_api.retention_doctor(), pgreact_api.retention_detail(text,text) TO %I', reader_role::text);
END
$$;

COMMENT ON EXTENSION pg_react IS
    'M21 audited dependency-aware retention and measured catalog scale over the M20 platform';
-- M22 bounded support provenance.  Provenance is derived from the existing
-- support graph in the same transaction as truth maintenance.

CREATE TABLE pgreact_internal.support_provenance_bindings (
    support_id uuid NOT NULL REFERENCES pgreact_internal.derived_supports ON DELETE CASCADE,
    binding_order integer NOT NULL CHECK (binding_order > 0),
    relation_version_id uuid NOT NULL,
    relation_name text NOT NULL,
    binding_name name NOT NULL,
    pg_type_name text NOT NULL,
    canonical_value jsonb NOT NULL,
    semantic_key bigint NOT NULL,
    fact_id uuid NOT NULL,
    is_derived boolean NOT NULL,
    active boolean NOT NULL,
    first_frontier bigint NOT NULL,
    last_frontier bigint,
    invalidated_at timestamptz,
    PRIMARY KEY (support_id, binding_order)
);

CREATE INDEX support_provenance_bindings_lookup
    ON pgreact_internal.support_provenance_bindings
       (relation_version_id, semantic_key, binding_order);

CREATE FUNCTION pgreact_internal.rebuild_support_provenance(target_support_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE support_row record;
BEGIN
    SELECT s.*, v.source_view_oid, v.source_view_name
      INTO support_row
      FROM pgreact_internal.derived_supports s
      JOIN pgreact_internal.rule_versions v USING (rule_version_id)
     WHERE s.support_id = target_support_id;
    IF NOT FOUND THEN RETURN; END IF;

    DELETE FROM pgreact_internal.support_provenance_bindings
     WHERE support_id = target_support_id;

    INSERT INTO pgreact_internal.support_provenance_bindings(
        support_id, binding_order, relation_version_id, relation_name,
        binding_name, pg_type_name, canonical_value, semantic_key, fact_id,
        is_derived, active, first_frontier, last_frontier, invalidated_at)
    SELECT target_support_id, 1000000 + a.attnum, support_row.rule_version_id,
           support_row.source_view_name, a.attname,
           pg_catalog.format_type(a.atttypid, a.atttypmod),
           support_row.source_binding -> a.attname, support_row.semantic_key,
           support_row.fact_id, false, support_row.active,
           support_row.first_frontier, support_row.last_frontier,
           support_row.invalidated_at
      FROM pg_catalog.pg_attribute a
     WHERE a.attrelid = support_row.source_view_oid
       AND a.attnum > 0 AND NOT a.attisdropped
       AND support_row.source_binding ? a.attname::text;

    INSERT INTO pgreact_internal.support_provenance_bindings(
        support_id, binding_order, relation_version_id, relation_name,
        binding_name, pg_type_name, canonical_value, semantic_key, fact_id,
        is_derived, active, first_frontier, last_frontier, invalidated_at)
    SELECT target_support_id, input.input_order, input.relation_version_id,
           relation.relation_name || '@' || relation_version.version::text,
           ('input_' || input.input_order)::name, relation_version.row_type_name,
           COALESCE(fact.fact, jsonb_build_object(
               'semantic_key', input.semantic_key, 'fact_id', input.fact_id)),
           input.semantic_key, input.fact_id, true, support_row.active,
           support_row.first_frontier, support_row.last_frontier,
           support_row.invalidated_at
      FROM pgreact_internal.derived_support_inputs input
      JOIN pgreact_internal.derived_relation_versions relation_version
        USING (relation_version_id)
      JOIN pgreact_internal.derived_relations relation
        USING (relation_id)
      LEFT JOIN pgreact_internal.derived_facts fact
        ON fact.relation_version_id = input.relation_version_id
       AND fact.fact_id = input.fact_id
       WHERE input.support_id = target_support_id;

    IF NOT EXISTS (
        SELECT 1 FROM pgreact_internal.support_provenance_bindings
         WHERE support_id = target_support_id) THEN
        INSERT INTO pgreact_internal.support_provenance_bindings(
            support_id, binding_order, relation_version_id, relation_name,
            binding_name, pg_type_name, canonical_value, semantic_key, fact_id,
            is_derived, active, first_frontier, last_frontier, invalidated_at)
        VALUES (
            target_support_id, 1, support_row.rule_version_id,
            support_row.source_view_name, '_record', 'jsonb',
            support_row.source_binding, support_row.semantic_key,
            support_row.fact_id, false, support_row.active,
            support_row.first_frontier, support_row.last_frontier,
            support_row.invalidated_at);
    END IF;
END
$$;

CREATE FUNCTION pgreact_internal.sync_support_provenance()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    PERFORM pgreact_internal.rebuild_support_provenance(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.support_id ELSE NEW.support_id END);
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;

CREATE TRIGGER pgreact_sync_support_provenance
AFTER INSERT OR UPDATE OF source_binding, fact, active, last_frontier, invalidated_at
ON pgreact_internal.derived_supports
FOR EACH ROW EXECUTE FUNCTION pgreact_internal.sync_support_provenance();

CREATE TRIGGER pgreact_sync_support_input_provenance
AFTER INSERT OR UPDATE OR DELETE ON pgreact_internal.derived_support_inputs
FOR EACH ROW EXECUTE FUNCTION pgreact_internal.sync_support_provenance();

DO $$
DECLARE target_support_id uuid;
BEGIN
    FOR target_support_id IN
        SELECT support_id FROM pgreact_internal.derived_supports ORDER BY support_id
    LOOP
        PERFORM pgreact_internal.rebuild_support_provenance(target_support_id);
    END LOOP;
END
$$;

CREATE FUNCTION pgreact_internal.assert_provenance_reader(target_relation uuid)
RETURNS pgreact_internal.derived_relation_versions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE relation_row pgreact_internal.derived_relation_versions%ROWTYPE;
    caller_oid oid := (SELECT oid FROM pg_catalog.pg_roles WHERE rolname = session_user);
BEGIN
    SELECT * INTO STRICT relation_row
      FROM pgreact_internal.derived_relation_versions
     WHERE relation_version_id = target_relation;
    IF relation_row.owner_oid <> caller_oid
       AND NOT pgreact_internal.is_operator_admin()
       AND NOT EXISTS (
           SELECT 1 FROM pgreact_internal.application_roles role
            WHERE role.role_kind = 'reader'
              AND pg_catalog.pg_has_role(session_user, role.role_oid, 'member'))
       AND NOT EXISTS (
           SELECT 1 FROM pgreact_internal.advanced_readers role
            WHERE pg_catalog.pg_has_role(session_user, role.role_oid, 'member')) THEN
        RAISE EXCEPTION 'M22_PROVENANCE_FORBIDDEN: reader role required for %', target_relation;
    END IF;
    RETURN relation_row;
END
$$;

CREATE FUNCTION pgreact_internal.provenance_support_json(target_support_id uuid)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'support_id', support.support_id,
        'rule_version_id', support.rule_version_id,
        'activation_id', support.activation_id,
        'activation_generation', support.activation_generation,
        'activation_revision', support.activation_revision,
        'logical_support_id', support.logical_support_id,
        'active', support.active,
        'first_frontier', support.first_frontier,
        'last_frontier', support.last_frontier,
        'grounded', support.grounded,
        'bindings', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'binding_order', binding.binding_order,
                'relation_version_id', binding.relation_version_id,
                'relation', binding.relation_name,
                'name', binding.binding_name,
                'type', binding.pg_type_name,
                'canonical_value', binding.canonical_value,
                'semantic_key', binding.semantic_key,
                'fact_id', binding.fact_id,
                'derived', binding.is_derived)
                ORDER BY binding.binding_order)
              FROM pgreact_internal.support_provenance_bindings binding
             WHERE binding.support_id = support.support_id), '[]'::jsonb),
        'negative_evidence', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'evidence_id', evidence.evidence_id,
                'relation', evidence.relation_name,
                'semantic_key', evidence.semantic_key,
                'source_stratum', evidence.source_stratum,
                'lower_frontier', evidence.lower_frontier)
                ORDER BY evidence.input_order)
              FROM pgreact_internal.negative_dependency_evidence evidence
             WHERE evidence.support_id = support.support_id AND evidence.active), '[]'::jsonb),
        'aggregate_evidence', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'evidence_id', evidence.evidence_id,
                'relation', evidence.relation_name,
                'group_key', evidence.semantic_key,
                'count', evidence.exact_count,
                'comparison', evidence.comparison,
                'threshold', evidence.threshold,
                'source_stratum', evidence.source_stratum,
                'lower_frontier', evidence.lower_frontier)
                ORDER BY evidence.evidence_id)
              FROM pgreact_internal.aggregate_dependency_evidence evidence
             WHERE evidence.support_id = support.support_id AND evidence.active), '[]'::jsonb))
      FROM pgreact_internal.derived_supports support
     WHERE support.support_id = target_support_id
$$;

CREATE FUNCTION pgreact_internal.provenance_proof(
    target_relation uuid, target_key bigint, max_depth integer, max_nodes integer)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    WITH RECURSIVE proof(relation_version_id, semantic_key, depth, path, cycle) AS (
        SELECT $1, $2, 0,
               ARRAY[format('%s:%s', $1, $2)]::text[], false
        UNION ALL
        SELECT input.relation_version_id, input.semantic_key, proof.depth + 1,
               proof.path || format('%s:%s', input.relation_version_id, input.semantic_key),
               format('%s:%s', input.relation_version_id, input.semantic_key) = ANY(proof.path)
          FROM proof
          JOIN pgreact_internal.derived_supports support
            ON support.relation_version_id = proof.relation_version_id
           AND support.semantic_key = proof.semantic_key
           AND support.active
          JOIN pgreact_internal.derived_support_inputs input
            ON input.support_id = support.support_id
         WHERE NOT proof.cycle AND proof.depth < $3
    ), grouped AS (
        SELECT relation_version_id, semantic_key, min(depth) AS depth,
               bool_or(cycle) AS cycle, max(depth) AS deepest
          FROM proof
         GROUP BY relation_version_id, semantic_key
    ), classified AS (
        SELECT grouped.*,
               CASE
                 WHEN grouped.cycle THEN 'CYCLE'
                 WHEN NOT EXISTS (
                     SELECT 1
                       FROM pgreact_internal.derived_supports support
                       JOIN pgreact_internal.derived_support_inputs input
                         ON input.support_id = support.support_id
                      WHERE support.relation_version_id = grouped.relation_version_id
                        AND support.semantic_key = grouped.semantic_key
                        AND support.active) THEN 'GROUNDED'
                 WHEN grouped.deepest >= $3 THEN 'TRUNCATED'
                 ELSE 'DERIVED'
               END AS state
          FROM grouped
    ), ranked AS (
        SELECT classified.*, row_number() OVER (
            ORDER BY depth, relation_version_id, semantic_key) AS ordinal
          FROM classified
    )
    SELECT jsonb_build_object(
        'nodes', COALESCE(jsonb_agg(jsonb_build_object(
            'relation_version_id', relation_version_id,
            'semantic_key', semantic_key,
            'depth', depth, 'state', state)
            ORDER BY depth, relation_version_id, semantic_key)
            FILTER (WHERE ordinal <= $4), '[]'::jsonb),
        'total_nodes', count(*),
        'omitted_nodes', greatest(count(*) - $4, 0),
        'truncated', count(*) > $4,
        'max_depth', $3,
        'max_nodes', $4)
      FROM ranked
$$;

CREATE FUNCTION pgreact_api.explain_provenance(
    target_relation uuid, target_key bigint,
    max_supports integer DEFAULT 100,
    continuation_token text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE relation_row pgreact_internal.derived_relation_versions%ROWTYPE;
    fact_value jsonb; support_total bigint; remaining_count bigint; returned_count integer;
    support_rows jsonb; proof jsonb; token jsonb; after_support uuid;
    support_digest bytea; continuation text; result jsonb;
    program_id uuid; inherited_proof jsonb;
BEGIN
    relation_row := pgreact_internal.assert_provenance_reader(target_relation);
    IF max_supports NOT BETWEEN 1 AND 1000 THEN
        RAISE EXCEPTION 'M22_PROVENANCE_LIMIT: max_supports must be between 1 and 1000';
    END IF;
    SELECT fact INTO fact_value
      FROM pgreact_internal.derived_facts
     WHERE relation_version_id = target_relation AND semantic_key = target_key;
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'contract_version', 10, 'status', 'UNAVAILABLE',
            'relation', relation_row.public_view_name || '@' || relation_row.version,
            'semantic_key', target_key,
            'diagnostic', jsonb_build_object(
                'code', 'M22_PROVENANCE_UNAVAILABLE',
                'message', 'the requested derived fact has no retained current proof',
                'remediation', 'reconcile the relation or restore retained history'));
    END IF;

    SELECT count(*), sha256(convert_to(COALESCE(string_agg(
        support_id::text, ',' ORDER BY support_id), ''), 'UTF8'))
      INTO support_total, support_digest
      FROM pgreact_internal.derived_supports
     WHERE relation_version_id = target_relation
       AND semantic_key = target_key AND active;
    IF continuation_token IS NOT NULL THEN
        BEGIN
            token := convert_from(decode(continuation_token, 'base64'), 'UTF8')::jsonb;
            IF token ->> 'relation' <> target_relation::text
               OR (token ->> 'semantic_key')::bigint <> target_key
               OR token ->> 'digest' <> encode(support_digest, 'hex') THEN
                RAISE EXCEPTION 'M22_PROVENANCE_SNAPSHOT_CHANGED';
            END IF;
            after_support := (token ->> 'after_support_id')::uuid;
        EXCEPTION WHEN SQLSTATE 'P0001' THEN RAISE;
                WHEN OTHERS THEN
            RAISE EXCEPTION 'M22_PROVENANCE_CONTINUATION_INVALID: token is expired or malformed';
        END;
    END IF;

    SELECT COALESCE(jsonb_agg(row_json ORDER BY support_id), '[]'::jsonb)
      INTO support_rows
      FROM (
          SELECT support.support_id,
                 pgreact_internal.provenance_support_json(support.support_id) AS row_json
            FROM pgreact_internal.derived_supports support
           WHERE support.relation_version_id = target_relation
             AND support.semantic_key = target_key AND support.active
             AND (after_support IS NULL OR support.support_id > after_support)
           ORDER BY support.support_id
           LIMIT max_supports
      ) page;
    returned_count := jsonb_array_length(support_rows);
    IF after_support IS NULL THEN
        remaining_count := support_total;
    ELSE
        SELECT count(*) INTO remaining_count
          FROM pgreact_internal.derived_supports support
         WHERE support.relation_version_id = target_relation
           AND support.semantic_key = target_key AND support.active
           AND support.support_id > after_support;
    END IF;
    IF returned_count > 0 AND returned_count < remaining_count THEN
        continuation := encode(convert_to(jsonb_build_object(
            'relation', target_relation, 'semantic_key', target_key,
            'digest', encode(support_digest, 'hex'),
            'after_support_id', (support_rows -> (returned_count - 1)) ->> 'support_id'
        )::text, 'UTF8'), 'base64');
    END IF;
    proof := pgreact_internal.provenance_proof(target_relation, target_key, 32, 1000);
    SELECT support.program_version_id INTO program_id
      FROM pgreact_internal.derived_supports support
     WHERE support.relation_version_id = target_relation
       AND support.semantic_key = target_key AND support.active
       AND support.program_version_id IS NOT NULL
     ORDER BY support.program_version_id LIMIT 1;
    inherited_proof := CASE WHEN program_id IS NULL THEN
        jsonb_build_object('relation_version_id', target_relation, 'semantic_key', target_key,
                           'supports', '[]'::jsonb)
      ELSE pgreact_internal.recursive_fact_proof(
          program_id, target_relation, target_key, '{}'::uuid[]) END;
    result := jsonb_build_object(
        'contract_version', 10, 'status', 'GROUNDED',
        'relation', relation_row.public_view_name || '@' || relation_row.version,
        'relation_version_id', target_relation, 'semantic_key', target_key,
        'fact', fact_value,
        'supports', support_rows,
        'total_supports', support_total,
        'returned_supports', returned_count,
        'omitted_supports', remaining_count - returned_count,
        'continuation', continuation,
        'proof', proof,
        'inherited_proof', inherited_proof,
        'bounds', jsonb_build_object(
            'max_supports', max_supports, 'max_depth', 32,
            'max_nodes', 1000, 'max_payload_bytes', 1048576));
    RETURN result || jsonb_build_object('payload_bytes', pg_column_size(result));
END
$$;

CREATE FUNCTION pgreact_api.explain_provenance_advanced(
    target_relation uuid, target_key bigint,
    max_supports integer DEFAULT 100,
    continuation_token text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    IF NOT pgreact_internal.is_operator_admin()
       AND NOT EXISTS (
           SELECT 1 FROM pgreact_internal.advanced_readers role
            WHERE pg_catalog.pg_has_role(session_user, role.role_oid, 'member')) THEN
        RAISE EXCEPTION 'M22_PROVENANCE_FORBIDDEN: advanced-reader role required';
    END IF;
    RETURN pgreact_api.explain_provenance(
        target_relation, target_key, max_supports, continuation_token)
        || jsonb_build_object('reader_class', 'advanced');
END
$$;

CREATE FUNCTION pgreact_api.provenance_validate(target_relation uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE relation_row pgreact_internal.derived_relation_versions%ROWTYPE;
    active_supports bigint; missing_bindings bigint; over_bound bigint;
BEGIN
    relation_row := pgreact_internal.assert_provenance_reader(target_relation);
    SELECT count(*), count(*) FILTER (WHERE NOT EXISTS (
        SELECT 1 FROM pgreact_internal.support_provenance_bindings binding
         WHERE binding.support_id = support.support_id)), count(*) FILTER (WHERE EXISTS (
        SELECT 1 FROM pgreact_internal.support_provenance_bindings binding
         WHERE binding.support_id = support.support_id
         GROUP BY binding.support_id HAVING count(*) > 1000))
      INTO active_supports, missing_bindings, over_bound
      FROM pgreact_internal.derived_supports support
     WHERE support.relation_version_id = target_relation AND support.active;
    RETURN jsonb_build_object(
        'contract_version', 10,
        'relation', relation_row.public_view_name || '@' || relation_row.version,
        'status', CASE WHEN missing_bindings = 0 AND over_bound = 0 THEN 'ready' ELSE 'attention' END,
        'diagnostics', jsonb_build_array(
            CASE WHEN missing_bindings > 0 THEN jsonb_build_object(
                'code', 'M22_PROVENANCE_MISSING', 'severity', 'ERROR',
                'count', missing_bindings, 'remediation', 'reconcile the derived relation') END,
            CASE WHEN over_bound > 0 THEN jsonb_build_object(
                'code', 'M22_PROVENANCE_BOUND', 'severity', 'ERROR',
                'count', over_bound, 'remediation', 'reduce support fan-out or raise the frozen contract bound') END),
        'active_supports', active_supports,
        'missing_bindings', missing_bindings, 'over_bound_supports', over_bound,
        'limits', jsonb_build_object('max_bindings_per_support', 1000));
END
$$;

CREATE FUNCTION pgreact_api.provenance_preview(
    target_relation uuid, target_key bigint DEFAULT NULL, max_facts integer DEFAULT 100)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE relation_row pgreact_internal.derived_relation_versions%ROWTYPE;
    facts jsonb;
BEGIN
    relation_row := pgreact_internal.assert_provenance_reader(target_relation);
    IF max_facts NOT BETWEEN 1 AND 1000 THEN
        RAISE EXCEPTION 'M22_PROVENANCE_LIMIT: max_facts must be between 1 and 1000';
    END IF;
    IF target_key IS NOT NULL THEN
        RETURN pgreact_api.explain_provenance(target_relation, target_key, max_facts, NULL)
            || jsonb_build_object('mode', 'preview');
    END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'semantic_key', fact.semantic_key, 'fact', fact.fact,
        'support_count', fact.support_count)
        ORDER BY fact.semantic_key), '[]'::jsonb)
      INTO facts
      FROM (
          SELECT * FROM pgreact_internal.derived_facts
           WHERE relation_version_id = target_relation
           ORDER BY semantic_key LIMIT max_facts
      ) fact;
    RETURN jsonb_build_object(
        'contract_version', 10, 'mode', 'preview',
        'relation', relation_row.public_view_name || '@' || relation_row.version,
        'relation_version_id', target_relation, 'facts', facts,
        'returned_facts', jsonb_array_length(facts), 'max_facts', max_facts);
END
$$;

CREATE FUNCTION pgreact_api.provenance_status(target_relation uuid DEFAULT NULL)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 10,
        'relations', COALESCE(jsonb_agg(jsonb_build_object(
            'relation_version_id', relation_version_id,
            'relation', public_view_name || '@' || version,
            'active_supports', active_supports,
            'bindings', binding_count,
            'missing_supports', missing_supports,
            'storage_bytes', storage_bytes)
            ORDER BY public_view_name, version), '[]'::jsonb),
        'limits', jsonb_build_object(
            'max_bindings_per_support', 1000, 'max_depth', 32,
            'max_nodes', 1000, 'max_payload_bytes', 1048576))
      FROM (
          SELECT relation_version.relation_version_id,
                 relation_version.public_view_name, relation_version.version,
                 count(DISTINCT support.support_id) FILTER (WHERE support.active) AS active_supports,
                 count(binding.support_id) FILTER (WHERE support.active) AS binding_count,
                 count(DISTINCT support.support_id) FILTER (WHERE support.active
                     AND binding.support_id IS NULL) AS missing_supports,
                 pg_total_relation_size('pgreact_internal.support_provenance_bindings'::regclass) AS storage_bytes
            FROM pgreact_internal.derived_relation_versions relation_version
            LEFT JOIN pgreact_internal.derived_supports support
              ON support.relation_version_id = relation_version.relation_version_id
            LEFT JOIN pgreact_internal.support_provenance_bindings binding
              ON binding.support_id = support.support_id
           WHERE relation_version.state = 'ACTIVE'
             AND ($1 IS NULL OR relation_version.relation_version_id = $1)
           GROUP BY relation_version.relation_version_id,
                    relation_version.public_view_name, relation_version.version
      ) status
$$;

CREATE FUNCTION pgreact_api.provenance_doctor()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    SELECT jsonb_build_object(
        'contract_version', 10,
        'status', CASE WHEN EXISTS (
            SELECT 1 FROM pgreact_internal.derived_supports support
             WHERE support.active AND NOT EXISTS (
                 SELECT 1 FROM pgreact_internal.support_provenance_bindings binding
                  WHERE binding.support_id = support.support_id)) THEN 'attention' ELSE 'ready' END,
        'diagnostics', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'code', 'M22_PROVENANCE_MISSING', 'severity', 'ERROR',
            'support_id', support.support_id,
            'message', 'an active support has no typed provenance binding',
            'remediation', 'run provenance reconciliation before relying on explanation')
            ORDER BY support.support_id)
          FROM pgreact_internal.derived_supports support
         WHERE support.active AND NOT EXISTS (
             SELECT 1 FROM pgreact_internal.support_provenance_bindings binding
              WHERE binding.support_id = support.support_id)), '[]'::jsonb),
        'extension_version', (SELECT extversion FROM pg_catalog.pg_extension WHERE extname = 'pg_react'))
$$;

CREATE OR REPLACE FUNCTION pgreact_api.retention_doctor()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
    WITH diagnostics AS (
        SELECT jsonb_build_object('code','M21_EXTENSION_VERSION','severity','ERROR',
            'message','pg_react extension version is not 0.19.0',
            'hint','Install matching extension files and run ALTER EXTENSION UPDATE.') diagnostic
        WHERE NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname='pg_react' AND extversion='0.19.0')
        UNION ALL
        SELECT jsonb_build_object('code','M21_RETENTION_BATCH_FAILED','severity','ERROR',
            'message','a retention batch failed','hint','Inspect retention_audit and retry after resolving the recorded error.')
        WHERE EXISTS (SELECT 1 FROM pgreact_internal.retention_batches WHERE state='FAILED')
        UNION ALL
        SELECT jsonb_build_object('code','M21_RETENTION_DISABLED','severity','INFO',
            'message','retention is disabled by default','hint','Configure and enable one operator-owned retention policy before pruning.')
        WHERE NOT (SELECT enabled FROM pgreact_internal.retention_policies WHERE singleton)
    )
    SELECT jsonb_build_object('contract_version',9,
        'status',CASE WHEN EXISTS (SELECT 1 FROM diagnostics WHERE diagnostic->>'severity'='ERROR') THEN 'attention' ELSE 'ready' END,
        'diagnostics',COALESCE((SELECT jsonb_agg(diagnostic) FROM diagnostics),'[]'::jsonb))
$$;

CREATE OR REPLACE FUNCTION pgreact_api.configure_roles(
    author_role regrole, operator_role regrole, worker_role regrole,
    reader_role regrole, advanced_reader_role regrole)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE previous name;
BEGIN
    PERFORM pgreact_api.configure_roles(author_role, operator_role, worker_role, reader_role);
    SELECT role_oid::regrole::text INTO previous FROM pgreact_internal.advanced_readers;
    IF previous IS NOT NULL THEN
        EXECUTE format('REVOKE ALL ON FUNCTION pgreact_api.explain_provenance_advanced(uuid,bigint,integer,text) FROM %I', previous);
    END IF;
    DELETE FROM pgreact_internal.advanced_readers;
    INSERT INTO pgreact_internal.advanced_readers VALUES (advanced_reader_role);
    EXECUTE format('GRANT USAGE ON SCHEMA pgreact_api TO %I', advanced_reader_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.explain_provenance_advanced(uuid,bigint,integer,text) TO %I', advanced_reader_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.provenance_validate(uuid), pgreact_api.provenance_preview(uuid,bigint,integer) TO %I', author_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.provenance_status(uuid), pgreact_api.provenance_preview(uuid,bigint,integer), pgreact_api.explain_provenance(uuid,bigint,integer,text), pgreact_api.provenance_doctor() TO %I', reader_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.provenance_status(uuid), pgreact_api.provenance_preview(uuid,bigint,integer), pgreact_api.explain_provenance(uuid,bigint,integer,text), pgreact_api.provenance_doctor() TO %I', operator_role::text);
END
$$;

REVOKE ALL ON ALL TABLES IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_api FROM PUBLIC;

COMMENT ON EXTENSION pg_react IS
    'M22 bounded typed support provenance over the M21 retention and catalog-scale platform';

-- M23 practical temporal conditions. Temporal state remains on the inherited
-- match stream and monotone database-time frontier; no second scheduler exists.
ALTER TABLE pgreact_internal.operational_settings
    ADD COLUMN max_temporal_keys_per_pass integer NOT NULL DEFAULT 100000
        CHECK (max_temporal_keys_per_pass BETWEEN 1 AND 10000000);

CREATE TABLE pgreact_internal.temporal_rules (
    rule_version_id uuid PRIMARY KEY REFERENCES pgreact_internal.rule_versions,
    primitive text NOT NULL CHECK (primitive IN ('DURATION', 'ABSENCE', 'COOLDOWN', 'HYSTERESIS')),
    duration_us bigint CHECK (duration_us IS NULL OR duration_us > 0),
    deadline_column name,
    cooldown_us bigint CHECK (cooldown_us IS NULL OR cooldown_us > 0),
    recovery_condition_oid oid,
    recovery_condition_name text,
    recovery_key_column name,
    clock_domain text NOT NULL DEFAULT 'DATABASE_TIME' CHECK (clock_domain = 'DATABASE_TIME'),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    CHECK ((primitive = 'DURATION' AND duration_us IS NOT NULL AND deadline_column IS NULL
             AND cooldown_us IS NULL AND recovery_condition_oid IS NULL)
        OR (primitive = 'ABSENCE' AND deadline_column IS NOT NULL AND duration_us IS NULL
             AND cooldown_us IS NULL AND recovery_condition_oid IS NULL)
        OR (primitive = 'COOLDOWN' AND cooldown_us IS NOT NULL AND duration_us IS NULL
             AND deadline_column IS NULL AND recovery_condition_oid IS NULL)
        OR (primitive = 'HYSTERESIS' AND duration_us IS NULL AND deadline_column IS NULL
             AND cooldown_us IS NULL AND recovery_condition_oid IS NOT NULL))
);

CREATE TABLE pgreact_internal.temporal_state (
    rule_version_id uuid NOT NULL REFERENCES pgreact_internal.temporal_rules,
    semantic_key bigint NOT NULL,
    state text NOT NULL CHECK (state IN ('WAITING', 'PENDING', 'ACTIVE', 'COOLDOWN', 'ARMED', 'RECOVERED')),
    active boolean NOT NULL DEFAULT false,
    input_true boolean NOT NULL DEFAULT false,
    recovery_true boolean NOT NULL DEFAULT false,
    continuous_since timestamptz,
    pending_deadline timestamptz,
    cooldown_until timestamptz,
    generation bigint NOT NULL DEFAULT 0 CHECK (generation >= 0),
    last_frontier timestamptz NOT NULL,
    last_bindings jsonb,
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (rule_version_id, semantic_key)
);
CREATE INDEX temporal_state_deadline_idx
    ON pgreact_internal.temporal_state (rule_version_id, pending_deadline, semantic_key)
    WHERE pending_deadline IS NOT NULL;
CREATE INDEX temporal_state_cooldown_idx
    ON pgreact_internal.temporal_state (rule_version_id, cooldown_until, semantic_key)
    WHERE cooldown_until IS NOT NULL;

CREATE TABLE pgreact_internal.temporal_history (
    temporal_event_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    rule_version_id uuid NOT NULL REFERENCES pgreact_internal.temporal_rules,
    semantic_key bigint NOT NULL,
    lifecycle_event_id bigint REFERENCES pgreact_internal.lifecycle_events,
    event_kind text NOT NULL CHECK (event_kind IN ('OBSERVE', 'ACTIVATE', 'DEACTIVATE')),
    primitive_state text NOT NULL,
    input_true boolean NOT NULL,
    recovery_true boolean NOT NULL,
    continuous_since timestamptz,
    pending_deadline timestamptz,
    cooldown_until timestamptz,
    clock_frontier timestamptz NOT NULL,
    bindings jsonb,
    recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX temporal_history_key_idx
    ON pgreact_internal.temporal_history (rule_version_id, semantic_key, temporal_event_id);

CREATE FUNCTION pgreact_internal.temporal_duration_us(value interval)
RETURNS bigint
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
SET search_path = pg_catalog, pg_temp
AS $m23$
DECLARE micros numeric;
BEGIN
    IF value IS NULL OR extract(year FROM value) <> 0 OR extract(month FROM value) <> 0 THEN
        RAISE EXCEPTION 'M23_DURATION_VALUE: duration must be a positive integral microsecond interval';
    END IF;
    micros := extract(epoch FROM value)::numeric * 1000000;
    IF micros <> trunc(micros) OR micros < 1 OR micros > 31557600000000000 THEN
        RAISE EXCEPTION 'M23_DURATION_VALUE: duration must be a positive integral microsecond interval within the published bound';
    END IF;
    RETURN micros::bigint;
END
$m23$;

CREATE FUNCTION pgreact_internal.validate_temporal_rule(
    condition regclass,
    semantic_key name,
    primitive text,
    duration interval DEFAULT NULL,
    deadline_column name DEFAULT NULL,
    cooldown interval DEFAULT NULL,
    recovery_condition regclass DEFAULT NULL,
    recovery_key_column name DEFAULT NULL
)
RETURNS TABLE(
    contract_version integer, code text, severity text,
    object_identity text, message text, hint text, details jsonb
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
DECLARE diagnostic record; duration_us bigint; cooldown_us bigint;
BEGIN
    SELECT result.* INTO diagnostic
    FROM pgreact.validate_rule(condition, ARRAY[semantic_key]::name[], NULL::regprocedure) result
    WHERE result.severity = 'ERROR' ORDER BY result.code LIMIT 1;
    IF FOUND THEN
        RETURN QUERY SELECT 11, diagnostic.code, diagnostic.severity,
            diagnostic.object_identity, diagnostic.message, diagnostic.hint, diagnostic.details;
        RETURN;
    END IF;
    IF primitive NOT IN ('DURATION', 'ABSENCE', 'COOLDOWN', 'HYSTERESIS') THEN
        RETURN QUERY SELECT 11, 'M23_PRIMITIVE', 'ERROR', condition::text,
            'primitive must be DURATION, ABSENCE, COOLDOWN, or HYSTERESIS',
            'Choose one supported practical temporal primitive.', '{}'::jsonb;
        RETURN;
    END IF;
    IF primitive = 'DURATION' THEN
        BEGIN duration_us := pgreact_internal.temporal_duration_us(duration);
        EXCEPTION WHEN OTHERS THEN
            RETURN QUERY SELECT 11, 'M23_DURATION_VALUE', 'ERROR', condition::text,
                SQLERRM, 'Use a positive integral microsecond interval.', '{}'::jsonb;
            RETURN;
        END;
        IF deadline_column IS NOT NULL OR cooldown IS NOT NULL OR recovery_condition IS NOT NULL THEN
            RETURN QUERY SELECT 11, 'M23_DECLARATION_SHAPE', 'ERROR', condition::text,
                'duration conditions accept only one fixed database-time duration',
                'Remove deadline, cooldown, and recovery inputs.', '{}'::jsonb;
            RETURN;
        END IF;
    ELSIF primitive = 'ABSENCE' THEN
        IF deadline_column IS NULL OR duration IS NOT NULL OR cooldown IS NOT NULL
           OR recovery_condition IS NOT NULL THEN
            RETURN QUERY SELECT 11, 'M23_DECLARATION_SHAPE', 'ERROR', condition::text,
                'absence conditions require one direct deadline column and no other temporal input',
                'Project one finite timestamptz deadline unchanged from the condition view.', '{}'::jsonb;
            RETURN;
        END IF;
        SELECT result.* INTO diagnostic
        FROM pgreact_internal.validate_deadline_rule(condition, semantic_key, deadline_column, NULL::regprocedure) result
        WHERE result.severity = 'ERROR' ORDER BY result.code LIMIT 1;
        IF FOUND THEN
            RETURN QUERY SELECT 11, diagnostic.code, diagnostic.severity,
                diagnostic.object_identity, diagnostic.message, diagnostic.hint, diagnostic.details;
            RETURN;
        END IF;
    ELSIF primitive = 'COOLDOWN' THEN
        BEGIN cooldown_us := pgreact_internal.temporal_duration_us(cooldown);
        EXCEPTION WHEN OTHERS THEN
            RETURN QUERY SELECT 11, 'M23_COOLDOWN_VALUE', 'ERROR', condition::text,
                SQLERRM, 'Use a positive integral microsecond interval.', '{}'::jsonb;
            RETURN;
        END;
        IF duration IS NOT NULL OR deadline_column IS NOT NULL OR recovery_condition IS NOT NULL THEN
            RETURN QUERY SELECT 11, 'M23_DECLARATION_SHAPE', 'ERROR', condition::text,
                'cooldown conditions accept one fixed database-time cooldown',
                'Remove duration, deadline, and recovery inputs.', '{}'::jsonb;
            RETURN;
        END IF;
    ELSE
        IF recovery_condition IS NULL OR recovery_key_column IS NULL
           OR duration IS NOT NULL OR deadline_column IS NOT NULL OR cooldown IS NOT NULL THEN
            RETURN QUERY SELECT 11, 'M23_RECOVERY_DECLARATION', 'ERROR', condition::text,
                'hysteresis conditions require one enter view and one recovery view',
                'Supply recovery_condition and recovery_key_column only.', '{}'::jsonb;
            RETURN;
        END IF;
        SELECT result.* INTO diagnostic
        FROM pgreact.validate_rule(recovery_condition, ARRAY[recovery_key_column]::name[], NULL::regprocedure) result
        WHERE result.severity = 'ERROR' ORDER BY result.code LIMIT 1;
        IF FOUND THEN
            RETURN QUERY SELECT 11, 'M23_RECOVERY_' || diagnostic.code, diagnostic.severity,
                diagnostic.object_identity, diagnostic.message, diagnostic.hint, diagnostic.details;
            RETURN;
        END IF;
    END IF;
    RETURN QUERY SELECT 11, 'OK', 'INFO', condition::text,
        'temporal declaration is valid on the bounded database-time coordinator path',
        'Use author_temporal_rule, then run the coordinator at the required committed frontier.',
        jsonb_build_object('primitive', primitive, 'clock_domain', 'DATABASE_TIME',
                           'duration_us', duration_us, 'cooldown_us', cooldown_us,
                           'deadline_column', deadline_column,
                           'recovery_condition', recovery_condition::text,
                           'recovery_key_column', recovery_key_column);
END
$m23$;

CREATE FUNCTION pgreact_api.validate_temporal_rule(
    condition regclass,
    semantic_key name,
    primitive text,
    duration interval DEFAULT NULL,
    deadline_column name DEFAULT NULL,
    cooldown interval DEFAULT NULL,
    recovery_condition regclass DEFAULT NULL,
    recovery_key_column name DEFAULT NULL
)
RETURNS TABLE(
    contract_version integer, code text, severity text,
    object_identity text, message text, hint text, details jsonb
)
LANGUAGE SQL SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
    SELECT * FROM pgreact_internal.validate_temporal_rule(
        $1, $2, $3, $4, $5, $6, $7, $8)
$m23$;

CREATE FUNCTION pgreact_api.author_temporal_rule(
    rule_name text,
    condition regclass,
    semantic_key name,
    primitive text,
    duration interval DEFAULT NULL,
    deadline_column name DEFAULT NULL,
    cooldown interval DEFAULT NULL,
    recovery_condition regclass DEFAULT NULL,
    recovery_key_column name DEFAULT NULL,
    on_activate regprocedure DEFAULT NULL,
    salience integer DEFAULT 0,
    agenda_group text DEFAULT 'default',
    max_attempts integer DEFAULT 1,
    initial_backoff_seconds integer DEFAULT 1,
    backoff_multiplier numeric DEFAULT 2,
    max_backoff_seconds integer DEFAULT 60
)
RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
DECLARE diagnostic record; version_id uuid; version_row pgreact_internal.rule_versions%ROWTYPE;
    duration_us bigint; cooldown_us bigint;
BEGIN
    SELECT result.* INTO diagnostic
    FROM pgreact_internal.validate_temporal_rule(
        condition, semantic_key, primitive, duration, deadline_column,
        cooldown, recovery_condition, recovery_key_column) result
    WHERE result.severity = 'ERROR' ORDER BY result.code LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react temporal validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    IF primitive = 'DURATION' THEN duration_us := pgreact_internal.temporal_duration_us(duration); END IF;
    IF primitive = 'COOLDOWN' THEN cooldown_us := pgreact_internal.temporal_duration_us(cooldown); END IF;
    version_id := pgreact.create_rule(
        name => rule_name, definition => condition,
        key_columns => ARRAY[semantic_key]::name[], kind => 'CONSTRAINT',
        on_activate => NULL::regprocedure, on_deactivate => NULL::regprocedure,
        on_change => NULL::regprocedure, bootstrap_policy => 'SEED_CURRENT',
        change_columns => NULL::name[], salience => salience,
        agenda_group => agenda_group, conflict_key_columns => NULL::name[],
        max_attempts => max_attempts, initial_backoff_seconds => initial_backoff_seconds,
        backoff_multiplier => backoff_multiplier, max_backoff_seconds => max_backoff_seconds);
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions
    WHERE rule_version_id = version_id;
    IF on_activate IS NOT NULL THEN
        PERFORM pgreact_internal.add_typed_binding(
            version_id, 'ACTIVATE', on_activate, max_attempts,
            initial_backoff_seconds, backoff_multiplier, max_backoff_seconds);
    END IF;
    INSERT INTO pgreact_internal.temporal_rules (
        rule_version_id, primitive, duration_us, deadline_column, cooldown_us,
        recovery_condition_oid, recovery_condition_name, recovery_key_column)
    VALUES (
        version_id, primitive, duration_us, deadline_column, cooldown_us,
        recovery_condition, recovery_condition::text, recovery_key_column);
    EXECUTE format('DROP TRIGGER IF EXISTS pgreact_finalize ON %s', version_row.match_relid::regclass);
    DELETE FROM pgreact_internal.agenda WHERE rule_version_id = version_id;
    DELETE FROM pgreact_internal.lifecycle_events WHERE rule_version_id = version_id;
    DELETE FROM pgreact_internal.activation_state WHERE rule_version_id = version_id;
    EXECUTE format(
        'CREATE CONSTRAINT TRIGGER pgreact_temporal_finalize '
        'AFTER INSERT OR UPDATE OR DELETE ON %s DEFERRABLE INITIALLY DEFERRED '
        'FOR EACH ROW EXECUTE FUNCTION pgreact_internal.finalize_temporal_match_delta(%L)',
        version_row.match_relid::regclass, version_id::text);
    PERFORM pgreact_internal.reconcile_temporal_rule(version_id);
    RETURN version_id;
END
$m23$;

CREATE FUNCTION pgreact_internal.finalize_temporal_match_delta()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
DECLARE version_id uuid := TG_ARGV[0]::uuid; key_column name; old_key bigint; new_key bigint;
BEGIN
    SELECT rule_versions.key_column INTO STRICT key_column
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = version_id;
    IF TG_OP <> 'INSERT' THEN
        old_key := (to_jsonb(OLD) ->> key_column)::bigint;
        IF old_key IS NOT NULL THEN PERFORM pgreact_internal.reconcile_temporal_key(version_id, old_key); END IF;
    END IF;
    IF TG_OP <> 'DELETE' THEN
        new_key := (to_jsonb(NEW) ->> key_column)::bigint;
        IF new_key IS NOT NULL AND new_key IS DISTINCT FROM old_key THEN
            PERFORM pgreact_internal.reconcile_temporal_key(version_id, new_key);
        END IF;
    END IF;
    RETURN NULL;
END
$m23$;

CREATE FUNCTION pgreact_internal.reconcile_temporal_key(target_version_id uuid, target_key bigint)
RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
<<temporal_key>>
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE;
    spec pgreact_internal.temporal_rules%ROWTYPE;
    prior_state pgreact_internal.temporal_state%ROWTYPE;
    prior_activation pgreact_internal.activation_state%ROWTYPE;
    frontier timestamptz; candidate_count bigint; candidate_bindings jsonb;
    declared_deadline timestamptz; recovery_count bigint; recovery_true boolean := false;
    input_true boolean; new_active boolean; new_state text; new_continuous timestamptz;
    new_pending timestamptz; new_cooldown timestamptz; new_bindings jsonb;
    activation uuid; canonical bytea; digest bytea; lifecycle_event bigint;
    event_kind text; next_generation bigint; event_bindings jsonb;
BEGIN
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions WHERE rule_version_id = target_version_id;
    SELECT * INTO STRICT spec FROM pgreact_internal.temporal_rules WHERE rule_version_id = target_version_id;
    SELECT clock.frontier INTO STRICT frontier
    FROM pgreact_internal.clock_frontier clock FOR UPDATE;
    EXECUTE format(
        'SELECT count(*)::bigint, min(to_jsonb(v)::text)::jsonb FROM %s v WHERE (%I)::bigint = $1',
        version_row.match_relid::regclass, version_row.key_column)
        INTO candidate_count, candidate_bindings USING target_key;
    IF candidate_count > 1 THEN
        RAISE EXCEPTION 'M23_DUPLICATE_KEY: % contains multiple rows for semantic key %',
            version_row.source_view_name, target_key;
    END IF;
    IF spec.deadline_column IS NOT NULL AND candidate_count = 1 THEN
        EXECUTE format(
            'SELECT (to_jsonb(v) ->> %L)::timestamptz FROM %s v WHERE (%I)::bigint = $1',
            spec.deadline_column::text, version_row.match_relid::regclass, version_row.key_column)
            INTO declared_deadline USING target_key;
        IF declared_deadline IS NULL OR NOT isfinite(declared_deadline) THEN
            RAISE EXCEPTION 'M23_DEADLINE_VALUE: deadline must be finite and non-null for key %', target_key;
        END IF;
    END IF;
    input_true := candidate_count = 1;
    IF spec.recovery_condition_oid IS NOT NULL THEN
        EXECUTE format(
            'SELECT count(*)::bigint FROM %s v WHERE (to_jsonb(v) ->> %L)::bigint = $1',
            spec.recovery_condition_oid::regclass, spec.recovery_key_column::text)
            INTO recovery_count USING target_key;
        IF recovery_count > 1 THEN
            RAISE EXCEPTION 'M23_DUPLICATE_RECOVERY_KEY: recovery condition has multiple rows for key %', target_key;
        END IF;
        recovery_true := recovery_count = 1;
    END IF;
    SELECT * INTO prior_state FROM pgreact_internal.temporal_state
    WHERE rule_version_id = target_version_id AND semantic_key = target_key FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO pgreact_internal.temporal_state (
            rule_version_id, semantic_key, state, last_frontier)
        VALUES (target_version_id, target_key, 'WAITING', frontier);
        SELECT * INTO prior_state FROM pgreact_internal.temporal_state
        WHERE rule_version_id = target_version_id AND semantic_key = target_key FOR UPDATE;
    END IF;
    new_active := prior_state.active;
    new_state := prior_state.state;
    new_continuous := prior_state.continuous_since;
    new_pending := prior_state.pending_deadline;
    new_cooldown := prior_state.cooldown_until;
    new_bindings := COALESCE(candidate_bindings, prior_state.last_bindings,
                             jsonb_build_object('semantic_key', target_key));

    IF spec.primitive = 'DURATION' THEN
        IF NOT input_true THEN
            new_active := false; new_state := 'WAITING';
            new_continuous := NULL; new_pending := NULL;
        ELSIF NOT isfinite(frontier) THEN
            new_active := false; new_state := 'WAITING';
        ELSIF new_continuous IS NULL THEN
            new_active := false; new_state := 'PENDING';
            new_continuous := frontier;
            new_pending := frontier + spec.duration_us * interval '1 microsecond';
        ELSIF prior_state.active THEN
            new_active := true; new_state := 'ACTIVE';
        ELSIF new_pending <= frontier THEN
            new_active := true; new_state := 'ACTIVE';
        ELSE
            new_active := false; new_state := 'PENDING';
        END IF;
    ELSIF spec.primitive = 'ABSENCE' THEN
        IF input_true THEN
            new_active := false; new_state := 'WAITING';
            new_pending := declared_deadline;
        ELSIF new_pending IS NULL THEN
            new_active := false; new_state := 'WAITING';
        ELSIF isfinite(frontier) AND frontier >= new_pending THEN
            new_active := true; new_state := 'ACTIVE';
        ELSE
            new_active := false; new_state := 'PENDING';
        END IF;
    ELSIF spec.primitive = 'COOLDOWN' THEN
        IF input_true THEN
            IF prior_state.active THEN
                new_active := true; new_state := 'ACTIVE';
            ELSIF new_cooldown IS NOT NULL AND (NOT isfinite(frontier) OR new_cooldown > frontier) THEN
                new_active := false; new_state := 'COOLDOWN';
            ELSIF isfinite(frontier) THEN
                new_active := true; new_state := 'ACTIVE'; new_cooldown := NULL;
            ELSE
                new_active := false; new_state := 'WAITING';
            END IF;
        ELSIF prior_state.active THEN
            new_active := false; new_state := 'COOLDOWN';
            new_cooldown := CASE WHEN isfinite(frontier)
                THEN frontier + spec.cooldown_us * interval '1 microsecond' ELSE NULL END;
        ELSIF new_cooldown IS NOT NULL AND (NOT isfinite(frontier) OR new_cooldown > frontier) THEN
            new_active := false; new_state := 'COOLDOWN';
        ELSE
            new_active := false; new_state := 'WAITING'; new_cooldown := NULL;
        END IF;
    ELSE
        IF prior_state.active AND recovery_true THEN
            new_active := false; new_state := 'RECOVERED';
        ELSIF prior_state.active THEN
            new_active := true; new_state := 'ACTIVE';
        ELSIF input_true AND isfinite(frontier) THEN
            new_active := true; new_state := 'ACTIVE';
        ELSIF recovery_true THEN
            new_active := false; new_state := 'RECOVERED';
        ELSE
            new_active := false; new_state := 'ARMED';
        END IF;
    END IF;

    IF new_active IS DISTINCT FROM prior_state.active AND isfinite(frontier) THEN
        canonical := pgreact_internal.canonical_bigint_v1(target_key);
        digest := pgreact_internal.activation_digest(target_version_id, canonical);
        activation := pgreact_internal.activation_uuid(digest);
        SELECT * INTO prior_activation FROM pgreact_internal.activation_state
        WHERE rule_version_id = target_version_id AND activation_id = activation FOR UPDATE;
        event_bindings := COALESCE(new_bindings, jsonb_build_object('semantic_key', target_key));
        IF new_active THEN
            next_generation := COALESCE(prior_activation.generation, 0) + 1;
            INSERT INTO pgreact_internal.activation_state (
                rule_version_id, activation_id, semantic_key, canonical_key,
                canonical_key_digest, key_codec_version, active, generation, revision,
                current_bindings, last_active_bindings, first_seen_at, last_seen_at)
            VALUES (target_version_id, activation, target_key, canonical, digest, 1, true,
                    next_generation, 0, event_bindings, event_bindings,
                    clock_timestamp(), clock_timestamp())
            ON CONFLICT (rule_version_id, activation_id) DO UPDATE SET
                active = true, generation = EXCLUDED.generation, revision = 0,
                current_bindings = EXCLUDED.current_bindings,
                last_active_bindings = EXCLUDED.last_active_bindings,
                last_seen_at = EXCLUDED.last_seen_at, deactivated_at = NULL;
            lifecycle_event := pgreact_internal.emit_event(
                version_row, activation, next_generation, 0, 'ACTIVATE', NULL, event_bindings);
            event_kind := 'ACTIVATE';
        ELSE
            next_generation := COALESCE(prior_activation.generation, 1);
            UPDATE pgreact_internal.activation_state
            SET active = false, current_bindings = NULL,
                deactivated_at = clock_timestamp(), last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id AND activation_id = activation;
            lifecycle_event := pgreact_internal.emit_event(
                version_row, activation, next_generation, 0, 'DEACTIVATE',
                COALESCE(prior_activation.last_active_bindings, event_bindings), NULL);
            event_kind := 'DEACTIVATE';
        END IF;
    ELSE
        next_generation := prior_state.generation;
    END IF;
    UPDATE pgreact_internal.temporal_state AS target
    SET state = temporal_key.new_state, active = temporal_key.new_active,
        input_true = temporal_key.input_true, recovery_true = temporal_key.recovery_true,
        continuous_since = temporal_key.new_continuous,
        pending_deadline = temporal_key.new_pending, cooldown_until = temporal_key.new_cooldown,
        generation = CASE WHEN temporal_key.lifecycle_event IS NULL
                          THEN target.generation ELSE temporal_key.next_generation END,
        last_frontier = temporal_key.frontier, last_bindings = temporal_key.new_bindings,
        updated_at = clock_timestamp()
    WHERE target.rule_version_id = target_version_id AND target.semantic_key = target_key;
    INSERT INTO pgreact_internal.temporal_history (
        rule_version_id, semantic_key, lifecycle_event_id, event_kind,
        primitive_state, input_true, recovery_true, continuous_since,
        pending_deadline, cooldown_until, clock_frontier, bindings)
    VALUES (target_version_id, target_key, lifecycle_event,
            COALESCE(event_kind, 'OBSERVE'), new_state, input_true, recovery_true,
            new_continuous, new_pending, new_cooldown, frontier, new_bindings);
    RETURN COALESCE(lifecycle_event, 0);
END
$m23$;

CREATE FUNCTION pgreact_internal.reconcile_temporal_rule(target_version_id uuid)
RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE;
    spec pgreact_internal.temporal_rules%ROWTYPE; item record; statement text; changed bigint := 0;
BEGIN
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id;
    SELECT * INTO STRICT spec FROM pgreact_internal.temporal_rules
    WHERE rule_version_id = target_version_id;
    statement := format(
        'SELECT (%1$I)::bigint AS semantic_key FROM %2$s WHERE %1$I IS NOT NULL '
        'UNION SELECT semantic_key FROM pgreact_internal.temporal_state WHERE rule_version_id = %3$L::uuid',
        version_row.key_column, version_row.match_relid::regclass, target_version_id::text);
    IF spec.recovery_condition_oid IS NOT NULL THEN
        statement := statement || format(
            ' UNION SELECT (to_jsonb(v) ->> %L)::bigint FROM %s v '
            'WHERE (to_jsonb(v) ->> %L) IS NOT NULL',
            spec.recovery_key_column::text, spec.recovery_condition_oid::regclass,
            spec.recovery_key_column::text);
    END IF;
    FOR item IN EXECUTE statement || ' ORDER BY 1' LOOP
        changed := changed + pgreact_internal.reconcile_temporal_key(
            target_version_id, item.semantic_key);
    END LOOP;
    RETURN changed;
END
$m23$;

CREATE FUNCTION pgreact_internal.reconcile_temporal_frontier()
RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
DECLARE spec record; changed bigint := 0;
    max_keys integer;
    total_keys bigint;
BEGIN
    SELECT max_temporal_keys_per_pass INTO max_keys
    FROM pgreact_internal.operational_settings;
    SELECT count(*) INTO total_keys
    FROM pgreact_internal.temporal_state state
    JOIN pgreact_internal.temporal_rules temporal USING (rule_version_id)
    JOIN pgreact_internal.rule_versions version USING (rule_version_id)
    WHERE version.state = 'ACTIVE';
    IF total_keys > max_keys THEN
        RAISE EXCEPTION 'M23_TEMPORAL_LIMIT: % temporal keys exceed max_temporal_keys_per_pass %',
            total_keys, max_keys;
    END IF;
    FOR spec IN
        SELECT rule_version_id FROM pgreact_internal.temporal_rules spec
        JOIN pgreact_internal.rule_versions version USING (rule_version_id)
        WHERE version.state = 'ACTIVE' ORDER BY rule_version_id
    LOOP
        changed := changed + pgreact_internal.reconcile_temporal_rule(spec.rule_version_id);
    END LOOP;
    RETURN changed;
END
$m23$;

CREATE FUNCTION pgreact_api.temporal_preview(target_name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE SQL STABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
    SELECT jsonb_build_object(
        'contract_version', 11, 'mode', 'PREVIEW',
        'clock_frontier', (SELECT frontier FROM pgreact_internal.clock_frontier),
        'rules', COALESCE(jsonb_agg(jsonb_build_object(
            'rule', rule.rule_name, 'primitive', spec.primitive,
            'clock_domain', spec.clock_domain, 'states', COALESCE((
                SELECT jsonb_agg(to_jsonb(state) ORDER BY state.semantic_key)
                FROM pgreact_internal.temporal_state state
                WHERE state.rule_version_id = spec.rule_version_id), '[]'::jsonb))
            ORDER BY rule.rule_name), '[]'::jsonb))
    FROM pgreact_internal.temporal_rules spec
    JOIN pgreact_internal.rules rule ON rule.rule_id = (
        SELECT version.rule_id FROM pgreact_internal.rule_versions version
        WHERE version.rule_version_id = spec.rule_version_id)
    WHERE $1 IS NULL OR rule.rule_name = $1
$m23$;

CREATE FUNCTION pgreact_api.temporal_status(target_name text DEFAULT NULL)
RETURNS jsonb
LANGUAGE SQL STABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
    SELECT pgreact_api.temporal_preview($1) || jsonb_build_object('mode', 'STATUS')
$m23$;

CREATE FUNCTION pgreact_api.temporal_history(target_name text)
RETURNS jsonb
LANGUAGE SQL STABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'rule', rule.rule_name, 'semantic_key', history.semantic_key,
        'event_kind', history.event_kind, 'primitive_state', history.primitive_state,
        'input_true', history.input_true, 'recovery_true', history.recovery_true,
        'continuous_since', history.continuous_since,
        'pending_deadline', history.pending_deadline,
        'cooldown_until', history.cooldown_until,
        'clock_frontier', history.clock_frontier,
        'lifecycle_event_id', history.lifecycle_event_id,
        'bindings', history.bindings) ORDER BY history.temporal_event_id), '[]'::jsonb)
    FROM pgreact_internal.temporal_history history
    JOIN pgreact_internal.rule_versions version USING (rule_version_id)
    JOIN pgreact_internal.rules rule USING (rule_id)
    WHERE rule.rule_name = $1
$m23$;

CREATE FUNCTION pgreact_api.temporal_explain(target_name text, target_key bigint)
RETURNS jsonb
LANGUAGE SQL STABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
    SELECT jsonb_build_object(
        'contract_version', 11, 'rule', rule.rule_name, 'semantic_key', $2,
        'declaration', jsonb_build_object('primitive', spec.primitive,
            'duration_us', spec.duration_us, 'deadline_column', spec.deadline_column,
            'cooldown_us', spec.cooldown_us, 'clock_domain', spec.clock_domain,
            'recovery_condition', spec.recovery_condition_name,
            'recovery_key_column', spec.recovery_key_column),
        'state', (SELECT to_jsonb(state) FROM pgreact_internal.temporal_state state
                  WHERE state.rule_version_id = spec.rule_version_id AND state.semantic_key = $2),
        'history', COALESCE((SELECT jsonb_agg(to_jsonb(history) ORDER BY history.temporal_event_id)
            FROM pgreact_internal.temporal_history history
            WHERE history.rule_version_id = spec.rule_version_id AND history.semantic_key = $2), '[]'::jsonb),
        'boundary', 'committed database-time frontier; consequence delivery remains asynchronous')
    FROM pgreact_internal.temporal_rules spec
    JOIN pgreact_internal.rule_versions version USING (rule_version_id)
    JOIN pgreact_internal.rules rule USING (rule_id)
    WHERE rule.rule_name = $1
$m23$;

CREATE FUNCTION pgreact_api.temporal_doctor()
RETURNS jsonb
LANGUAGE SQL STABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
    WITH diagnostics AS (
        SELECT jsonb_build_object('code', 'M23_EXTENSION_VERSION', 'severity', 'ERROR',
            'object_identity', 'pg_react', 'message', 'pg_react extension version is not 0.20.0',
            'hint', 'Install matching extension files and run ALTER EXTENSION pg_react UPDATE.') diagnostic
        WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_extension
                          WHERE extname = 'pg_react' AND extversion = '0.20.0')
        UNION ALL
        SELECT jsonb_build_object('code', 'M23_TEMPORAL_ORPHAN_STATE', 'severity', 'ERROR',
            'object_identity', state.rule_version_id::text,
            'message', 'temporal state has no active temporal declaration',
            'hint', 'Run temporal reconciliation or remove the incomplete declaration.')
        FROM pgreact_internal.temporal_state state
        LEFT JOIN pgreact_internal.temporal_rules spec USING (rule_version_id)
        WHERE spec.rule_version_id IS NULL
        UNION ALL
        SELECT jsonb_build_object('code', 'M23_TEMPORAL_BACKWARD_FRONTIER', 'severity', 'ERROR',
            'object_identity', 'clock_frontier',
            'message', 'temporal frontier is behind a recorded temporal observation',
            'hint', 'Restore the last complete clock frontier before advancing again.')
        WHERE EXISTS (SELECT 1 FROM pgreact_internal.temporal_state state
                      WHERE state.last_frontier > (SELECT frontier FROM pgreact_internal.clock_frontier))
    ), ordered AS (
        SELECT diagnostic FROM diagnostics
        ORDER BY CASE diagnostic ->> 'severity' WHEN 'ERROR' THEN 1 WHEN 'WARNING' THEN 2 ELSE 3 END,
                 diagnostic ->> 'code', diagnostic ->> 'object_identity'
    )
    SELECT jsonb_build_object('contract_version', 11,
        'status', CASE WHEN EXISTS (SELECT 1 FROM ordered WHERE diagnostic ->> 'severity' = 'ERROR')
                       THEN 'attention' ELSE 'ready' END,
        'diagnostics', COALESCE((SELECT jsonb_agg(diagnostic) FROM ordered), '[]'::jsonb),
        'clock_domain', 'DATABASE_TIME', 'limits', jsonb_build_object(
            'max_temporal_keys_per_pass', (SELECT max_temporal_keys_per_pass
                                           FROM pgreact_internal.operational_settings)))
$m23$;

CREATE FUNCTION pgreact_api.reconcile_temporal_rule(target_name text)
RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
DECLARE version_id uuid; repaired bigint;
BEGIN
    SELECT version.rule_version_id INTO STRICT version_id
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    JOIN pgreact_internal.temporal_rules spec USING (rule_version_id)
    WHERE rule.rule_name = target_name AND version.state = 'ACTIVE';
    PERFORM pgreact.refresh_rule(version_id);
    SET CONSTRAINTS ALL IMMEDIATE;
    repaired := pgreact_internal.reconcile_temporal_rule(version_id);
    RETURN repaired;
END
$m23$;

CREATE FUNCTION pgreact_api.pause_temporal_rule(target_name text)
RETURNS void LANGUAGE SQL SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $m23$
    SELECT pgreact.pause_rule((SELECT version.rule_version_id
        FROM pgreact_internal.rules rule JOIN pgreact_internal.rule_versions version USING (rule_id)
        JOIN pgreact_internal.temporal_rules spec USING (rule_version_id)
        WHERE rule.rule_name = $1 ORDER BY version.created_at DESC LIMIT 1))
$m23$;

CREATE FUNCTION pgreact_api.resume_temporal_rule(target_name text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
DECLARE version_id uuid;
BEGIN
    SELECT version.rule_version_id INTO STRICT version_id
    FROM pgreact_internal.rules rule JOIN pgreact_internal.rule_versions version USING (rule_id)
    JOIN pgreact_internal.temporal_rules spec USING (rule_version_id)
    WHERE rule.rule_name = target_name AND version.state = 'PAUSED';
    PERFORM pgreact.resume_rule(version_id);
    PERFORM pgreact_internal.reconcile_temporal_rule(version_id);
END
$m23$;

CREATE FUNCTION pgreact_api.remove_temporal_rule(target_name text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m23$
DECLARE version_id uuid;
BEGIN
    SELECT version.rule_version_id INTO STRICT version_id
    FROM pgreact_internal.rules rule JOIN pgreact_internal.rule_versions version USING (rule_id)
    JOIN pgreact_internal.temporal_rules spec USING (rule_version_id)
    WHERE rule.rule_name = target_name AND version.state <> 'REMOVED'
    ORDER BY version.created_at DESC LIMIT 1;
    PERFORM pgreact.pause_rule(version_id);
    DELETE FROM pgreact_internal.temporal_history WHERE rule_version_id = version_id;
    DELETE FROM pgreact_internal.temporal_state WHERE rule_version_id = version_id;
    DELETE FROM pgreact_internal.temporal_rules WHERE rule_version_id = version_id;
    PERFORM pgreact.remove_rule(version_id);
END
$m23$;

ALTER FUNCTION pgreact_api.run(timestamptz) SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.run(timestamptz) RENAME TO run_m22;
CREATE FUNCTION pgreact_api.run(sampled_time timestamptz DEFAULT clock_timestamp())
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $m23$
DECLARE result jsonb; temporal_changed bigint;
BEGIN
    result := pgreact_internal.run_m22(sampled_time);
    temporal_changed := pgreact_internal.reconcile_temporal_frontier();
    RETURN jsonb_set(result || jsonb_build_object('temporal_changed', temporal_changed),
        '{contract_version}', '11'::jsonb, true);
END
$m23$;

ALTER FUNCTION pgreact_api.doctor() SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.doctor() RENAME TO doctor_m22;
CREATE FUNCTION pgreact_api.doctor()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $m23$
DECLARE result jsonb; diagnostics jsonb; temporal jsonb;
BEGIN
    result := pgreact_internal.doctor_m22();
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.ordinality), '[]'::jsonb)
    INTO diagnostics
    FROM jsonb_array_elements(COALESCE(result -> 'diagnostics', '[]'::jsonb))
         WITH ORDINALITY item
    WHERE item.value ->> 'code' NOT LIKE '%_EXTENSION_VERSION';
    temporal := pgreact_api.temporal_doctor();
    diagnostics := diagnostics || COALESCE(temporal -> 'diagnostics', '[]'::jsonb);
    RETURN jsonb_build_object('contract_version', 11,
        'status', CASE WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(diagnostics) item
                                    WHERE item ->> 'severity' = 'ERROR')
                       THEN 'attention' ELSE 'ready' END,
        'diagnostics', diagnostics);
END
$m23$;

ALTER FUNCTION pgreact_api.configure_roles(regrole, regrole, regrole, regrole, regrole)
    SET SCHEMA pgreact_internal;
ALTER FUNCTION pgreact_internal.configure_roles(regrole, regrole, regrole, regrole, regrole)
    RENAME TO configure_roles_m22;
CREATE FUNCTION pgreact_api.configure_roles(
    author_role regrole, operator_role regrole, worker_role regrole,
    reader_role regrole, advanced_reader_role regrole)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $m23$
BEGIN
    PERFORM pgreact_internal.configure_roles_m22(
        author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.validate_temporal_rule(regclass,name,text,interval,name,interval,regclass,name), '
        'pgreact_api.author_temporal_rule(text,regclass,name,text,interval,name,interval,regclass,name,regprocedure,integer,text,integer,integer,numeric,integer) TO %I', author_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.temporal_preview(text), pgreact_api.temporal_status(text), '
        'pgreact_api.temporal_history(text), pgreact_api.temporal_explain(text,bigint), pgreact_api.temporal_doctor() TO %I', reader_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.temporal_preview(text), pgreact_api.temporal_status(text), '
        'pgreact_api.temporal_history(text), pgreact_api.temporal_explain(text,bigint), pgreact_api.temporal_doctor(), '
        'pgreact_api.reconcile_temporal_rule(text), pgreact_api.pause_temporal_rule(text), '
        'pgreact_api.resume_temporal_rule(text), pgreact_api.remove_temporal_rule(text) TO %I', operator_role::text);
END
$m23$;

REVOKE ALL ON ALL TABLES IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_internal FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pgreact_api FROM PUBLIC;

DO $m23$
DECLARE author_role regrole; operator_role regrole; worker_role regrole;
    reader_role regrole; advanced_reader_role regrole;
BEGIN
    SELECT role_oid::regrole INTO author_role FROM pgreact_internal.application_roles WHERE role_kind = 'author';
    SELECT role_oid::regrole INTO operator_role FROM pgreact_internal.application_roles WHERE role_kind = 'operator';
    SELECT role_oid::regrole INTO worker_role FROM pgreact_internal.application_roles WHERE role_kind = 'worker';
    SELECT role_oid::regrole INTO reader_role FROM pgreact_internal.application_roles WHERE role_kind = 'reader';
    SELECT role_oid::regrole INTO advanced_reader_role FROM pgreact_internal.advanced_readers;
    IF author_role IS NOT NULL AND operator_role IS NOT NULL AND worker_role IS NOT NULL
       AND reader_role IS NOT NULL AND advanced_reader_role IS NOT NULL THEN
        PERFORM pgreact_api.configure_roles(
            author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    END IF;
END
$m23$;

COMMENT ON EXTENSION pg_react IS
    'M23 practical database-time temporal conditions over the M22 provenance platform';
-- M24 effective-dated policy versions. Policy authority is selected from the
-- committed database-time frontier; deployment time and effective time remain
-- separate.

CREATE TABLE pgreact_internal.effective_policies (
    policy_id uuid PRIMARY KEY,
    policy_name text NOT NULL UNIQUE,
    owner_oid oid NOT NULL,
    authoritative_version_id uuid,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE pgreact_internal.effective_policy_versions (
    policy_version_id uuid PRIMARY KEY,
    policy_id uuid NOT NULL REFERENCES pgreact_internal.effective_policies,
    rule_version_id uuid UNIQUE REFERENCES pgreact_internal.rule_versions,
    target_kind text NOT NULL DEFAULT 'RULE'
        CHECK (target_kind IN ('RULE', 'PROGRAM')),
    program_version_id uuid REFERENCES pgreact_internal.derivation_program_versions,
    program_definition jsonb,
    version integer NOT NULL CHECK (version > 0),
    valid_from timestamptz NOT NULL CHECK (isfinite(valid_from)),
    valid_to timestamptz CHECK (valid_to IS NULL OR (isfinite(valid_to) AND valid_to > valid_from)),
    deployment_state text NOT NULL CHECK (deployment_state IN ('DEPLOYED', 'PAUSED', 'REMOVED')),
    effective_state text NOT NULL DEFAULT 'FUTURE'
        CHECK (effective_state IN ('FUTURE', 'CURRENT', 'EXPIRED', 'GAP', 'PAUSED', 'REMOVED')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (policy_id, version),
    CHECK (
        (target_kind = 'RULE' AND rule_version_id IS NOT NULL
            AND program_version_id IS NULL AND program_definition IS NULL)
        OR
        (target_kind = 'PROGRAM' AND rule_version_id IS NULL
            AND program_definition IS NOT NULL)
    )
);

CREATE INDEX effective_policy_interval_idx
    ON pgreact_internal.effective_policy_versions (policy_id, valid_from, valid_to);

CREATE TABLE pgreact_internal.effective_policy_history (
    transition_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    policy_id uuid NOT NULL REFERENCES pgreact_internal.effective_policies,
    policy_version_id uuid REFERENCES pgreact_internal.effective_policy_versions,
    event_kind text NOT NULL CHECK (event_kind IN (
        'DEPLOYED', 'EFFECTIVE', 'EXPIRED', 'GAP', 'PAUSED', 'RESUMED', 'REMOVED'
    )),
    frontier timestamptz NOT NULL,
    details jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (policy_version_id, event_kind, frontier)
);

CREATE VIEW pgreact.effective_policies AS
SELECT policy.policy_id,
       policy.policy_name,
       pg_get_userbyid(policy.owner_oid) AS owner,
       policy.authoritative_version_id,
       frontier.frontier,
       CASE
           WHEN policy.authoritative_version_id IS NOT NULL THEN 'CURRENT'
           WHEN EXISTS (
               SELECT 1
               FROM pgreact_internal.effective_policy_versions version
               WHERE version.policy_id = policy.policy_id
                 AND version.deployment_state = 'DEPLOYED'
                 AND version.valid_from > frontier.frontier
           ) THEN 'FUTURE'
           ELSE 'GAP'
       END AS state,
       policy.created_at
FROM pgreact_internal.effective_policies policy
CROSS JOIN pgreact_internal.clock_frontier frontier;

CREATE VIEW pgreact.effective_policy_versions AS
SELECT version.policy_version_id,
       policy.policy_id,
       policy.policy_name,
       version.rule_version_id,
       version.target_kind,
       version.program_version_id,
       COALESCE(rule.rule_name, version.program_definition ->> 'name') AS rule_name,
       version.version,
       version.valid_from,
       version.valid_to,
       version.deployment_state,
       version.effective_state,
       version.policy_version_id = policy.authoritative_version_id AS authoritative,
       version.created_at
FROM pgreact_internal.effective_policy_versions version
JOIN pgreact_internal.effective_policies policy USING (policy_id)
LEFT JOIN pgreact_internal.rule_versions rule_version USING (rule_version_id)
LEFT JOIN pgreact_internal.rules rule USING (rule_id)
WHERE version.deployment_state <> 'REMOVED';

CREATE FUNCTION pgreact_internal.m24_policy_version_state(
    target_valid_from timestamptz,
    target_valid_to timestamptz,
    target_deployment_state text,
    target_frontier timestamptz
)
RETURNS text
LANGUAGE SQL
IMMUTABLE
PARALLEL SAFE
SET search_path = pg_catalog, pg_temp
AS $m24$
    SELECT CASE
        WHEN $3 = 'PAUSED' THEN 'PAUSED'
        WHEN $3 = 'REMOVED' THEN 'REMOVED'
        WHEN $1 > $4 THEN 'FUTURE'
        WHEN $2 IS NOT NULL AND $2 <= $4 THEN 'EXPIRED'
        ELSE 'CURRENT'
    END
$m24$;

CREATE FUNCTION pgreact_internal.validate_effective_policy(
    target_policy_name text,
    target_rule_version_id uuid,
    target_valid_from timestamptz,
    target_valid_to timestamptz
)
RETURNS TABLE(
    contract_version integer,
    code text,
    severity text,
    object_identity text,
    message text,
    hint text,
    details jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m24$
DECLARE policy_row pgreact_internal.effective_policies%ROWTYPE;
    version_row pgreact_internal.rule_versions%ROWTYPE;
    frontier timestamptz;
    overlap record;
BEGIN
    SELECT clock.frontier INTO STRICT frontier
    FROM pgreact_internal.clock_frontier clock;

    IF target_policy_name IS NULL OR btrim(target_policy_name) = '' THEN
        RETURN QUERY SELECT 12, 'M24_POLICY_NAME', 'ERROR', '<unnamed>',
            'policy name must not be empty',
            'Choose one stable name for the policy identity.', '{}'::jsonb;
        RETURN;
    END IF;
    IF target_valid_from IS NULL OR NOT isfinite(target_valid_from) THEN
        RETURN QUERY SELECT 12, 'M24_VALID_FROM', 'ERROR', target_policy_name,
            'valid_from must be finite and non-null',
            'Use one finite timestamptz business-effective boundary.', '{}'::jsonb;
        RETURN;
    END IF;
    IF target_valid_to IS NOT NULL
       AND (NOT isfinite(target_valid_to) OR target_valid_to <= target_valid_from) THEN
        RETURN QUERY SELECT 12, 'M24_VALID_INTERVAL', 'ERROR', target_policy_name,
            'valid_to must be finite and greater than valid_from',
            'Use a half-open interval [valid_from, valid_to) or leave valid_to null for no upper bound.',
            jsonb_build_object('valid_from', target_valid_from, 'valid_to', target_valid_to);
        RETURN;
    END IF;
    IF target_valid_from < frontier THEN
        RETURN QUERY SELECT 12, 'M24_RETROACTIVE_INTERVAL', 'ERROR', target_policy_name,
            'a new effective policy version cannot begin before the committed frontier',
            'Schedule the version at or after the current database-time frontier; historical truth is not recomputed.',
            jsonb_build_object('frontier', frontier, 'valid_from', target_valid_from);
        RETURN;
    END IF;

    SELECT * INTO version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_rule_version_id;
    IF NOT FOUND OR version_row.state = 'REMOVED' THEN
        RETURN QUERY SELECT 12, 'M24_TARGET_NOT_FOUND', 'ERROR', target_rule_version_id::text,
            'the target rule version does not exist or has been removed',
            'Create or retain one immutable rule version before scheduling it.', '{}'::jsonb;
        RETURN;
    END IF;
    IF version_row.owner_oid <> (SELECT oid FROM pg_roles WHERE rolname = session_user)
       AND NOT pgreact_internal.is_operator_admin() THEN
        RETURN QUERY SELECT 12, 'M24_TARGET_FORBIDDEN', 'ERROR', target_rule_version_id::text,
            'only the rule owner or pgreact_admin may schedule this policy version',
            'Use the owning role or the configured operator role.', '{}'::jsonb;
        RETURN;
    END IF;
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.derivation_rule_versions
        WHERE rule_version_id = target_rule_version_id
    ) THEN
        RETURN QUERY SELECT 12, 'M24_PROGRAM_MEMBER_RULE', 'ERROR', target_rule_version_id::text,
            'a derivation-program member must be scheduled as part of its complete program',
            'Use author_effective_program with the immutable program definition.',
            '{}'::jsonb;
        RETURN;
    END IF;

    SELECT * INTO policy_row
    FROM pgreact_internal.effective_policies
    WHERE policy_name = target_policy_name;
    IF FOUND AND policy_row.owner_oid <> version_row.owner_oid
       AND NOT pgreact_internal.is_operator_admin() THEN
        RETURN QUERY SELECT 12, 'M24_POLICY_OWNER', 'ERROR', target_policy_name,
            'all versions of one policy must have one owner',
            'Schedule the version as the existing policy owner.', '{}'::jsonb;
        RETURN;
    END IF;

    SELECT version.policy_version_id, version.valid_from, version.valid_to
    INTO overlap
    FROM pgreact_internal.effective_policy_versions version
    JOIN pgreact_internal.effective_policies policy USING (policy_id)
    WHERE policy.policy_name = target_policy_name
      AND version.deployment_state <> 'REMOVED'
      AND version.rule_version_id <> target_rule_version_id
      AND version.valid_from < COALESCE(target_valid_to, 'infinity'::timestamptz)
      AND target_valid_from < COALESCE(version.valid_to, 'infinity'::timestamptz)
    ORDER BY version.valid_from, version.policy_version_id
    LIMIT 1;
    IF FOUND THEN
        RETURN QUERY SELECT 12, 'M24_INTERVAL_OVERLAP', 'ERROR', target_policy_name,
            'effective intervals for one policy must not overlap',
            'Use adjacent half-open intervals or an explicit no-authority gap.',
            jsonb_build_object('existing_version', overlap.policy_version_id,
                               'existing_valid_from', overlap.valid_from,
                               'existing_valid_to', overlap.valid_to,
                               'valid_from', target_valid_from,
                               'valid_to', target_valid_to);
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1 FROM pgreact_internal.effective_policy_versions
        WHERE rule_version_id = target_rule_version_id
          AND deployment_state <> 'REMOVED'
    ) THEN
        RETURN QUERY SELECT 12, 'M24_VERSION_ALREADY_SCHEDULED', 'ERROR',
            target_rule_version_id::text,
            'one immutable rule version can belong to only one effective policy version',
            'Create a new immutable rule version for a new policy interval.', '{}'::jsonb;
        RETURN;
    END IF;

    RETURN QUERY SELECT 12, 'OK', 'INFO', target_policy_name,
        'effective policy interval is valid and has unique authority',
        'Deploy it; it remains dormant until the committed database-time frontier reaches valid_from.',
        jsonb_build_object(
            'clock_domain', 'DATABASE_TIME',
            'interval', jsonb_build_array(target_valid_from, target_valid_to),
            'boundary', '[valid_from, valid_to)',
            'equality', 'the version beginning at the boundary is authoritative');
END
$m24$;

CREATE FUNCTION pgreact_api.validate_effective_policy(
    policy_name text,
    rule_version_id uuid,
    valid_from timestamptz,
    valid_to timestamptz DEFAULT NULL
)
RETURNS TABLE(
    contract_version integer,
    code text,
    severity text,
    object_identity text,
    message text,
    hint text,
    details jsonb
)
LANGUAGE SQL
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m24$
    SELECT * FROM pgreact_internal.validate_effective_policy($1, $2, $3, $4)
$m24$;

CREATE FUNCTION pgreact_internal.validate_effective_program(
    target_policy_name text,
    target_definition jsonb,
    target_valid_from timestamptz,
    target_valid_to timestamptz
)
RETURNS TABLE(
    contract_version integer,
    code text,
    severity text,
    object_identity text,
    message text,
    hint text,
    details jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m24$
DECLARE frontier timestamptz;
    policy_row pgreact_internal.effective_policies%ROWTYPE;
    diagnostic record;
    overlap record;
BEGIN
    SELECT clock.frontier INTO STRICT frontier
    FROM pgreact_internal.clock_frontier clock;
    IF target_policy_name IS NULL OR btrim(target_policy_name) = '' THEN
        RETURN QUERY SELECT 12, 'M24_POLICY_NAME', 'ERROR', '<unnamed>',
            'policy name must not be empty',
            'Choose one stable name for the policy identity.', '{}'::jsonb;
        RETURN;
    END IF;
    IF target_valid_from IS NULL OR NOT isfinite(target_valid_from) THEN
        RETURN QUERY SELECT 12, 'M24_VALID_FROM', 'ERROR', target_policy_name,
            'valid_from must be finite and non-null',
            'Use one finite timestamptz business-effective boundary.', '{}'::jsonb;
        RETURN;
    END IF;
    IF target_valid_to IS NOT NULL
       AND (NOT isfinite(target_valid_to) OR target_valid_to <= target_valid_from) THEN
        RETURN QUERY SELECT 12, 'M24_VALID_INTERVAL', 'ERROR', target_policy_name,
            'valid_to must be finite and greater than valid_from',
            'Use a half-open interval [valid_from, valid_to) or leave valid_to null for no upper bound.',
            jsonb_build_object('valid_from', target_valid_from, 'valid_to', target_valid_to);
        RETURN;
    END IF;
    IF target_valid_from < frontier THEN
        RETURN QUERY SELECT 12, 'M24_RETROACTIVE_INTERVAL', 'ERROR', target_policy_name,
            'a new effective policy version cannot begin before the committed frontier',
            'Schedule the version at or after the current database-time frontier.',
            jsonb_build_object('frontier', frontier, 'valid_from', target_valid_from);
        RETURN;
    END IF;
    SELECT result.* INTO diagnostic
    FROM pgreact.validate_derivation_program(target_definition) result
    WHERE result.severity = 'ERROR'
    ORDER BY result.code, result.object_identity
    LIMIT 1;
    IF FOUND THEN
        RETURN QUERY SELECT 12, diagnostic.code, diagnostic.severity,
            diagnostic.object_identity, diagnostic.message, diagnostic.hint,
            diagnostic.details;
        RETURN;
    END IF;
    SELECT * INTO policy_row
    FROM pgreact_internal.effective_policies
    WHERE policy_name = target_policy_name;
    IF FOUND AND policy_row.owner_oid <> (
        SELECT oid FROM pg_roles WHERE rolname = session_user
    ) AND NOT pgreact_internal.is_operator_admin() THEN
        RETURN QUERY SELECT 12, 'M24_POLICY_OWNER', 'ERROR', target_policy_name,
            'all versions of one policy must have one owner',
            'Schedule the version as the existing policy owner.', '{}'::jsonb;
        RETURN;
    END IF;
    IF FOUND AND EXISTS (
        SELECT 1
        FROM pgreact_internal.effective_policy_versions version
        WHERE version.policy_id = policy_row.policy_id
          AND version.deployment_state <> 'REMOVED'
          AND version.target_kind <> 'PROGRAM'
    ) THEN
        RETURN QUERY SELECT 12, 'M24_POLICY_TARGET_KIND', 'ERROR', target_policy_name,
            'one effective policy cannot mix rule and derivation-program versions',
            'Use a new policy identity for the other target kind.', '{}'::jsonb;
        RETURN;
    END IF;
    SELECT version.policy_version_id, version.valid_from, version.valid_to
    INTO overlap
    FROM pgreact_internal.effective_policy_versions version
    JOIN pgreact_internal.effective_policies policy USING (policy_id)
    WHERE policy.policy_name = target_policy_name
      AND version.deployment_state <> 'REMOVED'
      AND version.valid_from < COALESCE(target_valid_to, 'infinity'::timestamptz)
      AND target_valid_from < COALESCE(version.valid_to, 'infinity'::timestamptz)
    ORDER BY version.valid_from, version.policy_version_id
    LIMIT 1;
    IF FOUND THEN
        RETURN QUERY SELECT 12, 'M24_INTERVAL_OVERLAP', 'ERROR', target_policy_name,
            'effective intervals for one policy must not overlap',
            'Use adjacent half-open intervals or an explicit no-authority gap.',
            jsonb_build_object('existing_version', overlap.policy_version_id,
                               'existing_valid_from', overlap.valid_from,
                               'existing_valid_to', overlap.valid_to,
                               'valid_from', target_valid_from,
                               'valid_to', target_valid_to);
        RETURN;
    END IF;
    RETURN QUERY SELECT 12, 'OK', 'INFO', target_policy_name,
        'effective derivation-program interval is valid and has unique authority',
        'Deploy it; the program remains dormant until the committed database-time frontier reaches valid_from.',
        jsonb_build_object(
            'clock_domain', 'DATABASE_TIME',
            'target_kind', 'PROGRAM',
            'program', target_definition ->> 'name',
            'version', target_definition ->> 'version',
            'interval', jsonb_build_array(target_valid_from, target_valid_to),
            'boundary', '[valid_from, valid_to)');
END
$m24$;

CREATE FUNCTION pgreact_api.validate_effective_program(
    policy_name text,
    definition jsonb,
    valid_from timestamptz,
    valid_to timestamptz DEFAULT NULL
)
RETURNS TABLE(
    contract_version integer,
    code text,
    severity text,
    object_identity text,
