$m32$;

CREATE OR REPLACE VIEW pgreact.rules AS
SELECT r.rule_id, r.rule_name, v.rule_version_id, pg_get_userbyid(v.owner_oid) AS owner,
       v.source_view_name, v.key_column, v.consequence_identity, v.bootstrap_policy, v.state,
       v.created_at, r.rule_name AS name, 'rule'::text AS kind,
       '1'::text AS version,
       encode(COALESCE(api.declaration_digest, ''::bytea), 'hex') AS declaration_digest
FROM pgreact_internal.rules r
JOIN pgreact_internal.rule_versions v USING (rule_id)
LEFT JOIN pgreact_internal.api_declarations api
  ON api.kind = 'rule' AND api.object_name = r.rule_name AND api.state = 'DEPLOYED'
WHERE v.state <> 'REMOVED';

CREATE VIEW pgreact.matches AS
SELECT rule.name, rule.rule_name, rule.rule_version_id, activation.activation_id,
       activation.semantic_key, activation.current_bindings AS bindings,
       activation.active, activation.generation, activation.first_seen_at,
       activation.last_seen_at, activation.deactivated_at, activation.revision
FROM pgreact.activations activation
JOIN pgreact.rules rule USING (rule_version_id);

CREATE VIEW pgreact.decisions AS
SELECT program.program_id, program.program_name AS name, program.program_name,
       program.owner, program.state, program.version_id, program.version_no,
       program.candidate_relation, program.subject_key_column,
       program.candidate_key_column, program.priority_column, program.result_columns,
       program.result_types, program.max_candidates, program.valid_from, program.valid_to,
       program.source_signature, program.source_definition_digest, program.version_state,
       program.deployed_at
FROM pgreact.decision_programs program;

CREATE OR REPLACE VIEW pgreact.policy_sets AS
SELECT set.policy_set_id, set.set_name, pg_get_userbyid(set.owner_oid) AS owner,
       set.created_at, set.set_name AS name
FROM pgreact_internal.policy_sets set;

CREATE VIEW pgreact.work AS
SELECT 'rule'::text AS kind, rule.rule_name AS name, rule.version,
       episode.episode_id::text AS work_id, episode.state,
       (episode.state IN ('PENDING', 'LEASED')) AS claimable,
       episode.completed_at AS updated_at
FROM pgreact.episodes episode
JOIN pgreact.rules rule USING (rule_version_id)
UNION ALL
SELECT 'decision'::text, program.program_name, version.version_no::text,
       work.subject_key::text, state.state, work.claimable, work.updated_at
FROM pgreact_internal.decision_work work
JOIN pgreact_internal.decision_programs program USING (program_id)
JOIN pgreact_internal.decision_program_versions version
  ON version.program_id = work.program_id
JOIN pgreact_internal.decision_subject_state state
  ON state.program_id = work.program_id
 AND state.subject_key = work.subject_key
 AND version.version_id = state.version_id;

CREATE OR REPLACE VIEW pgreact.attempts AS
SELECT execution.execution_id, execution.episode_id, execution.attempt_no,
       execution.worker_id, execution.started_at, execution.finished_at,
       execution.status, execution.error_message, execution.error_code,
       execution.event_kind, rule.rule_name AS name
FROM pgreact_internal.executions execution
LEFT JOIN pgreact_internal.agenda episode USING (episode_id)
LEFT JOIN pgreact_internal.rules rule USING (rule_id);

CREATE VIEW pgreact.health AS
SELECT finding ->> 'code' AS code,
       finding ->> 'severity' AS severity,
       finding ->> 'target' AS target,
       finding ->> 'field' AS field,
       finding ->> 'message' AS message,
       finding ->> 'hint' AS hint,
       finding -> 'details' AS details,
       (finding ->> 'blocking')::boolean AS blocking
FROM (
    SELECT pgreact_internal.m32_finding_shape(to_jsonb(diagnostic)) AS finding
    FROM pgreact.health_check() diagnostic
) shaped;

COMMENT ON EXTENSION pg_react IS
    'M32 PostgreSQL-native ordinary interface over the authoritative M31 runtime';

-- M33 installed-reality inventory and frozen v1 finding registry.

CREATE OR REPLACE FUNCTION pgreact_internal.m33_installed_inventory()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m33$
WITH function_rows AS (
    SELECT n.nspname AS schema_name,
           p.proname AS name,
           format('%I.%I(%s)', n.nspname, p.proname,
                  pg_get_function_identity_arguments(p.oid)) AS identity,
           pg_get_function_identity_arguments(p.oid) AS identity_arguments,
           pg_get_function_arguments(p.oid) AS arguments,
           pg_get_function_result(p.oid) AS result_type,
           CASE p.prokind WHEN 'p' THEN 'procedure' ELSE 'function' END AS kind,
           CASE p.provolatile WHEN 'i' THEN 'IMMUTABLE'
                              WHEN 's' THEN 'STABLE'
                              ELSE 'VOLATILE' END AS volatility,
           p.prosecdef AS security_definer,
           COALESCE(p.proconfig, ARRAY[]::text[]) AS configuration,
           COALESCE(to_jsonb(p.proargnames), '[]'::jsonb) AS argument_names,
           COALESCE((
               SELECT jsonb_agg(jsonb_build_object(
                   'grantee', CASE WHEN a.grantee = 0 THEN 'PUBLIC'
                                   ELSE pg_get_userbyid(a.grantee) END,
                   'privilege', a.privilege_type,
                   'grantable', a.is_grantable
               ) ORDER BY a.grantee, a.privilege_type)
               FROM aclexplode(COALESCE(
                   p.proacl, acldefault('f', p.proowner))) AS a
           ), '[]'::jsonb) AS grants
    FROM pg_proc AS p
    JOIN pg_namespace AS n ON n.oid = p.pronamespace
    WHERE n.nspname IN ('pgreact', 'pgreact_api')
),
type_rows AS (
    SELECT n.nspname AS schema_name,
           t.typname AS name,
           t.typtype AS kind,
           format_type(t.oid, NULL) AS identity,
           COALESCE((
               SELECT jsonb_agg(jsonb_build_object(
                   'name', a.attname,
                   'type', format_type(a.atttypid, a.atttypmod),
                   'not_null', a.attnotnull
               ) ORDER BY a.attnum)
               FROM pg_attribute AS a
               WHERE a.attrelid = t.typrelid
                 AND a.attnum > 0
                 AND NOT a.attisdropped
           ), '[]'::jsonb) AS fields
    FROM pg_type AS t
    JOIN pg_namespace AS n ON n.oid = t.typnamespace
    WHERE n.nspname IN ('pgreact', 'pgreact_api')
      AND t.typtype IN ('c', 'd', 'e', 'r')
),
view_rows AS (
    SELECT n.nspname AS schema_name,
           c.relname AS name,
           CASE c.relkind WHEN 'm' THEN 'materialized_view'
                          ELSE 'view' END AS kind,
           COALESCE((
               SELECT jsonb_agg(jsonb_build_object(
                   'name', a.attname,
                   'type', format_type(a.atttypid, a.atttypmod),
                   'not_null', a.attnotnull,
                   'ordinal', a.attnum
               ) ORDER BY a.attnum)
               FROM pg_attribute AS a
               WHERE a.attrelid = c.oid
                 AND a.attnum > 0
                 AND NOT a.attisdropped
           ), '[]'::jsonb) AS columns
    FROM pg_class AS c
    JOIN pg_namespace AS n ON n.oid = c.relnamespace
    WHERE n.nspname = 'pgreact'
      AND c.relkind IN ('v', 'm')
),
relation_grants AS (
    SELECT n.nspname AS object_schema,
           c.relname AS object_name,
           CASE c.relkind WHEN 'm' THEN 'MATERIALIZED VIEW'
                          ELSE 'VIEW' END AS object_kind,
           CASE WHEN a.grantee = 0 THEN 'PUBLIC'
                ELSE pg_get_userbyid(a.grantee) END AS grantee,
           a.privilege_type AS privilege,
           a.is_grantable AS grantable
    FROM pg_class AS c
    JOIN pg_namespace AS n ON n.oid = c.relnamespace
    CROSS JOIN LATERAL aclexplode(COALESCE(
        c.relacl, acldefault('r', c.relowner))) AS a
    WHERE n.nspname = 'pgreact'
      AND c.relkind IN ('v', 'm')
),
function_grants AS (
    SELECT n.nspname AS object_schema,
           format('%I(%s)', p.proname,
                  pg_get_function_identity_arguments(p.oid)) AS object_name,
           'FUNCTION'::text AS object_kind,
           CASE WHEN a.grantee = 0 THEN 'PUBLIC'
                ELSE pg_get_userbyid(a.grantee) END AS grantee,
           a.privilege_type AS privilege,
           a.is_grantable AS grantable
    FROM pg_proc AS p
    JOIN pg_namespace AS n ON n.oid = p.pronamespace
    CROSS JOIN LATERAL aclexplode(COALESCE(
        p.proacl, acldefault('f', p.proowner))) AS a
    WHERE n.nspname IN ('pgreact', 'pgreact_api')
),
schema_grants AS (
    SELECT n.nspname AS object_schema,
           NULL::name AS object_name,
           'SCHEMA'::text AS object_kind,
           CASE WHEN a.grantee = 0 THEN 'PUBLIC'
                ELSE pg_get_userbyid(a.grantee) END AS grantee,
           a.privilege_type AS privilege,
           a.is_grantable AS grantable
    FROM pg_namespace AS n
    CROSS JOIN LATERAL aclexplode(COALESCE(
        n.nspacl, acldefault('n', n.nspowner))) AS a
    WHERE n.nspname IN ('pgreact', 'pgreact_api')
),
declaration_fields AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'name', a.attname,
               'type', format_type(a.atttypid, a.atttypmod),
               'not_null', a.attnotnull,
               'ordinal', a.attnum
           ) ORDER BY a.attnum), '[]'::jsonb) AS fields
    FROM pg_attribute AS a
    JOIN pg_type AS t ON t.typrelid = a.attrelid
    JOIN pg_namespace AS n ON n.oid = t.typnamespace
    WHERE n.nspname = 'pgreact_api'
      AND t.typname = 'declaration'
      AND a.attnum > 0
      AND NOT a.attisdropped
),
aliases AS (
    SELECT jsonb_agg(jsonb_build_object(
               'alias', alias_name,
               'canonical', canonical_name,
               'present', EXISTS (
                   SELECT 1
                   FROM pg_proc AS p
                   JOIN pg_namespace AS n ON n.oid = p.pronamespace
                   WHERE format('%I.%I', n.nspname, p.proname) = alias_name
               )
           ) ORDER BY alias_name) AS rows
    FROM (VALUES
        ('pgreact_api.author_rule', 'pgreact.rule'),
        ('pgreact_api.validate_rule', 'pgreact.validate'),
        ('pgreact_api.run_rule', 'pgreact.run'),
        ('pgreact_api.rule_status', 'pgreact.status'),
        ('pgreact_api.matches', 'pgreact.matches'),
        ('pgreact_api.jobs', 'pgreact.work'),
        ('pgreact_api.attempts', 'pgreact.attempts'),
        ('pgreact_api.explain_rule', 'pgreact.explain'),
        ('pgreact_api.validate', 'pgreact.validate'),
        ('pgreact_api.preview', 'pgreact.preview'),
        ('pgreact_api.deploy', 'pgreact.deploy'),
        ('pgreact_api.remove', 'pgreact.remove'),
        ('pgreact_api.run', 'pgreact.run'),
        ('pgreact_api.explain', 'pgreact.explain'),
        ('pgreact_api.doctor', 'pgreact.doctor')
    ) AS v(alias_name, canonical_name)
)
SELECT jsonb_build_object(
    'schema_version', 1,
    'extension_version', (
        SELECT extversion FROM pg_extension WHERE extname = 'pg_react'
    ),
    'functions', COALESCE((
        SELECT jsonb_agg(to_jsonb(f) ORDER BY f.schema_name, f.name,
                         f.identity_arguments)
        FROM function_rows AS f
    ), '[]'::jsonb),
    'overloads', COALESCE((
        SELECT jsonb_agg(to_jsonb(f) ORDER BY f.schema_name, f.name,
                         f.identity_arguments)
        FROM function_rows AS f
        WHERE (SELECT count(*) FROM function_rows AS same
               WHERE same.schema_name = f.schema_name
                 AND same.name = f.name) > 1
    ), '[]'::jsonb),
    'types', COALESCE((
        SELECT jsonb_agg(to_jsonb(t) ORDER BY t.schema_name, t.name)
        FROM type_rows AS t
    ), '[]'::jsonb),
    'public_views', COALESCE((
        SELECT jsonb_agg(to_jsonb(v) ORDER BY v.schema_name, v.name)
        FROM view_rows AS v
    ), '[]'::jsonb),
    'grants', COALESCE((
        SELECT jsonb_agg(to_jsonb(g) ORDER BY g.object_schema,
                         g.object_kind, g.object_name, g.grantee, g.privilege)
        FROM (
            SELECT * FROM relation_grants
            UNION ALL
            SELECT * FROM function_grants
            UNION ALL
            SELECT * FROM schema_grants
        ) AS g
    ), '[]'::jsonb),
    'declaration_fields', (SELECT fields FROM declaration_fields),
    'aliases', COALESCE((SELECT rows FROM aliases), '[]'::jsonb)
)
$m33$;

CREATE OR REPLACE FUNCTION pgreact_internal.m33_inventory()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m33$
    SELECT pgreact_internal.m33_installed_inventory()
$m33$;

CREATE OR REPLACE VIEW pgreact_internal.m33_finding_registry AS
SELECT *
FROM (VALUES
    (1, 'M32_INVALID_DECLARATION', 'invalid declaration', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_MISSING_OBJECT', 'missing PostgreSQL object', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_AMBIGUOUS_OBJECT', 'ambiguous PostgreSQL object', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_WRONG_KEY_TYPE', 'wrong key type', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_INVALID_ACTION_SIGNATURE', 'invalid action signature', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_UNAUTHORIZED_OBJECT', 'unauthorized object', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_RLS_UNSUPPORTED', 'RLS unsupported', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_SOURCE_DRIFT', 'source drift', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_ACTION_DRIFT', 'action drift', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_STALE_PREVIEW', 'stale preview', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_UNSUPPORTED_KIND', 'unsupported ordinary kind', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_ADVANCED_ONLY', 'advanced-only operation', 'WARNING', false, '<unknown>', '<unknown>'),
    (1, 'M32_RESOURCE_LIMIT', 'resource limit', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_RECOVERY_BARRIER', 'recovery barrier', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_INCOMPLETE_FRONTIER', 'incomplete frontier', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_POLICY_SCOPE_INCOMPATIBLE', 'policy-scope incompatibility', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_DECLARATION_MIGRATION_REQUIRED', 'declaration migration required', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_DEPRECATED_COMPATIBILITY', 'deprecated compatibility surface', 'WARNING', false, '<unknown>', '<unknown>'),
    (1, 'M32_RUNTIME_READY', 'managed runtime readiness', 'INFO', false, 'managed runtime or installation target', 'runtime readiness'),
    (1, 'M32_RUNTIME_NOT_READY', 'managed runtime readiness', 'ERROR', true, '<unknown>', '<unknown>'),
    (1, 'M32_WORK_FAILED', 'durable work failure', 'ERROR', false, '<unknown>', '<unknown>'),
    (1, 'M32_RETRY_EXHAUSTED', 'exhausted retry', 'ERROR', false, '<unknown>', '<unknown>')
) AS registry(schema_version, code, category, default_severity, blocking, target, field);

CREATE OR REPLACE FUNCTION pgreact_internal.m33_finding_registry()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m33$
    SELECT jsonb_build_object(
        'schema_version', 1,
        'finding_shape', jsonb_build_array(
            'code', 'severity', 'blocking', 'target',
            'field', 'message', 'hint', 'details'
        ),
        'severity', jsonb_build_array('ERROR', 'WARNING', 'INFO'),
        'codes', COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.code), '[]'::jsonb)
    )
    FROM pgreact_internal.m33_finding_registry AS r
$m33$;

CREATE OR REPLACE FUNCTION pgreact_internal.m33_check_finding(finding jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m33$
DECLARE
    normalized jsonb;
    finding_code text;
    errors text[] := ARRAY[]::text[];
BEGIN
    IF finding IS NULL OR jsonb_typeof(finding) <> 'object' THEN
        RETURN jsonb_build_object(
            'valid', false,
            'code', NULL,
            'errors', jsonb_build_array('finding must be a JSON object')
        );
    END IF;

    normalized := pgreact_internal.m32_finding_shape(finding);
    finding_code := finding ->> 'code';
    IF NOT EXISTS (
        SELECT 1 FROM pgreact_internal.m33_finding_registry AS r
        WHERE r.code = finding_code
    ) THEN
        errors := array_append(errors, 'code is not in the stable v1 registry');
    END IF;
    IF NOT (finding ?& ARRAY[
        'code', 'severity', 'blocking', 'target',
        'field', 'message', 'hint', 'details'
    ]) THEN
        errors := array_append(errors, 'finding shape is incomplete');
    END IF;
    IF finding ->> 'severity' NOT IN ('ERROR', 'WARNING', 'INFO') THEN
        errors := array_append(errors, 'severity is not one of ERROR, WARNING, INFO');
    END IF;
    IF jsonb_typeof(finding -> 'blocking') <> 'boolean' THEN
        errors := array_append(errors, 'blocking must be boolean');
    END IF;
    IF jsonb_typeof(finding -> 'details') <> 'object' THEN
        errors := array_append(errors, 'details must be an object');
    END IF;

    RETURN jsonb_build_object(
        'valid', cardinality(errors) = 0,
        'code', finding_code,
        'normalized', normalized,
        'errors', to_jsonb(errors)
    );
END
$m33$;

CREATE OR REPLACE FUNCTION pgreact_internal.m33_check_findings(findings jsonb)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m33$
    SELECT CASE WHEN jsonb_typeof($1) = 'array' THEN
        jsonb_build_object(
            'valid', COALESCE(bool_and((checked.result ->> 'valid')::boolean), true),
            'findings', COALESCE(jsonb_agg(checked.result ORDER BY checked.ordinal), '[]'::jsonb)
        )
    ELSE
        jsonb_build_object(
            'valid', false,
            'findings', jsonb_build_array(jsonb_build_object(
                'valid', false,
                'code', NULL,
                'errors', jsonb_build_array('findings must be a JSON array')
            ))
        )
    END
    FROM (
        SELECT item.ordinal,
               pgreact_internal.m33_check_finding(item.value) AS result
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof($1) = 'array'
                                       THEN $1 ELSE '[]'::jsonb END)
             WITH ORDINALITY AS item(value, ordinal)
    ) AS checked
$m33$;

REVOKE ALL ON TABLE pgreact_internal.m33_finding_registry FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m33_installed_inventory() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m33_inventory() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m33_finding_registry() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m33_check_finding(jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m33_check_findings(jsonb) FROM PUBLIC;

-- M34 read-only deployment-impact comparison over the authoritative M33 state.

CREATE OR REPLACE FUNCTION pgreact_internal.m34_finding(
    code text,
    severity text,
    target text,
    field text,
    message text,
    hint text,
    details jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
STRICT
AS $m34$
    SELECT jsonb_build_object(
        'code', $1,
        'severity', $2,
        'blocking', $2 = 'ERROR',
        'target', $3,
        'field', $4,
        'message', $5,
        'hint', $6,
        'details', COALESCE($7, '{}'::jsonb))
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_finding_registry()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
    SELECT jsonb_build_object(
        'schema_version', 1,
        'milestone', 'M34',
        'finding_shape', jsonb_build_array(
            'code', 'severity', 'blocking', 'target',
            'field', 'message', 'hint', 'details'),
        'severity', jsonb_build_array('ERROR', 'WARNING', 'INFO'),
        'codes', jsonb_build_array(
            jsonb_build_object('code', 'M34_INVALID_DECLARATION', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_OPTIONS', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_TARGET_NOT_FOUND', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_TARGET_KIND', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_TARGET_NAME', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_TARGET_VERSION', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_UNAUTHORIZED_TARGET', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_UNAUTHORIZED_SOURCE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_RLS_UNSUPPORTED', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_SOURCE_DRIFT', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_PROPOSAL_DUPLICATE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_WRONG_KEY_TYPE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_RESOURCE_LIMIT', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_SAMPLED_TIME', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_UNSUPPORTED_KIND', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_AUTHORITATIVE_CHANGED', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M34_COMPARISON_INCOMPLETE', 'severity', 'WARNING'),
            jsonb_build_object('code', 'M34_NO_EFFECT', 'severity', 'INFO')))
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_authoritative_checksum()
RETURNS text
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
    SELECT encode(sha256(convert_to(jsonb_build_object(
        'frontier', (SELECT frontier FROM pgreact_internal.clock_frontier WHERE singleton),
        'declarations', COALESCE((
            SELECT jsonb_agg(to_jsonb(row_data) ORDER BY row_data.declaration_id)
            FROM pgreact_internal.api_declarations row_data), '[]'::jsonb),
        'rules', COALESCE((
            SELECT jsonb_agg(to_jsonb(row_data) ORDER BY row_data.rule_version_id)
            FROM pgreact_internal.rule_versions row_data), '[]'::jsonb),
        'matches', COALESCE((
            SELECT jsonb_agg(to_jsonb(row_data) ORDER BY row_data.rule_version_id, row_data.activation_id)
            FROM pgreact_internal.activation_state row_data), '[]'::jsonb),
        'decisions', COALESCE((
            SELECT jsonb_agg(to_jsonb(row_data) ORDER BY row_data.program_id, row_data.subject_key)
            FROM pgreact_internal.decision_subject_state row_data), '[]'::jsonb),
        'work', COALESCE((
            SELECT jsonb_agg(to_jsonb(row_data) ORDER BY row_data.kind, row_data.name, row_data.work_id)
            FROM pgreact.work row_data), '[]'::jsonb),
        'policy_sets', COALESCE((
            SELECT jsonb_agg(to_jsonb(row_data) ORDER BY row_data.policy_set_id, row_data.version)
            FROM pgreact_internal.policy_set_versions row_data), '[]'::jsonb)
    )::text, 'UTF8')), 'hex')
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_require_source(
    source_oid oid,
    source_name text
)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
DECLARE rls_enabled boolean;
BEGIN
    IF source_oid IS NULL THEN
        RAISE EXCEPTION 'M34_SOURCE_DRIFT: source relation % no longer exists', source_name;
    END IF;
    SELECT relrowsecurity INTO rls_enabled
    FROM pg_class
    WHERE oid = source_oid;
    IF rls_enabled THEN
        RAISE EXCEPTION 'M34_RLS_UNSUPPORTED: source relation % uses row-level security', source_name;
    END IF;
    IF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
        RAISE EXCEPTION 'M34_UNAUTHORIZED_SOURCE: caller lacks SELECT on source relation %', source_name;
    END IF;
END
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_raw_rows(
    rows jsonb,
    total_count bigint,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
STRICT
AS $m34$
    SELECT jsonb_build_object(
        'rows', COALESCE((
            SELECT jsonb_agg(item.value ORDER BY item.ordinality)
            FROM jsonb_array_elements($1) WITH ORDINALITY item(value, ordinality)
            WHERE item.ordinality <= $3), '[]'::jsonb),
        'rows_considered', $2,
        'truncated', $2 > $3)
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_rule_rows(
    source_oid oid,
    key_column name,
    source_label text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
DECLARE total_count bigint;
    null_count bigint;
    duplicate_count bigint;
    rows jsonb;
    key_type regtype;
BEGIN
    SELECT a.atttypid::regtype INTO key_type
    FROM pg_attribute a
    WHERE a.attrelid = source_oid
      AND a.attname = key_column
      AND a.attnum > 0
      AND NOT a.attisdropped;
    IF key_type IS DISTINCT FROM 'bigint'::regtype THEN
        RAISE EXCEPTION 'M34_WRONG_KEY_TYPE: rule key % must be bigint', key_column;
    END IF;
    EXECUTE format('SELECT count(*) FROM %s', source_oid::regclass) INTO total_count;
    EXECUTE format('SELECT count(*) FROM %s WHERE %I IS NULL', source_oid::regclass, key_column)
        INTO null_count;
    IF null_count > 0 THEN
        RAISE EXCEPTION 'M34_SOURCE_DRIFT: rule source % contains null keys', source_oid::regclass;
    END IF;
    EXECUTE format(
        'SELECT count(*) FROM (
             SELECT %1$I FROM %2$s GROUP BY %1$I HAVING count(*) > 1
         ) duplicates', key_column, source_oid::regclass)
        INTO duplicate_count;
    IF duplicate_count > 0 THEN
        RAISE EXCEPTION 'M34_PROPOSAL_DUPLICATE: rule source % contains duplicate keys',
            source_oid::regclass;
    END IF;
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(jsonb_build_object(
             ''subject_key'', s.%1$I::text,
             ''result_key'', s.%1$I::text,
             ''state'', ''MATCH'',
             ''value'', to_jsonb(s),
             ''work'', jsonb_build_object(''would_be_work'', true),
             ''evidence'', jsonb_build_object(
                 ''source'', $2, ''complete'', true))
             ORDER BY s.%1$I), ''[]''::jsonb)
         FROM (
             SELECT * FROM %2$s
             ORDER BY %1$I
             LIMIT ($1 + 1)
         ) s', key_column, source_oid::regclass)
        INTO rows
        USING evidence_limit, source_label;
    RETURN jsonb_build_object(
        'rows', rows,
        'rows_considered', total_count,
        'truncated', total_count > evidence_limit);
END
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_current_rule_rows(
    target_name text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
    SELECT jsonb_build_object(
        'rows', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                       'subject_key', match_row.semantic_key::text,
                       'result_key', match_row.semantic_key::text,
                       'state', CASE WHEN match_row.active THEN 'MATCH' ELSE 'INACTIVE' END,
                       'value', match_row.bindings - '__pgt_row_id',
                       'work', jsonb_build_object(
                           'would_be_work', match_row.active),
                       'evidence', jsonb_build_object(
                           'source', 'pgreact.matches',
                           'generation', match_row.generation,
                           'revision', match_row.revision,
                           'complete', true))
                   ORDER BY match_row.semantic_key)
            FROM (
                SELECT *
                FROM pgreact.matches
                WHERE name = $1 AND active
                ORDER BY semantic_key
                LIMIT ($2 + 1)
            ) match_row), '[]'::jsonb),
        'rows_considered', (
            SELECT count(*) FROM pgreact.matches
            WHERE name = $1 AND active),
        'truncated', (
            SELECT count(*) > $2 FROM pgreact.matches
            WHERE name = $1 AND active))
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_decision_rows(
    source_oid oid,
    subject_column name,
    candidate_column name,
    priority_column name,
    result_columns name[],
    max_candidates integer,
    source_label text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
DECLARE total_count bigint;
    null_count bigint;
    duplicate_count bigint;
    over_limit_count bigint;
    rows jsonb;
BEGIN
    EXECUTE format(
        'SELECT count(*) FROM %1$s
         WHERE %2$I IS NULL OR %3$I IS NULL OR %4$I IS NULL',
        source_oid::regclass, subject_column, candidate_column, priority_column)
        INTO null_count;
    IF null_count > 0 THEN
        RAISE EXCEPTION 'M34_SOURCE_DRIFT: decision source % contains null identities or priorities',
            source_oid::regclass;
    END IF;
    EXECUTE format(
        'SELECT count(*) FROM (
             SELECT %1$I, %2$I FROM %3$s
             GROUP BY %1$I, %2$I HAVING count(*) > 1
         ) duplicates', subject_column, candidate_column, source_oid::regclass)
        INTO duplicate_count;
    IF duplicate_count > 0 THEN
        RAISE EXCEPTION 'M34_PROPOSAL_DUPLICATE: decision source % contains duplicate candidates',
            source_oid::regclass;
    END IF;
    EXECUTE format(
        'SELECT count(*) FROM (
             SELECT %1$I FROM %2$s
             GROUP BY %1$I HAVING count(*) > $1
         ) over_limit', subject_column, source_oid::regclass)
        INTO over_limit_count
        USING max_candidates;
    IF over_limit_count > 0 THEN
        RAISE EXCEPTION 'M34_RESOURCE_LIMIT: decision source % exceeds max_candidates',
            source_oid::regclass;
    END IF;
    EXECUTE format('SELECT count(DISTINCT %1$I) FROM %2$s', subject_column, source_oid::regclass)
        INTO total_count;
    EXECUTE format(
        'WITH source AS (
             SELECT s.%1$I::bigint AS subject_key,
                    s.%2$I::bigint AS candidate_key,
                    s.%3$I::bigint AS priority,
                    to_jsonb(s) AS row_data
             FROM %4$s s
         ), ranked AS (
             SELECT source.*,
                    min(priority) OVER (PARTITION BY subject_key) AS best_priority
             FROM source
         ), grouped AS (
             SELECT subject_key,
                    min(priority) AS best_priority,
                    count(*) AS candidate_count,
                    count(*) FILTER (WHERE priority = best_priority) AS top_count,
                    min(candidate_key) FILTER (WHERE priority = best_priority) AS winner_candidate,
                    (array_agg(row_data ORDER BY candidate_key)
                        FILTER (WHERE priority = best_priority))[1] AS winner_row,
                    jsonb_agg(jsonb_build_object(
                        ''candidate'', candidate_key::text,
                        ''priority'', priority,
                        ''value'', row_data)
                        ORDER BY candidate_key) AS competitors
             FROM ranked
             GROUP BY subject_key
         ), limited AS (
             SELECT *
             FROM grouped
             ORDER BY subject_key
             LIMIT ($1 + 1)
         )
         SELECT COALESCE(jsonb_agg(jsonb_build_object(
                    ''subject_key'', subject_key::text,
                    ''result_key'', CASE WHEN top_count = 1
                                         THEN winner_candidate::text ELSE NULL END,
                    ''state'', CASE WHEN top_count = 1
                                    THEN ''WINNER'' ELSE ''AMBIGUOUS'' END,
                    ''value'', jsonb_build_object(
                        ''candidate'', CASE WHEN top_count = 1
                                            THEN winner_candidate ELSE NULL END,
                        ''priority'', best_priority,
                        ''result'', CASE WHEN top_count = 1
                                         THEN pgreact_internal.decision_result(
                                             winner_row, $3) ELSE NULL END),
                    ''work'', jsonb_build_object(
                        ''would_be_work'', top_count = 1),
                    ''evidence'', jsonb_build_object(
                        ''source'', $2,
                        ''candidate_count'', candidate_count,
                        ''competitors'', competitors,
                        ''complete'', true))
                ORDER BY subject_key), ''[]''::jsonb)
         FROM limited', subject_column, candidate_column, priority_column, source_oid::regclass)
        INTO rows
        USING evidence_limit, source_label, result_columns;
    RETURN jsonb_build_object(
        'rows', rows,
        'rows_considered', total_count,
        'truncated', total_count > evidence_limit);
END
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_current_decision_rows(
    target_name text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
    SELECT jsonb_build_object(
        'rows', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                       'subject_key', winner.subject_key::text,
                       'result_key', winner.winner_candidate::text,
                       'state', winner.state,
                       'value', jsonb_build_object(
                           'candidate', winner.winner_candidate,
                           'priority', winner.winner_priority,
                           'result', winner.winner_result,
                           'claimable', winner.claimable),
                       'work', jsonb_build_object(
                           'would_be_work', winner.claimable),
                       'evidence', jsonb_build_object(
                           'source', 'pgreact.decision_winners',
                           'competitors', winner.competitors,
                           'competitors_truncated', winner.competitors_truncated,
                           'complete', NOT winner.competitors_truncated))
                   ORDER BY winner.subject_key)
            FROM (
                SELECT *
                FROM pgreact.decision_winners
                WHERE program_name = $1
                ORDER BY subject_key
                LIMIT ($2 + 1)
            ) winner), '[]'::jsonb),
        'rows_considered', (
            SELECT count(*) FROM pgreact.decision_winners
            WHERE program_name = $1),
        'truncated', (
            SELECT count(*) > $2 FROM pgreact.decision_winners
            WHERE program_name = $1))
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_policy_rows(
    current_normalized jsonb,
    proposed_normalized jsonb,
    current_set_name text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
DECLARE current_members jsonb;
    current_subjects jsonb;
    proposed_members jsonb;
    proposed_subjects jsonb;
    current_rows jsonb;
    proposed_rows jsonb;
    current_count bigint;
    proposed_count bigint;
    current_member_count bigint;
    proposed_member_count bigint;
    current_subject_count bigint;
    proposed_subject_count bigint;
    source_oid oid;
    key_names name[];
    key_types text[];
    values_expression text;
    complete_expression text;
BEGIN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'subject_key', 'member:' || (item.value ->> 'kind') || ':' ||
                              (item.value ->> 'name') || ':' || (item.value ->> 'version'),
               'result_key', 'member:' || (item.value ->> 'kind') || ':' ||
                             (item.value ->> 'name') || ':' || (item.value ->> 'version'),
               'state', 'MEMBER',
               'value', item.value,
               'work', jsonb_build_object('would_be_work', false),
               'evidence', jsonb_build_object('source', 'pgreact.policy_set_members',
                                              'complete', true))
               ORDER BY item.value ->> 'kind', item.value ->> 'name', item.value ->> 'version'),
           '[]'::jsonb)
    INTO current_members
    FROM (
        SELECT item.value
        FROM jsonb_array_elements(
                 COALESCE(current_normalized -> 'spec' -> 'members', '[]'::jsonb))
             WITH ORDINALITY item(value, ordinal)
        WHERE item.ordinal <= evidence_limit + 1
    ) item;
    current_member_count := jsonb_array_length(
        COALESCE(current_normalized -> 'spec' -> 'members', '[]'::jsonb));
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'subject_key', 'subject:' || row_data.subject_identity,
               'result_key', 'subject:' || row_data.subject_identity,
               'state', 'ELIGIBLE',
               'value', row_data.subject_values,
               'work', jsonb_build_object('would_be_work', false),
               'evidence', jsonb_build_object(
                   'source', 'pgreact.policy_set_eligible_subjects',
                   'complete', true))
               ORDER BY row_data.subject_identity), '[]'::jsonb)
    INTO current_subjects
    FROM (
        SELECT row_data.*
        FROM pgreact.policy_set_eligible_subjects row_data
        WHERE row_data.set_name = current_set_name
          AND row_data.version = current_normalized -> 'spec' ->> 'version'
        ORDER BY row_data.subject_identity
        LIMIT (evidence_limit + 1)
    ) row_data;
    SELECT count(*) INTO current_subject_count
    FROM pgreact.policy_set_eligible_subjects row_data
    WHERE row_data.set_name = current_set_name
      AND row_data.version = current_normalized -> 'spec' ->> 'version';

    proposed_members := COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
                   'subject_key', 'member:' || (item.value ->> 'kind') || ':' ||
                                  (item.value ->> 'name') || ':' || (item.value ->> 'version'),
                   'result_key', 'member:' || (item.value ->> 'kind') || ':' ||
                                 (item.value ->> 'name') || ':' || (item.value ->> 'version'),
                   'state', 'MEMBER',
                   'value', item.value,
                   'work', jsonb_build_object('would_be_work', false),
                   'evidence', jsonb_build_object('source', 'proposed declaration',
                                                  'complete', true))
                   ORDER BY item.value ->> 'kind', item.value ->> 'name', item.value ->> 'version')
        FROM (
            SELECT item.value
            FROM jsonb_array_elements(
                     COALESCE(proposed_normalized -> 'spec' -> 'members', '[]'::jsonb))
                 WITH ORDINALITY item(value, ordinal)
            WHERE item.ordinal <= evidence_limit + 1
        ) item), '[]'::jsonb);
    proposed_member_count := jsonb_array_length(
        COALESCE(proposed_normalized -> 'spec' -> 'members', '[]'::jsonb));

    IF proposed_normalized -> 'spec' -> 'applicability' ->> 'source_kind'
       IS DISTINCT FROM 'relation' THEN
        RAISE EXCEPTION 'M34_UNSUPPORTED_KIND: M34 requires a relational applicability source';
    END IF;
    source_oid := to_regclass(proposed_normalized -> 'spec' -> 'applicability' ->> 'relation');
    PERFORM pgreact_internal.m34_require_source(
        source_oid, proposed_normalized -> 'spec' -> 'applicability' ->> 'relation');
    SELECT array_agg(value::name ORDER BY ordinal),
           array_agg(a.atttypid::regtype::text ORDER BY ordinal)
    INTO key_names, key_types
    FROM jsonb_array_elements_text(
             proposed_normalized -> 'spec' -> 'applicability' -> 'subject_keys')
         WITH ORDINALITY requested(value, ordinal)
    JOIN pg_attribute a
      ON a.attrelid = source_oid
     AND a.attname = requested.value::name
     AND a.attnum > 0
     AND NOT a.attisdropped;
    IF cardinality(key_names) IS DISTINCT FROM
       jsonb_array_length(proposed_normalized -> 'spec' -> 'applicability' -> 'subject_keys') THEN
        RAISE EXCEPTION 'M34_SOURCE_DRIFT: applicability key column is missing';
    END IF;
    SELECT string_agg(format('to_jsonb(s.%I)', key_name), ', ' ORDER BY ordinal),
           string_agg(format('s.%I IS NOT NULL', key_name), ' AND ' ORDER BY ordinal)
    INTO values_expression, complete_expression
    FROM unnest(key_names) WITH ORDINALITY requested(key_name, ordinal);
    values_expression := 'jsonb_build_array(' || values_expression || ')';
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(jsonb_build_object(
                    ''subject_key'', ''subject:'' ||
                        encode(pgreact_internal.m30_key_identity($1, x.subject_values), ''hex''),
                    ''result_key'', ''subject:'' ||
                        encode(pgreact_internal.m30_key_identity($1, x.subject_values), ''hex''),
                    ''state'', ''ELIGIBLE'',
                    ''value'', x.subject_values,
                    ''work'', jsonb_build_object(''would_be_work'', false),
                    ''evidence'', jsonb_build_object(
                        ''source'', $2, ''complete'', true))
                ORDER BY x.subject_values::text), ''[]''::jsonb)
         FROM (
             SELECT distinct_values.subject_values
             FROM (
                 SELECT DISTINCT %1$s AS subject_values
                 FROM %2$s s
                 WHERE %3$s
             ) distinct_values
             ORDER BY distinct_values.subject_values::text
             LIMIT ($3 + 1)
         ) x', values_expression, source_oid::regclass, complete_expression)
        INTO proposed_subjects
        USING key_types,
              proposed_normalized -> 'spec' -> 'applicability' ->> 'relation',
              evidence_limit;
    EXECUTE format(
        'SELECT count(*) FROM (
             SELECT DISTINCT %1$s AS subject_values
             FROM %2$s s
             WHERE %3$s
         ) distinct_values', values_expression, source_oid::regclass, complete_expression)
        INTO proposed_subject_count;

    current_rows := current_members || current_subjects;
    proposed_rows := proposed_members || proposed_subjects;
    current_count := current_member_count + current_subject_count;
    proposed_count := proposed_member_count + proposed_subject_count;
    RETURN jsonb_build_object(
        'current', jsonb_build_object(
            'rows', current_rows,
            'rows_considered', current_count,
            'truncated', current_count > evidence_limit),
        'proposed', jsonb_build_object(
            'rows', proposed_rows,
            'rows_considered', proposed_count,
            'truncated', proposed_count > evidence_limit));
END
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_delta(
    current_rows jsonb,
    proposed_rows jsonb
)
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
STRICT
AS $m34$
WITH current_values AS (
    SELECT value ->> 'subject_key' AS subject_key, value
    FROM jsonb_array_elements($1) item(value)
), proposed_values AS (
    SELECT value ->> 'subject_key' AS subject_key, value
    FROM jsonb_array_elements($2) item(value)
), changes AS (
    SELECT COALESCE(current_values.subject_key, proposed_values.subject_key) AS subject_key,
           current_values.value AS current_value,
           proposed_values.value AS proposed_value,
           CASE
               WHEN current_values.value IS NULL THEN 'ADDED'
               WHEN proposed_values.value IS NULL THEN 'REMOVED'
               WHEN current_values.value ->> 'state' IS NOT DISTINCT FROM
                    proposed_values.value ->> 'state'
                AND current_values.value -> 'value' IS NOT DISTINCT FROM
                    proposed_values.value -> 'value' THEN 'UNCHANGED'
               ELSE 'CHANGED'
           END AS change
    FROM current_values
    FULL JOIN proposed_values USING (subject_key)
)
SELECT jsonb_build_object(
    'rows', COALESCE(jsonb_agg(jsonb_build_object(
        'subject_key', subject_key,
        'result_key', subject_key,
        'change', change,
        'state', COALESCE(proposed_value ->> 'state', current_value ->> 'state'),
        'current_value', current_value -> 'value',
        'proposed_value', proposed_value -> 'value',
        'work', COALESCE(proposed_value -> 'work', current_value -> 'work'),
        'evidence', jsonb_build_object(
            'current', current_value -> 'evidence',
            'proposed', proposed_value -> 'evidence',
            'complete', true))
        ORDER BY subject_key), '[]'::jsonb),
    'counts', jsonb_build_object(
        'added', count(*) FILTER (WHERE change = 'ADDED'),
        'removed', count(*) FILTER (WHERE change = 'REMOVED'),
        'changed', count(*) FILTER (WHERE change = 'CHANGED'),
        'unchanged', count(*) FILTER (WHERE change = 'UNCHANGED')))
FROM changes
$m34$;

CREATE OR REPLACE FUNCTION pgreact_internal.m34_compare(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    options jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
DECLARE validation jsonb;
    proposed_normalized jsonb;
    current_normalized jsonb;
    current_owner oid;
    current_checksum text;
    after_checksum text;
    current_model jsonb;
    proposed_model jsonb;
    delta_model jsonb;
    current_rows jsonb;
    proposed_rows jsonb;
    delta_rows jsonb;
    lifecycle_rows jsonb;
    work_rows jsonb;
    current_count bigint;
    proposed_count bigint;
    missing_count bigint := 0;
    evidence_limit integer := 100;
    sampled_time timestamptz;
    source_frontier timestamptz;
    started_at timestamptz := clock_timestamp();
    comparison_complete boolean;
    target_kind text := (deployed).kind;
    target_name text := (deployed).name;
    target_version text := (deployed).version;
    source_oid oid;
    key_column name;
    subject_column name;
    candidate_column name;
    priority_column name;
    result_columns name[];
    max_candidates integer;
    relation_name text;
BEGIN
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M34_OPTIONS: options must be a JSON object';
    END IF;
    IF options ? 'evidence_limit' THEN
        IF jsonb_typeof(options -> 'evidence_limit') IS DISTINCT FROM 'number'
           OR (options ->> 'evidence_limit')::integer < 1
           OR (options ->> 'evidence_limit')::integer > 1000 THEN
            RAISE EXCEPTION 'M34_RESOURCE_LIMIT: evidence_limit must be between 1 and 1000';
        END IF;
        evidence_limit := (options ->> 'evidence_limit')::integer;
    END IF;
    IF options ? 'sampled_time'
       AND jsonb_typeof(options -> 'sampled_time') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'M34_OPTIONS: sampled_time must be an RFC3339 timestamp string';
    END IF;
    SELECT frontier INTO source_frontier
    FROM pgreact_internal.clock_frontier
    WHERE singleton;
    sampled_time := COALESCE(
        NULLIF(options ->> 'sampled_time', '')::timestamptz,
        source_frontier);
    IF sampled_time IS DISTINCT FROM source_frontier THEN
        RAISE EXCEPTION 'M34_SAMPLED_TIME: comparison must use the current authoritative frontier %',
            source_frontier;
    END IF;
    IF proposed IS NULL THEN
        RAISE EXCEPTION 'M34_INVALID_DECLARATION: proposed declaration is required';
    END IF;
    IF target_kind IS NULL OR target_name IS NULL THEN
        RAISE EXCEPTION 'M34_TARGET_NOT_FOUND: deployed target kind and name are required';
    END IF;
    IF (proposed).kind IS DISTINCT FROM target_kind THEN
        RAISE EXCEPTION 'M34_TARGET_KIND: proposed and deployed kinds must match';
    END IF;
    IF (proposed).name IS DISTINCT FROM target_name THEN
        RAISE EXCEPTION 'M34_TARGET_NAME: proposed declaration name must match deployed target name';
    END IF;
    validation := pgreact.validate(proposed);
    IF validation ->> 'state' = 'attention' THEN
        RETURN jsonb_build_object(
            'contract_version', 21,
            'operation', 'compare',
            'target', jsonb_build_object(
                'kind', target_kind, 'name', target_name, 'version', target_version),
            'state', 'attention',
            'summary', jsonb_build_object('read_only', true),
            'findings', validation -> 'findings',
            'current', '[]'::jsonb,
            'proposed', '[]'::jsonb,
            'delta', '[]'::jsonb,
            'lifecycle', '[]'::jsonb,
            'work', '[]'::jsonb,
            'truncated', false);
    END IF;
    proposed_normalized := COALESCE(
        validation -> 'evidence' -> 'normalized_declaration',
        pgreact_internal.m28_normalize(proposed));

    IF target_kind = 'policy_set' THEN
        SELECT version.normalized, set.owner_oid
        INTO current_normalized, current_owner
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE set.set_name = target_name
          AND version.state = 'DEPLOYED'
          AND version.valid_from <= source_frontier
          AND (version.valid_to IS NULL OR source_frontier < version.valid_to)
          AND (target_version IS NULL OR version.version = target_version)
        ORDER BY version.valid_from DESC, version.created_at DESC
        LIMIT 1;
    ELSE
        SELECT row_data.normalized, row_data.owner_oid
        INTO current_normalized, current_owner
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
        IF current_normalized IS NULL THEN
            RAISE EXCEPTION 'M34_TARGET_NOT_FOUND: deployed % % was not found',
                target_kind, target_name;
        END IF;
        IF target_version IS NOT NULL AND target_version <> '1' THEN
            RAISE EXCEPTION 'M34_TARGET_VERSION: only the deployed declaration version 1 is supported';
        END IF;
    END IF;
    IF current_normalized IS NULL THEN
        RAISE EXCEPTION 'M34_TARGET_NOT_FOUND: deployed % % was not found',
            target_kind, target_name;
    END IF;
    IF NOT pg_has_role(session_user, current_owner, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin()
       AND NOT EXISTS (
           SELECT 1
           FROM pgreact_internal.application_roles role_row
           WHERE role_row.role_kind = 'reader'
             AND pg_has_role(session_user, role_row.role_oid, 'member')) THEN
        RAISE EXCEPTION 'M34_UNAUTHORIZED_TARGET: caller is not allowed to inspect %', target_name;
    END IF;
    current_checksum := pgreact_internal.m34_authoritative_checksum();

    IF target_kind = 'rule' THEN
        relation_name := proposed_normalized -> 'spec' ->> 'condition';
        source_oid := to_regclass(relation_name);
        PERFORM pgreact_internal.m34_require_source(source_oid, relation_name);
        key_column := (proposed_normalized -> 'spec' ->> 'semantic_key')::name;
        proposed_model := pgreact_internal.m34_rule_rows(
            source_oid, key_column, relation_name, evidence_limit);
        SELECT row_data.source_view_oid, row_data.key_column
        INTO source_oid, key_column
        FROM pgreact_internal.rule_versions row_data
        JOIN pgreact_internal.rules rule USING (rule_id)
        WHERE rule.rule_name = target_name
          AND row_data.state <> 'REMOVED'
        ORDER BY row_data.created_at DESC
        LIMIT 1;
        PERFORM pgreact_internal.m34_require_source(source_oid, source_oid::regclass::text);
        current_model := pgreact_internal.m34_current_rule_rows(target_name, evidence_limit);
    ELSIF target_kind = 'decision_program' THEN
        relation_name := proposed_normalized -> 'spec' ->> 'candidate_relation';
        source_oid := to_regclass(relation_name);
        PERFORM pgreact_internal.m34_require_source(source_oid, relation_name);
        subject_column := (proposed_normalized -> 'spec' ->> 'subject_key')::name;
        candidate_column := (proposed_normalized -> 'spec' ->> 'candidate_key')::name;
        priority_column := (proposed_normalized -> 'spec' ->> 'priority')::name;
        SELECT array_agg(value::name ORDER BY ordinal)
        INTO result_columns
        FROM jsonb_array_elements_text(proposed_normalized -> 'spec' -> 'results')
             WITH ORDINALITY item(value, ordinal);
        max_candidates := COALESCE(
            (proposed_normalized -> 'spec' ->> 'max_candidates')::integer, 1000);
        proposed_model := pgreact_internal.m34_decision_rows(
            source_oid, subject_column, candidate_column, priority_column,
            result_columns, max_candidates, relation_name, evidence_limit);
        SELECT version.candidate_relation_oid
        INTO source_oid
        FROM pgreact_internal.decision_program_versions version
        JOIN pgreact_internal.decision_programs program USING (program_id)
        WHERE program.program_name = target_name
          AND version.state = 'DEPLOYED'
        ORDER BY version.valid_from DESC, version.version_no DESC
        LIMIT 1;
        PERFORM pgreact_internal.m34_require_source(source_oid, source_oid::regclass::text);
        current_model := pgreact_internal.m34_current_decision_rows(target_name, evidence_limit);
        SELECT count(*) INTO missing_count
        FROM jsonb_array_elements(current_model -> 'rows') current_row
        WHERE NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
            WHERE proposed_row.value ->> 'subject_key' =
                  current_row.value ->> 'subject_key');
        IF missing_count > 0 THEN
            SELECT COALESCE(jsonb_agg(row_data ORDER BY row_data ->> 'subject_key'), '[]'::jsonb)
            INTO proposed_rows
            FROM (
                SELECT proposed_row.value AS row_data
                FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
                UNION ALL
                SELECT jsonb_build_object(
                           'subject_key', current_row.value ->> 'subject_key',
                           'result_key', NULL,
                           'state', 'NO_CANDIDATE',
                           'value', jsonb_build_object(
                               'candidate', NULL,
                               'priority', NULL,
                               'result', NULL,
                               'claimable', false),
                           'work', jsonb_build_object('would_be_work', false),
                           'evidence', jsonb_build_object(
                               'source', 'pgreact.decision_winners',
                               'complete', true))
                FROM jsonb_array_elements(current_model -> 'rows') current_row
                WHERE NOT EXISTS (
                    SELECT 1
                    FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
                    WHERE proposed_row.value ->> 'subject_key' =
                          current_row.value ->> 'subject_key')
            ) rows;
            proposed_model := jsonb_build_object(
                'rows', proposed_rows,
                'rows_considered',
                    (proposed_model ->> 'rows_considered')::bigint + missing_count,
                'truncated',
                    COALESCE((proposed_model ->> 'truncated')::boolean, false)
                    OR ((
                        proposed_model ->> 'rows_considered')::bigint + missing_count
                        > evidence_limit));
        END IF;
    ELSIF target_kind = 'policy_set' THEN
        proposed_model := pgreact_internal.m34_policy_rows(
            current_normalized, proposed_normalized, target_name, evidence_limit) -> 'proposed';
        current_model := pgreact_internal.m34_policy_rows(
            current_normalized, proposed_normalized, target_name, evidence_limit) -> 'current';
    ELSE
        RAISE EXCEPTION 'M34_UNSUPPORTED_KIND: comparison does not approximate %', target_kind;
    END IF;

    current_rows := current_model -> 'rows';
    proposed_rows := proposed_model -> 'rows';
    delta_model := pgreact_internal.m34_delta(current_rows, proposed_rows);
    delta_rows := delta_model -> 'rows';
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
    INTO lifecycle_rows
    FROM jsonb_array_elements(delta_rows) item(value)
    WHERE item.value ->> 'change' <> 'UNCHANGED';
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
    INTO work_rows
    FROM jsonb_array_elements(proposed_rows) item(value)
    WHERE (item.value -> 'work' ->> 'would_be_work')::boolean;
    comparison_complete := NOT COALESCE((current_model ->> 'truncated')::boolean, false)
        AND NOT COALESCE((proposed_model ->> 'truncated')::boolean, false)
        AND jsonb_array_length(delta_rows) <= evidence_limit;
    after_checksum := pgreact_internal.m34_authoritative_checksum();
    IF current_checksum IS DISTINCT FROM after_checksum THEN
        RAISE EXCEPTION 'M34_AUTHORITATIVE_CHANGED: authoritative state changed during comparison';
    END IF;
    current_count := (current_model ->> 'rows_considered')::bigint;
    proposed_count := (proposed_model ->> 'rows_considered')::bigint;
    RETURN jsonb_build_object(
        'contract_version', 21,
        'operation', 'compare',
        'target', jsonb_build_object(
            'kind', target_kind, 'name', target_name, 'version', target_version),
        'state', CASE WHEN comparison_complete THEN 'ready' ELSE 'partial' END,
        'summary', jsonb_build_object(
            'read_only', true,
            'current_count', current_count,
            'proposed_count', proposed_count,
            'delta_counts', CASE WHEN comparison_complete
                THEN delta_model -> 'counts' ELSE NULL END,
            'counts_exact', comparison_complete,
            'affected_subject_count', CASE WHEN comparison_complete THEN
                COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0)
                ELSE NULL END,
            'would_be_work', COALESCE((
                SELECT count(*)
                FROM jsonb_array_elements(proposed_rows) item
                WHERE (item.value -> 'work' ->> 'would_be_work')::boolean), 0)),
        'evidence', jsonb_build_object(
            'sampled_time', sampled_time,
            'source_frontier', source_frontier,
            'applicability_snapshot', CASE WHEN target_kind = 'policy_set'
                THEN proposed_normalized -> 'spec' -> 'applicability' ELSE NULL END,
            'declaration_digest', encode(
                sha256(convert_to(proposed_normalized::text, 'UTF8')), 'hex'),
            'authoritative_checksum_before', current_checksum,
            'authoritative_checksum_after', after_checksum,
            'complete', comparison_complete,
            'evidence_limit', evidence_limit),
        'cost', jsonb_build_object(
            'rows_considered', current_count + proposed_count,
            'affected_subjects', CASE WHEN comparison_complete THEN
                COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0)
                ELSE NULL END,
            'dependency_fan_out', 0,
            'reevaluation', 0,
            'cascade_depth', 0,
            'would_be_work', COALESCE((
                SELECT count(*)
                FROM jsonb_array_elements(proposed_rows) item
                WHERE (item.value -> 'work' ->> 'would_be_work')::boolean), 0),
            'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000,
            'memory_bytes', NULL,
            'temporary_storage_bytes', 0),
        'findings', CASE WHEN comparison_complete THEN
            jsonb_build_array(pgreact_internal.m34_finding(
                'M34_NO_EFFECT', 'INFO', target_name, '<comparison>',
                'comparison completed without changing authoritative state',
                'No deployment or run is required to inspect this result.'))
            ELSE jsonb_build_array(pgreact_internal.m34_finding(
                'M34_COMPARISON_INCOMPLETE', 'WARNING', target_name, '<comparison>',
                'evidence was truncated at the requested limit',
                'Increase evidence_limit or inspect the relational result stream.'))
            END,
        'current', pgreact_internal.m34_raw_rows(
            current_rows, current_count, evidence_limit) -> 'rows',
        'proposed', pgreact_internal.m34_raw_rows(
            proposed_rows, proposed_count, evidence_limit) -> 'rows',
        'delta', pgreact_internal.m34_raw_rows(
            delta_rows,
            jsonb_array_length(delta_rows),
            evidence_limit) -> 'rows',
        'lifecycle', pgreact_internal.m34_raw_rows(
            lifecycle_rows,
            jsonb_array_length(lifecycle_rows),
            evidence_limit) -> 'rows',
        'work', pgreact_internal.m34_raw_rows(
            work_rows,
            jsonb_array_length(work_rows),
            evidence_limit) -> 'rows',
        'truncated', NOT comparison_complete);
END
$m34$;

CREATE OR REPLACE FUNCTION pgreact.compare(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    options jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
    SELECT pgreact_internal.m34_compare($1, $2, $3)
$m34$;

CREATE OR REPLACE FUNCTION pgreact.compare_results(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    options jsonb DEFAULT '{}'::jsonb
)
RETURNS TABLE(
    result_set text,
    kind text,
    name text,
    subject_key text,
    result_key text,
    state text,
    delta text,
    current_value jsonb,
    proposed_value jsonb,
    evidence jsonb,
    complete boolean,
    sampled_time timestamptz,
    source_frontier timestamptz,
    declaration_digest text
)
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m34$
WITH comparison AS (
    SELECT pgreact.compare($1, $2, $3) AS value
), rows AS (
    SELECT 'current'::text AS result_set, item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'current') item(value)
    UNION ALL
    SELECT 'proposed', item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'proposed') item(value)
    UNION ALL
    SELECT 'delta', item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'delta') item(value)
    UNION ALL
    SELECT 'lifecycle', item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'lifecycle') item(value)
    UNION ALL
    SELECT 'work', item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'work') item(value)
)
SELECT result_set,
       comparison.value -> 'target' ->> 'kind',
       comparison.value -> 'target' ->> 'name',
       rows.value ->> 'subject_key',
       rows.value ->> 'result_key',
       rows.value ->> 'state',
       rows.value ->> 'change',
       rows.value -> 'current_value',
       rows.value -> 'proposed_value',
       rows.value -> 'evidence',
       (comparison.value -> 'evidence' ->> 'complete')::boolean,
       (comparison.value -> 'evidence' ->> 'sampled_time')::timestamptz,
       (comparison.value -> 'evidence' ->> 'source_frontier')::timestamptz,
       comparison.value -> 'evidence' ->> 'declaration_digest'
FROM comparison
JOIN rows ON true
$m34$;

REVOKE ALL ON FUNCTION pgreact_internal.m34_finding(text, text, text, text, text, text, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_finding_registry() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_authoritative_checksum() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_require_source(oid, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_raw_rows(jsonb, bigint, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_rule_rows(oid, name, text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_current_rule_rows(text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_decision_rows(oid, name, name, name, name[], integer, text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_current_decision_rows(text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_policy_rows(jsonb, jsonb, text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_delta(jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m34_compare(pgreact_api.declaration, pgreact_api.target, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact.compare(pgreact_api.declaration, pgreact_api.target, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact.compare_results(pgreact_api.declaration, pgreact_api.target, jsonb) FROM PUBLIC;

DO $m34$
DECLARE role_row record;
BEGIN
    FOR role_row IN
        SELECT role_oid::regrole AS role_name
        FROM pgreact_internal.application_roles
        WHERE role_kind IN ('author', 'operator', 'reader')
    LOOP
        EXECUTE format(
            'GRANT EXECUTE ON FUNCTION pgreact.compare(pgreact_api.declaration, pgreact_api.target, jsonb), '
            'pgreact.compare_results(pgreact_api.declaration, pgreact_api.target, jsonb) TO %I',
            role_row.role_name::text);
    END LOOP;
END
$m34$;

COMMENT ON FUNCTION pgreact.compare(pgreact_api.declaration, pgreact_api.target, jsonb) IS
    'M34 bounded read-only comparison of a proposed declaration with one deployed target';
COMMENT ON FUNCTION pgreact.compare_results(pgreact_api.declaration, pgreact_api.target, jsonb) IS
    'M34 relational current, proposed, and delta rows for a read-only comparison';
COMMENT ON EXTENSION pg_react IS
    'M34 deployment-impact simulation: bounded read-only comparison over current authoritative state';

-- M35 read-only hypothetical row-change comparison over the M34 evaluator.

CREATE OR REPLACE FUNCTION pgreact_internal.m35_finding(
    code text,
    severity text,
    target text,
    field text,
    message text,
    hint text,
    details jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
STRICT
AS $m35$
    SELECT jsonb_build_object(
        'code', $1,
        'severity', $2,
        'blocking', $2 = 'ERROR',
        'target', $3,
        'field', $4,
        'message', $5,
        'hint', $6,
        'details', COALESCE($7, '{}'::jsonb))
$m35$;

CREATE OR REPLACE FUNCTION pgreact_internal.m35_finding_registry()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
    SELECT jsonb_build_object(
        'schema_version', 1,
        'milestone', 'M35',
        'finding_shape', jsonb_build_array(
            'code', 'severity', 'blocking', 'target',
            'field', 'message', 'hint', 'details'),
        'severity', jsonb_build_array('ERROR', 'WARNING', 'INFO'),
        'codes', jsonb_build_array(
            jsonb_build_object('code', 'M35_CHANGE_SET_INVALID', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_REQUIRED_FIELD', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_UNKNOWN_FIELD', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_RELATION', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_OPERATION', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_ORDINAL', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_DUPLICATE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_CONFLICT', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_KEY', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_ROW', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_CHANGE_STALE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_UNAUTHORIZED_SOURCE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_RLS_UNSUPPORTED', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_UNSUPPORTED_SOURCE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_RESOURCE_LIMIT', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_AUTHORITATIVE_CHANGED', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M35_COMPARISON_INCOMPLETE', 'severity', 'WARNING'),
            jsonb_build_object('code', 'M35_NO_EFFECT', 'severity', 'INFO')))
$m35$;

CREATE OR REPLACE FUNCTION pgreact_internal.m35_require_source(
    source_oid oid,
    source_name text
)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
-- ponytail: direct tables and one bigint key keep simulation bounded; add
-- typed composite-key and view adapters only with a new evidence-backed contract.
DECLARE relation_kind "char";
    rls_enabled boolean;
BEGIN
    IF source_oid IS NULL THEN
        RAISE EXCEPTION 'M35_CHANGE_RELATION: source relation % no longer exists', source_name;
    END IF;
    SELECT relkind, relrowsecurity
    INTO relation_kind, rls_enabled
    FROM pg_class
    WHERE oid = source_oid;
    IF relation_kind NOT IN ('r', 'p') THEN
        RAISE EXCEPTION 'M35_UNSUPPORTED_SOURCE: source relation % must be a table', source_name;
    END IF;
    IF rls_enabled THEN
        RAISE EXCEPTION 'M35_RLS_UNSUPPORTED: source relation % uses row-level security', source_name;
    END IF;
    IF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
        RAISE EXCEPTION 'M35_UNAUTHORIZED_SOURCE: caller lacks SELECT on source relation %', source_name;
    END IF;
END
$m35$;

CREATE OR REPLACE FUNCTION pgreact_internal.m35_source_checksum(
    source_oid oid,
    key_column name
)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
DECLARE checksum text;
BEGIN
    EXECUTE format(
        'SELECT encode(sha256(convert_to(COALESCE(
             (SELECT jsonb_agg(to_jsonb(s) ORDER BY s.%1$I, to_jsonb(s)::text)::text
                FROM %2$s s), ''[]''), ''UTF8'')), ''hex'')',
        key_column, source_oid::regclass)
    INTO checksum;
    RETURN checksum;
END
$m35$;

CREATE OR REPLACE FUNCTION pgreact_internal.m35_check_image(
    source_oid oid,
    image jsonb,
    image_name text
)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
DECLARE expected_count bigint;
    actual_count bigint;
    unknown_field text;
    missing_field text;
    converted jsonb;
BEGIN
    IF jsonb_typeof(image) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M35_CHANGE_ROW: % must be a complete JSON object', image_name;
    END IF;
    SELECT count(*) INTO expected_count
    FROM pg_attribute
    WHERE attrelid = source_oid AND attnum > 0 AND NOT attisdropped;
    SELECT count(*) INTO actual_count FROM jsonb_object_keys(image);
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(image) AS key
    WHERE NOT EXISTS (
        SELECT 1 FROM pg_attribute
        WHERE attrelid = source_oid AND attnum > 0 AND NOT attisdropped
          AND attname = key)
    ORDER BY key
    LIMIT 1;
    SELECT a.attname INTO missing_field
    FROM pg_attribute a
    WHERE a.attrelid = source_oid AND a.attnum > 0 AND NOT a.attisdropped
      AND NOT (image ? a.attname)
    ORDER BY a.attnum
    LIMIT 1;
    IF actual_count IS DISTINCT FROM expected_count OR unknown_field IS NOT NULL
       OR missing_field IS NOT NULL THEN
        RAISE EXCEPTION 'M35_CHANGE_ROW: % must contain exactly the source columns', image_name;
    END IF;
    BEGIN
        EXECUTE format(
            'SELECT to_jsonb(jsonb_populate_record(NULL::%s, $1))',
            source_oid::regclass)
        INTO converted
        USING image;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'M35_CHANGE_ROW: % does not match the source column types', image_name;
    END;
END
$m35$;

CREATE OR REPLACE FUNCTION pgreact_internal.m35_apply_changes(
    source_oid oid,
    key_column name,
    change_set jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
DECLARE rows jsonb;
    item jsonb;
    operation text;
    key_text text;
    existing jsonb;
    row_count bigint;
    duplicate_count bigint;
    null_count bigint;
    unknown_field text;
    key_type regtype;
BEGIN
    PERFORM pgreact_internal.m35_require_source(source_oid, source_oid::regclass::text);
    IF jsonb_typeof(change_set) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: change_set must be a JSON array';
    END IF;
    SELECT a.atttypid::regtype INTO key_type
    FROM pg_attribute a
    WHERE a.attrelid = source_oid AND a.attname = key_column
      AND a.attnum > 0 AND NOT a.attisdropped;
    IF key_type IS DISTINCT FROM 'bigint'::regtype THEN
        RAISE EXCEPTION 'M35_CHANGE_KEY: identity column % must be bigint', key_column;
    END IF;
    EXECUTE format('SELECT count(*) FROM %s WHERE %I IS NULL', source_oid::regclass, key_column)
    INTO null_count;
    IF null_count > 0 THEN
        RAISE EXCEPTION 'M35_CHANGE_KEY: source relation contains null identities';
    END IF;
    EXECUTE format(
        'SELECT count(*) FROM (SELECT %1$I FROM %2$s GROUP BY %1$I HAVING count(*) > 1) d',
        key_column, source_oid::regclass)
    INTO duplicate_count;
    IF duplicate_count > 0 THEN
        RAISE EXCEPTION 'M35_CHANGE_DUPLICATE: source relation contains duplicate identities';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'object'
           OR NOT (item.value ?& ARRAY['relation', 'operation', 'ordinal', 'key', 'before', 'after'])
           OR (SELECT count(*) FROM jsonb_object_keys(item.value)) <> 6
    ) THEN
        RAISE EXCEPTION 'M35_CHANGE_REQUIRED_FIELD: every change must contain relation, operation, ordinal, key, before, and after';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_array_elements(change_set) item(value),
         jsonb_object_keys(item.value) AS key
    WHERE key NOT IN ('relation', 'operation', 'ordinal', 'key', 'before', 'after')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M35_CHANGE_UNKNOWN_FIELD: change field % is not supported', unknown_field;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        WHERE jsonb_typeof(item.value -> 'ordinal') IS DISTINCT FROM 'number'
           OR item.value ->> 'ordinal' !~ '^[1-9][0-9]*$'
    ) THEN
        RAISE EXCEPTION 'M35_CHANGE_ORDINAL: ordinals must be positive integers';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        GROUP BY (item.value ->> 'ordinal')::bigint
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'M35_CHANGE_DUPLICATE: ordinals must be unique';
    END IF;
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.%1$I), ''[]''::jsonb)
         FROM %2$s s', key_column, source_oid::regclass)
    INTO rows;
    FOR item IN
        SELECT value
        FROM jsonb_array_elements(change_set) AS change(value)
        ORDER BY (value ->> 'ordinal')::bigint
    LOOP
        IF to_regclass(item ->> 'relation') IS DISTINCT FROM source_oid THEN
            RAISE EXCEPTION 'M35_CHANGE_RELATION: change relation % does not match %',
                item ->> 'relation', source_oid::regclass;
        END IF;
        operation := item ->> 'operation';
        IF operation IS NULL OR operation NOT IN ('INSERT', 'UPDATE', 'DELETE') THEN
            RAISE EXCEPTION 'M35_CHANGE_OPERATION: operation % is not supported', operation;
        END IF;
        IF jsonb_typeof(item -> 'key') IS DISTINCT FROM 'object'
           OR (SELECT count(*) FROM jsonb_object_keys(item -> 'key')) <> 1
           OR NOT (item -> 'key' ? key_column::text)
           OR jsonb_typeof(item -> 'key' -> key_column::text) IS DISTINCT FROM 'number'
           OR item -> 'key' ->> key_column::text !~ '^-?[0-9]+$' THEN
            RAISE EXCEPTION 'M35_CHANGE_KEY: key must contain one integer % value', key_column;
        END IF;
        key_text := item -> 'key' ->> key_column::text;
        IF operation = 'INSERT' THEN
            IF jsonb_typeof(item -> 'before') IS DISTINCT FROM 'null'
               OR jsonb_typeof(item -> 'after') IS DISTINCT FROM 'object' THEN
                RAISE EXCEPTION 'M35_CHANGE_ROW: INSERT requires a null before image and an after image';
            END IF;
            PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'after', 'after');
            IF item -> 'after' ->> key_column::text IS DISTINCT FROM key_text THEN
                RAISE EXCEPTION 'M35_CHANGE_KEY: INSERT key does not match its after image';
            END IF;
            SELECT count(*) INTO row_count
            FROM jsonb_array_elements(rows) current_row(value)
            WHERE current_row.value ->> key_column::text = key_text;
            IF row_count > 0 THEN
                RAISE EXCEPTION 'M35_CHANGE_CONFLICT: INSERT identity % already exists', key_text;
            END IF;
            rows := rows || jsonb_build_array(item -> 'after');
        ELSE
            IF jsonb_typeof(item -> 'before') IS DISTINCT FROM 'object'
               OR jsonb_typeof(item -> 'after') IS DISTINCT FROM
                  (CASE WHEN operation = 'UPDATE' THEN 'object' ELSE 'null' END) THEN
                RAISE EXCEPTION 'M35_CHANGE_ROW: % requires the correct before and after images', operation;
            END IF;
            PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'before', 'before');
            IF operation = 'UPDATE' THEN
                PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'after', 'after');
                IF item -> 'after' ->> key_column::text IS DISTINCT FROM key_text THEN
                    RAISE EXCEPTION 'M35_CHANGE_KEY: UPDATE cannot change its identity';
                END IF;
            END IF;
            SELECT count(*), (array_agg(current_row.value))[1]
            INTO row_count, existing
            FROM jsonb_array_elements(rows) current_row(value)
            WHERE current_row.value ->> key_column::text = key_text;
            IF row_count = 0 THEN
                RAISE EXCEPTION 'M35_CHANGE_STALE: identity % is not present', key_text;
            ELSIF row_count > 1 THEN
                RAISE EXCEPTION 'M35_CHANGE_DUPLICATE: identity % is ambiguous', key_text;
            ELSIF existing IS DISTINCT FROM item -> 'before' THEN
                RAISE EXCEPTION 'M35_CHANGE_STALE: before image for identity % is stale', key_text;
            END IF;
            SELECT COALESCE(jsonb_agg(
                       CASE WHEN current_row.value ->> key_column::text = key_text
                            THEN CASE WHEN operation = 'UPDATE'
                                      THEN item -> 'after' ELSE NULL END
                            ELSE current_row.value END
                       ORDER BY current_row.ordinality), '[]'::jsonb)
            INTO rows
            FROM jsonb_array_elements(rows) WITH ORDINALITY current_row(value, ordinality)
            WHERE NOT (operation = 'DELETE'
                       AND current_row.value ->> key_column::text = key_text);
        END IF;
    END LOOP;
    RETURN rows;
END
$m35$;

CREATE OR REPLACE FUNCTION pgreact_internal.m35_rule_rows(
    rows jsonb,
    key_column name,
    source_label text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
SELECT jsonb_build_object(
    'rows', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
                   'subject_key', item.value ->> $2,
                   'result_key', item.value ->> $2,
                   'state', 'MATCH',
                   'value', item.value,
                   'work', jsonb_build_object('would_be_work', true),
                   'evidence', jsonb_build_object(
                       'source', $3, 'hypothetical', true, 'complete', true))
                   ORDER BY (item.value ->> $2)::bigint)
        FROM (
            SELECT value
            FROM jsonb_array_elements($1) item(value)
            ORDER BY (item.value ->> $2)::bigint
            LIMIT $4
        ) item), '[]'::jsonb),
    'rows_considered', jsonb_array_length($1),
    'truncated', jsonb_array_length($1) > $4)
$m35$;

CREATE OR REPLACE FUNCTION pgreact_internal.m35_decision_rows(
    rows jsonb,
    subject_column name,
    candidate_column name,
    priority_column name,
    result_columns name[],
    max_candidates integer,
    source_label text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
DECLARE total_count bigint;
    duplicate_count bigint;
    over_limit_count bigint;
    result_rows jsonb;
BEGIN
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(rows) item(value)
        WHERE item.value ->> subject_column::text IS NULL
           OR item.value ->> candidate_column::text IS NULL
           OR item.value ->> priority_column::text IS NULL
    ) THEN
        RAISE EXCEPTION 'M35_CHANGE_ROW: decision rows require subject, candidate, and priority values';
    END IF;
    SELECT count(*) INTO duplicate_count
    FROM (
        SELECT item.value ->> subject_column::text, item.value ->> candidate_column::text
        FROM jsonb_array_elements(rows) item(value)
        GROUP BY item.value ->> subject_column::text, item.value ->> candidate_column::text
        HAVING count(*) > 1
    ) duplicates;
    IF duplicate_count > 0 THEN
        RAISE EXCEPTION 'M35_CHANGE_DUPLICATE: decision source contains duplicate candidates';
    END IF;
    SELECT count(*) INTO over_limit_count
    FROM (
        SELECT item.value ->> subject_column::text
        FROM jsonb_array_elements(rows) item(value)
        GROUP BY item.value ->> subject_column::text
        HAVING count(*) > max_candidates
    ) over_limit;
    IF over_limit_count > 0 THEN
        RAISE EXCEPTION 'M35_RESOURCE_LIMIT: decision source exceeds max_candidates';
    END IF;
    SELECT count(DISTINCT (item.value ->> subject_column::text)::bigint)
    INTO total_count
    FROM jsonb_array_elements(rows) item(value);
    WITH candidates AS (
        SELECT item.value AS row_data,
               (item.value ->> subject_column::text)::bigint AS subject_key,
               (item.value ->> candidate_column::text)::bigint AS candidate_key,
               (item.value ->> priority_column::text)::bigint AS priority
        FROM jsonb_array_elements(rows) item(value)
    ), ranked AS (
        SELECT candidates.*, min(priority) OVER (PARTITION BY subject_key) AS best_priority
        FROM candidates
    ), grouped AS (
        SELECT subject_key,
               min(priority) AS best_priority,
               count(*) AS candidate_count,
               count(*) FILTER (WHERE priority = best_priority) AS top_count,
               min(candidate_key) FILTER (WHERE priority = best_priority) AS winner_candidate,
               (array_agg(row_data ORDER BY candidate_key)
                   FILTER (WHERE priority = best_priority))[1] AS winner_row,
               jsonb_agg(jsonb_build_object(
                   'candidate', candidate_key::text,
                   'priority', priority,
                   'value', row_data) ORDER BY candidate_key) AS competitors
        FROM ranked
        GROUP BY subject_key
    ), limited AS (
        SELECT * FROM grouped ORDER BY subject_key LIMIT evidence_limit
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'subject_key', subject_key::text,
               'result_key', CASE WHEN top_count = 1 THEN winner_candidate::text END,
               'state', CASE WHEN top_count = 1 THEN 'WINNER' ELSE 'AMBIGUOUS' END,
               'value', jsonb_build_object(
                   'candidate', CASE WHEN top_count = 1 THEN winner_candidate END,
                   'priority', best_priority,
                   'result', CASE WHEN top_count = 1
                                  THEN pgreact_internal.decision_result(winner_row, result_columns)
                             END,
                   'claimable', top_count = 1),
               'work', jsonb_build_object('would_be_work', top_count = 1),
               'evidence', jsonb_build_object(
                   'source', source_label,
                   'candidate_count', candidate_count,
                   'competitors', competitors,
                   'hypothetical', true,
                   'complete', true)) ORDER BY subject_key), '[]'::jsonb)
    INTO result_rows
    FROM limited;
    RETURN jsonb_build_object(
        'rows', result_rows,
        'rows_considered', total_count,
        'truncated', total_count > evidence_limit);
END
$m35$;

CREATE OR REPLACE FUNCTION pgreact_internal.m35_policy_subject_rows(
    rows jsonb,
    key_column name,
    source_label text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
WITH subjects AS (
    SELECT DISTINCT (item.value ->> $2)::bigint AS subject_key
    FROM jsonb_array_elements($1) item(value)
), limited AS (
    SELECT subject_key
    FROM subjects
    ORDER BY subject_key
    LIMIT $4
)
SELECT jsonb_build_object(
    'rows', COALESCE(jsonb_agg(jsonb_build_object(
        'subject_key', 'subject:' || encode(
            pgreact_internal.m30_key_identity(
                ARRAY['bigint']::text[], jsonb_build_array(subject_key)), 'hex'),
        'result_key', 'subject:' || encode(
            pgreact_internal.m30_key_identity(
                ARRAY['bigint']::text[], jsonb_build_array(subject_key)), 'hex'),
        'state', 'ELIGIBLE',
        'value', jsonb_build_array(subject_key),
        'work', jsonb_build_object('would_be_work', false),
        'evidence', jsonb_build_object(
            'source', $3, 'hypothetical', true, 'complete', true))
        ORDER BY subject_key), '[]'::jsonb),
    'rows_considered', (SELECT count(*) FROM subjects),
    'truncated', (SELECT count(*) FROM subjects) > $4)
FROM limited
$m35$;

CREATE OR REPLACE FUNCTION pgreact_internal.m35_compare(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    change_set jsonb,
    options jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
DECLARE effective_proposed pgreact_api.declaration;
    proposed_normalized jsonb;
    base jsonb;
    base_options jsonb;
    source_oid oid;
    source_label text;
    key_column name;
    target_kind text := (deployed).kind;
    target_name text := (deployed).name;
    target_version text := (deployed).version;
    evidence_limit integer := 100;
    max_changes integer := 1000;
    source_frontier timestamptz;
    sampled_time timestamptz;
    started_at timestamptz := clock_timestamp();
    source_checksum_before text;
    source_checksum_after text;
    authoritative_checksum_before text;
    authoritative_checksum_after text;
    source_rows jsonb;
    current_rows jsonb;
    proposed_rows jsonb;
    delta_rows jsonb;
    lifecycle_rows jsonb;
    work_rows jsonb;
    proposed_model jsonb;
    delta_model jsonb;
    current_count bigint;
    proposed_count bigint;
    missing_count bigint := 0;
    comparison_complete boolean;
    change_set_digest text;
    member_rows jsonb;
    subject_model jsonb;
    member_count bigint := 0;
    subject_count bigint := 0;
    key_names name[];
    result_columns name[];
    max_candidates integer;
BEGIN
    target_kind := (deployed).kind;
    target_name := (deployed).name;
    target_version := (deployed).version;
    effective_proposed := proposed;
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: options must be a JSON object';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_object_keys(options) AS key
        WHERE key NOT IN ('evidence_limit', 'sampled_time', 'max_changes')
    ) THEN
        RAISE EXCEPTION 'M35_CHANGE_UNKNOWN_FIELD: unsupported comparison option';
    END IF;
    IF options ? 'evidence_limit' THEN
        IF jsonb_typeof(options -> 'evidence_limit') IS DISTINCT FROM 'number'
           OR options ->> 'evidence_limit' !~ '^[1-9][0-9]*$'
           OR (options ->> 'evidence_limit')::integer > 1000 THEN
            RAISE EXCEPTION 'M35_RESOURCE_LIMIT: evidence_limit must be between 1 and 1000';
        END IF;
        evidence_limit := (options ->> 'evidence_limit')::integer;
    END IF;
    IF options ? 'max_changes' THEN
        IF jsonb_typeof(options -> 'max_changes') IS DISTINCT FROM 'number'
           OR options ->> 'max_changes' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_changes')::integer > 1000 THEN
            RAISE EXCEPTION 'M35_RESOURCE_LIMIT: max_changes must be between 1 and 1000';
        END IF;
        max_changes := (options ->> 'max_changes')::integer;
    END IF;
    IF jsonb_typeof(change_set) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: change_set must be a JSON array';
    END IF;
    IF jsonb_array_length(change_set) > max_changes THEN
        RAISE EXCEPTION 'M35_RESOURCE_LIMIT: change_set exceeds max_changes';
    END IF;
    IF options ? 'sampled_time'
       AND jsonb_typeof(options -> 'sampled_time') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: sampled_time must be an RFC3339 timestamp string';
    END IF;
    IF effective_proposed IS NULL THEN
        SELECT ROW(row_data.api_version, row_data.kind, row_data.object_name,
                   row_data.spec)::pgreact_api.declaration
        INTO effective_proposed
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
        SELECT row_data.normalized INTO proposed_normalized
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
        IF effective_proposed IS NULL THEN
            RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: deployed declaration is required';
        END IF;
    ELSE
        proposed_normalized := pgreact_internal.m28_normalize(effective_proposed);
    END IF;
    IF target_kind NOT IN ('rule', 'decision_program', 'policy_set') THEN
        RAISE EXCEPTION 'M35_UNSUPPORTED_SOURCE: target kind % is not supported', target_kind;
    END IF;
    IF (effective_proposed).kind IS DISTINCT FROM target_kind
       OR (effective_proposed).name IS DISTINCT FROM target_name THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: proposed and deployed targets must match';
    END IF;
    IF target_kind = 'rule' THEN
        source_label := proposed_normalized -> 'spec' ->> 'condition';
        key_column := (proposed_normalized -> 'spec' ->> 'semantic_key')::name;
    ELSIF target_kind = 'decision_program' THEN
        source_label := proposed_normalized -> 'spec' ->> 'candidate_relation';
        key_column := (proposed_normalized -> 'spec' ->> 'candidate_key')::name;
    ELSE
        source_label := proposed_normalized -> 'spec' -> 'applicability' ->> 'relation';
        SELECT array_agg(value::name ORDER BY ordinal)
        INTO key_names
        FROM jsonb_array_elements_text(
                 proposed_normalized -> 'spec' -> 'applicability' -> 'subject_keys')
             WITH ORDINALITY requested(value, ordinal);
        IF cardinality(key_names) IS DISTINCT FROM 1 THEN
            RAISE EXCEPTION 'M35_UNSUPPORTED_SOURCE: M35 requires one bigint policy subject key';
        END IF;
        key_column := key_names[1];
    END IF;
    source_oid := to_regclass(source_label);
    PERFORM pgreact_internal.m35_require_source(source_oid, source_label);
    source_checksum_before := pgreact_internal.m35_source_checksum(source_oid, key_column);
    base_options := options - 'max_changes';
    base := pgreact.compare(effective_proposed, deployed, base_options);
    IF base ->> 'state' = 'attention' THEN
        RETURN base || jsonb_build_object(
            'contract_version', 22,
            'simulation', 'hypothetical_fact_changes',
            'change_set_digest', encode(
                sha256(convert_to(change_set::text, 'UTF8')), 'hex'));
    END IF;
    source_rows := pgreact_internal.m35_apply_changes(source_oid, key_column, change_set);
    current_rows := base -> 'current';
    current_count := (base -> 'summary' ->> 'current_count')::bigint;
    IF target_kind = 'rule' THEN
        proposed_model := pgreact_internal.m35_rule_rows(
            source_rows, key_column, source_label, evidence_limit);
    ELSIF target_kind = 'decision_program' THEN
        SELECT array_agg(value::name ORDER BY ordinal)
        INTO result_columns
        FROM jsonb_array_elements_text(proposed_normalized -> 'spec' -> 'results')
             WITH ORDINALITY item(value, ordinal);
        max_candidates := COALESCE(
            (proposed_normalized -> 'spec' ->> 'max_candidates')::integer, 1000);
        proposed_model := pgreact_internal.m35_decision_rows(
            source_rows,
            (proposed_normalized -> 'spec' ->> 'subject_key')::name,
            (proposed_normalized -> 'spec' ->> 'candidate_key')::name,
            (proposed_normalized -> 'spec' ->> 'priority')::name,
            result_columns, max_candidates, source_label, evidence_limit);
        SELECT count(*) INTO missing_count
        FROM jsonb_array_elements(current_rows) current_row
        WHERE NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
            WHERE proposed_row.value ->> 'subject_key' = current_row.value ->> 'subject_key');
        IF missing_count > 0 THEN
            SELECT COALESCE(jsonb_agg(row_data ORDER BY row_data ->> 'subject_key'), '[]'::jsonb)
            INTO proposed_rows
            FROM (
                SELECT proposed_row.value AS row_data
                FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
                UNION ALL
                SELECT jsonb_build_object(
                           'subject_key', current_row.value ->> 'subject_key',
                           'result_key', NULL,
                           'state', 'NO_CANDIDATE',
                           'value', jsonb_build_object(
                               'candidate', NULL, 'priority', NULL, 'result', NULL),
                           'work', jsonb_build_object('would_be_work', false),
                           'evidence', jsonb_build_object(
                               'source', 'pgreact.decision_winners',
                               'hypothetical', true, 'complete', true))
                FROM jsonb_array_elements(current_rows) current_row
                WHERE NOT EXISTS (
                    SELECT 1 FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
                    WHERE proposed_row.value ->> 'subject_key' = current_row.value ->> 'subject_key')
            ) rows;
            proposed_model := jsonb_build_object(
                'rows', proposed_rows,
                'rows_considered', (proposed_model ->> 'rows_considered')::bigint + missing_count,
                'truncated', COALESCE((proposed_model ->> 'truncated')::boolean, false)
                    OR (proposed_model ->> 'rows_considered')::bigint + missing_count
                       > evidence_limit);
        END IF;
    ELSE
        subject_model := pgreact_internal.m35_policy_subject_rows(
            source_rows, key_column, source_label, evidence_limit);
        SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
        INTO member_rows
        FROM jsonb_array_elements(base -> 'proposed') item(value)
        WHERE item.value ->> 'subject_key' NOT LIKE 'subject:%';
        member_count := jsonb_array_length(
            COALESCE(proposed_normalized -> 'spec' -> 'members', '[]'::jsonb));
        subject_count := (subject_model ->> 'rows_considered')::bigint;
        proposed_model := jsonb_build_object(
            'rows', COALESCE(member_rows, '[]'::jsonb) || (subject_model -> 'rows'),
            'rows_considered', member_count + subject_count,
            'truncated', COALESCE((base ->> 'truncated')::boolean, false)
                OR COALESCE((subject_model ->> 'truncated')::boolean, false)
                OR member_count > evidence_limit);
    END IF;
    proposed_rows := proposed_model -> 'rows';
    proposed_count := (proposed_model ->> 'rows_considered')::bigint;
    delta_model := pgreact_internal.m34_delta(current_rows, proposed_rows);
    delta_rows := delta_model -> 'rows';
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
    INTO lifecycle_rows
    FROM jsonb_array_elements(delta_rows) item(value)
    WHERE item.value ->> 'change' <> 'UNCHANGED';
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
    INTO work_rows
    FROM jsonb_array_elements(proposed_rows) item(value)
    WHERE (item.value -> 'work' ->> 'would_be_work')::boolean;
    source_checksum_after := pgreact_internal.m35_source_checksum(source_oid, key_column);
    authoritative_checksum_before := base -> 'evidence' ->> 'authoritative_checksum_before';
    authoritative_checksum_after := pgreact_internal.m34_authoritative_checksum();
    IF source_checksum_before IS DISTINCT FROM source_checksum_after
       OR authoritative_checksum_before IS DISTINCT FROM authoritative_checksum_after THEN
        RAISE EXCEPTION 'M35_AUTHORITATIVE_CHANGED: authoritative source or pg-react state changed during comparison';
    END IF;
    source_frontier := (base -> 'evidence' ->> 'source_frontier')::timestamptz;
    sampled_time := (base -> 'evidence' ->> 'sampled_time')::timestamptz;
    comparison_complete := NOT COALESCE((base ->> 'truncated')::boolean, false)
        AND NOT COALESCE((proposed_model ->> 'truncated')::boolean, false)
        AND jsonb_array_length(delta_rows) <= evidence_limit;
    change_set_digest := encode(sha256(convert_to(change_set::text, 'UTF8')), 'hex');
    RETURN jsonb_build_object(
        'contract_version', 22,
        'operation', 'compare',
        'simulation', 'hypothetical_fact_changes',
        'target', jsonb_build_object(
            'kind', target_kind, 'name', target_name, 'version', target_version),
        'state', CASE WHEN comparison_complete THEN 'ready' ELSE 'partial' END,
        'summary', jsonb_build_object(
            'read_only', true,
            'current_count', current_count,
            'proposed_count', proposed_count,
            'delta_counts', CASE WHEN comparison_complete THEN delta_model -> 'counts' END,
            'counts_exact', comparison_complete,
            'affected_subject_count', CASE WHEN comparison_complete THEN
                COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0) END,
            'hypothetical_change_count', jsonb_array_length(change_set),
            'would_be_work', COALESCE((
                SELECT count(*) FROM jsonb_array_elements(proposed_rows) item
                WHERE (item.value -> 'work' ->> 'would_be_work')::boolean), 0)),
        'snapshot', jsonb_build_object(
            'source_relation', source_label,
            'source_frontier', source_frontier,
            'sampled_time', sampled_time,
            'applicability_snapshot', base -> 'evidence' -> 'applicability_snapshot',
            'authoritative_checksum_before', authoritative_checksum_before,
            'authoritative_checksum_after', authoritative_checksum_after,
            'source_checksum_before', source_checksum_before,
            'source_checksum_after', source_checksum_after),
        'evidence', jsonb_build_object(
            'declaration_digest', base -> 'evidence' ->> 'declaration_digest',
            'change_set_digest', change_set_digest,
            'changed_facts', change_set,
            'causal', jsonb_build_object(
                'changed_facts', jsonb_array_length(change_set),
                'support', 'production evaluator evidence',
                'complete', comparison_complete),
            'complete', comparison_complete,
            'evidence_limit', evidence_limit),
        'cost', jsonb_build_object(
            'rows_considered', current_count + proposed_count,
            'hypothetical_rows', jsonb_array_length(change_set),
            'affected_subjects', CASE WHEN comparison_complete THEN
                COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0) END,
            'dependency_fan_out', 0,
            'reevaluation', proposed_count,
            'cascade_depth', 0,
            'temporary_storage_bytes', 0,
            'memory_bytes', NULL,
            'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000),
        'findings', CASE WHEN comparison_complete THEN
            jsonb_build_array(pgreact_internal.m35_finding(
                'M35_NO_EFFECT', 'INFO', target_name, '<comparison>',
                'hypothetical comparison completed without changing source or pg-react state',
                'Apply the reviewed change separately if you want to change production.'))
            ELSE jsonb_build_array(pgreact_internal.m35_finding(
                'M35_COMPARISON_INCOMPLETE', 'WARNING', target_name, '<comparison>',
                'hypothetical evidence was truncated at the requested limit',
                'Increase evidence_limit or reduce the input and inspect the bounded result.')) END,
        'current', pgreact_internal.m34_raw_rows(current_rows, current_count, evidence_limit) -> 'rows',
        'proposed', pgreact_internal.m34_raw_rows(proposed_rows, proposed_count, evidence_limit) -> 'rows',
        'delta', pgreact_internal.m34_raw_rows(
            delta_rows, jsonb_array_length(delta_rows), evidence_limit) -> 'rows',
        'lifecycle', pgreact_internal.m34_raw_rows(
            lifecycle_rows, jsonb_array_length(lifecycle_rows), evidence_limit) -> 'rows',
        'work', pgreact_internal.m34_raw_rows(
            work_rows, jsonb_array_length(work_rows), evidence_limit) -> 'rows',
        'truncated', NOT comparison_complete)
;
END
$m35$;

CREATE FUNCTION pgreact.compare(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    change_set jsonb,
    options jsonb
)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
    SELECT pgreact_internal.m35_compare($1, $2, $3, $4)
$m35$;

CREATE FUNCTION pgreact.compare_results(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    change_set jsonb,
    options jsonb
)
RETURNS TABLE(
    result_set text,
    kind text,
    name text,
    subject_key text,
    result_key text,
    state text,
    delta text,
    current_value jsonb,
    proposed_value jsonb,
    evidence jsonb,
    complete boolean,
    sampled_time timestamptz,
    source_frontier timestamptz,
    declaration_digest text,
    change_set_digest text,
    source_checksum_before text,
    source_checksum_after text
)
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m35$
WITH comparison AS (
    SELECT pgreact.compare($1, $2, $3, $4) AS value
), rows AS (
    SELECT 'current'::text AS result_set, item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'current') item(value)
    UNION ALL
    SELECT 'proposed', item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'proposed') item(value)
    UNION ALL
    SELECT 'delta', item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'delta') item(value)
    UNION ALL
    SELECT 'lifecycle', item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'lifecycle') item(value)
    UNION ALL
    SELECT 'work', item.value
    FROM comparison, jsonb_array_elements(comparison.value -> 'work') item(value)
)
SELECT result_set,
       comparison.value -> 'target' ->> 'kind',
       comparison.value -> 'target' ->> 'name',
       rows.value ->> 'subject_key',
       rows.value ->> 'result_key',
       rows.value ->> 'state',
       rows.value ->> 'change',
       rows.value -> 'current_value',
       rows.value -> 'proposed_value',
       rows.value -> 'evidence',
       (comparison.value -> 'evidence' ->> 'complete')::boolean,
       (comparison.value -> 'snapshot' ->> 'sampled_time')::timestamptz,
       (comparison.value -> 'snapshot' ->> 'source_frontier')::timestamptz,
       comparison.value -> 'evidence' ->> 'declaration_digest',
       comparison.value -> 'evidence' ->> 'change_set_digest',
       comparison.value -> 'snapshot' ->> 'source_checksum_before',
       comparison.value -> 'snapshot' ->> 'source_checksum_after'
FROM comparison
JOIN rows ON true
$m35$;

REVOKE ALL ON FUNCTION pgreact_internal.m35_finding(text, text, text, text, text, text, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m35_finding_registry() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m35_require_source(oid, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m35_source_checksum(oid, name) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m35_check_image(oid, jsonb, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m35_apply_changes(oid, name, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m35_rule_rows(jsonb, name, text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m35_decision_rows(jsonb, name, name, name, name[], integer, text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m35_policy_subject_rows(jsonb, name, text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m35_compare(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact.compare(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact.compare_results(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb) FROM PUBLIC;

DO $m35$
DECLARE role_row record;
BEGIN
    FOR role_row IN
        SELECT role_oid::regrole AS role_name
        FROM pgreact_internal.application_roles
        WHERE role_kind IN ('author', 'operator', 'reader')
    LOOP
        EXECUTE format(
            'GRANT EXECUTE ON FUNCTION pgreact.compare(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb), '
            'pgreact.compare_results(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb) TO %I',
            role_row.role_name::text);
    END LOOP;
END
$m35$;

COMMENT ON FUNCTION pgreact.compare(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb) IS
    'M35 bounded read-only comparison with ordered hypothetical typed row changes';
COMMENT ON FUNCTION pgreact.compare_results(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb) IS
    'M35 relational current, proposed, delta, lifecycle, and work rows for hypothetical changes';
COMMENT ON EXTENSION pg_react IS
    'M35 hypothetical fact simulation: bounded read-only comparison of typed ordered row changes';
-- M36 read-only caller-supplied historical replay over the M35 evaluator.

CREATE OR REPLACE FUNCTION pgreact_internal.m36_finding(
    code text,
    severity text,
    target text,
    field text,
    message text,
    hint text,
    details jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
STRICT
AS $m36$
    SELECT jsonb_build_object(
        'code', $1,
        'severity', $2,
        'blocking', $2 = 'ERROR',
        'target', $3,
        'field', $4,
        'message', $5,
        'hint', $6,
        'details', COALESCE($7, '{}'::jsonb))
$m36$;

CREATE OR REPLACE FUNCTION pgreact_internal.m36_finding_registry()
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m36$
    SELECT jsonb_build_object(
        'schema_version', 1,
        'milestone', 'M36',
        'finding_shape', jsonb_build_array(
            'code', 'severity', 'blocking', 'target',
            'field', 'message', 'hint', 'details'),
        'severity', jsonb_build_array('ERROR', 'WARNING', 'INFO'),
        'codes', jsonb_build_array(
            jsonb_build_object('code', 'M36_SNAPSHOT_INVALID', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_SNAPSHOT_REQUIRED_FIELD', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_SNAPSHOT_UNKNOWN_FIELD', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_SNAPSHOT_RELATION', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_SNAPSHOT_SCHEMA', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_SNAPSHOT_ROW', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_SNAPSHOT_DUPLICATE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_INVALID', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_REQUIRED_FIELD', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_UNKNOWN_FIELD', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_ORDINAL', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_DUPLICATE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_NONMONOTONE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_LATE_INPUT', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_FINALIZED', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_CONFLICT', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_STALE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_UNAUTHORIZED_TARGET', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_UNAUTHORIZED_SOURCE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_RLS_UNSUPPORTED', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_UNSUPPORTED_TARGET', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_UNSUPPORTED_SOURCE', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_AMBIGUOUS', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_CYCLIC', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_RESOURCE_LIMIT', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_AUTHORITATIVE_CHANGED', 'severity', 'ERROR'),
            jsonb_build_object('code', 'M36_REPLAY_INCOMPLETE', 'severity', 'WARNING'),
            jsonb_build_object('code', 'M36_NO_EFFECT', 'severity', 'INFO')))
$m36$;

CREATE OR REPLACE FUNCTION pgreact_internal.m36_schema_fingerprint(source_oid oid)
RETURNS text
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m36$
    SELECT encode(sha256(convert_to(COALESCE((
        SELECT string_agg(format('%s:%s:%s:%s:%s:%s:%s',
                              a.attnum, a.attname, a.atttypid::regtype,
                              a.atttypmod, a.attcollation::oid,
                              a.attnotnull, a.attgenerated), '|'
                         ORDER BY a.attnum)
        FROM pg_attribute a
        WHERE a.attrelid = $1 AND a.attnum > 0 AND NOT a.attisdropped),
        ''), 'UTF8')), 'hex')
$m36$;

CREATE OR REPLACE FUNCTION pgreact_internal.m36_require_source(
    source_oid oid,
    source_name text
)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m36$
DECLARE
    relation_kind "char";
    rls_enabled boolean;
BEGIN
    IF source_oid IS NULL THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_RELATION: source relation % no longer exists', source_name;
    END IF;
    SELECT relkind, relrowsecurity
    INTO relation_kind, rls_enabled
    FROM pg_class
    WHERE oid = source_oid;
    IF relation_kind NOT IN ('r', 'p') THEN
        RAISE EXCEPTION 'M36_UNSUPPORTED_SOURCE: source relation % must be a table', source_name;
    END IF;
    IF rls_enabled THEN
        RAISE EXCEPTION 'M36_RLS_UNSUPPORTED: source relation % uses row-level security', source_name;
    END IF;
    IF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
        RAISE EXCEPTION 'M36_UNAUTHORIZED_SOURCE: caller lacks SELECT on source relation %', source_name;
    END IF;
END
$m36$;

CREATE OR REPLACE FUNCTION pgreact_internal.m36_snapshot_digest(relations jsonb)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
AS $m36$
DECLARE
    relation_item jsonb;
    row_material text;
    material text := '';
BEGIN
    FOR relation_item IN
        SELECT value
        FROM jsonb_array_elements($1) item(value)
        ORDER BY value ->> 'relation'
    LOOP
        SELECT COALESCE(string_agg(value::text, ',' ORDER BY value::text), '')
        INTO row_material
        FROM jsonb_array_elements(relation_item -> 'rows') row(value);
        material := material || (relation_item ->> 'relation') || '=' || row_material || E'\n';
    END LOOP;
    RETURN encode(sha256(convert_to(material, 'UTF8')), 'hex');
END
$m36$;

CREATE OR REPLACE FUNCTION pgreact_internal.m36_validate_rows(
    source_oid oid,
    key_column name,
    rows jsonb,
    source_label text
)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m36$
DECLARE
    duplicate_count bigint;
    row_item jsonb;
BEGIN
    IF jsonb_typeof(rows) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_ROW: rows for % must be a JSON array', source_label;
    END IF;
    FOR row_item IN SELECT value FROM jsonb_array_elements(rows) item(value)
    LOOP
        BEGIN
            PERFORM pgreact_internal.m35_check_image(source_oid, row_item, 'snapshot row');
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'M36_SNAPSHOT_ROW: row in % does not match the source schema', source_label;
        END;
        IF row_item ->> key_column::text IS NULL
           OR row_item ->> key_column::text !~ '^-?[0-9]+$' THEN
            RAISE EXCEPTION 'M36_SNAPSHOT_ROW: % identity must be a bigint value', source_label;
        END IF;
    END LOOP;
    SELECT count(*) INTO duplicate_count
    FROM (
        SELECT value ->> key_column::text
        FROM jsonb_array_elements(rows) item(value)
        GROUP BY value ->> key_column::text
        HAVING count(*) > 1
    ) duplicates;
    IF duplicate_count > 0 THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_DUPLICATE: % contains duplicate identities', source_label;
    END IF;
END
$m36$;

CREATE OR REPLACE FUNCTION pgreact_internal.m36_apply_changes(
    source_oid oid,
    key_column name,
    source_label text,
    rows jsonb,
    change_set jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m36$
DECLARE
    item jsonb;
    operation text;
    key_text text;
    existing jsonb;
    row_count bigint;
    unknown_field text;
BEGIN
    IF jsonb_typeof(change_set) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M36_REPLAY_INVALID: change_set must be a JSON array';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'object'
           OR NOT (item.value ?& ARRAY['relation', 'operation', 'ordinal', 'key', 'before', 'after'])
           OR (SELECT count(*) FROM jsonb_object_keys(item.value)) <> 6
    ) THEN
        RAISE EXCEPTION 'M36_REPLAY_REQUIRED_FIELD: every change must contain relation, operation, ordinal, key, before, and after';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_array_elements(change_set) item(value),
         jsonb_object_keys(item.value) AS key
    WHERE key NOT IN ('relation', 'operation', 'ordinal', 'key', 'before', 'after')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M36_REPLAY_UNKNOWN_FIELD: change field % is not supported', unknown_field;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        WHERE jsonb_typeof(item.value -> 'ordinal') IS DISTINCT FROM 'number'
           OR item.value ->> 'ordinal' !~ '^[1-9][0-9]*$'
    ) THEN
        RAISE EXCEPTION 'M36_REPLAY_ORDINAL: change ordinals must be positive integers';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        GROUP BY (item.value ->> 'ordinal')::bigint
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'M36_REPLAY_DUPLICATE: change ordinals must be unique';
    END IF;
    FOR item IN
        SELECT value
        FROM jsonb_array_elements(change_set) change(value)
        ORDER BY (value ->> 'ordinal')::bigint
    LOOP
        IF to_regclass(item ->> 'relation') IS DISTINCT FROM source_oid THEN
            RAISE EXCEPTION 'M36_SNAPSHOT_RELATION: change relation % does not match %',
                item ->> 'relation', source_label;
        END IF;
        operation := item ->> 'operation';
        IF operation IS NULL OR operation NOT IN ('INSERT', 'UPDATE', 'DELETE') THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: operation % is not supported', operation;
        END IF;
        IF jsonb_typeof(item -> 'key') IS DISTINCT FROM 'object'
           OR (SELECT count(*) FROM jsonb_object_keys(item -> 'key')) <> 1
           OR NOT (item -> 'key' ? key_column::text)
           OR jsonb_typeof(item -> 'key' -> key_column::text) IS DISTINCT FROM 'number'
           OR item -> 'key' ->> key_column::text !~ '^-?[0-9]+$' THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: key must contain one integer % value', key_column;
        END IF;
        key_text := item -> 'key' ->> key_column::text;
        IF operation = 'INSERT' THEN
            IF jsonb_typeof(item -> 'before') IS DISTINCT FROM 'null'
               OR jsonb_typeof(item -> 'after') IS DISTINCT FROM 'object' THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: INSERT requires a null before image and an after image';
            END IF;
            BEGIN
                PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'after', 'after');
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: after image does not match the source schema';
            END;
            IF item -> 'after' ->> key_column::text IS DISTINCT FROM key_text THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: INSERT key does not match its after image';
            END IF;
            SELECT count(*) INTO row_count
            FROM jsonb_array_elements(rows) current_row(value)
            WHERE current_row.value ->> key_column::text = key_text;
            IF row_count > 0 THEN
                RAISE EXCEPTION 'M36_REPLAY_CONFLICT: INSERT identity % already exists', key_text;
            END IF;
            rows := rows || jsonb_build_array(item -> 'after');
        ELSE
            IF jsonb_typeof(item -> 'before') IS DISTINCT FROM 'object'
               OR jsonb_typeof(item -> 'after') IS DISTINCT FROM
                  (CASE WHEN operation = 'UPDATE' THEN 'object' ELSE 'null' END) THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: % requires the correct before and after images', operation;
            END IF;
            BEGIN
                PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'before', 'before');
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: before image does not match the source schema';
            END;
            IF operation = 'UPDATE' THEN
                BEGIN
                    PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'after', 'after');
                EXCEPTION WHEN OTHERS THEN
                    RAISE EXCEPTION 'M36_REPLAY_INVALID: after image does not match the source schema';
                END;
                IF item -> 'after' ->> key_column::text IS DISTINCT FROM key_text THEN
                    RAISE EXCEPTION 'M36_REPLAY_INVALID: UPDATE cannot change its identity';
                END IF;
            END IF;
            SELECT count(*), (array_agg(current_row.value))[1]
            INTO row_count, existing
            FROM jsonb_array_elements(rows) current_row(value)
            WHERE current_row.value ->> key_column::text = key_text;
            IF row_count = 0 THEN
                RAISE EXCEPTION 'M36_REPLAY_STALE: identity % is not present', key_text;
            ELSIF row_count > 1 THEN
                RAISE EXCEPTION 'M36_REPLAY_DUPLICATE: identity % is ambiguous', key_text;
            ELSIF existing IS DISTINCT FROM item -> 'before' THEN
                RAISE EXCEPTION 'M36_REPLAY_STALE: before image for identity % is stale', key_text;
            END IF;
            SELECT COALESCE(jsonb_agg(
                       CASE WHEN current_row.value ->> key_column::text = key_text
                            THEN CASE WHEN operation = 'UPDATE'
                                      THEN item -> 'after' ELSE NULL END
                            ELSE current_row.value END
                       ORDER BY current_row.ordinality), '[]'::jsonb)
            INTO rows
            FROM jsonb_array_elements(rows) WITH ORDINALITY current_row(value, ordinality)
            WHERE NOT (operation = 'DELETE'
                       AND current_row.value ->> key_column::text = key_text);
        END IF;
    END LOOP;
    RETURN rows;
END
$m36$;

CREATE OR REPLACE FUNCTION pgreact_internal.m36_model(
    normalized jsonb,
    target_kind text,
    rows jsonb,
    source_label text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m36$
DECLARE
    key_column name;
    subject_column name;
    candidate_column name;
    priority_column name;
    result_columns name[];
    max_candidates integer;
    member_rows jsonb;
    subject_model jsonb;
    member_count bigint;
BEGIN
    IF target_kind = 'rule' THEN
        key_column := (normalized -> 'spec' ->> 'semantic_key')::name;
        RETURN pgreact_internal.m35_rule_rows(rows, key_column, source_label, evidence_limit);
    ELSIF target_kind = 'decision_program' THEN
        subject_column := (normalized -> 'spec' ->> 'subject_key')::name;
        candidate_column := (normalized -> 'spec' ->> 'candidate_key')::name;
        priority_column := (normalized -> 'spec' ->> 'priority')::name;
        SELECT array_agg(value::name ORDER BY ordinal)
        INTO result_columns
        FROM jsonb_array_elements_text(normalized -> 'spec' -> 'results')
             WITH ORDINALITY item(value, ordinal);
        max_candidates := COALESCE(
            (normalized -> 'spec' ->> 'max_candidates')::integer, 1000);
        RETURN pgreact_internal.m35_decision_rows(
            rows, subject_column, candidate_column, priority_column,
            result_columns, max_candidates, source_label, evidence_limit);
    ELSIF target_kind = 'policy_set' THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
                   'subject_key', 'member:' || (item.value ->> 'kind') || ':' ||
                                  (item.value ->> 'name') || ':' || (item.value ->> 'version'),
                   'result_key', 'member:' || (item.value ->> 'kind') || ':' ||
                                 (item.value ->> 'name') || ':' || (item.value ->> 'version'),
                   'state', 'MEMBER',
                   'value', item.value,
                   'work', jsonb_build_object('would_be_work', false),
                   'evidence', jsonb_build_object(
                       'source', 'pgreact.policy_set_members', 'complete', true))
                   ORDER BY item.value ->> 'kind', item.value ->> 'name', item.value ->> 'version'),
               '[]'::jsonb)
        INTO member_rows
        FROM jsonb_array_elements(COALESCE(normalized -> 'spec' -> 'members', '[]'::jsonb)) item(value);
        member_count := jsonb_array_length(COALESCE(normalized -> 'spec' -> 'members', '[]'::jsonb));
        subject_model := pgreact_internal.m35_policy_subject_rows(
            rows,
            ((normalized -> 'spec' -> 'applicability' -> 'subject_keys' ->> 0)::name),
            source_label,
            evidence_limit);
        RETURN jsonb_build_object(
            'rows', member_rows || (subject_model -> 'rows'),
            'rows_considered', member_count + (subject_model ->> 'rows_considered')::bigint,
            'truncated', member_count > evidence_limit
                OR COALESCE((subject_model ->> 'truncated')::boolean, false));
    END IF;
    RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: target kind % is not supported', target_kind;
END
$m36$;

CREATE OR REPLACE FUNCTION pgreact_internal.m36_replay(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    initial_snapshot jsonb,
    replay_steps jsonb,
    options jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m36$
DECLARE
    target_kind text := (deployed).kind;
    target_name text := (deployed).name;
    target_version text := (deployed).version;
    target_owner oid;
    frozen_normalized jsonb;
    normalized jsonb;
    validation jsonb;
    source_label text;
    source_oid oid;
    key_column name;
    source_schema_before text;
    source_schema_after text;
    target_digest_before text;
    target_digest_after text;
    source_rows jsonb;
    initial_snapshot_digest text;
    current_rows jsonb;
    previous_model_rows jsonb;
    initial_model jsonb;
    model jsonb;
    delta_model jsonb;
    delta_rows jsonb;
    lifecycle_rows jsonb;
    work_rows jsonb;
    initial_result jsonb;
    step_result jsonb;
    step_results jsonb := '[]'::jsonb;
    snapshot_relations jsonb;
    snapshot_relation jsonb;
    step jsonb;
    snapshot_digest text;
    replay_digest text;
    declaration_digest text;
    authoritative_checksum_before text;
    authoritative_checksum_after text;
    evidence_limit integer := 100;
    max_steps integer := 100;
    max_changes integer := 1000;
    max_snapshot_rows integer := 10000;
    max_total_changes integer := 10000;
    snapshot_row_count bigint;
    total_changes bigint := 0;
    step_count integer := 0;
    previous_ordinal bigint := 0;
    ordinal bigint;
    previous_frontier timestamptz;
    previous_sampled_time timestamptz;
    previous_watermark timestamptz;
    current_frontier timestamptz;
    current_sampled_time timestamptz;
    current_watermark timestamptz;
    starting_frontier timestamptz;
    starting_sampled_time timestamptz;
    starting_watermark timestamptz;
    finalized boolean := false;
    final_step boolean;
    key_not_null boolean;
    replay_complete boolean := true;
    step_complete boolean;
    rows_considered bigint := 0;
    affected_subjects bigint := 0;
    started_at timestamptz := clock_timestamp();
    unknown_field text;
    expected_source text;
BEGIN
    IF deployed IS NULL OR target_kind IS NULL OR target_name IS NULL THEN
        RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: deployed target kind and name are required';
    END IF;
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M36_REPLAY_INVALID: options must be a JSON object';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(options) AS key
    WHERE key NOT IN ('evidence_limit', 'max_steps', 'max_changes',
                      'max_snapshot_rows', 'max_total_changes')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M36_REPLAY_UNKNOWN_FIELD: option % is not supported', unknown_field;
    END IF;
    IF options ? 'evidence_limit' THEN
        IF jsonb_typeof(options -> 'evidence_limit') IS DISTINCT FROM 'number'
           OR options ->> 'evidence_limit' !~ '^[1-9][0-9]*$'
           OR (options ->> 'evidence_limit')::integer > 1000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: evidence_limit must be between 1 and 1000';
        END IF;
        evidence_limit := (options ->> 'evidence_limit')::integer;
    END IF;
    IF options ? 'max_steps' THEN
        IF jsonb_typeof(options -> 'max_steps') IS DISTINCT FROM 'number'
           OR options ->> 'max_steps' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_steps')::integer > 1000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: max_steps must be between 1 and 1000';
        END IF;
        max_steps := (options ->> 'max_steps')::integer;
    END IF;
    IF options ? 'max_changes' THEN
        IF jsonb_typeof(options -> 'max_changes') IS DISTINCT FROM 'number'
           OR options ->> 'max_changes' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_changes')::integer > 1000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: max_changes must be between 1 and 1000';
        END IF;
        max_changes := (options ->> 'max_changes')::integer;
    END IF;
    IF options ? 'max_snapshot_rows' THEN
        IF jsonb_typeof(options -> 'max_snapshot_rows') IS DISTINCT FROM 'number'
           OR options ->> 'max_snapshot_rows' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_snapshot_rows')::integer > 100000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: max_snapshot_rows must be between 1 and 100000';
        END IF;
        max_snapshot_rows := (options ->> 'max_snapshot_rows')::integer;
    END IF;
    IF options ? 'max_total_changes' THEN
        IF jsonb_typeof(options -> 'max_total_changes') IS DISTINCT FROM 'number'
           OR options ->> 'max_total_changes' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_total_changes')::integer > 100000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: max_total_changes must be between 1 and 100000';
        END IF;
        max_total_changes := (options ->> 'max_total_changes')::integer;
    END IF;
    IF jsonb_typeof(replay_steps) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M36_REPLAY_INVALID: replay_steps must be a JSON array';
    END IF;
    IF jsonb_array_length(replay_steps) > max_steps THEN
        RAISE EXCEPTION 'M36_RESOURCE_LIMIT: replay_steps exceeds max_steps';
    END IF;

    IF target_kind = 'policy_set' THEN
        SELECT version.normalized, set.owner_oid
        INTO frozen_normalized, target_owner
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE set.set_name = target_name
          AND version.state = 'DEPLOYED'
          AND (target_version IS NULL OR version.version = target_version)
        ORDER BY version.valid_from DESC, version.created_at DESC
        LIMIT 1;
    ELSE
        SELECT row_data.normalized, row_data.owner_oid
        INTO frozen_normalized, target_owner
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
        IF target_version IS NOT NULL AND target_version <> '1' THEN
            RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: only deployed declaration version 1 is supported';
        END IF;
    END IF;
    IF frozen_normalized IS NULL THEN
        RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: deployed % % was not found', target_kind, target_name;
    END IF;
    target_digest_before := encode(sha256(convert_to(frozen_normalized::text, 'UTF8')), 'hex');
    IF NOT pg_has_role(session_user, target_owner, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin()
       AND NOT EXISTS (
           SELECT 1 FROM pgreact_internal.application_roles role_row
           WHERE role_row.role_kind = 'reader'
             AND pg_has_role(session_user, role_row.role_oid, 'member')) THEN
        RAISE EXCEPTION 'M36_UNAUTHORIZED_TARGET: caller is not allowed to inspect %', target_name;
    END IF;
    IF proposed IS NULL THEN
        normalized := frozen_normalized;
    ELSE
        IF (proposed).kind IS DISTINCT FROM target_kind
           OR (proposed).name IS DISTINCT FROM target_name THEN
            RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: proposed and deployed targets must match';
        END IF;
        validation := pgreact_internal.m28_validate(proposed);
        IF EXISTS (
            SELECT 1 FROM jsonb_array_elements(validation -> 'findings') finding(value)
            WHERE value ->> 'severity' = 'ERROR'
        ) THEN
            RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: proposed declaration is invalid: %',
                validation -> 'findings';
        END IF;
        normalized := pgreact_internal.m28_normalize(proposed);
    END IF;

    IF target_kind = 'rule' THEN
        source_label := normalized -> 'spec' ->> 'condition';
        key_column := (normalized -> 'spec' ->> 'semantic_key')::name;
    ELSIF target_kind = 'decision_program' THEN
        source_label := normalized -> 'spec' ->> 'candidate_relation';
        key_column := (normalized -> 'spec' ->> 'candidate_key')::name;
    ELSIF target_kind = 'policy_set' THEN
        source_label := normalized -> 'spec' -> 'applicability' ->> 'relation';
        IF jsonb_array_length(COALESCE(
               normalized -> 'spec' -> 'applicability' -> 'subject_keys', '[]'::jsonb)) <> 1 THEN
            RAISE EXCEPTION 'M36_UNSUPPORTED_SOURCE: M36 requires one bigint policy subject key';
        END IF;
        key_column := (normalized -> 'spec' -> 'applicability' -> 'subject_keys' ->> 0)::name;
    ELSE
        RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: target kind % is not supported', target_kind;
    END IF;
    source_oid := to_regclass(source_label);
    PERFORM pgreact_internal.m36_require_source(source_oid, source_label);
    SELECT a.atttypid::regtype, a.attnotnull
    INTO expected_source, key_not_null
    FROM pg_attribute a
    WHERE a.attrelid = source_oid AND a.attname = key_column
      AND a.attnum > 0 AND NOT a.attisdropped;
    IF expected_source IS DISTINCT FROM 'bigint' OR NOT key_not_null THEN
        RAISE EXCEPTION 'M36_UNSUPPORTED_SOURCE: identity column % must be non-null bigint', key_column;
    END IF;
    source_schema_before := pgreact_internal.m36_schema_fingerprint(source_oid);

    IF initial_snapshot IS NULL OR jsonb_typeof(initial_snapshot) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_INVALID: initial_snapshot must be a JSON object';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(initial_snapshot) AS key
    WHERE key NOT IN ('relations', 'source_frontier', 'sampled_time', 'event_time_watermark')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_UNKNOWN_FIELD: snapshot field % is not supported', unknown_field;
    END IF;
    IF NOT (initial_snapshot ?& ARRAY['relations', 'source_frontier', 'sampled_time', 'event_time_watermark'])
       OR jsonb_typeof(initial_snapshot -> 'relations') IS DISTINCT FROM 'array'
       OR jsonb_array_length(initial_snapshot -> 'relations') <> 1 THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_REQUIRED_FIELD: snapshot needs one relation and its three starting times';
    END IF;
    snapshot_relations := initial_snapshot -> 'relations';
    snapshot_relation := snapshot_relations -> 0;
    IF jsonb_typeof(snapshot_relation) IS DISTINCT FROM 'object'
       OR NOT (snapshot_relation ?& ARRAY['relation', 'rows', 'schema_fingerprint']) THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_REQUIRED_FIELD: relation needs relation, rows, and schema_fingerprint fields';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(snapshot_relation) AS key
    WHERE key NOT IN ('relation', 'rows', 'schema_fingerprint')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_UNKNOWN_FIELD: relation field % is not supported', unknown_field;
    END IF;
    IF to_regclass(snapshot_relation ->> 'relation') IS DISTINCT FROM source_oid THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_RELATION: snapshot relation % does not match %',
            snapshot_relation ->> 'relation', source_label;
    END IF;
    IF snapshot_relation ->> 'relation' IS DISTINCT FROM source_oid::regclass::text THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_RELATION: snapshot relation must use canonical name %',
            source_oid::regclass;
    END IF;
    PERFORM pgreact_internal.m36_validate_rows(
        source_oid, key_column, snapshot_relation -> 'rows', source_label);
    SELECT COALESCE(jsonb_array_length(snapshot_relation -> 'rows'), 0)
    INTO snapshot_row_count;
    IF snapshot_row_count > max_snapshot_rows THEN
        RAISE EXCEPTION 'M36_RESOURCE_LIMIT: initial snapshot exceeds max_snapshot_rows';
    END IF;
    IF snapshot_relation ? 'schema_fingerprint'
       AND snapshot_relation ->> 'schema_fingerprint' IS DISTINCT FROM source_schema_before THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_SCHEMA: supplied schema_fingerprint does not match %', source_label;
    END IF;
    BEGIN
        starting_frontier := (initial_snapshot ->> 'source_frontier')::timestamptz;
        starting_sampled_time := (initial_snapshot ->> 'sampled_time')::timestamptz;
        starting_watermark := (initial_snapshot ->> 'event_time_watermark')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_INVALID: snapshot times must be valid timestamps';
    END;
    IF starting_frontier IS NULL OR starting_sampled_time IS NULL OR starting_watermark IS NULL THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_REQUIRED_FIELD: snapshot times cannot be null';
    END IF;
    IF starting_sampled_time > starting_frontier THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_INVALID: sampled_time cannot be after source_frontier';
    END IF;

    authoritative_checksum_before := pgreact_internal.m34_authoritative_checksum();
    source_rows := snapshot_relation -> 'rows';
    snapshot_digest := pgreact_internal.m36_snapshot_digest(snapshot_relations);
    initial_snapshot_digest := snapshot_digest;
    declaration_digest := encode(sha256(convert_to(normalized::text, 'UTF8')), 'hex');
    initial_model := pgreact_internal.m36_model(
        normalized, target_kind, source_rows, source_label, evidence_limit);
    previous_model_rows := initial_model -> 'rows';
    previous_frontier := starting_frontier;
    previous_sampled_time := starting_sampled_time;
    previous_watermark := starting_watermark;
    replay_complete := NOT COALESCE((initial_model ->> 'truncated')::boolean, false);
    rows_considered := rows_considered + (initial_model ->> 'rows_considered')::bigint;
    initial_result := jsonb_build_object(
        'result_set', 'initial',
        'ordinal', 0,
        'source_frontier', starting_frontier,
        'sampled_time', starting_sampled_time,
        'event_time_watermark', starting_watermark,
        'change_set', '[]'::jsonb,
        'rows', initial_model -> 'rows',
        'rows_considered', initial_model -> 'rows_considered',
        'delta', '[]'::jsonb,
        'lifecycle', '[]'::jsonb,
        'work', '[]'::jsonb,
        'snapshot_checksum_before', initial_snapshot_digest,
        'snapshot_checksum_after', initial_snapshot_digest,
        'complete', replay_complete);

    FOR step IN SELECT value FROM jsonb_array_elements(replay_steps) item(value)
    LOOP
        step_count := step_count + 1;
        IF jsonb_typeof(step) IS DISTINCT FROM 'object'
           OR NOT (step ?& ARRAY['ordinal', 'source_frontier', 'sampled_time',
                                 'event_time_watermark', 'change_set']) THEN
            RAISE EXCEPTION 'M36_REPLAY_REQUIRED_FIELD: every step needs ordinal, source_frontier, sampled_time, event_time_watermark, and change_set';
        END IF;
        SELECT key INTO unknown_field
        FROM jsonb_object_keys(step) AS key
        WHERE key NOT IN ('ordinal', 'source_frontier', 'sampled_time',
                          'event_time_watermark', 'change_set', 'final')
        ORDER BY key
        LIMIT 1;
        IF unknown_field IS NOT NULL THEN
            RAISE EXCEPTION 'M36_REPLAY_UNKNOWN_FIELD: step field % is not supported', unknown_field;
        END IF;
        IF step ->> 'ordinal' !~ '^[1-9][0-9]*$' THEN
            RAISE EXCEPTION 'M36_REPLAY_ORDINAL: step ordinals must be positive integers';
        END IF;
        ordinal := (step ->> 'ordinal')::bigint;
        IF ordinal <= previous_ordinal THEN
            IF ordinal = previous_ordinal THEN
                RAISE EXCEPTION 'M36_REPLAY_DUPLICATE: step ordinals must be unique';
            END IF;
            RAISE EXCEPTION 'M36_REPLAY_NONMONOTONE: step ordinals must increase';
        END IF;
        BEGIN
            current_frontier := (step ->> 'source_frontier')::timestamptz;
            current_sampled_time := (step ->> 'sampled_time')::timestamptz;
            current_watermark := (step ->> 'event_time_watermark')::timestamptz;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: step times must be valid timestamps';
        END;
        IF current_frontier IS NULL OR current_sampled_time IS NULL OR current_watermark IS NULL THEN
            RAISE EXCEPTION 'M36_REPLAY_REQUIRED_FIELD: step times cannot be null';
        END IF;
        IF current_frontier < previous_frontier OR current_sampled_time < previous_sampled_time THEN
            RAISE EXCEPTION 'M36_REPLAY_NONMONOTONE: source_frontier and sampled_time cannot move backward';
        END IF;
        IF current_watermark < previous_watermark THEN
            RAISE EXCEPTION 'M36_REPLAY_LATE_INPUT: event_time_watermark cannot move backward';
        END IF;
        IF current_sampled_time > current_frontier THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: sampled_time cannot be after source_frontier';
        END IF;
        IF finalized THEN
            RAISE EXCEPTION 'M36_REPLAY_FINALIZED: replay cannot continue after a final step';
        END IF;
        IF jsonb_typeof(step -> 'change_set') IS DISTINCT FROM 'array' THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: change_set must be a JSON array';
        END IF;
        IF jsonb_array_length(step -> 'change_set') > max_changes THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: step change_set exceeds max_changes';
        END IF;
        total_changes := total_changes + jsonb_array_length(step -> 'change_set');
        IF total_changes > max_total_changes THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: replay changes exceed max_total_changes';
        END IF;
        IF step ? 'final' AND jsonb_typeof(step -> 'final') IS DISTINCT FROM 'boolean' THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: final must be boolean';
        END IF;
        final_step := COALESCE((step ->> 'final')::boolean, false);
        snapshot_digest := pgreact_internal.m36_snapshot_digest(
            jsonb_build_array(jsonb_build_object('relation', source_label, 'rows', source_rows)));
        current_rows := pgreact_internal.m36_apply_changes(
            source_oid, key_column, source_label, source_rows, step -> 'change_set');
        snapshot_digest := pgreact_internal.m36_snapshot_digest(
            jsonb_build_array(jsonb_build_object('relation', source_label, 'rows', current_rows)));
        model := pgreact_internal.m36_model(
            normalized, target_kind, current_rows, source_label, evidence_limit);
        delta_model := pgreact_internal.m34_delta(previous_model_rows, model -> 'rows');
        delta_rows := delta_model -> 'rows';
        SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
        INTO lifecycle_rows
        FROM jsonb_array_elements(delta_rows) item(value)
        WHERE item.value ->> 'change' <> 'UNCHANGED';
        SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
        INTO work_rows
        FROM jsonb_array_elements(model -> 'rows') item(value)
        WHERE (item.value -> 'work' ->> 'would_be_work')::boolean;
        step_complete := replay_complete
            AND NOT COALESCE((model ->> 'truncated')::boolean, false)
            AND jsonb_array_length(delta_rows) <= evidence_limit;
        step_result := jsonb_build_object(
            'result_set', 'step',
            'ordinal', ordinal,
            'source_frontier', current_frontier,
            'sampled_time', current_sampled_time,
            'event_time_watermark', current_watermark,
            'change_set', step -> 'change_set',
            'rows', model -> 'rows',
            'rows_considered', model -> 'rows_considered',
            'delta', delta_rows,
            'lifecycle', lifecycle_rows,
            'work', work_rows,
            'snapshot_checksum_before', pgreact_internal.m36_snapshot_digest(
                jsonb_build_array(jsonb_build_object('relation', source_label, 'rows', source_rows))),
            'snapshot_checksum_after', snapshot_digest,
            'complete', step_complete);
        step_results := step_results || jsonb_build_array(step_result);
        previous_model_rows := model -> 'rows';
        source_rows := current_rows;
        previous_ordinal := ordinal;
        previous_frontier := current_frontier;
        previous_sampled_time := current_sampled_time;
        previous_watermark := current_watermark;
        replay_complete := step_complete;
        IF final_step THEN
            finalized := true;
        END IF;
        rows_considered := rows_considered + (model ->> 'rows_considered')::bigint;
        IF step_complete THEN
            affected_subjects := affected_subjects
                + COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0);
        END IF;
    END LOOP;
    authoritative_checksum_after := pgreact_internal.m34_authoritative_checksum();
    source_schema_after := pgreact_internal.m36_schema_fingerprint(source_oid);
    IF authoritative_checksum_before IS DISTINCT FROM authoritative_checksum_after
       OR source_schema_before IS DISTINCT FROM source_schema_after THEN
        RAISE EXCEPTION 'M36_AUTHORITATIVE_CHANGED: authoritative source or pg-react state changed during replay';
    END IF;
    IF target_kind = 'policy_set' THEN
        SELECT version.normalized INTO frozen_normalized
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE set.set_name = target_name
          AND version.state = 'DEPLOYED'
          AND (target_version IS NULL OR version.version = target_version)
        ORDER BY version.valid_from DESC, version.created_at DESC
        LIMIT 1;
    ELSE
        SELECT row_data.normalized INTO frozen_normalized
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
    END IF;
    target_digest_after := encode(sha256(convert_to(frozen_normalized::text, 'UTF8')), 'hex');
    IF target_digest_before IS DISTINCT FROM target_digest_after THEN
        RAISE EXCEPTION 'M36_AUTHORITATIVE_CHANGED: deployed declaration changed during replay';
    END IF;
    replay_digest := encode(sha256(convert_to(
        initial_snapshot_digest || E'\n' || replay_steps::text, 'UTF8')), 'hex');
    initial_result := initial_result
        || jsonb_build_object(
            'declaration_digest', declaration_digest,
            'snapshot_digest', initial_snapshot_digest,
            'replay_digest', replay_digest);
    RETURN jsonb_build_object(
        'contract_version', 23,
        'operation', 'replay',
        'simulation', 'historical_replay',
        'target', jsonb_build_object(
            'kind', target_kind, 'name', target_name, 'version', target_version),
        'state', CASE WHEN replay_complete THEN 'ready' ELSE 'partial' END,
        'summary', jsonb_build_object(
            'read_only', true,
            'initial_row_count', snapshot_row_count,
            'replay_step_count', step_count,
            'replay_change_count', total_changes,
            'final_row_count', jsonb_array_length(previous_model_rows),
            'counts_exact', replay_complete,
            'affected_subject_count', CASE WHEN replay_complete THEN affected_subjects END),
        'snapshot', jsonb_build_object(
            'relations', jsonb_build_array(jsonb_build_object(
                'relation', source_label,
                'schema_fingerprint', source_schema_before,
                'snapshot_checksum', initial_snapshot_digest)),
            'starting_source_frontier', starting_frontier,
            'starting_sampled_time', starting_sampled_time,
            'starting_event_time_watermark', starting_watermark,
            'ending_source_frontier', previous_frontier,
            'ending_sampled_time', previous_sampled_time,
            'ending_event_time_watermark', previous_watermark,
            'authoritative_checksum_before', authoritative_checksum_before,
            'authoritative_checksum_after', authoritative_checksum_after,
            'source_schema_fingerprint_before', source_schema_before,
            'source_schema_fingerprint_after', source_schema_after),
        'evidence', jsonb_build_object(
            'declaration_digest', declaration_digest,
            'snapshot_digest', initial_snapshot_digest,
            'replay_digest', replay_digest,
            'source_frontier', jsonb_build_object(
                'start', starting_frontier, 'end', previous_frontier),
            'sampled_time', jsonb_build_object(
                'start', starting_sampled_time, 'end', previous_sampled_time),
            'event_time_watermark', jsonb_build_object(
                'start', starting_watermark, 'end', previous_watermark),
            'causal', jsonb_build_object(
                'changed_facts', total_changes,
                'steps', step_count,
                'complete', replay_complete),
            'complete', replay_complete,
            'evidence_limit', evidence_limit),
        'cost', jsonb_build_object(
            'snapshot_rows', snapshot_row_count,
            'replay_steps', step_count,
            'change_rows', total_changes,
            'rows_considered', rows_considered,
            'affected_subjects', CASE WHEN replay_complete THEN affected_subjects END,
            'dependency_fan_out', 0,
            'reevaluation', rows_considered,
            'cascade_depth', 0,
            'temporary_storage_bytes', 0,
            'memory_bytes', NULL,
            'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000),
        'findings', CASE WHEN replay_complete THEN
            jsonb_build_array(pgreact_internal.m36_finding(
                'M36_NO_EFFECT', 'INFO', target_name, '<replay>',
                'historical replay completed without changing source or pg-react state',
                'Apply reviewed production changes separately if you want to change data.'))
            ELSE jsonb_build_array(pgreact_internal.m36_finding(
                'M36_REPLAY_INCOMPLETE', 'WARNING', target_name, '<replay>',
                'historical replay evidence was truncated at the requested limit',
                'Increase evidence_limit or reduce the supplied snapshot.')) END,
        'initial', initial_result,
        'steps', step_results,
        'final', jsonb_build_object(
            'result_set', 'final',
            'ordinal', previous_ordinal,
            'source_frontier', previous_frontier,
            'sampled_time', previous_sampled_time,
            'event_time_watermark', previous_watermark,
            'rows', previous_model_rows,
            'complete', replay_complete,
            'snapshot_checksum', pgreact_internal.m36_snapshot_digest(
                jsonb_build_array(jsonb_build_object('relation', source_label, 'rows', source_rows)))));
END
$m36$;

CREATE FUNCTION pgreact.replay(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    initial_snapshot jsonb,
    replay_steps jsonb,
    options jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m36$
    SELECT pgreact_internal.m36_replay($1, $2, $3, $4, $5)
$m36$;

CREATE FUNCTION pgreact.replay_results(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    initial_snapshot jsonb,
    replay_steps jsonb,
    options jsonb DEFAULT '{}'::jsonb
)
RETURNS TABLE(
    result_set text,
    step_ordinal bigint,
    kind text,
    name text,
    subject_key text,
    result_key text,
    state text,
    delta text,
    current_value jsonb,
    proposed_value jsonb,
    evidence jsonb,
    complete boolean,
    sampled_time timestamptz,
    source_frontier timestamptz,
    event_time_watermark timestamptz,
    declaration_digest text,
    snapshot_digest text,
    replay_digest text,
    snapshot_checksum_before text,
    snapshot_checksum_after text
)
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m36$
WITH replay AS (
    SELECT pgreact.replay($1, $2, $3, $4, $5) AS value
), envelopes AS (
    SELECT value -> 'initial' AS envelope FROM replay
    UNION ALL
    SELECT item.value FROM replay, jsonb_array_elements(value -> 'steps') item(value)
    UNION ALL
    SELECT value -> 'final' FROM replay
), rows AS (
    SELECT envelope, envelope ->> 'result_set' AS result_set,
           (envelope ->> 'ordinal')::bigint AS step_ordinal, item.value
    FROM envelopes, jsonb_array_elements(envelope -> 'rows') item(value)
    UNION ALL
    SELECT envelope, 'delta', (envelope ->> 'ordinal')::bigint, item.value
    FROM envelopes, jsonb_array_elements(envelope -> 'delta') item(value)
    WHERE envelope ->> 'result_set' = 'step'
)
SELECT result_set,
       step_ordinal,
       replay.value -> 'target' ->> 'kind',
       replay.value -> 'target' ->> 'name',
       rows.value ->> 'subject_key',
       rows.value ->> 'result_key',
       rows.value ->> 'state',
       rows.value ->> 'change',
       rows.value -> 'current_value',
       rows.value -> 'proposed_value',
       rows.value -> 'evidence',
       (rows.envelope ->> 'complete')::boolean,
       (rows.envelope ->> 'sampled_time')::timestamptz,
       (rows.envelope ->> 'source_frontier')::timestamptz,
       (rows.envelope ->> 'event_time_watermark')::timestamptz,
       replay.value -> 'evidence' ->> 'declaration_digest',
       replay.value -> 'evidence' ->> 'snapshot_digest',
       replay.value -> 'evidence' ->> 'replay_digest',
       rows.envelope ->> 'snapshot_checksum_before',
       rows.envelope ->> 'snapshot_checksum_after'
FROM replay
JOIN rows ON true
$m36$;

REVOKE ALL ON FUNCTION pgreact_internal.m36_finding(text, text, text, text, text, text, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m36_finding_registry() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m36_schema_fingerprint(oid) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m36_require_source(oid, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m36_snapshot_digest(jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m36_validate_rows(oid, name, jsonb, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m36_apply_changes(oid, name, text, jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m36_model(jsonb, text, jsonb, text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m36_replay(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact.replay(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact.replay_results(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) FROM PUBLIC;

DO $m36$
DECLARE
    role_row record;
BEGIN
    FOR role_row IN
        SELECT role_oid::regrole AS role_name
        FROM pgreact_internal.application_roles
        WHERE role_kind IN ('author', 'operator', 'reader')
    LOOP
        EXECUTE format(
            'GRANT EXECUTE ON FUNCTION pgreact.replay(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb), '
            'pgreact.replay_results(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) TO %I',
            role_row.role_name::text);
    END LOOP;
END
$m36$;

COMMENT ON FUNCTION pgreact.replay(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) IS
    'M36 bounded read-only replay of a caller-supplied typed snapshot and historical changes';
COMMENT ON FUNCTION pgreact.replay_results(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) IS
    'M36 relational initial, step, delta, and final rows for historical replay';
COMMENT ON EXTENSION pg_react IS
    'M36 historical replay: bounded read-only evaluation of caller-supplied typed history';

-- M37 comparative backtesting over the M36 read-only replay evaluator.

CREATE OR REPLACE FUNCTION pgreact_internal.m37_finding(
    code text,
    severity text,
    target text,
    field text,
    message text,
    hint text,
    details jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
STRICT
AS $m37$
    SELECT jsonb_build_object(
        'code', $1,
        'severity', $2,
        'blocking', $2 = 'ERROR',
        'target', $3,
        'field', $4,
        'message', $5,
        'hint', $6,
        'details', COALESCE($7, '{}'::jsonb))
$m37$;

CREATE OR REPLACE FUNCTION pgreact_internal.m37_finding_registry()
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
AS $m37$
SELECT jsonb_build_array(
    jsonb_build_object('code', 'M37_OPTIONS_INVALID', 'severity', 'ERROR'),
    jsonb_build_object('code', 'M37_UNKNOWN_FIELD', 'severity', 'ERROR'),
    jsonb_build_object('code', 'M37_INCOMPATIBLE_TARGET', 'severity', 'ERROR'),
    jsonb_build_object('code', 'M37_SHARED_INPUT', 'severity', 'ERROR'),
    jsonb_build_object('code', 'M37_AUTHORITATIVE_CHANGED', 'severity', 'ERROR'),
    jsonb_build_object('code', 'M37_COMPARISON_INCOMPLETE', 'severity', 'WARNING'),
    jsonb_build_object('code', 'M37_NO_EFFECT', 'severity', 'INFO'))
$m37$;

CREATE OR REPLACE FUNCTION pgreact_internal.m37_differences(
    baseline jsonb,
    candidate jsonb,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
AS $m37$
WITH sides AS (
    SELECT 'baseline'::text AS side, $1 AS replay
    UNION ALL
    SELECT 'candidate'::text, $2
), envelopes AS (
    SELECT side, replay -> 'initial' AS envelope
    FROM sides
    UNION ALL
    SELECT side, item.value
    FROM sides
    CROSS JOIN LATERAL jsonb_array_elements(
        COALESCE(replay -> 'steps', '[]'::jsonb)) item(value)
    UNION ALL
    SELECT side, replay -> 'final'
    FROM sides
), side_rows AS (
    SELECT side,
           envelope ->> 'result_set' AS result_set,
           (envelope ->> 'ordinal')::bigint AS ordinal,
           item.value ->> 'subject_key' AS subject_key,
           COALESCE(item.value ->> 'result_key', item.value ->> 'subject_key') AS result_key,
           item.value AS value
    FROM envelopes
    CROSS JOIN LATERAL jsonb_array_elements(
        COALESCE(envelope -> 'rows', '[]'::jsonb)) item(value)
    UNION ALL
    SELECT side,
           'delta',
           (envelope ->> 'ordinal')::bigint,
           item.value ->> 'subject_key',
           COALESCE(item.value ->> 'result_key', item.value ->> 'subject_key'),
           item.value
    FROM envelopes
    CROSS JOIN LATERAL jsonb_array_elements(
        COALESCE(envelope -> 'delta', '[]'::jsonb)) item(value)
    WHERE envelope ->> 'result_set' = 'step'
), baseline_rows AS (
    SELECT * FROM side_rows WHERE side = 'baseline'
), candidate_rows AS (
    SELECT * FROM side_rows WHERE side = 'candidate'
), changes AS (
    SELECT COALESCE(baseline_rows.result_set, candidate_rows.result_set) AS result_set,
           COALESCE(baseline_rows.ordinal, candidate_rows.ordinal) AS ordinal,
           COALESCE(baseline_rows.subject_key, candidate_rows.subject_key) AS subject_key,
           COALESCE(baseline_rows.result_key, candidate_rows.result_key) AS result_key,
           baseline_rows.value AS baseline_value,
           candidate_rows.value AS candidate_value,
           CASE
               WHEN baseline_rows.value IS NULL THEN 'ADDED'
               WHEN candidate_rows.value IS NULL THEN 'REMOVED'
               WHEN baseline_rows.value ->> 'state' IS NOT DISTINCT FROM
                    candidate_rows.value ->> 'state'
                AND COALESCE(baseline_rows.value -> 'value',
                    jsonb_build_object('current_value', baseline_rows.value -> 'current_value',
                                       'proposed_value', baseline_rows.value -> 'proposed_value'))
                    IS NOT DISTINCT FROM COALESCE(candidate_rows.value -> 'value',
                    jsonb_build_object('current_value', candidate_rows.value -> 'current_value',
                                       'proposed_value', candidate_rows.value -> 'proposed_value'))
                AND baseline_rows.value -> 'work' IS NOT DISTINCT FROM
                    candidate_rows.value -> 'work' THEN 'UNCHANGED'
               ELSE 'CHANGED'
           END AS change
    FROM baseline_rows
    FULL JOIN candidate_rows
      ON baseline_rows.result_set = candidate_rows.result_set
     AND baseline_rows.ordinal = candidate_rows.ordinal
     AND baseline_rows.subject_key = candidate_rows.subject_key
     AND baseline_rows.result_key = candidate_rows.result_key
), limited AS (
    SELECT *
    FROM changes
    ORDER BY result_set, ordinal, subject_key, result_key
    LIMIT $3
)
SELECT jsonb_build_object(
    'rows', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
                   'result_set', result_set,
                   'ordinal', ordinal,
                   'subject_key', subject_key,
                   'result_key', result_key,
                   'change', change,
                   'state', COALESCE(candidate_value ->> 'state', baseline_value ->> 'state'),
                   'baseline', jsonb_build_object(
                       'state', baseline_value ->> 'state',
                       'value', COALESCE(baseline_value -> 'value',
                           jsonb_build_object('current_value', baseline_value -> 'current_value',
                                              'proposed_value', baseline_value -> 'proposed_value')),
                       'work', baseline_value -> 'work',
                       'evidence', baseline_value -> 'evidence'),
                   'candidate', jsonb_build_object(
                       'state', candidate_value ->> 'state',
                       'value', COALESCE(candidate_value -> 'value',
                           jsonb_build_object('current_value', candidate_value -> 'current_value',
                                              'proposed_value', candidate_value -> 'proposed_value')),
                       'work', candidate_value -> 'work',
                       'evidence', candidate_value -> 'evidence'),
                   'evidence', jsonb_build_object(
                       'baseline', baseline_value -> 'evidence',
                       'candidate', candidate_value -> 'evidence',
                       'complete', true))
                   ORDER BY result_set, ordinal, subject_key, result_key)
        FROM limited), '[]'::jsonb),
    'counts', (SELECT jsonb_build_object(
        'added', count(*) FILTER (WHERE change = 'ADDED'),
        'removed', count(*) FILTER (WHERE change = 'REMOVED'),
        'changed', count(*) FILTER (WHERE change = 'CHANGED'),
        'unchanged', count(*) FILTER (WHERE change = 'UNCHANGED'))
        FROM changes),
    'rows_considered', (SELECT count(*) FROM changes),
    'affected_subjects', (SELECT count(DISTINCT subject_key)
                          FILTER (WHERE change <> 'UNCHANGED')
                          FROM changes),
    'truncated', (SELECT count(*) > $3 FROM changes))
$m37$;

CREATE OR REPLACE FUNCTION pgreact_internal.m37_backtest(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    initial_snapshot jsonb,
    replay_steps jsonb,
    options jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m37$
DECLARE
    target_kind text := (deployed).kind;
    target_name text := (deployed).name;
    baseline jsonb;
    candidate jsonb;
    differences jsonb;
    options_object jsonb := COALESCE(options, '{}'::jsonb);
    unknown_field text;
    evidence_limit integer := 100;
    complete boolean;
    comparison_digest text;
    started_at timestamptz := clock_timestamp();
BEGIN
    IF deployed IS NULL OR target_kind IS NULL OR target_name IS NULL THEN
        RAISE EXCEPTION 'M37_INCOMPATIBLE_TARGET: deployed target kind and name are required';
    END IF;
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M37_OPTIONS_INVALID: options must be a JSON object';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(options) AS key
    WHERE key NOT IN ('evidence_limit', 'max_steps', 'max_changes',
                      'max_snapshot_rows', 'max_total_changes')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M37_UNKNOWN_FIELD: option % is not supported', unknown_field;
    END IF;
    IF proposed IS NOT NULL
       AND ((proposed).kind IS DISTINCT FROM target_kind
            OR (proposed).name IS DISTINCT FROM target_name) THEN
        RAISE EXCEPTION 'M37_INCOMPATIBLE_TARGET: candidate and baseline targets must match';
    END IF;
    IF options ? 'evidence_limit' THEN
        evidence_limit := (options ->> 'evidence_limit')::integer;
    END IF;

    baseline := pgreact_internal.m36_replay(
        NULL::pgreact_api.declaration, deployed, initial_snapshot, replay_steps, options);
    candidate := pgreact_internal.m36_replay(
        proposed, deployed, initial_snapshot, replay_steps, options);

    IF baseline -> 'evidence' ->> 'snapshot_digest' IS DISTINCT FROM
       candidate -> 'evidence' ->> 'snapshot_digest'
       OR baseline -> 'evidence' ->> 'replay_digest' IS DISTINCT FROM
          candidate -> 'evidence' ->> 'replay_digest'
       OR baseline -> 'snapshot' ->> 'source_schema_fingerprint_before' IS DISTINCT FROM
          candidate -> 'snapshot' ->> 'source_schema_fingerprint_before'
       OR baseline -> 'snapshot' ->> 'authoritative_checksum_before' IS DISTINCT FROM
          candidate -> 'snapshot' ->> 'authoritative_checksum_before'
       OR baseline -> 'snapshot' ->> 'authoritative_checksum_after' IS DISTINCT FROM
          candidate -> 'snapshot' ->> 'authoritative_checksum_after' THEN
        RAISE EXCEPTION 'M37_SHARED_INPUT: baseline and candidate did not use one shared frozen history';
    END IF;
    IF baseline -> 'snapshot' ->> 'authoritative_checksum_before' IS DISTINCT FROM
       baseline -> 'snapshot' ->> 'authoritative_checksum_after'
       OR candidate -> 'snapshot' ->> 'authoritative_checksum_before' IS DISTINCT FROM
          candidate -> 'snapshot' ->> 'authoritative_checksum_after' THEN
        RAISE EXCEPTION 'M37_AUTHORITATIVE_CHANGED: authoritative state changed during backtest';
    END IF;

    differences := pgreact_internal.m37_differences(baseline, candidate, evidence_limit);
    complete := baseline ->> 'state' = 'ready'
        AND candidate ->> 'state' = 'ready'
        AND NOT (differences ->> 'truncated')::boolean;
    comparison_digest := encode(sha256(convert_to(
        COALESCE(baseline -> 'evidence' ->> 'declaration_digest', '') || E'\n' ||
        COALESCE(candidate -> 'evidence' ->> 'declaration_digest', '') || E'\n' ||
        COALESCE(baseline -> 'evidence' ->> 'snapshot_digest', '') || E'\n' ||
        COALESCE(baseline -> 'evidence' ->> 'replay_digest', '') || E'\n' ||
        (differences -> 'counts')::text, 'UTF8')), 'hex');

    RETURN jsonb_build_object(
        'contract_version', 24,
        'operation', 'backtest',
        'simulation', 'comparative_backtesting',
        'target', baseline -> 'target',
        'state', CASE WHEN complete THEN 'ready' ELSE 'partial' END,
        'summary', jsonb_build_object(
            'read_only', true,
            'initial_row_count', (baseline -> 'summary' ->> 'initial_row_count')::bigint,
            'replay_step_count', (baseline -> 'summary' ->> 'replay_step_count')::integer,
            'replay_change_count', (baseline -> 'summary' ->> 'replay_change_count')::bigint,
            'baseline_final_row_count', (baseline -> 'summary' ->> 'final_row_count')::bigint,
            'candidate_final_row_count', (candidate -> 'summary' ->> 'final_row_count')::bigint,
            'difference_counts', differences -> 'counts',
            'counts_exact', complete,
            'affected_subject_count', CASE WHEN complete
                THEN (differences ->> 'affected_subjects')::bigint END),
        'shared_input', jsonb_build_object(
            'snapshot_digest', baseline -> 'evidence' ->> 'snapshot_digest',
            'replay_digest', baseline -> 'evidence' ->> 'replay_digest',
            'starting_source_frontier', baseline -> 'snapshot' ->> 'starting_source_frontier',
            'ending_source_frontier', baseline -> 'snapshot' ->> 'ending_source_frontier',
            'starting_sampled_time', baseline -> 'snapshot' ->> 'starting_sampled_time',
            'ending_sampled_time', baseline -> 'snapshot' ->> 'ending_sampled_time',
            'starting_event_time_watermark', baseline -> 'snapshot' ->> 'starting_event_time_watermark',
            'ending_event_time_watermark', baseline -> 'snapshot' ->> 'ending_event_time_watermark'),
        'evidence', jsonb_build_object(
            'baseline_declaration_digest', baseline -> 'evidence' ->> 'declaration_digest',
            'candidate_declaration_digest', candidate -> 'evidence' ->> 'declaration_digest',
            'snapshot_digest', baseline -> 'evidence' ->> 'snapshot_digest',
            'replay_digest', baseline -> 'evidence' ->> 'replay_digest',
            'comparison_digest', comparison_digest,
            'changed_subjects', differences -> 'rows',
            'complete', complete,
            'evidence_limit', evidence_limit),
        'cost', jsonb_build_object(
            'baseline', baseline -> 'cost',
            'candidate', candidate -> 'cost',
            'comparison', jsonb_build_object(
                'aligned_rows', differences -> 'rows_considered',
                'changed_rows', (differences -> 'counts' ->> 'added')::bigint
                    + (differences -> 'counts' ->> 'removed')::bigint
                    + (differences -> 'counts' ->> 'changed')::bigint,
                'affected_subjects', differences -> 'affected_subjects',
                'evidence_rows', jsonb_array_length(differences -> 'rows'),
                'counts_exact', complete,
                'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000)),
        'findings', CASE WHEN complete THEN
            jsonb_build_array(pgreact_internal.m37_finding(
                'M37_NO_EFFECT', 'INFO', target_name, '<backtest>',
                'comparative backtest completed without changing source or pg-react state',
                'Apply reviewed production changes separately if you want to change data.'))
            ELSE jsonb_build_array(pgreact_internal.m37_finding(
                'M37_COMPARISON_INCOMPLETE', 'WARNING', target_name, '<backtest>',
                'comparative evidence was truncated at the requested limit',
                'Increase evidence_limit or reduce the supplied snapshot.')) END,
        'baseline', baseline,
        'candidate', candidate,
        'differences', differences)
    ;
END
$m37$;

CREATE FUNCTION pgreact.backtest(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    initial_snapshot jsonb,
    replay_steps jsonb,
    options jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m37$
    SELECT pgreact_internal.m37_backtest($1, $2, $3, $4, $5)
$m37$;

CREATE FUNCTION pgreact.backtest_results(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    initial_snapshot jsonb,
    replay_steps jsonb,
    options jsonb DEFAULT '{}'::jsonb
)
RETURNS TABLE(
    side text,
    result_set text,
    step_ordinal bigint,
    kind text,
    name text,
    subject_key text,
    result_key text,
    state text,
    change text,
    baseline_value jsonb,
    candidate_value jsonb,
    baseline_work jsonb,
    candidate_work jsonb,
    baseline_evidence jsonb,
    candidate_evidence jsonb,
    complete boolean,
    sampled_time timestamptz,
    source_frontier timestamptz,
    event_time_watermark timestamptz,
    baseline_declaration_digest text,
    candidate_declaration_digest text,
    snapshot_digest text,
    replay_digest text,
    comparison_digest text
)
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m37$
WITH backtest AS (
    SELECT pgreact_internal.m37_backtest($1, $2, $3, $4, $5) AS value
), sides AS (
    SELECT 'baseline'::text AS side, value, value -> 'baseline' AS replay
    FROM backtest
    UNION ALL
    SELECT 'candidate'::text, value, value -> 'candidate'
    FROM backtest
), envelopes AS (
    SELECT side, value, replay, replay -> 'initial' AS envelope
    FROM sides
    UNION ALL
    SELECT sides.side, sides.value, sides.replay, item.value
    FROM sides
    CROSS JOIN LATERAL jsonb_array_elements(
        COALESCE(replay -> 'steps', '[]'::jsonb)) item(value)
    UNION ALL
    SELECT side, sides.value, replay, replay -> 'final'
    FROM sides
), side_rows AS (
    SELECT side, envelopes.value, envelope, false AS is_delta, item.value AS row_data,
           envelope ->> 'result_set' AS result_set,
           (envelope ->> 'ordinal')::bigint AS ordinal
    FROM envelopes
    CROSS JOIN LATERAL jsonb_array_elements(
        COALESCE(envelope -> 'rows', '[]'::jsonb)) item(value)
    UNION ALL
    SELECT side, envelopes.value, envelope, true, item.value, 'delta',
           (envelope ->> 'ordinal')::bigint
    FROM envelopes
    CROSS JOIN LATERAL jsonb_array_elements(
        COALESCE(envelope -> 'delta', '[]'::jsonb)) item(value)
    WHERE envelope ->> 'result_set' = 'step'
), result_rows AS (
    SELECT side,
           result_set,
           ordinal,
           value -> 'target' ->> 'kind' AS kind,
           value -> 'target' ->> 'name' AS name,
           row_data ->> 'subject_key' AS subject_key,
           COALESCE(row_data ->> 'result_key', row_data ->> 'subject_key') AS result_key,
           row_data ->> 'state' AS state,
           CASE WHEN is_delta THEN row_data ->> 'change' END AS change,
           CASE WHEN side = 'baseline' THEN
               CASE WHEN is_delta THEN row_data -> 'current_value' ELSE row_data -> 'value' END END AS baseline_value,
           CASE WHEN side = 'candidate' THEN
               CASE WHEN is_delta THEN row_data -> 'proposed_value' ELSE row_data -> 'value' END END AS candidate_value,
           CASE WHEN side = 'baseline' THEN row_data -> 'work' END AS baseline_work,
           CASE WHEN side = 'candidate' THEN row_data -> 'work' END AS candidate_work,
           CASE WHEN side = 'baseline' THEN row_data -> 'evidence' END AS baseline_evidence,
           CASE WHEN side = 'candidate' THEN row_data -> 'evidence' END AS candidate_evidence,
           (envelope ->> 'complete')::boolean AS complete,
           (envelope ->> 'sampled_time')::timestamptz AS sampled_time,
           (envelope ->> 'source_frontier')::timestamptz AS source_frontier,
           (envelope ->> 'event_time_watermark')::timestamptz AS event_time_watermark,
           value -> 'evidence' ->> 'baseline_declaration_digest' AS baseline_declaration_digest,
           value -> 'evidence' ->> 'candidate_declaration_digest' AS candidate_declaration_digest,
           value -> 'evidence' ->> 'snapshot_digest' AS snapshot_digest,
           value -> 'evidence' ->> 'replay_digest' AS replay_digest,
           value -> 'evidence' ->> 'comparison_digest' AS comparison_digest
    FROM side_rows
), difference_rows AS (
    SELECT 'difference'::text AS side,
           item.value ->> 'result_set' AS result_set,
           (item.value ->> 'ordinal')::bigint AS ordinal,
           backtest.value -> 'target' ->> 'kind' AS kind,
           backtest.value -> 'target' ->> 'name' AS name,
           item.value ->> 'subject_key' AS subject_key,
           item.value ->> 'result_key' AS result_key,
           item.value ->> 'state' AS state,
           item.value ->> 'change' AS change,
           item.value -> 'baseline' -> 'value' AS baseline_value,
           item.value -> 'candidate' -> 'value' AS candidate_value,
           item.value -> 'baseline' -> 'work' AS baseline_work,
           item.value -> 'candidate' -> 'work' AS candidate_work,
           item.value -> 'baseline' -> 'evidence' AS baseline_evidence,
           item.value -> 'candidate' -> 'evidence' AS candidate_evidence,
           (backtest.value ->> 'state') = 'ready' AS complete,
           NULL::timestamptz AS sampled_time,
           NULL::timestamptz AS source_frontier,
           NULL::timestamptz AS event_time_watermark,
           backtest.value -> 'evidence' ->> 'baseline_declaration_digest' AS baseline_declaration_digest,
           backtest.value -> 'evidence' ->> 'candidate_declaration_digest' AS candidate_declaration_digest,
           backtest.value -> 'evidence' ->> 'snapshot_digest' AS snapshot_digest,
           backtest.value -> 'evidence' ->> 'replay_digest' AS replay_digest,
           backtest.value -> 'evidence' ->> 'comparison_digest' AS comparison_digest
    FROM backtest
    CROSS JOIN LATERAL jsonb_array_elements(
        COALESCE(backtest.value -> 'differences' -> 'rows', '[]'::jsonb)) item(value)
)
SELECT * FROM result_rows
UNION ALL
SELECT * FROM difference_rows
$m37$;

REVOKE ALL ON FUNCTION pgreact_internal.m37_finding(text, text, text, text, text, text, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m37_finding_registry() FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m37_differences(jsonb, jsonb, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact_internal.m37_backtest(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact.backtest(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION pgreact.backtest_results(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) FROM PUBLIC;

DO $m37$
DECLARE
    role_row record;
BEGIN
    FOR role_row IN
        SELECT role_oid::regrole AS role_name
        FROM pgreact_internal.application_roles
        WHERE role_kind IN ('author', 'operator', 'reader')
    LOOP
        EXECUTE format(
            'GRANT EXECUTE ON FUNCTION pgreact.backtest(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb), '
            'pgreact.backtest_results(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) TO %I',
            role_row.role_name::text);
    END LOOP;
END
$m37$;

COMMENT ON FUNCTION pgreact.backtest(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) IS
    'M37 bounded read-only comparative backtest of two policy versions over one supplied history';
COMMENT ON FUNCTION pgreact.backtest_results(pgreact_api.declaration, pgreact_api.target, jsonb, jsonb, jsonb) IS
    'M37 relational baseline, candidate, delta, and difference rows for comparative backtesting';
COMMENT ON EXTENSION pg_react IS
    'M37 comparative backtesting: bounded read-only comparison of two policy versions over supplied history';
-- M38 bounded why-changed evidence over the M34-M37 result contracts.

CREATE OR REPLACE FUNCTION pgreact_internal.m38_finding(
    code text,
    severity text,
    target text,
    field text,
    message text,
    hint text,
    details jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
STRICT
AS $m38$
    SELECT jsonb_build_object(
        'code', $1,
        'severity', $2,
        'blocking', $2 = 'ERROR',
        'target', $3,
        'field', $4,
        'message', $5,
        'hint', $6,
        'details', COALESCE($7, '{}'::jsonb))
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_finding_registry()
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
AS $m38$
SELECT jsonb_build_array(
    jsonb_build_object('code', 'M38_OPTIONS_INVALID', 'severity', 'ERROR'),
    jsonb_build_object('code', 'M38_UNKNOWN_FIELD', 'severity', 'ERROR'),
    jsonb_build_object('code', 'M38_EVIDENCE_UNAVAILABLE', 'severity', 'WARNING'),
    jsonb_build_object('code', 'M38_EVIDENCE_PARTIAL', 'severity', 'WARNING'),
    jsonb_build_object('code', 'M38_EVIDENCE_UNSUPPORTED', 'severity', 'WARNING'),
    jsonb_build_object('code', 'M38_EVIDENCE_AMBIGUOUS', 'severity', 'WARNING'),
    jsonb_build_object('code', 'M38_EVIDENCE_CYCLIC', 'severity', 'WARNING'),
    jsonb_build_object('code', 'M38_EVIDENCE_LIMIT', 'severity', 'WARNING'),
    jsonb_build_object('code', 'M38_NO_EFFECT', 'severity', 'INFO'))
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_requested(options jsonb)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $m38$
BEGIN
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object'
       OR NOT options ? 'why_changed' THEN
        RETURN false;
    END IF;
    IF jsonb_typeof(options -> 'why_changed') IS DISTINCT FROM 'boolean' THEN
        RAISE EXCEPTION 'M38_OPTIONS_INVALID: why_changed must be a boolean';
    END IF;
    RETURN (options ->> 'why_changed')::boolean;
END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_strip_options(options jsonb)
RETURNS jsonb
LANGUAGE SQL
IMMUTABLE
AS $m38$
    SELECT CASE WHEN jsonb_typeof($1) = 'object' THEN $1 - 'why_changed' ELSE $1 END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_cause_kind(path text)
RETURNS text
LANGUAGE SQL
IMMUTABLE
STRICT
AS $m38$
    SELECT CASE
        WHEN lower($1) LIKE '%work%' THEN 'would_be_work'
        WHEN lower($1) LIKE '%winner%' THEN 'decision_winner'
        WHEN lower($1) LIKE '%candidate%' OR lower($1) LIKE '%competitor%' THEN 'decision_candidate'
        WHEN lower($1) LIKE '%applicability%' OR lower($1) LIKE '%subject%' THEN 'applicability'
        WHEN lower($1) LIKE '%parameter%' THEN 'parameter'
        WHEN lower($1) LIKE '%threshold%' OR lower($1) LIKE '%aggregate%' THEN 'threshold'
        WHEN lower($1) LIKE '%deadline%' OR lower($1) LIKE '%window%' OR lower($1) LIKE '%effective%' THEN 'deadline'
        WHEN lower($1) LIKE '%support%' OR lower($1) LIKE '%provenance%' THEN 'positive_support'
        WHEN lower($1) LIKE '%derived%' THEN 'derived_fact'
        WHEN lower($1) LIKE '%revision%' OR lower($1) LIKE '%generation%' OR lower($1) LIKE '%state%' THEN 'lifecycle_revision'
        ELSE 'source_fact'
    END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_causes(
    baseline jsonb,
    candidate jsonb,
    baseline_evidence jsonb,
    candidate_evidence jsonb,
    baseline_work jsonb,
    candidate_work jsonb,
    change_kind text
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m38$
DECLARE
    field_name text;
    before_value jsonb;
    after_value jsonb;
    causes jsonb := '[]'::jsonb;
    path text;
BEGIN
    IF jsonb_typeof(baseline) = 'object' AND jsonb_typeof(candidate) = 'object' THEN
        FOR field_name IN
            SELECT key
            FROM (
                SELECT jsonb_object_keys(baseline) AS key
                UNION
                SELECT jsonb_object_keys(candidate) AS key
            ) fields
            ORDER BY key
        LOOP
            before_value := baseline -> field_name;
            after_value := candidate -> field_name;
            IF before_value IS DISTINCT FROM after_value THEN
                path := 'value.' || field_name;
                causes := causes || jsonb_build_array(jsonb_build_object(
                    'kind', pgreact_internal.m38_cause_kind(path),
                    'direction', CASE
                        WHEN before_value IS NULL THEN 'added'
                        WHEN after_value IS NULL THEN 'removed'
                        ELSE 'changed' END,
                    'path', path,
                    'before', before_value,
                    'after', after_value,
                    'public_evidence', jsonb_build_object(
                        'baseline', COALESCE(baseline_evidence, '{}'::jsonb),
                        'candidate', COALESCE(candidate_evidence, '{}'::jsonb))));
            END IF;
        END LOOP;
    ELSIF baseline IS DISTINCT FROM candidate THEN
        causes := causes || jsonb_build_array(jsonb_build_object(
            'kind', 'source_fact',
            'direction', CASE
                WHEN baseline IS NULL THEN 'added'
                WHEN candidate IS NULL THEN 'removed'
                ELSE 'changed' END,
            'path', 'value',
            'before', baseline,
            'after', candidate,
            'public_evidence', jsonb_build_object(
                'baseline', COALESCE(baseline_evidence, '{}'::jsonb),
                'candidate', COALESCE(candidate_evidence, '{}'::jsonb))));
    END IF;
    IF baseline_work IS DISTINCT FROM candidate_work THEN
        causes := causes || jsonb_build_array(jsonb_build_object(
            'kind', 'would_be_work',
            'direction', CASE
                WHEN baseline_work IS NULL THEN 'added'
                WHEN candidate_work IS NULL THEN 'removed'
                ELSE 'changed' END,
            'path', 'work',
            'before', baseline_work,
            'after', candidate_work,
            'public_evidence', jsonb_build_object(
                'baseline', COALESCE(baseline_evidence, '{}'::jsonb),
                'candidate', COALESCE(candidate_evidence, '{}'::jsonb))));
    END IF;
    IF jsonb_array_length(causes) = 0 AND change_kind <> 'UNCHANGED' THEN
        causes := jsonb_build_array(jsonb_build_object(
            'kind', 'lifecycle_revision',
            'direction', 'changed',
            'path', 'state',
            'before', baseline,
            'after', candidate,
            'public_evidence', jsonb_build_object(
                'baseline', COALESCE(baseline_evidence, '{}'::jsonb),
                'candidate', COALESCE(candidate_evidence, '{}'::jsonb))));
    END IF;
    RETURN causes;
END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_explain_row(
    operation text,
    result_set text,
    ordinal text,
    subject_key text,
    result_key text,
    change_kind text,
    baseline_side text,
    candidate_side text,
    baseline jsonb,
    candidate jsonb,
    baseline_work jsonb,
    candidate_work jsonb,
    baseline_evidence jsonb,
    candidate_evidence jsonb,
    comparison_point jsonb,
    origin_state text,
    originating_result_digest text
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m38$
DECLARE
    causes jsonb;
    semantic jsonb;
    state text;
    started_at timestamptz := clock_timestamp();
BEGIN
    IF change_kind = 'UNCHANGED' THEN
        RETURN NULL;
    END IF;
    causes := pgreact_internal.m38_causes(
        baseline, candidate, baseline_evidence, candidate_evidence,
        baseline_work, candidate_work, change_kind);
    state := CASE
        WHEN baseline_evidence IS NULL AND candidate_evidence IS NULL THEN 'unavailable'
        WHEN origin_state IS DISTINCT FROM 'ready' THEN 'partial'
        ELSE 'complete'
    END;
    semantic := jsonb_build_object(
        'version', 1,
        'state', state,
        'originating_operation', operation,
        'side_pair', jsonb_build_object(
            'baseline', baseline_side, 'candidate', candidate_side),
        'result', jsonb_build_object(
            'result_set', result_set,
            'ordinal', ordinal,
            'subject_key', subject_key,
            'result_key', result_key,
            'change', change_kind),
        'comparison_point', comparison_point,
        'causes', causes,
        'evidence', jsonb_build_object(
            'baseline', COALESCE(baseline_evidence, '{}'::jsonb),
            'candidate', COALESCE(candidate_evidence, '{}'::jsonb),
            'path_is_public', true,
            'causes_exact', state = 'complete'),
        'originating_result_digest', originating_result_digest,
        'cost', jsonb_build_object(
            'cause_discovery', jsonb_array_length(causes),
            'evidence_expansion', jsonb_array_length(causes),
            'path_depth', CASE WHEN jsonb_array_length(causes) > 0 THEN 1 ELSE 0 END,
            'returned_nodes', jsonb_array_length(causes)));
    RETURN semantic || jsonb_build_object(
        'explanation_digest', encode(sha256(convert_to(semantic::text, 'UTF8')), 'hex'),
        'cost', semantic -> 'cost' || jsonb_build_object(
            'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000));
END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_annotate_rows(
    rows jsonb,
    operation text,
    baseline_side text,
    candidate_side text,
    result_set_name text,
    context jsonb,
    row_mode text
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m38$
DECLARE
    row_item jsonb;
    annotated jsonb;
    why jsonb;
    output_rows jsonb := '[]'::jsonb;
    change_kind text;
    baseline_value jsonb;
    candidate_value jsonb;
    baseline_work jsonb;
    candidate_work jsonb;
    baseline_evidence jsonb;
    candidate_evidence jsonb;
    ordinal text;
    point jsonb;
    digest text;
BEGIN
    digest := encode(sha256(convert_to(context::text, 'UTF8')), 'hex');
    FOR row_item IN SELECT value FROM jsonb_array_elements(COALESCE(rows, '[]'::jsonb)) item(value)
    LOOP
        change_kind := row_item ->> 'change';
        IF change_kind IS NULL OR change_kind = 'UNCHANGED' THEN
            output_rows := output_rows || jsonb_build_array(row_item);
            CONTINUE;
        END IF;
        IF row_mode = 'backtest' THEN
            baseline_value := row_item -> 'baseline' -> 'value';
            candidate_value := row_item -> 'candidate' -> 'value';
            baseline_work := row_item -> 'baseline' -> 'work';
            candidate_work := row_item -> 'candidate' -> 'work';
            baseline_evidence := row_item -> 'baseline' -> 'evidence';
            candidate_evidence := row_item -> 'candidate' -> 'evidence';
        ELSE
            baseline_value := row_item -> 'current_value';
            candidate_value := row_item -> 'proposed_value';
            baseline_work := row_item -> 'current_work';
            candidate_work := row_item -> 'proposed_work';
            baseline_evidence := row_item -> 'evidence' -> 'current';
            candidate_evidence := row_item -> 'evidence' -> 'proposed';
        END IF;
        ordinal := COALESCE(
            row_item ->> 'ordinal',
            context ->> 'ordinal',
            context -> 'step' ->> 'ordinal');
        point := jsonb_build_object(
            'result_set', result_set_name,
            'ordinal', ordinal,
            'sampled_time', COALESCE(
                context ->> 'sampled_time',
                context -> 'evidence' ->> 'sampled_time',
                context -> 'snapshot' ->> 'sampled_time',
                context -> 'step' ->> 'sampled_time'),
            'source_frontier', COALESCE(
                context ->> 'source_frontier',
                context -> 'evidence' ->> 'source_frontier',
                context -> 'snapshot' ->> 'source_frontier',
                context -> 'step' ->> 'source_frontier'),
            'event_time_watermark', COALESCE(
                context ->> 'event_time_watermark',
                context -> 'step' ->> 'event_time_watermark'));
        why := pgreact_internal.m38_explain_row(
            operation, result_set_name, ordinal,
            row_item ->> 'subject_key',
            COALESCE(row_item ->> 'result_key', row_item ->> 'subject_key'),
            change_kind, baseline_side, candidate_side,
            baseline_value, candidate_value,
            baseline_work, candidate_work,
            baseline_evidence, candidate_evidence,
            point, context ->> 'state', digest);
        annotated := row_item || jsonb_build_object(
            'why_changed', why,
            'evidence', COALESCE(row_item -> 'evidence', '{}'::jsonb)
                || jsonb_build_object('why_changed', why));
        IF row_mode = 'backtest' THEN
            annotated := annotated || jsonb_build_object(
                'baseline', COALESCE(row_item -> 'baseline', '{}'::jsonb)
                    || jsonb_build_object('evidence',
                        COALESCE(row_item -> 'baseline' -> 'evidence', '{}'::jsonb)
                            || jsonb_build_object('why_changed', why)),
                'candidate', COALESCE(row_item -> 'candidate', '{}'::jsonb)
                    || jsonb_build_object('evidence',
                        COALESCE(row_item -> 'candidate' -> 'evidence', '{}'::jsonb)
                            || jsonb_build_object('why_changed', why)));
        END IF;
        output_rows := output_rows || jsonb_build_array(annotated);
    END LOOP;
    RETURN output_rows;
END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_metadata(
    rows jsonb,
    complete boolean,
    evidence_limit integer,
    originating_result_digest text
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m38$
DECLARE
    semantic jsonb;
    row_count bigint;
    cause_count bigint;
    started_at timestamptz := clock_timestamp();
BEGIN
    SELECT count(*), COALESCE(sum(jsonb_array_length(value -> 'why_changed' -> 'causes')), 0)
    INTO row_count, cause_count
    FROM jsonb_array_elements(COALESCE(rows, '[]'::jsonb)) item(value)
    WHERE value ? 'why_changed';
    semantic := jsonb_build_object(
        'requested', true,
        'state', CASE WHEN complete THEN 'complete' ELSE 'partial' END,
        'causes_exact', complete,
        'rows_explained', row_count,
        'causes_returned', cause_count,
        'evidence_limit', evidence_limit,
        'originating_result_digest', originating_result_digest,
        'cost', jsonb_build_object(
            'cause_discovery', row_count,
            'evidence_expansion', cause_count,
            'path_depth', CASE WHEN cause_count > 0 THEN 1 ELSE 0 END,
            'returned_nodes', cause_count));
    RETURN semantic || jsonb_build_object(
        'explanation_digest', encode(sha256(convert_to(semantic::text, 'UTF8')), 'hex'),
        'cost', semantic -> 'cost' || jsonb_build_object(
            'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000));
END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_finish(
    result jsonb,
    explained_rows jsonb,
    operation text,
    evidence_limit integer
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m38$
DECLARE
    digest text := encode(sha256(convert_to(result::text, 'UTF8')), 'hex');
    metadata jsonb;
    complete boolean := result ->> 'state' = 'ready';
BEGIN
    metadata := pgreact_internal.m38_metadata(
        explained_rows, complete, evidence_limit, digest);
    RETURN result || jsonb_build_object(
        'contract_version', 25,
        'evidence', COALESCE(result -> 'evidence', '{}'::jsonb)
            || jsonb_build_object('why_changed', metadata),
        'findings', COALESCE(result -> 'findings', '[]'::jsonb)
            || jsonb_build_array(pgreact_internal.m38_finding(
                CASE WHEN complete THEN 'M38_NO_EFFECT' ELSE 'M38_EVIDENCE_PARTIAL' END,
                CASE WHEN complete THEN 'INFO' ELSE 'WARNING' END,
                COALESCE(result -> 'target' ->> 'name', '<comparison>'),
                '<why_changed>',
                CASE WHEN complete
                    THEN 'why-changed evidence completed without changing authoritative state'
                    ELSE 'why-changed evidence is bounded and incomplete'
                END,
                'Increase the evidence limit or use the originating result to inspect the bound.')));
END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_annotate_compare(
    result jsonb,
    operation text
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m38$
DECLARE
    delta jsonb;
    lifecycle jsonb;
    explained jsonb;
    evidence_limit integer := COALESCE((result -> 'evidence' ->> 'evidence_limit')::integer, 100);
BEGIN
    delta := pgreact_internal.m38_annotate_rows(
        result -> 'delta', operation, 'current', 'proposed', 'delta', result, 'comparison');
    lifecycle := pgreact_internal.m38_annotate_rows(
        result -> 'lifecycle', operation, 'current', 'proposed', 'lifecycle', result, 'comparison');
    explained := COALESCE(delta, '[]'::jsonb) || COALESCE(lifecycle, '[]'::jsonb);
    result := result || jsonb_build_object('delta', delta, 'lifecycle', lifecycle);
    RETURN pgreact_internal.m38_finish(result, explained, operation, evidence_limit);
END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_annotate_replay(result jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m38$
DECLARE
    step_item jsonb;
    step_output jsonb;
    delta jsonb;
    lifecycle jsonb;
    steps jsonb := '[]'::jsonb;
    explained jsonb := '[]'::jsonb;
    evidence_limit integer := COALESCE((result -> 'evidence' ->> 'evidence_limit')::integer, 100);
BEGIN
    FOR step_item IN SELECT value FROM jsonb_array_elements(COALESCE(result -> 'steps', '[]'::jsonb)) item(value)
    LOOP
        step_output := result || jsonb_build_object('step', step_item);
        delta := pgreact_internal.m38_annotate_rows(
            step_item -> 'delta', 'replay', 'previous', 'current',
            'delta', step_output, 'comparison');
        lifecycle := pgreact_internal.m38_annotate_rows(
            step_item -> 'lifecycle', 'replay', 'previous', 'current',
            'lifecycle', step_output, 'comparison');
        step_item := step_item || jsonb_build_object('delta', delta, 'lifecycle', lifecycle);
        steps := steps || jsonb_build_array(step_item);
        explained := explained || COALESCE(delta, '[]'::jsonb) || COALESCE(lifecycle, '[]'::jsonb);
    END LOOP;
    result := result || jsonb_build_object('steps', steps);
    RETURN pgreact_internal.m38_finish(result, explained, 'replay', evidence_limit);
END
$m38$;

CREATE OR REPLACE FUNCTION pgreact_internal.m38_annotate_backtest(result jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m38$
DECLARE
    rows jsonb;
    differences jsonb;
    evidence_limit integer := COALESCE((result -> 'evidence' ->> 'evidence_limit')::integer, 100);
BEGIN
    rows := pgreact_internal.m38_annotate_rows(
        result -> 'differences' -> 'rows', 'backtest',
        'baseline', 'candidate', 'difference', result, 'backtest');
    differences := COALESCE(result -> 'differences', '{}'::jsonb)
        || jsonb_build_object('rows', rows);
    result := result || jsonb_build_object('differences', differences);
    RETURN pgreact_internal.m38_finish(result, rows, 'backtest', evidence_limit);
END
$m38$;

CREATE OR REPLACE FUNCTION pgreact.compare(
    proposed pgreact_api.declaration,
    deployed pgreact_api.target,
    options jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $m38$
    SELECT CASE WHEN pgreact_internal.m38_requested($3)
        THEN pgreact_internal.m38_annotate_compare(
            pgreact_internal.m34_compare($1, $2, pgreact_internal.m38_strip_options($3)),
            'compare')
        ELSE pgreact_internal.m34_compare($1, $2, pgreact_internal.m38_strip_options($3))
    END
$m38$;

